INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10103, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "晚", "is_correct": true, "explanation": "正确：“早”与“晚”构成反义，指时间靠后。"}, {"text": "快", "is_correct": false, "explanation": "不构成反义：“快”与“早”不是时间先后的对立。"}, {"text": "高", "is_correct": false, "explanation": "不构成反义：“高”与“早”没有对立关系。"}, {"text": "远", "is_correct": false, "explanation": "不构成反义：“远”的反义是“近”，与“早”无关。"}], "correct_answer": "晚", "explanations": {"晚": "正确：“早”与“晚”构成反义，指时间靠后。", "快": "不构成反义：“快”与“早”不是时间先后的对立。", "高": "不构成反义：“高”与“早”没有对立关系。", "远": "不构成反义：“远”的反义是“近”，与“早”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10103, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "晚", "is_correct": true, "explanation": "正确：“早”与“晚”构成反义，指时间靠后。"}, {"text": "慢", "is_correct": false, "explanation": "不构成反义：“慢”的反义是“快”，与“早”无关。"}, {"text": "重", "is_correct": false, "explanation": "不构成反义：“重”与“早”没有对立关系。"}, {"text": "冷", "is_correct": false, "explanation": "不构成反义：“冷”与“早”没有对立关系。"}], "correct_answer": "晚", "explanations": {"晚": "正确：“早”与“晚”构成反义，指时间靠后。", "慢": "不构成反义：“慢”的反义是“快”，与“早”无关。", "重": "不构成反义：“重”与“早”没有对立关系。", "冷": "不构成反义：“冷”与“早”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10103, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指太阳刚升起或时间靠前的时段。", "primary_collocate": null, "pronunciation": "zǎo", "ipa": "tsɑʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "今天你来得真早。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天睡得很早。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在才六点，还早呢。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么这么早就起床了？", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比我早到了十分钟。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来得早，花开得也早。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天要早点出发。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天起得很早。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车七点开，我们得早点去。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在去还太早，商店没开门。", "target_word": "早", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "早早", "label": "重叠"}], "register": "中性", "sense_fingerprint": "早·时间靠前，比一般时间提前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab2749-257c-4c70-be8d-c6367b76fc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10103, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "早", "is_correct": true, "explanation": "正确：“早”读 zǎo（第三声），意思是时间靠前。"}, {"text": "造", "is_correct": false, "explanation": "zào 与 zǎo 声调不同（第四声与第三声），意思是制造。"}, {"text": "草", "is_correct": false, "explanation": "cǎo 与 zǎo 声母不同（c 与 z），意思是草。"}, {"text": "好", "is_correct": false, "explanation": "hǎo 与 zǎo 声母不同（h 与 z），意思是好。"}, {"text": "找", "is_correct": false, "explanation": "zhǎo 与 zǎo 声母不同（zh 与 z），意思是寻找。"}], "explanations": {"早": "正确：“早”读 zǎo（第三声），意思是时间靠前。", "造": "zào 与 zǎo 声调不同（第四声与第三声），意思是制造。", "草": "cǎo 与 zǎo 声母不同（c 与 z），意思是草。", "好": "hǎo 与 zǎo 声母不同（h 与 z），意思是好。", "找": "zhǎo 与 zǎo 声母不同（zh 与 z），意思是寻找。"}, "sentence_index": null, "correct_answer": "早"}, "level_3": {"options": [{"text": "早", "is_correct": true, "explanation": "正确：“来得真早”表示到得时间靠前，符合语境。"}, {"text": "深", "is_correct": false, "explanation": "语义：深指空间或程度，“来得真深”不成立。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：“来得”后不搭配“轻”，不能说“来得真轻”。"}, {"text": "白", "is_correct": false, "explanation": "语义：白指颜色，不能说“来得真白”。"}], "explanations": {"早": "正确：“来得真早”表示到得时间靠前，符合语境。", "深": "语义：深指空间或程度，“来得真深”不成立。", "轻": "搭配：“来得”后不搭配“轻”，不能说“来得真轻”。", "白": "语义：白指颜色，不能说“来得真白”。"}, "sentence_index": 0, "correct_answer": "早"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "时间过得很早，一转眼就到了年底。", "explanation": "这里应该用〈快〉。“早”指时间靠前，不能说“时间过得很早”。"}, {"text": "他跑得很早，一下子就到了终点。", "explanation": "这里应该用〈快〉。“早”指时间靠前，不能形容速度；跑得快要说〈快〉。"}, {"text": "这辆自行车骑得很早，十分钟就到了。", "explanation": "这里应该用〈快〉。“早”指时间靠前，不能形容骑车的速度；骑得快要说〈快〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10103, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "早", "is_correct": true, "explanation": "正确：“早”读 zǎo（第三声），意思是时间靠前。"}, {"text": "扫", "is_correct": false, "explanation": "sǎo 与 zǎo 声母不同（s 与 z），意思是扫地。"}, {"text": "老", "is_correct": false, "explanation": "lǎo 与 zǎo 声母不同（l 与 z），意思是年老。"}, {"text": "糟", "is_correct": false, "explanation": "zāo 与 zǎo 声调不同（第一声与第三声），意思是糟糕。"}, {"text": "吵", "is_correct": false, "explanation": "chǎo 与 zǎo 声母不同（ch 与 z），意思是吵闹。"}], "explanations": {"早": "正确：“早”读 zǎo（第三声），意思是时间靠前。", "扫": "sǎo 与 zǎo 声母不同（s 与 z），意思是扫地。", "老": "lǎo 与 zǎo 声母不同（l 与 z），意思是年老。", "糟": "zāo 与 zǎo 声调不同（第一声与第三声），意思是糟糕。", "吵": "chǎo 与 zǎo 声母不同（ch 与 z），意思是吵闹。"}, "sentence_index": null, "correct_answer": "早"}, "level_3": {"options": [{"text": "早", "is_correct": true, "explanation": "正确：“要早点出发”表示提前出发，符合语境。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“要高点出发”不成立，“高”不搭配出发的时间。"}, {"text": "厚", "is_correct": false, "explanation": "语义：厚指物体的厚度，不说“要厚点出发”。"}, {"text": "粗", "is_correct": false, "explanation": "语义：粗形容粗细，与出发无关。"}], "explanations": {"早": "正确：“要早点出发”表示提前出发，符合语境。", "高": "搭配：“要高点出发”不成立，“高”不搭配出发的时间。", "厚": "语义：厚指物体的厚度，不说“要厚点出发”。", "粗": "语义：粗形容粗细，与出发无关。"}, "sentence_index": 6, "correct_answer": "早"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸色很早，看起来很累。", "explanation": "这里应该用〈憔悴〉。“早”指时间靠前，不能形容脸色；形容脸色难看要说〈憔悴〉。"}, {"text": "他的声音很早，听起来很沙哑。", "explanation": "这里应该用〈低沉〉。“早”不能形容声音的状态；声音低沉的说法是〈低沉〉。"}, {"text": "他的力气很早，搬起东西很轻松。", "explanation": "这里应该用〈大〉。“早”不能形容力气的多少；力气大要说〈大〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他比我很早到了十分钟。", "corrected_sentence": "他比我早到了十分钟。", "error_description": "比较句错误：“比”字句中“早”前不能加“很”，应说“他比我早到了十分钟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我们要早的一点到校。", "corrected_sentence": "明天我们要早一点到校。", "error_description": "结构错误：“早一点”修饰动词“到校”时不加“的”，应说“要早一点到校”，不说“要早的一点到校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
