INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10105, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "广泛地使用或应用。", "primary_collocate": null, "pronunciation": "guǎng fàn yìng yòng", "ipa": "kwɑŋ˨˩ fan˥˩ iŋ˥˩ yʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "材料科学的进步使得复合材料得以广泛应用，不仅减轻了结构重量，还增强了疲劳耐久性；计算流体动力学（CFD）的发展则使工程师能够在虚拟风洞中模拟极端工况下的气动性能，从而在原型制造前完成多轮迭代。", "target_word": "广泛应用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "中国早在唐代便已广泛应用雕版印刷，宋代毕昇更首创泥活字，开启了可重复排版的技术先河。", "target_word": "广泛应用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种新技术已经在医院广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机支付在中国广泛应用。", "target_word": "广泛应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳能在很多国家得到了广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料因为便宜，所以广泛应用在生活中。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种方法在学校里广泛应用了很多年。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑在工作中广泛应用，已成为不可或缺的工具。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "互联网让视频会议得以广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项技术已经在工厂里广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "技术、方法等被大范围地使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65ed119e-0d7b-4fd6-9dc2-f9c5d6a85cda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10105, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：复合材料不能“睡觉”，与上文的技术进步语境不符。"}, {"text": "瞎搞", "is_correct": false, "explanation": "语域：“瞎搞”是口语贬义，与这段书面论述的语域不合。"}, {"text": "广泛应用", "is_correct": true, "explanation": "正确：“得以”后接表示技术、方法被使用的动词，“广泛应用”符合上文语境。"}, {"text": "发脾气", "is_correct": false, "explanation": "语义：材料不会“发脾气”，句意不通。"}], "explanations": {"睡觉": "语义：复合材料不能“睡觉”，与上文的技术进步语境不符。", "瞎搞": "语域：“瞎搞”是口语贬义，与这段书面论述的语域不合。", "广泛应用": "正确：“得以”后接表示技术、方法被使用的动词，“广泛应用”符合上文语境。", "发脾气": "语义：材料不会“发脾气”，句意不通。"}, "sentence_index": 0, "correct_answer": "广泛应用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌在全国广泛应用。", "explanation": "这里应该用〈广泛流传〉。“广泛应用”指技术、方法被使用，不用于歌曲等作品。"}, {"text": "这位画家在全国广泛应用。", "explanation": "这里应该用〈广受欢迎〉。“广泛应用”的主语应是技术或方法，不能指人。"}, {"text": "这种蛋糕在本地广泛应用。", "explanation": "这里应该用〈广受欢迎〉。“广泛应用”的主语应是技术或方法，蛋糕是食物，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10105, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃饭", "is_correct": false, "explanation": "语义：“这种方法”不能吃饭，句意不通。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：“这种方法”不能呼吸，句意不通。"}, {"text": "广泛应用", "is_correct": true, "explanation": "正确：“在学校里……了很多年”指方法被大量使用，“广泛应用”符合句意。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”的主语应是人，不能用于“这种方法”。"}], "explanations": {"吃饭": "语义：“这种方法”不能吃饭，句意不通。", "呼吸": "语义：“这种方法”不能呼吸，句意不通。", "广泛应用": "正确：“在学校里……了很多年”指方法被大量使用，“广泛应用”符合句意。", "感冒": "搭配：“感冒”的主语应是人，不能用于“这种方法”。"}, "sentence_index": 6, "correct_answer": "广泛应用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们广泛应用了这位老朋友。", "explanation": "这里误把“广泛应用”当作〈结交〉之类的人际动作。“广泛应用”只用于技术、方法等，不能用于人。"}, {"text": "他广泛应用了这件新衣服。", "explanation": "这里应该用〈穿〉。“广泛应用”指技术、方法被普遍使用，衣物应说“穿”，不说“应用”。"}, {"text": "他广泛应用了这个笑话。", "explanation": "这里应该用〈讲〉。“广泛应用”指技术、方法被普遍使用，笑话应说“讲”，不说“应用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套系统已经广泛应用医院。", "corrected_sentence": "这套系统已经广泛应用于医院。", "error_description": "“广泛应用”带场所或领域作宾语时须加介词“于”，说“应用于医院”，不能说“广泛应用医院”；带技术或方法作宾语时可直接说“广泛应用雕版印刷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项技术广泛应用了于农业。", "corrected_sentence": "这项技术广泛应用于农业。", "error_description": "“应用于”是固定搭配，“了”不能插在“应用”和“于”之间，正确说法是“应用于农业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
