INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10107, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "最先创造或发明，指做别人没有做过的事情。", "primary_collocate": null, "pronunciation": "shǒu chuàng", "ipa": "ʂou˨˩ ʈʂʰuaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "中国早在唐代便已广泛应用雕版印刷，宋代毕昇更首创泥活字，开启了可重复排版的技术先河。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这家公司首创了网上买菜的服务。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法是我们学校首创的。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法以前没人用过，是他首创的。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位工程师首创了一种新的建房方法。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人首创了指南针，对航海很有帮助。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店首创了全场半价的促销活动。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她首创的做菜方法，现在很多人都在用。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市首创了免费借书的制度。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他首创的这个游戏，全世界的孩子都喜欢。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "首创了", "label": "体标"}, {"form": "首创过", "label": "体标"}, {"form": "首创者", "label": "复合"}], "register": "书面", "sense_fingerprint": "最先创造别人没做过的事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab2749-257c-4c70-be8d-c6367b76fc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10107, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修改", "is_correct": false, "explanation": "语义：「修改」指改动已有的东西，与「开启了可重复排版的技术先河」的首创义不合。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：「讨论」的对象是问题或方案，不能说讨论泥活字。"}, {"text": "首创", "is_correct": true, "explanation": "正确：「首创」指第一次创造，与「开启了可重复排版的技术先河」相合。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：「丢弃」意为抛弃，与开创新技术的语境相反。"}], "explanations": {"修改": "语义：「修改」指改动已有的东西，与「开启了可重复排版的技术先河」的首创义不合。", "讨论": "搭配：「讨论」的对象是问题或方案，不能说讨论泥活字。", "首创": "正确：「首创」指第一次创造，与「开启了可重复排版的技术先河」相合。", "丢弃": "语义：「丢弃」意为抛弃，与开创新技术的语境相反。"}, "sentence_index": 0, "correct_answer": "首创"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店首创了别的店的做法。", "explanation": "这里应该用〈效仿〉。首创指第一次做出别人没做过的事，学别人的做法要说效仿。"}, {"text": "他首创了朋友写的论文。", "explanation": "这里应该用〈抄袭〉。首创指原创的第一次，不能用来说把别人的成果据为己有。"}, {"text": "工厂首创了国外的模式。", "explanation": "这里应该用〈照搬〉。首创指前所未有，国外已有的模式只能说照搬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10107, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语是食物，不能说吃促销活动。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：「发表」多用于言论或文章，不说发表促销活动。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：「逃避」指躲开不想面对的事，小店不会躲避自己的促销。"}, {"text": "首创", "is_correct": true, "explanation": "正确：「首创」指第一次推出，与「全场半价的促销活动」相合。"}], "explanations": {"吃": "搭配：「吃」的宾语是食物，不能说吃促销活动。", "发表": "搭配：「发表」多用于言论或文章，不说发表促销活动。", "逃避": "语义：「逃避」指躲开不想面对的事，小店不会躲避自己的促销。", "首创": "正确：「首创」指第一次推出，与「全场半价的促销活动」相合。"}, "sentence_index": 6, "correct_answer": "首创"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他首创了父亲留下的手艺。", "explanation": "这里应该用〈继承〉。首创指第一次做出，父亲传下来的手艺只能说继承。"}, {"text": "小王首创了老师的讲课方法。", "explanation": "这里应该用〈借鉴〉。老师已经用过的讲课方法只能说借鉴，不能说首创。"}, {"text": "他首创了老师的字迹。", "explanation": "这里应该用〈仿照〉。字迹是已经存在的，照着写要说仿照，首创指第一次做出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他首创的了一种新的教学法。", "corrected_sentence": "他首创了一种新的教学法。", "error_description": "助词错误：“首创”后的“的”与“了”不能同时出现；表示完成应只用“了”，应说“他首创了一种新的教学法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10107, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法是他首创了的。", "corrected_sentence": "这个办法是他首创的。", "error_description": "「是……的」句中，「首创」后面直接接「的」，不能再加「了」，应说「是他首创的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
