INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "泥，指由水和土混合而成的柔软物质，常用于建筑或陶艺。", "primary_collocate": null, "pronunciation": "ní", "ipa": "ni˧˥", "syllable_count": 1, "sentences": [{"text": "中国早在唐代便已广泛应用雕版印刷，宋代毕昇用泥做成活字，开启了可重复排版的技术先河。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，路上有很多泥。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在河边玩泥，衣服都脏了。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的鞋上全是泥，一定走了很远的路。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用软软的泥，捏了一只小鸟。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在田里踩着泥，一步一步地走。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙是用泥和草做的，冬天很暖和。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把鞋上的泥洗干净。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水和土混在一起就成了泥。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块泥太硬了，要加一点水才能做杯子。", "target_word": "泥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}, {"form": "团", "label": "量词"}, {"form": "泥巴", "label": "复合"}, {"form": "泥土", "label": "复合"}], "register": "中性", "sense_fingerprint": "水和土混合而成的柔软物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab2749-257c-4c70-be8d-c6367b76fc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10108, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "泥", "is_correct": true, "explanation": "正确：「泥」（ní）指水和土混成的软物，是本词。"}, {"text": "你", "is_correct": false, "explanation": "nǐ（第三声）与 ní（第二声）声调不同，意思是「你」。"}, {"text": "离", "is_correct": false, "explanation": "lí 与 ní 声母不同（l 与 n），意思是「离开」。"}, {"text": "腻", "is_correct": false, "explanation": "nì（第四声）与 ní（第二声）声调不同，意思是「油腻」。"}, {"text": "宁", "is_correct": false, "explanation": "níng 比 ní 多一个韵尾 -ng，意思是「安宁」。"}], "explanations": {"泥": "正确：「泥」（ní）指水和土混成的软物，是本词。", "你": "nǐ（第三声）与 ní（第二声）声调不同，意思是「你」。", "离": "lí 与 ní 声母不同（l 与 n），意思是「离开」。", "腻": "nì（第四声）与 ní（第二声）声调不同，意思是「油腻」。", "宁": "níng 比 ní 多一个韵尾 -ng，意思是「安宁」。"}, "sentence_index": null, "correct_answer": "泥"}, "level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气是气体，不能用来制作活字。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，不能用来制作活字。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：活字需要实物材料，「声音」不能作为制作材料。"}, {"text": "泥", "is_correct": true, "explanation": "正确：“用泥做成活字”中的“泥”指制作活字的材料，与语境相合。"}], "explanations": {"空气": "语义：空气是气体，不能用来制作活字。", "时间": "语义：时间是抽象概念，不能用来制作活字。", "声音": "搭配：活字需要实物材料，「声音」不能作为制作材料。", "泥": "正确：“用泥做成活字”中的“泥”指制作活字的材料，与语境相合。"}, "sentence_index": 0, "correct_answer": "泥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "沙漠里到处都是泥，什么也长不出来。", "explanation": "这里应该用〈沙〉。沙漠里是干燥的沙子，不能说泥；泥指水和土混成的软物。"}, {"text": "他一吹，书上的泥就飞起来了。", "explanation": "这里应该用〈灰尘〉。灰尘是干燥的细粉，一吹就飞；泥是湿的软物，吹不起来。"}, {"text": "他渴极了，把泥倒进杯子里喝。", "explanation": "这里应该用〈水〉。泥是水和土混成的软物，不能倒进杯子里喝；要喝的是水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10108, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "泥", "is_correct": true, "explanation": "正确：「泥」（ní）指水和土混成的软物，是本词。"}, {"text": "拟", "is_correct": false, "explanation": "nǐ（第三声）与 ní（第二声）声调不同，意思是「拟定」。"}, {"text": "梨", "is_correct": false, "explanation": "lí 与 ní 声母不同（l 与 n），意思是「梨子」。"}, {"text": "逆", "is_correct": false, "explanation": "nì（第四声）与 ní（第二声）声调不同，意思是「逆行」。"}, {"text": "凝", "is_correct": false, "explanation": "níng 比 ní 多一个韵尾 -ng，意思是「凝结」。"}], "explanations": {"泥": "正确：「泥」（ní）指水和土混成的软物，是本词。", "拟": "nǐ（第三声）与 ní（第二声）声调不同，意思是「拟定」。", "梨": "lí 与 ní 声母不同（l 与 n），意思是「梨子」。", "逆": "nì（第四声）与 ní（第二声）声调不同，意思是「逆行」。", "凝": "níng 比 ní 多一个韵尾 -ng，意思是「凝结」。"}, "sentence_index": null, "correct_answer": "泥"}, "level_3": {"options": [{"text": "糖", "is_correct": false, "explanation": "语义：糖不能用来砌墙。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：梦想是抽象的念头，不能用来砌墙。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：墙要用建材砌成，「歌曲」不能作为砌墙的材料。"}, {"text": "泥", "is_correct": true, "explanation": "正确：墙用泥和草做成，「泥」指用于砌墙的土料，与「冬天很暖和」相合。"}], "explanations": {"糖": "语义：糖不能用来砌墙。", "梦想": "语义：梦想是抽象的念头，不能用来砌墙。", "歌曲": "搭配：墙要用建材砌成，「歌曲」不能作为砌墙的材料。", "泥": "正确：墙用泥和草做成，「泥」指用于砌墙的土料，与「冬天很暖和」相合。"}, "sentence_index": 6, "correct_answer": "泥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天上飘着几朵白白的泥。", "explanation": "这里应该用〈云〉。泥是地上水和土混成的软物，不会在天上飘。"}, {"text": "冬天下了一场大泥，地上一片白。", "explanation": "这里应该用〈雪〉。冬天从天上落下、让地上变白的是雪，不是泥。"}, {"text": "吃饭前要用泥把手洗干净。", "explanation": "这里应该用〈肥皂〉。泥会把手弄脏，洗手要用肥皂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从桌上拿起一只泥，开始捏杯子。", "corrected_sentence": "他从桌上拿起一块泥，开始捏杯子。", "error_description": "「泥」的量词是「块」或「团」；「只」多用于动物或成对物件中的单个，不用于泥，应改为「一块泥」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把泥捏了成一个小碗。", "corrected_sentence": "他把泥捏成了一个小碗。", "error_description": "「捏成」是结果补语，「成」要紧跟动词，应说「捏成了」，不能说「捏了成」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
