INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10112, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将文字、图片等素材按一定规则或格式进行排列、组合，以便于阅读或展示。", "primary_collocate": null, "pronunciation": "pái bǎn", "ipa": "pʰai˧˥ pan˨˩", "syllable_count": 2, "sentences": [{"text": "中国早在唐代便已广泛应用雕版印刷，宋代毕昇更首创泥活字，开启了可重复排版的技术先河。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "然而，受制于汉字数量庞大、排版复杂以及社会结构的限制，这一技术未能引发大规模的知识普及浪潮。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "老师请小李帮忙排版这份报纸。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的图片太多，排版很不容易。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学会了用电脑给文章排版。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她排版过很多本杂志，经验丰富。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排版的时候，字不要太小，不然读者看不清。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把图片放在文字下面，再排版。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请他给这张海报排版，字和图都要好看。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书做好以后，先排版，再印刷。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排版了", "label": "体标"}, {"form": "排版过", "label": "体标"}, {"form": "排版师", "label": "复合"}], "register": "中性", "sense_fingerprint": "把文字图片按格式排列组合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab2749-257c-4c70-be8d-c6367b76fc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10112, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排版", "is_correct": true, "explanation": "正确：排版（pái bǎn）指按一定规则排列文字、图片的版面。"}, {"text": "拍板", "is_correct": false, "explanation": "拍板（pāi bǎn）第一音节 pāi 为第一声，与 pái（第二声）声调不同，意思是拍板（做决定）。"}, {"text": "白板", "is_correct": false, "explanation": "白板（bái bǎn）第一音节声母为 b，与 p 不同，意思是白色的板子。"}, {"text": "排班", "is_correct": false, "explanation": "排班（pái bān）第二音节 bān 为第一声，与 bǎn（第三声）声调不同，意思是安排轮班。"}, {"text": "排满", "is_correct": false, "explanation": "排满（pái mǎn）第二音节声母为 m，与 b 不同，意思是排列到满。"}], "explanations": {"排版": "正确：排版（pái bǎn）指按一定规则排列文字、图片的版面。", "拍板": "拍板（pāi bǎn）第一音节 pāi 为第一声，与 pái（第二声）声调不同，意思是拍板（做决定）。", "白板": "白板（bái bǎn）第一音节声母为 b，与 p 不同，意思是白色的板子。", "排班": "排班（pái bān）第二音节 bān 为第一声，与 bǎn（第三声）声调不同，意思是安排轮班。", "排满": "排满（pái mǎn）第二音节声母为 m，与 b 不同，意思是排列到满。"}, "sentence_index": null, "correct_answer": "排版"}, "level_3": {"options": [{"text": "排版", "is_correct": true, "explanation": "正确：排版指按规则排列文字、图片，此处指可重复排版的印刷技术。"}, {"text": "发明", "is_correct": false, "explanation": "语义：活字的特点是可以反复排字使用，“可重复发明的技术”说不通。"}, {"text": "研磨", "is_correct": false, "explanation": "搭配：研磨指把东西磨碎，不能用来修饰“技术先河”，句意不通。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：雕刻要在整块板上刻字，每次都要重刻，与“泥活字”可重复使用的意思相悖。"}], "explanations": {"排版": "正确：排版指按规则排列文字、图片，此处指可重复排版的印刷技术。", "发明": "语义：活字的特点是可以反复排字使用，“可重复发明的技术”说不通。", "研磨": "搭配：研磨指把东西磨碎，不能用来修饰“技术先河”，句意不通。", "雕刻": "语义：雕刻要在整块板上刻字，每次都要重刻，与“泥活字”可重复使用的意思相悖。"}, "sentence_index": 0, "correct_answer": "排版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些桌子排版得很整齐。", "explanation": "这里应该用〈排列〉。排版指排列文字、图片的版面，桌椅等物件的摆放要用排列。"}, {"text": "这位画家每天排版一幅画。", "explanation": "这里应该用〈绘制〉。排版指排列文字、图片的版面，创作画作要用〈绘制〉，不能用排版。"}, {"text": "妈妈排版了今天的日程。", "explanation": "这里应该用〈安排〉。排版只用于文字、图片的版面，日程要用〈安排〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排版", "is_correct": true, "explanation": "正确：排版指按规则排列文字、图片，此处指排版时要注意字的大小。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与印刷品上的字和读者能否看清无关，不能说“字不要太小”。"}, {"text": "录音", "is_correct": false, "explanation": "语义：录音是录制声音，与字的大小和读者看清楚与否无关。"}, {"text": "切菜", "is_correct": false, "explanation": "搭配：切菜的对象是食材，不能与“字”搭配，句意不通。"}], "explanations": {"排版": "正确：排版指按规则排列文字、图片，此处指排版时要注意字的大小。", "唱歌": "语义：唱歌与印刷品上的字和读者能否看清无关，不能说“字不要太小”。", "录音": "语义：录音是录制声音，与字的大小和读者看清楚与否无关。", "切菜": "搭配：切菜的对象是食材，不能与“字”搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "排版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天排版我的头发，很整齐。", "explanation": "这里应该用〈梳〉。排版的对象是文字、图片等版面素材，头发不能排版。"}, {"text": "他排版了那只猫。", "explanation": "这里应该用〈喂养〉。排版指排列文字、图片的版面，照料猫要用〈喂养〉，不能用排版。"}, {"text": "园丁排版了院子里的树。", "explanation": "这里应该用〈修剪〉。排版的对象是文字、图片等版面素材，树木不能排版。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告他排版很得整齐。", "corrected_sentence": "这份报告他排版得很整齐。", "error_description": "补语标记错误：程度补语的“得”应紧接动词“排版”，应说“排版得很整齐”，“排版很得整齐”不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师这份报纸排版。", "corrected_sentence": "老师给这份报纸排版。", "error_description": "漏用介词：引出动作对象“这份报纸”的“给”不能省略，应说“老师给这份报纸排版”；去掉“给”后，“这份报纸”直接放在动词前，句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
