INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10113, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "先河比喻某一事业或行动的开创者或最早的做法。", "primary_collocate": null, "pronunciation": "xiān hé", "ipa": "ɕjɛn˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "中国早在唐代便已广泛应用雕版印刷，宋代毕昇更首创泥活字，开启了可重复排版的技术先河。", "target_word": "先河", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司开了行业的先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的实验开了新医学的先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家为现代诗歌开了先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市在环保方面开了先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项制度开了先河，别的地方也学了起来。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的做法为后来的学校开了先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书开了中国科幻小说的先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国第一所女子学校开了女子教育的先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇开了无人商店的先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "比喻某一事业或行动最早的做法，常与“开”搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e884783-3d98-4d71-90bb-6a5b56992bcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10113, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "先河", "is_correct": true, "explanation": "正确答案。xiānhé 指最早的开创之举。"}, {"text": "仙鹤", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，“仙鹤”指一种鸟，意思不同。"}, {"text": "相合", "is_correct": false, "explanation": "xiāng 与 xiān 仅韵尾不同（-ng 与 -n），“相合”指相符、相配。"}, {"text": "山河", "is_correct": false, "explanation": "shān 与 xiān 仅声母不同（sh 与 x），“山河”指山与河，意思无关。"}, {"text": "先喝", "is_correct": false, "explanation": "hē（第一声）与 hé（第二声）声调不同，“先喝”指先饮用。"}], "explanations": {"先河": "正确答案。xiānhé 指最早的开创之举。", "仙鹤": "hè（第四声）与 hé（第二声）声调不同，“仙鹤”指一种鸟，意思不同。", "相合": "xiāng 与 xiān 仅韵尾不同（-ng 与 -n），“相合”指相符、相配。", "山河": "shān 与 xiān 仅声母不同（sh 与 x），“山河”指山与河，意思无关。", "先喝": "hē（第一声）与 hé（第二声）声调不同，“先喝”指先饮用。"}, "sentence_index": null, "correct_answer": "先河"}, "level_3": {"options": [{"text": "先河", "is_correct": true, "explanation": "正确答案。“开启了……技术先河”指开创了某项技术的最早做法。"}, {"text": "余波", "is_correct": false, "explanation": "语义：“余波”指事件之后的影响，与“开启”的开端义相反。"}, {"text": "门道", "is_correct": false, "explanation": "语域：“门道”是口语词，指窍门，与前文的书面语“首创”“开启”不协调。"}, {"text": "障碍", "is_correct": false, "explanation": "搭配：“开启”后面接“大门”“序幕”“先河”这类开端，不能接“障碍”。"}], "explanations": {"先河": "正确答案。“开启了……技术先河”指开创了某项技术的最早做法。", "余波": "语义：“余波”指事件之后的影响，与“开启”的开端义相反。", "门道": "语域：“门道”是口语词，指窍门，与前文的书面语“首创”“开启”不协调。", "障碍": "搭配：“开启”后面接“大门”“序幕”“先河”这类开端，不能接“障碍”。"}, "sentence_index": 0, "correct_answer": "先河"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议是例行的先河。", "explanation": "这里应该用〈惯例〉。先河指最早开创的做法，不能指重复进行的例行事务；这类做法应说“惯例”。"}, {"text": "他每天早上都开先河。", "explanation": "先河只指一次性的首创，不能用于每天重复的习惯。"}, {"text": "别的公司早就这样做了，这家公司最后一个开了先河。", "explanation": "先河指最早开创的做法；最后一个跟着做的不能说开了先河，应说“跟进”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先河", "is_correct": true, "explanation": "正确答案。“开了……先河”指做了最早的做法，符合句意。"}, {"text": "尾声", "is_correct": false, "explanation": "语义：“尾声”指结束阶段，与“开”所表示的开端义相反，句意不合。"}, {"text": "榜样", "is_correct": false, "explanation": "搭配：说“树立榜样”，不说“开榜样”。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：“工厂”是生产场所，不能作为做法为学校所开的对象。"}], "explanations": {"先河": "正确答案。“开了……先河”指做了最早的做法，符合句意。", "尾声": "语义：“尾声”指结束阶段，与“开”所表示的开端义相反，句意不合。", "榜样": "搭配：说“树立榜样”，不说“开榜样”。", "工厂": "语义：“工厂”是生产场所，不能作为做法为学校所开的对象。"}, "sentence_index": 6, "correct_answer": "先河"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小镇跟随别人，开了无人商店的先河。", "explanation": "这里应该用〈效仿〉。先河指最早开创的做法；跟随别人的做法属于效仿，不能说成开先河。"}, {"text": "城里的超市早已有过无人收银，这个小镇的无人商店只是重复了先河。", "explanation": "这里应该用〈先例〉。先河指最早出现的首创之举；已经存在的做法只能称为先例，不能说成重复的先河。"}, {"text": "这个小镇的无人商店是照搬别人的先河。", "explanation": "这里应该用〈模仿〉。先河指最早开创的做法；照搬他人的做法是模仿，不是首创，不能说成先河。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店最早推出会员打折，做了先河。", "corrected_sentence": "这家书店最早推出会员打折，开了先河。", "error_description": "错误：“做了先河”。正确：“开了先河”。“先河”前面的动词要用“开”，不能用“做”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院开了一条远程问诊的先河。", "corrected_sentence": "这家医院开了远程问诊的先河。", "error_description": "错误：“一条……先河”。正确：“开了……的先河”。“先河”是比喻用法，前面不加数量词“一条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
