INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10114, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受到人、条件或因素的控制或约束。", "primary_collocate": null, "pronunciation": "shòu zhì yú", "ipa": "ʂoʊ̯˥˩ ʈʂɻ̩˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "然而，受制于汉字数量庞大、排版复杂以及社会结构的限制，这一技术未能引发大规模的知识普及浪潮。", "target_word": "受制于", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "从苹果、杏仁到咖啡与可可，这些人类饮食结构中的重要组成部分，其产量与质量皆深刻受制于蜂类活动的稳定性。", "target_word": "受制于", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家小公司受制于大公司。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民受制于天气，收成不稳定。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "受制于资金，我们不能再买新电脑。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想受制于任何人。", "target_word": "受制于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个国家的经济受制于外国市场。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "受制于场地，比赛只好改到室内。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂长期受制于原料价格。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "受制于时间，今天的会议只能开一小时。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "受制于", "label": "基本形式"}, {"form": "受制於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "行为或结果被他人、条件或因素控制、限制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b7ca80-ae1c-4e7c-a5ec-daf599d2e99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受惠于", "is_correct": false, "explanation": "语义：“受惠”指得到好处，与句中“限制”的语境相反。"}, {"text": "受制于", "is_correct": true, "explanation": "正确：“受制于汉字数量庞大、排版复杂以及社会结构的限制”表示受到限制，与语境一致。"}, {"text": "受教于", "is_correct": false, "explanation": "搭配：“受教于”指接受教导，不能用于汉字数量、排版这类限制条件。"}, {"text": "独立于", "is_correct": false, "explanation": "语义：“独立于”表示不受约束，与“受……的限制”的意思相反。"}], "explanations": {"受惠于": "语义：“受惠”指得到好处，与句中“限制”的语境相反。", "受制于": "正确：“受制于汉字数量庞大、排版复杂以及社会结构的限制”表示受到限制，与语境一致。", "受教于": "搭配：“受教于”指接受教导，不能用于汉字数量、排版这类限制条件。", "独立于": "语义：“独立于”表示不受约束，与“受……的限制”的意思相反。"}, "sentence_index": 0, "correct_answer": "受制于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他受制于多年的努力，终于成功了。", "explanation": "这里应该用〈受益于〉。受制于表示被约束，含消极意思；多年的努力带来的是好处，应说〈受益于〉。"}, {"text": "孩子受制于父母的关心，每天都很开心。", "explanation": "这里应该用〈享受〉。受制于表示被约束，含消极意思；父母的关心是好的，应说〈享受〉。"}, {"text": "这个孩子受制于一次表扬，马上行动了。", "explanation": "这里应该用〈受鼓舞〉。受制于表示被人或条件约束，含消极意思；受到表扬是正面的激励，应说〈受鼓舞〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受邀于", "is_correct": false, "explanation": "搭配：“受邀”的对象是人，经济不能“受邀于”市场。"}, {"text": "受制于", "is_correct": true, "explanation": "正确：“这个国家的经济受制于外国市场”表示经济受外国市场的影响和约束，与语境一致。"}, {"text": "受雇于", "is_correct": false, "explanation": "搭配：“受雇于”指被人或单位雇用，经济不能被市场雇用。"}, {"text": "受聘于", "is_correct": false, "explanation": "搭配：“受聘于”指被单位聘请任职，主语应是人，不能是“经济”。"}], "explanations": {"受邀于": "搭配：“受邀”的对象是人，经济不能“受邀于”市场。", "受制于": "正确：“这个国家的经济受制于外国市场”表示经济受外国市场的影响和约束，与语境一致。", "受雇于": "搭配：“受雇于”指被人或单位雇用，经济不能被市场雇用。", "受聘于": "搭配：“受聘于”指被单位聘请任职，主语应是人，不能是“经济”。"}, "sentence_index": 6, "correct_answer": "受制于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们受制于老师的鼓励，成绩进步得很快。", "explanation": "这里应该用〈受鼓舞〉。受制于表示被约束，含消极意思；老师的鼓励是正面的激励，应说〈受鼓舞〉。"}, {"text": "我受制于他的帮助，作业很快就完成了。", "explanation": "这里应该用〈受惠于〉。受制于表示被约束，含消极意思；“他的帮助”带来的是好处，应说〈受惠于〉。"}, {"text": "他受制于一块蛋糕，高兴得跳了起来。", "explanation": "这里应该用〈吃到〉。受制于表示被人或条件约束，“一块蛋糕”不能约束人，搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区的农民长期被受制于天气。", "corrected_sentence": "这个地区的农民长期受制于天气。", "error_description": "错误在于多加了“被”。“受制于”本身已有被动的意思，前面不能再加“被”，应说“长期受制于天气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市的交通受制于了天气，常常很拥挤。", "corrected_sentence": "这座城市的交通受制于天气，常常很拥挤。", "error_description": "错误在于“于”后面加了“了”。“受制于”是一个整体结构，“于”后直接接宾语，正确说法是“受制于天气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
