INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10115, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "记录语言的书写符号系统，是中文的基本单位。", "primary_collocate": null, "pronunciation": "hàn zì", "ipa": "xan˥˩ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "它们用汉字或符号记录指法和音位，适合传统乐器。", "target_word": "汉字", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "然而，受制于汉字数量庞大、排版复杂以及社会结构的限制，这一技术未能引发大规模的知识普及浪潮。", "target_word": "汉字", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "汉字是中国人用了几千年的文字。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个汉字都有自己的读音和意思。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汉字的笔画很多，外国学生觉得难写。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汉字从图画慢慢变成了今天的样子。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日本人今天仍然在用汉字。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汉字可以表示意思，也能表示声音。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学汉字要先学笔画，再学部件。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的汉字和今天的汉字不太一样。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "漢字", "label": "繁体"}, {"form": "常用汉字", "label": "复合"}], "register": "中性", "sense_fingerprint": "记录汉语的文字系统及其基本单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859509cb-ef91-48f7-818c-847e5d1c3de5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10115, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汉字", "is_correct": true, "explanation": "正确。「汉字」是记录语言的书写符号，可以用来记录指法和音位。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」不是记录用的符号，不能用来记录指法和音位。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：「汽油」是燃料，不是符号，不能用来记录指法和音位。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：「脚印」是脚踩出的痕迹，不能用来记录指法和音位。"}], "explanations": {"汉字": "正确。「汉字」是记录语言的书写符号，可以用来记录指法和音位。", "桌子": "语义：「桌子」不是记录用的符号，不能用来记录指法和音位。", "汽油": "语义：「汽油」是燃料，不是符号，不能用来记录指法和音位。", "脚印": "语义：「脚印」是脚踩出的痕迹，不能用来记录指法和音位。"}, "sentence_index": 0, "correct_answer": "汉字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汉字的阴性和阳性很难记，外国人常常记错。", "explanation": "这里应该用〈德语〉。阴性、阳性是德语等语言名词的语法性别，汉字是书写符号，没有性别之分。"}, {"text": "汉字的格变化很多，外国人很难记。", "explanation": "这里应该用〈俄语〉。格变化是俄语等语言中名词的语法形式，汉字是书写符号，不存在格变化。"}, {"text": "汉字的时态变化很多，外国人很难学。", "explanation": "这里应该用〈英语〉。时态是英语动词的变化，汉字是书写符号，没有时态，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汉字", "is_correct": true, "explanation": "正确。日本人在书写中仍然使用汉字，与「仍然在用」一致。"}, {"text": "空气", "is_correct": false, "explanation": "语义：「空气」不是可以使用的书写材料，句子不通。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：「用」后接工具，「微笑」不能作工具，与「在用」搭配不通。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：「眼泪」不是文字或符号，句子说的是使用文字。"}], "explanations": {"汉字": "正确。日本人在书写中仍然使用汉字，与「仍然在用」一致。", "空气": "语义：「空气」不是可以使用的书写材料，句子不通。", "微笑": "搭配：「用」后接工具，「微笑」不能作工具，与「在用」搭配不通。", "眼泪": "语义：「眼泪」不是文字或符号，句子说的是使用文字。"}, "sentence_index": 6, "correct_answer": "汉字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个电话号码里有一个汉字。", "explanation": "这里应该用〈数字〉。电话号码由数字组成，汉字是写和读的符号，号码里不会有汉字。"}, {"text": "一个完整的汉字要有主语和谓语。", "explanation": "这里应该用〈句子〉。汉字是单个文字，没有主语和谓语，讲主语和谓语要说句子。"}, {"text": "这句话写完了，最后要加一个汉字，比如句号。", "explanation": "这里应该用〈标点〉。句号是标点符号，不是汉字；句末加的是标点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师教我们写一本新汉字。", "corrected_sentence": "老师教我们写一个新汉字。", "error_description": "错误形式：「一本汉字」；正确形式：「一个汉字」。「本」用于书籍、本子，汉字是一个一个的字，应该用量词「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个汉字他写很清楚。", "corrected_sentence": "这个汉字他写得很清楚。", "error_description": "错误形式：「写很清楚」；正确形式：「写得很清楚」。动词和程度补语之间要用「得」连接，去掉「得」就不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10117, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微小", "is_correct": true, "explanation": "正确答案。“微小”与“庞大”在体积、规模上意思相反，是反义词。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”指不费力或心情愉快，与“庞大”没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”形容温度或感受，与“庞大”不构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、清晰，与“庞大”的体积、规模义无关。"}], "correct_answer": "微小", "explanations": {"微小": "正确答案。“微小”与“庞大”在体积、规模上意思相反，是反义词。", "轻松": "“轻松”指不费力或心情愉快，与“庞大”没有反义关系。", "温暖": "“温暖”形容温度或感受，与“庞大”不构成反义。", "清楚": "“清楚”形容明白、清晰，与“庞大”的体积、规模义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10117, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微小", "is_correct": true, "explanation": "正确答案。“微小”与“庞大”在体积、规模上意思相反，是反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜明，与“庞大”没有反义关系。"}, {"text": "温和", "is_correct": false, "explanation": "“温和”形容性情或气候平和，与“庞大”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度快，与“庞大”的体积、规模义无关。"}], "correct_answer": "微小", "explanations": {"微小": "正确答案。“微小”与“庞大”在体积、规模上意思相反，是反义词。", "明亮": "“明亮”形容光线充足或颜色鲜明，与“庞大”没有反义关系。", "温和": "“温和”形容性情或气候平和，与“庞大”没有反义关系。", "迅速": "“迅速”形容速度快，与“庞大”的体积、规模义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10117, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容体积、规模、数量、力量等非常大，超过一般水平。", "primary_collocate": null, "pronunciation": "páng dà", "ipa": "pʰɑŋ˧˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "然而，受制于汉字数量庞大、排版复杂以及社会结构的限制，这一技术未能引发大规模的知识普及浪潮。", "target_word": "庞大", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个城市的人口非常庞大。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们有一支庞大的队伍。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的规模很庞大。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修这座桥需要庞大的费用。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都有庞大的工作量。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家族很庞大，过年时来了五十多人。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要整理庞大的资料。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有庞大的人口和市场。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划的费用十分庞大。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容体积、规模、数量等大得超过一般水平", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e884783-3d98-4d71-90bb-6a5b56992bcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "庞大", "is_correct": true, "explanation": "正确答案。“汉字数量庞大”指数量非常大，符合“受制于”的语境。"}, {"text": "简单", "is_correct": false, "explanation": "语义：“简单”不用于形容数量，与“受制于……的限制”的语境逻辑相反。"}, {"text": "清晰", "is_correct": false, "explanation": "语义：“清晰”形容清楚可辨，不能描述数量，与句中的限制逻辑不合。"}, {"text": "亲切", "is_correct": false, "explanation": "语义：“亲切”形容态度或感觉，与数量无关。"}], "explanations": {"庞大": "正确答案。“汉字数量庞大”指数量非常大，符合“受制于”的语境。", "简单": "语义：“简单”不用于形容数量，与“受制于……的限制”的语境逻辑相反。", "清晰": "语义：“清晰”形容清楚可辨，不能描述数量，与句中的限制逻辑不合。", "亲切": "语义：“亲切”形容态度或感觉，与数量无关。"}, "sentence_index": 0, "correct_answer": "庞大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的颜色很庞大，看着让人发晕。", "explanation": "这里应该用〈鲜艳〉。庞大只形容体积、规模或数量，不能形容颜色，颜色浓艳应说“鲜艳”。"}, {"text": "他的性格很庞大，朋友们都很喜欢他。", "explanation": "庞大只形容体积、规模或数量，不能形容性格，形容性格要用“开朗”之类的词。"}, {"text": "这门课的学习时间很庞大，我每天都要学两个小时。", "explanation": "庞大不形容时间的长短，时间长要说“漫长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庞大", "is_correct": true, "explanation": "正确答案。“这个家族很庞大”指人口多，与“过年来了五十多人”相符。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指没有人、不热闹，与“过年时来了五十多人”矛盾。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：“精致”多形容物件，不说“家族精致”。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”指数量很少，与“来了五十多人”矛盾。"}], "explanations": {"庞大": "正确答案。“这个家族很庞大”指人口多，与“过年来了五十多人”相符。", "冷清": "语义：“冷清”指没有人、不热闹，与“过年时来了五十多人”矛盾。", "精致": "搭配：“精致”多形容物件，不说“家族精致”。", "稀少": "语义：“稀少”指数量很少，与“来了五十多人”矛盾。"}, "sentence_index": 6, "correct_answer": "庞大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车跑得很庞大，一下子就到了终点。", "explanation": "庞大不形容速度，速度快要说“飞快”。"}, {"text": "今天的温度很庞大，我们都热得受不了。", "explanation": "庞大不形容温度，温度高要说“高”或“炎热”。"}, {"text": "这碗汤的味道很庞大，喝一口就想吐。", "explanation": "庞大不形容味道，味道浓要说“浓”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市有一座庞大地图书馆。", "corrected_sentence": "这座城市有一座庞大的图书馆。", "error_description": "错误：“庞大地图书馆”。正确：“庞大的图书馆”。“地”用于修饰动词，修饰名词的定语要用“的”，此处误用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划的费用是庞大，我们得找投资。", "corrected_sentence": "这个计划的费用很庞大，我们得找投资。", "error_description": "错误：“是庞大”。正确：“很庞大”。形容词作谓语前应用程度副词“很”，不用“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
