INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10124, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻像潮水一样接连不断、声势浩大的社会运动或发展趋势。", "primary_collocate": null, "pronunciation": "làng cháo", "ipa": "lɑŋ˥˩ tʂʰɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "倘若此趋势持续，2026年或将见证一场静默的认知民主化浪潮——个体不再被算法凝视，而是通过可信赖的代理，主动参与数字身份的建构与协商。", "target_word": "浪潮", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "然而，受制于汉字数量庞大、排版复杂以及社会结构的限制，这一技术未能引发大规模的知识普及浪潮。", "target_word": "浪潮", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "新技术带来了一波学习浪潮。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这股读书浪潮影响了很多年轻人。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络购物的浪潮来得很快。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想跟上时代的浪潮。", "target_word": "浪潮", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "环保浪潮让更多人少用塑料袋。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "十年前，创业浪潮席卷了这座城市。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场改革浪潮改变了许多人的生活。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人都加入了出国留学的浪潮。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一波浪潮", "label": "量词"}, {"form": "一股浪潮", "label": "量词"}], "register": "书面", "sense_fingerprint": "浪潮：比喻接连不断、声势浩大的社会运动或发展趋势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ff47f7-e50e-4937-9c6f-4d98586d83d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪潮", "is_correct": true, "explanation": "正确答案。“一场……认知民主化浪潮”指声势浩大、接连不断的社会发展趋势。"}, {"text": "池塘", "is_correct": false, "explanation": "语义：池塘是静止的水域，与“民主化”这种动态的社会趋势不相称。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“一场”不修饰河流，河流也不指社会运动。"}, {"text": "台阶", "is_correct": false, "explanation": "语义：台阶是具体的建筑构件，不能指社会运动。"}], "explanations": {"浪潮": "正确答案。“一场……认知民主化浪潮”指声势浩大、接连不断的社会发展趋势。", "池塘": "语义：池塘是静止的水域，与“民主化”这种动态的社会趋势不相称。", "河流": "搭配：“一场”不修饰河流，河流也不指社会运动。", "台阶": "语义：台阶是具体的建筑构件，不能指社会运动。"}, "sentence_index": 0, "correct_answer": "浪潮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这股浪潮一动不动，好像被冻住了。", "explanation": "这里表示停滞，应该用〈停滞〉。“浪潮”指接连不断的运动，不指静止的状态。"}, {"text": "今年夏天，游客数量达到了浪潮。", "explanation": "这里应该用〈高峰〉。“浪潮”指社会趋势，数量达到顶点要用高峰，不说达到浪潮。"}, {"text": "他在课堂上掀起了一股浪潮，老师只好让他坐下。", "explanation": "这里表示闹腾，应该用〈捣乱〉。“浪潮”指社会趋势，不指课堂上的闹事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪潮", "is_correct": true, "explanation": "正确答案。“环保浪潮”指声势较大的环保运动，能让更多人少用塑料袋。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾不能让人少用塑料袋，与后文的意思不相容。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不能促使人改变消费习惯，与后文不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“环保”多修饰理念、运动，不说“环保石头”。"}], "explanations": {"浪潮": "正确答案。“环保浪潮”指声势较大的环保运动，能让更多人少用塑料袋。", "围巾": "语义：围巾不能让人少用塑料袋，与后文的意思不相容。", "闹钟": "语义：闹钟不能促使人改变消费习惯，与后文不符。", "石头": "搭配：“环保”多修饰理念、运动，不说“环保石头”。"}, "sentence_index": 6, "correct_answer": "浪潮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场演唱会的浪潮是最后一首歌。", "explanation": "这里应该用〈高潮〉。“浪潮”指接连不断的社会运动，不指演出最精彩的部分。"}, {"text": "这股浪潮的规模很小，只能算是一小滴水。", "explanation": "这里应该用〈涓流〉。“浪潮”指声势浩大的趋势，“规模很小”与其含义相反。"}, {"text": "他刚才打了一个大浪潮，把大家都吵醒了。", "explanation": "这里应该用〈喷嚏〉。“浪潮”指接连不断的社会运动，不能指人一下子发出的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一根新的网络浪潮席卷了全国。", "corrected_sentence": "一股新的网络浪潮席卷了全国。", "error_description": "“浪潮”的量词应用“股”或“波”，不能用“根”（细长物量词）计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场运动打起了一股学习浪潮。", "corrected_sentence": "这场运动掀起了一股学习浪潮。", "error_description": "“掀起浪潮”是固定搭配。“打起”不能与“浪潮”搭配，应说“掀起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10128, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10128, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10128, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指具有重大意义、能够对后续发展产生深远影响的性质或事件。", "primary_collocate": null, "pronunciation": "lì shǐ xìng", "ipa": "li˥˩ ʂɻ̩˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "真正将印刷术推向历史性变革的，是十五世纪中叶德意志地区的一位工匠——古腾堡。", "target_word": "历史性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这是一次历史性的会议，大家都很激动。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登上月球是人类历史性的一步。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是历史性的一天，我们终于成功了。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项历史性的决定影响了很多年。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国领导人举行了历史性的握手。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的建成具有历史性意义。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍下了那个历史性的瞬间。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛是一场历史性的胜利。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改革开放是中国历史性的转折。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷史性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "具有重大意义并影响后续发展的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e884783-3d98-4d71-90bb-6a5b56992bcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史性", "is_correct": true, "explanation": "正确：“历史性变革”指具有重大意义、影响深远的变革，与“真正”的语气一致。"}, {"text": "季节性", "is_correct": false, "explanation": "语义：“季节性”指按季节周期出现，与影响世纪发展的变革意义不符。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：“偶然性”指意外发生，与句中“真正”和“推向变革”的重大意义相反。"}, {"text": "老式", "is_correct": false, "explanation": "搭配：“老式”说事物的样式，不修饰“变革”这类影响历史的事件。"}], "explanations": {"历史性": "正确：“历史性变革”指具有重大意义、影响深远的变革，与“真正”的语气一致。", "季节性": "语义：“季节性”指按季节周期出现，与影响世纪发展的变革意义不符。", "偶然性": "语义：“偶然性”指意外发生，与句中“真正”和“推向变革”的重大意义相反。", "老式": "搭配：“老式”说事物的样式，不修饰“变革”这类影响历史的事件。"}, "sentence_index": 0, "correct_answer": "历史性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一顿历史性的午饭，吃完很快就忘了。", "explanation": "这里应该用〈平淡〉。历史性指具有重大意义，吃完就忘的午饭不具有这种性质，应说平淡。"}, {"text": "我午饭吃了一碗历史性的面条，跟平时一样。", "explanation": "这里应该用〈平常〉。历史性指具有重大意义，跟平时一样的面条应说平常。"}, {"text": "这次失败是一件历史性的小事。", "explanation": "这里应该用〈平凡〉。历史性指具有重大意义，不能用于形容这种微不足道的事情，此处应说平凡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史性", "is_correct": true, "explanation": "正确：“具有历史性意义”指这座桥的建成对历史有重大影响。"}, {"text": "短暂性", "is_correct": false, "explanation": "语义：“短暂性”指持续时间很短，与桥梁建成的长远意义相反。"}, {"text": "临时性", "is_correct": false, "explanation": "语义：“临时性”指暂时存在，与桥梁的长期作用不符。"}, {"text": "手工性", "is_correct": false, "explanation": "搭配：“手工性”描述制作方式，不能用来修饰“意义”。"}], "explanations": {"历史性": "正确：“具有历史性意义”指这座桥的建成对历史有重大影响。", "短暂性": "语义：“短暂性”指持续时间很短，与桥梁建成的长远意义相反。", "临时性": "语义：“临时性”指暂时存在，与桥梁的长期作用不符。", "手工性": "搭配：“手工性”描述制作方式，不能用来修饰“意义”。"}, "sentence_index": 6, "correct_answer": "历史性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天穿了一双历史性的袜子，是超市买的。", "explanation": "这里应该用〈普通〉。历史性指具有重大意义，形容超市买的袜子这类日常物品应说普通。"}, {"text": "老师上课时露出了历史性的表情，让学生安静下来。", "explanation": "这里应该用〈严肃〉。历史性指具有重大意义的事件或时刻，形容让学生安静的表情应说严肃。"}, {"text": "这次散步是一件历史性的琐事，走了十分钟就回家了。", "explanation": "这里应该用〈琐碎〉。历史性指具有重大意义，十分钟的散步微不足道，应说琐碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次通车是历史性地时刻。", "corrected_sentence": "这次通车是历史性的时刻。", "error_description": "错误形式是“历史性地时刻”，“地”是只修饰动词的副词后缀，不能用在名词“时刻”前。正确形式是“历史性的时刻”，“的”用来修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次航行在海洋史上历史性意义。", "corrected_sentence": "这次航行在海洋史上具有历史性意义。", "error_description": "错误形式是缺少动词“具有”，句子不完整。正确形式是“具有历史性意义”。“历史性意义”需要动词来带出，不能直接接在处所短语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
