INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指有专门手艺、技术熟练的工人。", "primary_collocate": null, "pronunciation": "gōng jiàng", "ipa": "kʊŋ˥ tɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "真正将印刷术推向历史性变革的，是十五世纪中叶德意志地区的一位工匠——古腾堡。", "target_word": "工匠", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位老工匠做的木椅非常结实。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工匠花了三天才修好这把锁。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，工匠靠手艺养活全家。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位工匠正在认真地雕刻石像。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工匠们把老房子修得很漂亮。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲是一位有名的陶瓷工匠。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好工匠从不会随便做东西。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工匠用铜做了一只小鸟。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻工匠向师傅学习怎么打铁。", "target_word": "工匠", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "工匠精神", "label": "复合词"}], "register": "中性", "sense_fingerprint": "有专门手艺、技术熟练的工人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e884783-3d98-4d71-90bb-6a5b56992bcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工匠", "is_correct": true, "explanation": "正确。“工匠”指有专门手艺、技术熟练的工人，与古腾堡制作印刷机和金属活字的身份相符。"}, {"text": "士兵", "is_correct": false, "explanation": "语义：士兵以作战为职业，与句中“推向历史性变革”的印刷术毫无关系。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师以烹饪为职业，与古腾堡改进印刷术的身份不符。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民从事农业生产，无法解释他在印刷术变革中的身份。"}], "explanations": {"工匠": "正确。“工匠”指有专门手艺、技术熟练的工人，与古腾堡制作印刷机和金属活字的身份相符。", "士兵": "语义：士兵以作战为职业，与句中“推向历史性变革”的印刷术毫无关系。", "厨师": "语义：厨师以烹饪为职业，与古腾堡改进印刷术的身份不符。", "农民": "语义：农民从事农业生产，无法解释他在印刷术变革中的身份。"}, "sentence_index": 0, "correct_answer": "工匠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位工匠每天在医院为病人做手术。", "explanation": "这里应该用〈医生〉。工匠指凭专门手艺做东西的人，为病人做手术要用医生。"}, {"text": "这位工匠在法庭上为被告辩护。", "explanation": "这里应该用〈律师〉。工匠指凭专门手艺做东西的人，在法庭上为被告辩护要用律师。"}, {"text": "这位工匠研究古代文字，写了三十年论文。", "explanation": "这里应该用〈学者〉。工匠指手艺人，不指做学术研究的人，研究和写论文要用“学者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工匠", "is_correct": true, "explanation": "正确。“工匠”指有专门手艺的工人，与“陶瓷”制作的手艺相符。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“陶瓷”修饰的是手艺或器物，不能修饰厨师，“陶瓷厨师”说不通。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手以唱歌为职业，与陶瓷制作毫无关联。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机以驾驶为职业，无法说明他在陶瓷方面的专长。"}], "explanations": {"工匠": "正确。“工匠”指有专门手艺的工人，与“陶瓷”制作的手艺相符。", "厨师": "搭配：“陶瓷”修饰的是手艺或器物，不能修饰厨师，“陶瓷厨师”说不通。", "歌手": "语义：歌手以唱歌为职业，与陶瓷制作毫无关联。", "司机": "语义：司机以驾驶为职业，无法说明他在陶瓷方面的专长。"}, "sentence_index": 6, "correct_answer": "工匠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位工匠在舞台上演了一出戏。", "explanation": "这里应该用〈演员〉。工匠指凭专门手艺做东西的人，在舞台上表演要用演员。"}, {"text": "这位工匠每天开车送客人。", "explanation": "这里应该用〈司机〉。工匠指凭专门手艺做东西的人，开车送客要用司机。"}, {"text": "这位工匠写了一本小说。", "explanation": "这里应该用〈作家〉。工匠指凭专门手艺做东西的人，写书创作要用作家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只工匠修好了我的旧钟表。", "corrected_sentence": "那位工匠修好了我的旧钟表。", "error_description": "量词错误。工匠指人，应说“那位工匠”；“那只”多用于动物或器物，错误的是量词“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老工匠的修好了旧椅子。", "corrected_sentence": "老工匠修好了旧椅子。", "error_description": "错误形式是“老工匠的修好了旧椅子”，“的”加在主语“工匠”后，使主语变成名词性短语，动词无法作谓语。正确形式是“老工匠修好了旧椅子”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
