INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10133, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去掉事物中的缺点，使之更完善。", "primary_collocate": null, "pronunciation": "gǎi liáng", "ipa": "kai̯˨˩˦ liɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他所改良的金属活字印刷系统，结合了螺旋压印机、油性墨水与精确铸造技术，实现了文字复制的标准化与高效率生产。", "target_word": "改良", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其次，所得有机肥用于家庭园艺，可改良土壤团粒结构，提升保水保肥能力，减少对化学肥料的依赖，形成“厨房—土壤—餐桌”的营养回路。", "target_word": "改良", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民改良了这里的土壤。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师想改良这台旧机器。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把旧品种改良成了新品种。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水稻是专家改良过的。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让茶更好喝，他改良了做法。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在改良产品的包装。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该先改良这块盐碱地。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李教授改良过很多种花。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改良了", "label": "体标（了）"}, {"form": "改良过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "去掉事物的缺点，使之更完善（土壤、品种、技术、工艺）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a854fec-be2f-4f93-bb5b-d6f5ac612a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10133, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改良", "is_correct": true, "explanation": "“改良”指去掉缺点、使之更完善，与“结合已有技术、实现高效率生产”的语境相符。"}, {"text": "废弃", "is_correct": false, "explanation": "语义：“废弃”指抛弃不用，与句中“实现了高效率生产”的结果相矛盾。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉，系统被拆掉后无法结合技术并投入生产。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”指弄坏，与句中“结合多项技术、实现高效率生产”的结果相矛盾。"}], "explanations": {"改良": "“改良”指去掉缺点、使之更完善，与“结合已有技术、实现高效率生产”的语境相符。", "废弃": "语义：“废弃”指抛弃不用，与句中“实现了高效率生产”的结果相矛盾。", "拆除": "语义：“拆除”指拆掉，系统被拆掉后无法结合技术并投入生产。", "破坏": "语义：“破坏”指弄坏，与句中“结合多项技术、实现高效率生产”的结果相矛盾。"}, "sentence_index": 0, "correct_answer": "改良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他改良了作业里的错误。", "explanation": "这里应该用〈改正〉。“改良”指把事物变得更完善，错误要用“改正”。"}, {"text": "他的病情改良了很多。", "explanation": "这里应该用〈改善〉。“改良”多用于土壤、品种、工艺等事物，病情要用“改善”。"}, {"text": "今年的产量改良了很多。", "explanation": "这里应该用〈提高〉。“改良”指改进事物的质量，产量这类数量要用“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10133, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改良", "is_correct": true, "explanation": "“改良”指改进做法使之更好，与“为了让茶更好喝”的目的一致。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”指弄坏，与“为了让茶更好喝”的目的正好相反。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”是遗忘，与“为了让茶更好喝”而有意作出的改动不符。"}, {"text": "美化", "is_correct": false, "explanation": "搭配：“美化”多用于环境、形象，不直接用于“做法”。"}], "explanations": {"改良": "“改良”指改进做法使之更好，与“为了让茶更好喝”的目的一致。", "破坏": "语义：“破坏”指弄坏，与“为了让茶更好喝”的目的正好相反。", "忘记": "语义：“忘记”是遗忘，与“为了让茶更好喝”而有意作出的改动不符。", "美化": "搭配：“美化”多用于环境、形象，不直接用于“做法”。"}, "sentence_index": 6, "correct_answer": "改良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的人口改良了很多。", "explanation": "这里应该用〈增加〉。“改良”指改进事物的质量，人口这类数量要用“增加”。"}, {"text": "政府改良了环境污染。", "explanation": "这里应该用〈治理〉。“改良”用于使事物更完善，污染这类问题要用“治理”。"}, {"text": "我们终于改良了这个误会。", "explanation": "这里应该用〈消除〉。“改良”是使事物更完善，误会要用“消除”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地已经改良了过。", "corrected_sentence": "这块地已经改良过了。", "error_description": "错误：体标“过”与“了”的顺序颠倒（改良了过）。正确：“改良过了”，“过”紧跟动词表示经历，“了”置于其后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器改良很好。", "corrected_sentence": "这台机器改良得很好。", "error_description": "错误：缺少补语标志“得”（改良很好）。正确：“改良得很好”，“得”引出对“改良”结果的补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
