INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "像螺壳表面那样一圈圈弯曲的线条或形状。", "primary_collocate": null, "pronunciation": "luó xuán", "ipa": "lwɔ˧˥ ɕɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "师傅在木棍上刻出了一道精细的螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风把落叶卷成了一个螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海螺壳上有一道漂亮的螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流在洞口转成了一个螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在空中慢慢画出一个大螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜗牛壳的螺旋越往里越小。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫把毛线绕成了一个螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里有一道白色的螺旋，像星系。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上画了一个螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟顺着风变成了一条螺旋。", "target_word": "螺旋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "螺旋桨", "label": "复合词"}], "register": "中性", "sense_fingerprint": "像螺壳一圈圈弯曲的线条或形状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e884783-3d98-4d71-90bb-6a5b56992bcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10136, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "螺旋", "is_correct": true, "explanation": "正确。“螺旋”指一圈圈弯曲的形状，与“刻出一道精细的”所修饰的线条相符。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：“一道精细的”修饰线条或图案，玻璃是材料，句意不通。"}, {"text": "木材", "is_correct": false, "explanation": "语义：“一道精细的”修饰线条或图案，木材是材料，句意不通。"}, {"text": "太阳能", "is_correct": false, "explanation": "语义：太阳能是能源，不是可以刻在木棍上的线条，句意不通。"}], "explanations": {"螺旋": "正确。“螺旋”指一圈圈弯曲的形状，与“刻出一道精细的”所修饰的线条相符。", "玻璃": "语义：“一道精细的”修饰线条或图案，玻璃是材料，句意不通。", "木材": "语义：“一道精细的”修饰线条或图案，木材是材料，句意不通。", "太阳能": "语义：太阳能是能源，不是可以刻在木棍上的线条，句意不通。"}, "sentence_index": 0, "correct_answer": "螺旋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人群中间形成了一个螺旋。", "explanation": "这里应该用〈漩涡〉。螺旋指一圈圈弯曲的形状，人群乱涌形成的回旋要说“漩涡”。"}, {"text": "这个班的螺旋有二十个人。", "explanation": "这里应该用〈人数〉。螺旋指盘绕的形状，不能用来说班级的人数，应说“人数”。"}, {"text": "这台机器的螺旋很快。", "explanation": "这里应该用〈转速〉。螺旋指盘绕的形状，不能用来说转动的快慢，机器转得快要说“转速”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "螺旋", "is_correct": true, "explanation": "正确。“螺旋”指一圈圈弯曲的形状，与“绕成”的动作相符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：毛线不能绕成蛋糕，蛋糕是食物，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是坚硬的固体，不能由毛线绕成。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见摸不着，毛线不能绕成声音。"}], "explanations": {"螺旋": "正确。“螺旋”指一圈圈弯曲的形状，与“绕成”的动作相符。", "蛋糕": "语义：毛线不能绕成蛋糕，蛋糕是食物，句意不通。", "石头": "语义：石头是坚硬的固体，不能由毛线绕成。", "声音": "语义：声音看不见摸不着，毛线不能绕成声音。"}, "sentence_index": 6, "correct_answer": "螺旋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人拧紧了一颗螺旋。", "explanation": "这里应该用〈螺丝〉。螺旋指盘绕的形状，拧紧的是螺丝这个零件，不能用“螺旋”。"}, {"text": "这道题的螺旋很难。", "explanation": "这里应该用〈难度〉。螺旋指盘绕的形状，题目的难易程度要说“难度”。"}, {"text": "天空中飞着一只螺旋。", "explanation": "这里应该用〈老鹰〉。螺旋指盘绕的形状，不是会飞的动物，天上飞的是老鹰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "纸上画着一张螺旋。", "corrected_sentence": "纸上画着一道螺旋。", "error_description": "量词错误。螺旋是线状的图形，应说“一道螺旋”；“张”多用于纸、桌子等平面物，错误的是量词“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "气流把碎纸卷了成螺旋。", "corrected_sentence": "气流把碎纸卷成了螺旋。", "error_description": "补语位置错误。“卷成”是动补结构，应说“卷成了”；“卷了成”把补语拆开，语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
