INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10137, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过施加压力使物体表面留下痕迹或图案。", "primary_collocate": null, "pronunciation": "yā yìn", "ipa": "ia˥ in˥˩", "syllable_count": 2, "sentences": [{"text": "工厂为了方便追踪，会用模具在每个零件表面压印序列号。", "target_word": "压印", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "工人用机器在皮包上压印公司的名字。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅在软软的蜡上压印了一个图案。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店会在每块皮革上压印品牌标志。", "target_word": "压印", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的名字压印在笔记本的封面上。", "target_word": "压印", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用钢模给铜板压印花纹。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在这张纸的右下角压印日期。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们在黏土上压印叶子的形状。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种机器能在金属片上压印很细的字。", "target_word": "压印", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子的底部压印着制造年份。", "target_word": "压印", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "压印了", "label": "完成体"}, {"form": "压印着", "label": "持续体"}, {"form": "压印过", "label": "经历体"}, {"form": "压印机", "label": "复合词"}, {"form": "壓印", "label": "繁体"}], "register": "中性", "sense_fingerprint": "压印|动词|施加压力使物体表面留下痕迹或图案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba171e17-0e71-47fc-bc45-dc66a5f33e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10137, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "压印", "is_correct": true, "explanation": "压印 yā yìn，指用压力在物体表面留下印记。"}, {"text": "牙印", "is_correct": false, "explanation": "yá（第二声）与 yā（第一声）声调不同，牙印意思是牙齿咬出的印子。"}, {"text": "押韵", "is_correct": false, "explanation": "yùn 与 yìn 韵母不同（u 与 i），押韵意思是诗句末尾韵母相同。"}, {"text": "压抑", "is_correct": false, "explanation": "压抑 yāyì 比 压印 yāyìn 少了韵尾 n，意思是压制、抑制。"}], "explanations": {"压印": "压印 yā yìn，指用压力在物体表面留下印记。", "牙印": "yá（第二声）与 yā（第一声）声调不同，牙印意思是牙齿咬出的印子。", "押韵": "yùn 与 yìn 韵母不同（u 与 i），押韵意思是诗句末尾韵母相同。", "压抑": "压抑 yāyì 比 压印 yāyìn 少了韵尾 n，意思是压制、抑制。"}, "sentence_index": null, "correct_answer": "压印"}, "level_3": {"options": [{"text": "压印", "is_correct": true, "explanation": "压印：用模具按压在零件表面留下印记，与序列号的标记语境相符。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：烘烤是用热力加工食物，不能在零件表面留下序列号。"}, {"text": "研磨", "is_correct": false, "explanation": "语义：研磨是把东西磨碎或磨平，与留下序列号的动作不符。"}, {"text": "蒸煮", "is_correct": false, "explanation": "搭配：蒸煮的对象多是食物，不能用来在零件表面留下号码。"}], "explanations": {"压印": "压印：用模具按压在零件表面留下印记，与序列号的标记语境相符。", "烘烤": "语义：烘烤是用热力加工食物，不能在零件表面留下序列号。", "研磨": "语义：研磨是把东西磨碎或磨平，与留下序列号的动作不符。", "蒸煮": "搭配：蒸煮的对象多是食物，不能用来在零件表面留下号码。"}, "sentence_index": 0, "correct_answer": "压印"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用音乐压印自己的心情。", "explanation": "这里应该用〈表达〉。压印指用压力在具体物体表面留下痕迹，心情是抽象的，不能被压印。"}, {"text": "他把垃圾压印进了桶里。", "explanation": "这里应该用〈扔〉。压印是靠压力留下印记，不是把东西投进容器。"}, {"text": "他用湿布压印了一下桌子。", "explanation": "这里应该用〈擦〉。擦是用布摩擦去除污渍，压印是按压留下印记，两者动作不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压印", "is_correct": true, "explanation": "压印：在纸上用压力留下日期的印记，与“右下角”的位置相符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是擦拭，不能在纸上留下日期。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：煮的对象是食物，不能带“日期”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发声，与在纸上做标记无关。"}], "explanations": {"压印": "压印：在纸上用压力留下日期的印记，与“右下角”的位置相符。", "擦": "语义：擦是擦拭，不能在纸上留下日期。", "煮": "搭配：煮的对象是食物，不能带“日期”作宾语。", "唱": "语义：唱是发声，与在纸上做标记无关。"}, "sentence_index": 6, "correct_answer": "压印"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用剪刀压印了一张纸。", "explanation": "这里应该用〈剪〉。剪是用刀具切断，压印是用模具按压留下印记，不能用剪刀压印。"}, {"text": "他在墙上压印了一层白色的油漆。", "explanation": "这里应该用〈涂〉。涂是把颜料铺在表面，油漆是液体，不能靠压力压印。"}, {"text": "他用洗衣机压印了衣服。", "explanation": "这里应该用〈洗〉。洗是清除污渍，压印是留下印记，两者不是同一动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人在皮带上压印了一只生产日期。", "corrected_sentence": "工人在皮带上压印了一个生产日期。", "error_description": "量词错误：“日期”应搭配“个”，“只”用于动物等，应改为“压印了一个生产日期”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机器把生产批号压印给每个盒子的底部。", "corrected_sentence": "机器把生产批号压印在每个盒子的底部。", "error_description": "介词错误：“压印”后引出处所应用“在”，“给”不能用于此处，应为“压印在每个盒子的底部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10139, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10139, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10139, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指含有油脂或油分的性质，常用于描述皮肤、头发或物品的含油程度。", "primary_collocate": null, "pronunciation": "yóu xìng", "ipa": "iou˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他所改良的金属活字印刷系统，结合了螺旋压印机、油性墨水与精确铸造技术，实现了文字复制的标准化与高效率生产。", "target_word": "油性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我的皮肤是油性的，夏天特别容易出油。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油性头发要经常洗，不然会很油。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支油性笔写的字，水洗不掉。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油性墨水不怕水，雨天也不会花。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油性皮肤的人最好用清爽的洗面奶。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上的油性漆干了以后很结实。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说我的头皮油性很强，要少吃油炸食品。", "target_word": "油性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面霜太油了，不适合油性皮肤用。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油性颜料画好以后，要很久才会干。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "油性笔", "label": "复合词"}, {"form": "油性漆", "label": "复合词"}], "register": "中性", "sense_fingerprint": "油性|形容词|含有油脂或油分的性质，用于皮肤头发物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba171e17-0e71-47fc-bc45-dc66a5f33e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10139, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "油性", "is_correct": true, "explanation": "油性 yóu xìng，指含有油脂或油分的性质。"}, {"text": "有幸", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，有幸意思是幸运。"}, {"text": "游行", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，游行意思是结队行进。"}, {"text": "有性", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，有性指有性别之分，如“有性生殖”。"}], "explanations": {"油性": "油性 yóu xìng，指含有油脂或油分的性质。", "有幸": "yǒu（第三声）与 yóu（第二声）声调不同，有幸意思是幸运。", "游行": "xíng（第二声）与 xìng（第四声）声调不同，游行意思是结队行进。", "有性": "yǒu（第三声）与 yóu（第二声）声调不同，有性指有性别之分，如“有性生殖”。"}, "sentence_index": null, "correct_answer": "油性"}, "level_3": {"options": [{"text": "油性", "is_correct": true, "explanation": "油性：修饰“墨水”，指以油脂为基的墨水，与印刷语境相符。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：易碎形容易破碎的物体，墨水不能用“易碎”来描述。"}, {"text": "木质", "is_correct": false, "explanation": "搭配：木质描述材料，墨水不能说木质。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻指低温凝固，与墨水的性质无关。"}], "explanations": {"油性": "油性：修饰“墨水”，指以油脂为基的墨水，与印刷语境相符。", "易碎": "语义：易碎形容易破碎的物体，墨水不能用“易碎”来描述。", "木质": "搭配：木质描述材料，墨水不能说木质。", "冷冻": "语义：冷冻指低温凝固，与墨水的性质无关。"}, "sentence_index": 0, "correct_answer": "油性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很油性，让人不太信任。", "explanation": "这里应该用〈油滑〉。油性形容物质含油的性质，形容人说话圆滑要用油滑。"}, {"text": "他的声音很油性，听起来很温柔。", "explanation": "这里应该用〈柔和〉。油性说的是物质含油的性质，不能形容声音；声音轻柔舒缓要用柔和。"}, {"text": "这块玻璃很油性，擦起来很光滑。", "explanation": "这里应该用〈油腻〉。油性说的是物质本身含油的性质，玻璃本身不含油，表面沾了油污才说油腻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10139, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "油性", "is_correct": true, "explanation": "油性：修饰“漆”，指油性漆，干后质地结实，与句意相符。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：柔软与“干了以后很结实”相矛盾。"}, {"text": "湿润", "is_correct": false, "explanation": "语义：湿润的漆尚未干透，不能说干了以后很结实。"}, {"text": "发酵", "is_correct": false, "explanation": "搭配：发酵是微生物作用的过程，不能用来修饰“漆”。"}], "explanations": {"油性": "油性：修饰“漆”，指油性漆，干后质地结实，与句意相符。", "柔软": "语义：柔软与“干了以后很结实”相矛盾。", "湿润": "语义：湿润的漆尚未干透，不能说干了以后很结实。", "发酵": "搭配：发酵是微生物作用的过程，不能用来修饰“漆”。"}, "sentence_index": 6, "correct_answer": "油性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气很油性，大家都不想出门。", "explanation": "这里应该用〈潮湿〉。油性形容含油的物品，不能描述天气。"}, {"text": "这盘炒饭很油性，我吃不下。", "explanation": "这里应该用〈油腻〉。油性多用于皮肤、头发和物品，形容食物油多要用油腻。"}, {"text": "鸟叫声很油性，听起来很清脆。", "explanation": "这里应该用〈悦耳〉。油性只说物质、皮肤、头发等含油的性质，不能形容声音；好听的鸟鸣要说悦耳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的皮肤是油性地，所以不用厚厚的面霜。", "corrected_sentence": "我的皮肤是油性的，所以不用厚厚的面霜。", "error_description": "助词错误：“是……的”结构中应用“的”，不能用“地”（“地”用于修饰动词）。应为“是油性的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的头发是油性着，每天都要洗。", "corrected_sentence": "我的头发是油性的，每天都要洗。", "error_description": "助词错误：“是……的”结构表示性质，句末应用“的”，不能用表示持续的“着”。应为“是油性的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
