INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "墨水是一种含有颜色或染料的液体，用于书写、绘画或打印。", "primary_collocate": null, "pronunciation": "mò shuǐ", "ipa": "mwo˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他所改良的金属活字印刷系统，结合了螺旋压印机、油性墨水与精确铸造技术，实现了文字复制的标准化与高效率生产。", "target_word": "墨水", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我的钢笔没有墨水了，要去买一瓶。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用蓝色墨水写了一封信。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墨水洒在白衬衫上，很难洗干净。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打印机里的墨水用完了，字印不出来。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把红墨水倒进小瓶子里。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶墨水是黑色的，用它画的画很好看。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别把墨水滴到纸上。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手指上沾着蓝色墨水。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了一支钢笔和两瓶墨水。", "target_word": "墨水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶", "label": "量词"}, {"form": "墨水瓶", "label": "复合"}, {"form": "蓝墨水", "label": "复合"}], "register": "中性", "sense_fingerprint": "墨水：书写、绘画、打印用的有色液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba171e17-0e71-47fc-bc45-dc66a5f33e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木炭", "is_correct": false, "explanation": "语义：木炭是燃料，不是可以与螺旋压印机、精确铸造技术并列的印刷材料。"}, {"text": "墨水", "is_correct": true, "explanation": "墨水：油性墨水是印刷用的有色液体，此处指印刷系统所用的油性墨，与前后的印刷技术相符。"}, {"text": "轮胎", "is_correct": false, "explanation": "搭配：“油性”一般修饰墨水、涂料，不能修饰轮胎，说“油性轮胎”不成立。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是金属紧固件，不是有颜色的液体材料，与“油性”不能配合。"}], "explanations": {"木炭": "语义：木炭是燃料，不是可以与螺旋压印机、精确铸造技术并列的印刷材料。", "墨水": "墨水：油性墨水是印刷用的有色液体，此处指印刷系统所用的油性墨，与前后的印刷技术相符。", "轮胎": "搭配：“油性”一般修饰墨水、涂料，不能修饰轮胎，说“油性轮胎”不成立。", "螺丝": "语义：螺丝是金属紧固件，不是有颜色的液体材料，与“油性”不能配合。"}, "sentence_index": 0, "correct_answer": "墨水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用墨水把墙刷了一遍。", "explanation": "这里应该用〈油漆〉。刷墙用的是油漆；墨水是书写、绘画或打印用的液体，不能用来刷墙。"}, {"text": "我给汽车加满了墨水。", "explanation": "这里应该用〈汽油〉。汽车加的是汽油；墨水是书写、绘画或打印用的液体，不能给汽车当燃料。"}, {"text": "我买了一块墨水。", "explanation": "这里应该用〈瓶〉。墨水是液体，按瓶计量；“块”用于块状的东西，不能用来计量墨水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是白色的，与“这瓶……是黑色的”相矛盾。"}, {"text": "墨水", "is_correct": true, "explanation": "墨水：墨水是黑色的有色液体，可以用来画画，前后两个分句都说得通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是用来喝的，不能用来画画，与“用它画的画很好看”不合。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：“瓶”用于盛装液体的物品，木头是固体，不能说“这瓶木头”。"}], "explanations": {"牛奶": "语义：牛奶是白色的，与“这瓶……是黑色的”相矛盾。", "墨水": "墨水：墨水是黑色的有色液体，可以用来画画，前后两个分句都说得通。", "饮料": "语义：饮料是用来喝的，不能用来画画，与“用它画的画很好看”不合。", "木头": "搭配：“瓶”用于盛装液体的物品，木头是固体，不能说“这瓶木头”。"}, "sentence_index": 6, "correct_answer": "墨水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用墨水在砚台上磨了很久。", "explanation": "这里应该用〈墨〉。磨墨磨的是固体的墨条，墨水是液体，不能在砚台上磨。"}, {"text": "我买了两双墨水。", "explanation": "这里应该用〈瓶〉。墨水是液体，按瓶计量；“双”用于成对的东西，不能用于墨水。"}, {"text": "我买了一根墨水。", "explanation": "这里应该用〈瓶〉。墨水是液体，按瓶计量；“根”用于细长的东西，不能用于墨水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了两本墨水。", "corrected_sentence": "他买了两瓶墨水。", "error_description": "错误在于量词：墨水是液体，应用“瓶”计量，“本”用于书册，不能用来数墨水。正确形式是“两瓶墨水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支笔没有墨水着，写不出字。", "corrected_sentence": "这支笔没有墨水了，写不出字。", "error_description": "体标错误：表示情况发生变化（墨水用完）应用句末“了”，“着”表示持续，不能用在这里。正确形式是“没有墨水了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
