INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把金属熔化后倒入模具中，冷却后制成器物。", "primary_collocate": null, "pronunciation": "zhù zào", "ipa": "ʈʂu˥˩ tsaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他所改良的金属活字印刷系统，结合了螺旋压印机、油性墨水与精确铸造技术，实现了文字复制的标准化与高效率生产。", "target_word": "铸造", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工人们用铜铸造了一口大钟。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人会把铁水倒进模具里铸造刀剑。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座铜像是五百年前铸造的。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂正在铸造一批新的铁锅。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铸造时，工人要先把金属熔化。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用金子铸造一个小奖杯。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅铸造的剑又硬又锋利。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的人怎么铸造这么大的鼎？", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铸造铁器需要很高的温度。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "铸造了", "label": "体标"}, {"form": "铸造过", "label": "体标"}, {"form": "铸造着", "label": "体标"}], "register": "中性", "sense_fingerprint": "铸造：熔化金属倒入模具制成器物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba171e17-0e71-47fc-bc45-dc66a5f33e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10142, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做饭的工艺，与螺旋压印机、金属活字印刷系统不相关，放在这里说不通。"}, {"text": "铸造", "is_correct": true, "explanation": "铸造：精确铸造技术指熔化金属倒入模具成型的工艺，与金属活字印刷系统相符。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“精确”通常修饰加工或测量类的技术，“饲养”说的是养动物，与“精确……技术”搭配不上。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙用于做点心，不是金属加工，与印刷系统的语境不合。"}], "explanations": {"烹饪": "语义：烹饪是做饭的工艺，与螺旋压印机、金属活字印刷系统不相关，放在这里说不通。", "铸造": "铸造：精确铸造技术指熔化金属倒入模具成型的工艺，与金属活字印刷系统相符。", "饲养": "搭配：“精确”通常修饰加工或测量类的技术，“饲养”说的是养动物，与“精确……技术”搭配不上。", "烘焙": "语义：烘焙用于做点心，不是金属加工，与印刷系统的语境不合。"}, "sentence_index": 0, "correct_answer": "铸造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑是去年铸造的。", "explanation": "这里应该用〈制造〉。电脑是由零件组装而成的，不是熔化金属倒入模具做成的，铸造只用于器物成型。"}, {"text": "师傅用锤子铸造了一把刀。", "explanation": "这里应该用〈锻造〉。锻造是用锤子敲打金属成型，铸造是把熔化的金属倒入模具，两者工艺不同。"}, {"text": "他们花了三年铸造这座桥。", "explanation": "这里应该用〈建造〉。桥是建筑，要用建造；铸造指把熔化的金属倒入模具制成器物，不能用来造桥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缝纫", "is_correct": false, "explanation": "语义：缝纫用针线，不能用金子来缝纫，与“用金子”的语境不合。"}, {"text": "熨烫", "is_correct": false, "explanation": "语义：熨烫是用熨斗把衣物弄平，不能用来制作金属奖杯。"}, {"text": "铸造", "is_correct": true, "explanation": "铸造：用金子熔化后倒入模具做成小奖杯，符合语境。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“一个小奖杯”这样的宾语。"}], "explanations": {"缝纫": "语义：缝纫用针线，不能用金子来缝纫，与“用金子”的语境不合。", "熨烫": "语义：熨烫是用熨斗把衣物弄平，不能用来制作金属奖杯。", "铸造": "铸造：用金子熔化后倒入模具做成小奖杯，符合语境。", "游泳": "配价：“游泳”是不及物动词，不能带“一个小奖杯”这样的宾语。"}, "sentence_index": 6, "correct_answer": "铸造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用电焊把两块钢板铸造在一起。", "explanation": "这里应该用〈焊接〉。铸造是把熔化的金属倒入模具成型，不能用来把两块钢板连在一起。"}, {"text": "他在木头上铸造了一只小鸟。", "explanation": "这里应该用〈雕刻〉。铸造需要熔化金属，木头不能熔化，不能说“铸造”木头做的小鸟。"}, {"text": "工人在高炉里铸造铁矿石。", "explanation": "这里应该用〈冶炼〉。冶炼是从矿石中提取金属，铸造是把金属做成器物，铁矿石不是成品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们终于把钟铸造了好。", "corrected_sentence": "工人们终于把钟铸造好了。", "error_description": "了的位置错误：“了”应放在结果补语“好”之后，应为“铸造好了”，不能插在“铸造”与“好”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们铸造得一口大钟。", "corrected_sentence": "我们铸造过一口大钟。", "error_description": "错误在于动态助词：表示曾经有过的经历应用“过”，应说“铸造过”；“得”用于动词后引出补语，这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
