INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10144, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依照原件或原样重新制作或仿制。", "primary_collocate": null, "pronunciation": "fù zhì", "ipa": "fu˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他所改良的金属活字印刷系统，结合了螺旋压印机、油性墨水与精确铸造技术，实现了文字复制的标准化与高效率生产。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这一突破不仅大幅降低了书籍的制作成本，更使《圣经》等文本得以以前所未有的速度和数量被复制，从而打破了教会对知识解释权的垄断。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "至十八世纪，识字率在西欧显著上升，公共图书馆、阅读社团与报刊媒体相继兴起，知识的传播不再局限于口耳相传或封闭的手稿交流，而是进入了一个可存储、可检索、可广泛复制的媒介时代。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "请把这个文件复制到我的电脑里。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去店里复制了一把钥匙。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画是别人复制的，不是原画。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以复制这段话，再发给朋友。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件很重要，请先复制一份存起来。", "target_word": "复制", "complexity_tier": "T3", "furigana": "zhè fèn wénjiàn hěn zhòngyào qǐng xiān fùzhì yí fèn cún qǐ lái", "sentence_source": "generated"}, {"text": "他复制了一份合同，放在家里。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器能快速复制很多一样的零件。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复制了", "label": "体标"}, {"form": "复制过", "label": "体标"}, {"form": "复制品", "label": "复合"}], "register": "中性", "sense_fingerprint": "复制：依照原件或原样重新制作、仿制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba171e17-0e71-47fc-bc45-dc66a5f33e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10144, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制（fù zhì）：依照原件或原样重新制作，是本词的读音与意思。"}, {"text": "副职", "is_correct": false, "explanation": "副职（fù zhí）与复制 fù zhì 声调不同（zhí 为第二声，zhì 为第四声），意思是副手的职位。"}, {"text": "复试", "is_correct": false, "explanation": "复试（fù shì）与复制 fù zhì 声母不同（sh 与 zh），意思是再次考试或第二轮面试。"}, {"text": "福祉", "is_correct": false, "explanation": "福祉（fú zhǐ）两个音节的声调都与复制不同，意思是幸福和福利。"}], "explanations": {"复制": "复制（fù zhì）：依照原件或原样重新制作，是本词的读音与意思。", "副职": "副职（fù zhí）与复制 fù zhì 声调不同（zhí 为第二声，zhì 为第四声），意思是副手的职位。", "复试": "复试（fù shì）与复制 fù zhì 声母不同（sh 与 zh），意思是再次考试或第二轮面试。", "福祉": "福祉（fú zhǐ）两个音节的声调都与复制不同，意思是幸福和福利。"}, "sentence_index": null, "correct_answer": "复制"}, "level_3": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制：名词化后说“文字复制”，指依照原样大量仿制文字，与“标准化”“高效率生产”相合。"}, {"text": "手写", "is_correct": false, "explanation": "语义：手写是逐字书写，与“金属活字印刷”“高效率生产”的机械化相矛盾，无法实现标准化。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：雕刻费时费力，与“高效率生产”相反，这句话说不通。"}, {"text": "创作", "is_correct": false, "explanation": "搭配：“标准化”不能修饰“创作”，创作讲究独创性，无法统一标准。"}], "explanations": {"复制": "复制：名词化后说“文字复制”，指依照原样大量仿制文字，与“标准化”“高效率生产”相合。", "手写": "语义：手写是逐字书写，与“金属活字印刷”“高效率生产”的机械化相矛盾，无法实现标准化。", "雕刻": "语义：雕刻费时费力，与“高效率生产”相反，这句话说不通。", "创作": "搭配：“标准化”不能修饰“创作”，创作讲究独创性，无法统一标准。"}, "sentence_index": 0, "correct_answer": "复制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他复制了这首古诗的意思。", "explanation": "这里应该用〈理解〉。复制指依原样仿制有形的物件或资料，意思是抽象的，只能理解，不能复制。"}, {"text": "他复制了昨天的天气。", "explanation": "这里应该用〈回忆〉。复制指依原样仿制物件或资料；天气不是可以仿制的东西，只能回忆、描述。"}, {"text": "他复制了一个小时前的心情。", "explanation": "这里应该用〈回想〉。复制指依原样仿制有形的物件或资料，心情只能回想、体会，不能复制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10144, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制（fù zhì）：依照原件或原样重新制作，是本词的读音与意思。"}, {"text": "父子", "is_correct": false, "explanation": "父子（fù zǐ）与复制 fù zhì 声母不同（z 与 zh），声调也不同，意思是父亲与儿子。"}, {"text": "副食", "is_correct": false, "explanation": "副食（fù shí）与复制 fù zhì 声母不同（sh 与 zh），第二音节声调也不同，意思是副食品。"}, {"text": "扶植", "is_correct": false, "explanation": "扶植（fú zhí）两个音节的声调都与复制不同，意思是扶助培植。"}], "explanations": {"复制": "复制（fù zhì）：依照原件或原样重新制作，是本词的读音与意思。", "父子": "父子（fù zǐ）与复制 fù zhì 声母不同（z 与 zh），声调也不同，意思是父亲与儿子。", "副食": "副食（fù shí）与复制 fù zhì 声母不同（sh 与 zh），第二音节声调也不同，意思是副食品。", "扶植": "扶植（fú zhí）两个音节的声调都与复制不同，意思是扶助培植。"}, "sentence_index": null, "correct_answer": "复制"}, "level_3": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制：依原样再做一份，句中指把这段话再做一份，然后发给朋友。"}, {"text": "烧掉", "is_correct": false, "explanation": "语义：烧掉后这段话就不存在了，无法再发给朋友。"}, {"text": "撕掉", "is_correct": false, "explanation": "语义：撕掉以后就没有这段话了，与“再发给朋友”矛盾。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”只能搭配饮品等，不能与“这段话”搭配。"}], "explanations": {"复制": "复制：依原样再做一份，句中指把这段话再做一份，然后发给朋友。", "烧掉": "语义：烧掉后这段话就不存在了，无法再发给朋友。", "撕掉": "语义：撕掉以后就没有这段话了，与“再发给朋友”矛盾。", "喝": "搭配：“喝”只能搭配饮品等，不能与“这段话”搭配。"}, "sentence_index": 6, "correct_answer": "复制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子复制了父亲的眼睛。", "explanation": "这里应该用〈遗传〉。复制是依原样仿制物件或资料；人的外貌特征由父母遗传，不说复制。"}, {"text": "他复制了房间的面积。", "explanation": "这里应该用〈测量〉。复制指依原样仿制有形的物件或资料，面积是数量，要用“测量”，不能说“复制”。"}, {"text": "导演复制了一段虚构的爱情。", "explanation": "这里应该用〈编造〉。复制指依原样仿制已有的东西；虚构的爱情没有原件可仿，要用“编造”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天复制了三张钥匙。", "corrected_sentence": "我昨天复制了三把钥匙。", "error_description": "量词错误：钥匙要用量词“把”，应说“复制了三把钥匙”，不说“三张钥匙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那份合同复制了到电脑里。", "corrected_sentence": "他把那份合同复制到了电脑里。", "error_description": "体标位置错误：“了”应放在补语“到”之后，说“复制到了电脑里”，不说“复制了到电脑里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10146, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "友谊", "is_correct": false, "explanation": "与「高效率」没有反义关系，「友谊」是人与人之间的情感，与工作效率无关。"}, {"text": "音乐", "is_correct": false, "explanation": "与「高效率」没有反义关系，「音乐」是艺术形式，与效率无关。"}, {"text": "低效率", "is_correct": true, "explanation": "正确。「低效率」与「高效率」构成反义，指做事效率低、效果差。"}, {"text": "海洋", "is_correct": false, "explanation": "与「高效率」没有反义关系，「海洋」是自然地理事物。"}], "correct_answer": "低效率", "explanations": {"友谊": "与「高效率」没有反义关系，「友谊」是人与人之间的情感，与工作效率无关。", "音乐": "与「高效率」没有反义关系，「音乐」是艺术形式，与效率无关。", "低效率": "正确。「低效率」与「高效率」构成反义，指做事效率低、效果差。", "海洋": "与「高效率」没有反义关系，「海洋」是自然地理事物。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10146, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "教室", "is_correct": false, "explanation": "与「高效率」没有反义关系，「教室」是学习场所，与效率无关。"}, {"text": "河流", "is_correct": false, "explanation": "与「高效率」没有反义关系，「河流」是自然地理事物。"}, {"text": "低效率", "is_correct": true, "explanation": "正确。「低效率」与「高效率」构成反义，指效率低、效果差。"}, {"text": "花园", "is_correct": false, "explanation": "与「高效率」没有反义关系，「花园」是种植花草的地方。"}], "correct_answer": "低效率", "explanations": {"教室": "与「高效率」没有反义关系，「教室」是学习场所，与效率无关。", "河流": "与「高效率」没有反义关系，「河流」是自然地理事物。", "低效率": "正确。「低效率」与「高效率」构成反义，指效率低、效果差。", "花园": "与「高效率」没有反义关系，「花园」是种植花草的地方。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10146, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在较短的时间内完成较多的工作或任务，效果很好。", "primary_collocate": null, "pronunciation": "gāo xiào lǜ", "ipa": "kau̯˥ ɕiau̯˥˩ ly˥˩", "syllable_count": 3, "sentences": [{"text": "他所改良的金属活字印刷系统，结合了螺旋压印机、油性墨水与精确铸造技术，实现了文字复制的标准化与高效率生产。", "target_word": "高效率", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "高效率是好员工的特点。", "target_word": "高效率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家工厂以高效率闻名。", "target_word": "高效率", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新机器带来了高效率。", "target_word": "高效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他工作时总是保持高效率。", "target_word": "高效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的计划能让我们保持高效率。", "target_word": "高效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高效率的团队每天按时完成任务。", "target_word": "高效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条生产线的高效率让老板很满意。", "target_word": "高效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议开得很短，这体现了公司的高效率。", "target_word": "高效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新系统让医院实现了高效率，病人不用等很久。", "target_word": "高效率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "短时间内完成较多工作且效果好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a7c30f6-37cc-4573-8a65-fd66c5bc2a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10146, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手工", "is_correct": false, "explanation": "语义：手工生产靠人力完成，与前文的标准化、精确铸造和机器印刷方向相反。"}, {"text": "高效率", "is_correct": true, "explanation": "正确。「高效率生产」指效率高、产量大的生产方式，与「标准化」相配。"}, {"text": "随意", "is_correct": false, "explanation": "语义：「随意」指做法随便、不规范，与「标准化」的要求相反，不适合修饰「生产」。"}, {"text": "低效率", "is_correct": false, "explanation": "语义：「低效率生产」与「实现了…标准化」的正面成就相矛盾。"}], "explanations": {"手工": "语义：手工生产靠人力完成，与前文的标准化、精确铸造和机器印刷方向相反。", "高效率": "正确。「高效率生产」指效率高、产量大的生产方式，与「标准化」相配。", "随意": "语义：「随意」指做法随便、不规范，与「标准化」的要求相反，不适合修饰「生产」。", "低效率": "语义：「低效率生产」与「实现了…标准化」的正面成就相矛盾。"}, "sentence_index": 0, "correct_answer": "高效率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆新车的高效率很快。", "explanation": "这里应该用〈速度〉。高效率说的是短时间内完成较多工作、效果很好，车的快慢要用「速度」。"}, {"text": "这家工厂每月的高效率是一万台。", "explanation": "这里应该用〈产量〉。高效率说的是做事快、效果好的程度，一个月做出多少台要用「产量」，效率不能用台数计量。"}, {"text": "这台机器的高效率是五千瓦。", "explanation": "这里应该用〈功率〉。高效率指做事快、效果好的程度，机器每秒做功多少、以千瓦计量要用「功率」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10146, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懒惰", "is_correct": false, "explanation": "语义：「懒惰的团队」与「每天按时完成任务」的意思相反。"}, {"text": "高效率", "is_correct": true, "explanation": "正确。「高效率的团队」指工作效率高，与「每天按时完成任务」的意思一致。"}, {"text": "混乱", "is_correct": false, "explanation": "语义：「混乱」的团队很难「按时完成任务」，与后半句矛盾。"}, {"text": "拖拉", "is_correct": false, "explanation": "语义：「拖拉」的团队行动拖延，很难「按时完成任务」，与后半句矛盾。"}], "explanations": {"懒惰": "语义：「懒惰的团队」与「每天按时完成任务」的意思相反。", "高效率": "正确。「高效率的团队」指工作效率高，与「每天按时完成任务」的意思一致。", "混乱": "语义：「混乱」的团队很难「按时完成任务」，与后半句矛盾。", "拖拉": "语义：「拖拉」的团队行动拖延，很难「按时完成任务」，与后半句矛盾。"}, "sentence_index": 6, "correct_answer": "高效率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试的高效率是九十分。", "explanation": "这里应该用〈成绩〉。高效率说的是做事快、效果好的程度，考试得的分数要用「成绩」，不能用效率来表示。"}, {"text": "这种药的高效率很好。", "explanation": "这里应该用〈效果〉。高效率说的是工作效率，药物的作用好不好要用「效果」。"}, {"text": "这家公司去年的高效率是两亿元。", "explanation": "这里应该用〈营业额〉。高效率说的是做事快、效果好的程度，一年卖出的总金额要用「营业额」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条生产线很高效率。", "corrected_sentence": "这条生产线保持着高效率。", "error_description": "错误：「高效率」是名词，不能直接受程度副词「很」修饰。正确：用动词带名词，写作「保持着高效率」（或说「效率很高」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王的团队保持一个高效率，每周都能按时交付。", "corrected_sentence": "小王的团队保持高效率，每周都能按时交付。", "error_description": "错误：「高效率」是抽象名词，前面不能直接加数量词「一个」计量。正确：去掉「一个」，写作「保持高效率」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
