INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10148, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度或数量变化很大。", "primary_collocate": null, "pronunciation": "dà fú", "ipa": "ta˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "这一突破不仅大幅降低了书籍的制作成本，更使《圣经》等文本得以以前所未有的速度和数量被复制，从而打破了教会对知识解释权的垄断。", "target_word": "大幅", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年价格大幅上涨。", "target_word": "大幅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨天客人大幅减少。", "target_word": "大幅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的成绩大幅提高。", "target_word": "大幅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新政策大幅提高了收入。", "target_word": "大幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机价格大幅下降了。", "target_word": "大幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂大幅增加了工作人员。", "target_word": "大幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为天气不好，今天的游客大幅减少。", "target_word": "大幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月公司的收入大幅下降，大家都很担心。", "target_word": "大幅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把价格大幅降低，买的人多了很多。", "target_word": "大幅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "修饰动词，表示变化的程度或数量很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a7c30f6-37cc-4573-8a65-fd66c5bc2a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稍微", "is_correct": false, "explanation": "语义：「不仅稍微降低了成本」与后文「更使……前所未有的速度和数量被复制」的递进语气相矛盾。"}, {"text": "大幅", "is_correct": true, "explanation": "正确。「大幅」表示降低的幅度很大，与「不仅……更……」的递进关系相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔降低」说明只是间或发生，无法支撑「打破垄断」这样的重大突破。"}, {"text": "从未", "is_correct": false, "explanation": "语义：「从未降低了」与完成体「了」矛盾，也与「突破」的意思相反。"}], "explanations": {"稍微": "语义：「不仅稍微降低了成本」与后文「更使……前所未有的速度和数量被复制」的递进语气相矛盾。", "大幅": "正确。「大幅」表示降低的幅度很大，与「不仅……更……」的递进关系相符。", "偶尔": "语义：「偶尔降低」说明只是间或发生，无法支撑「打破垄断」这样的重大突破。", "从未": "语义：「从未降低了」与完成体「了」矛盾，也与「突破」的意思相反。"}, "sentence_index": 0, "correct_answer": "大幅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大幅支持这个计划。", "explanation": "这里应该用〈大力〉。大幅说的是变化的幅度很大，表示支持的力度要用「大力」。"}, {"text": "我大幅喜欢这首歌。", "explanation": "这里应该用〈非常〉。「大幅」只表示变化的幅度大，表示喜欢的程度深要用「非常」。"}, {"text": "这本书大幅有趣。", "explanation": "这里应该用〈很〉。「大幅」只表示变化的幅度大，形容有趣的程度要用「很」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从未", "is_correct": false, "explanation": "语义：「从未增加」与句中「增加了」的完成语气相矛盾。"}, {"text": "大幅", "is_correct": true, "explanation": "正确。「大幅增加」说明工作人员的数量增长幅度很大，与句意相符。"}, {"text": "轻轻", "is_correct": false, "explanation": "搭配：「轻轻」形容动作的轻微，不用来修饰人员数量的增加。"}, {"text": "不再", "is_correct": false, "explanation": "语义：「不再增加」与「增加了工作人员」的事实矛盾。"}], "explanations": {"从未": "语义：「从未增加」与句中「增加了」的完成语气相矛盾。", "大幅": "正确。「大幅增加」说明工作人员的数量增长幅度很大，与句意相符。", "轻轻": "搭配：「轻轻」形容动作的轻微，不用来修饰人员数量的增加。", "不再": "语义：「不再增加」与「增加了工作人员」的事实矛盾。"}, "sentence_index": 6, "correct_answer": "大幅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我大幅同意你的看法。", "explanation": "这里应该用〈完全〉。「大幅」表示变化的幅度大，表示同意的程度要用「完全」。"}, {"text": "媒体大幅抨击了这项政策。", "explanation": "这里应该用〈猛烈〉。大幅修饰的是变化的幅度，抨击的力度要用「猛烈」。"}, {"text": "这两个数字大幅相同。", "explanation": "这里应该用〈完全〉。「大幅」表示变化的幅度大，两个数字一样的程度要用「完全」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "物价很大幅上涨了。", "corrected_sentence": "物价大幅上涨了。", "error_description": "错误：「大幅」是副词，前面不能再加程度副词「很」。正确：去掉「很」，写作「物价大幅上涨了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂的产量很大幅提高了。", "corrected_sentence": "工厂的产量大幅提高了。", "error_description": "错误：「大幅」是副词，前面不能再加程度副词「很」。正确：去掉「很」，写作「工厂的产量大幅提高了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
