INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10153, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "基督教经典，包括《旧约》和《新约》，被视为上帝启示的圣书。", "primary_collocate": null, "pronunciation": "shèng jīng", "ipa": "ʂɤŋ˥˩ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "这一突破不仅大幅降低了书籍的制作成本，更使《圣经》等文本得以以前所未有的速度和数量被复制，从而打破了教会对知识解释权的垄断。", "target_word": "圣经", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他有一本圣经。", "target_word": "圣经", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "圣经是一本很老的书。", "target_word": "圣经", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶每天晚上读圣经。", "target_word": "圣经", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "教堂里的人在读圣经。", "target_word": "圣经", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "圣经里有很多故事。", "target_word": "圣经", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他送了我一本圣经。", "target_word": "圣经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "圣经讲了上帝和人们的故事。", "target_word": "圣经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多信徒周日会去教堂读圣经。", "target_word": "圣经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本圣经是爷爷留下的，我一直带着。", "target_word": "圣经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "聖經", "label": "繁体"}], "register": "中性", "sense_fingerprint": "基督教经典，包括旧约和新约", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a7c30f6-37cc-4573-8a65-fd66c5bc2a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10153, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "圣经", "is_correct": true, "explanation": "正确答案。圣经指基督教经典，包括旧约和新约。"}, {"text": "圣境", "is_correct": false, "explanation": "第二音节 jìng（第四声）与 jīng（第一声）声调不同，意思是神圣的地方。"}, {"text": "胜景", "is_correct": false, "explanation": "第二音节 jǐng（第三声）与 jīng（第一声）声调不同，意思是美丽的景色。"}, {"text": "政经", "is_correct": false, "explanation": "zhèng 与 shèng 声母不同（zh 与 sh），意思是政治与经济，不是圣经。"}], "explanations": {"圣经": "正确答案。圣经指基督教经典，包括旧约和新约。", "圣境": "第二音节 jìng（第四声）与 jīng（第一声）声调不同，意思是神圣的地方。", "胜景": "第二音节 jǐng（第三声）与 jīng（第一声）声调不同，意思是美丽的景色。", "政经": "zhèng 与 shèng 声母不同（zh 与 sh），意思是政治与经济，不是圣经。"}, "sentence_index": null, "correct_answer": "圣经"}, "level_3": {"options": [{"text": "圣经", "is_correct": true, "explanation": "正确答案。《圣经》是基督教经典，是可以被大量复制的文本，与“等文本”“被复制”相符。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是影片，不是文本，不能说“使《电影》等文本被复制”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是文本，不能被复制成“等文本”的一部分，句子不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“等文本”不能与手机搭配，手机不是可以被复制的文本。"}], "explanations": {"圣经": "正确答案。《圣经》是基督教经典，是可以被大量复制的文本，与“等文本”“被复制”相符。", "电影": "语义：电影是影片，不是文本，不能说“使《电影》等文本被复制”。", "汽车": "语义：汽车不是文本，不能被复制成“等文本”的一部分，句子不通。", "手机": "搭配：“等文本”不能与手机搭配，手机不是可以被复制的文本。"}, "sentence_index": 0, "correct_answer": "圣经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸在厨房里翻圣经，找今晚要做的菜谱。", "explanation": "这里应该用〈菜谱〉。圣经指基督教经典，不能拿来查做菜的方法。"}, {"text": "皇帝下了一道圣经，要求全国百姓都要遵守。", "explanation": "这里应该用〈圣旨〉。圣经指基督教经典，皇帝发布的命令要说圣旨。"}, {"text": "我每天晚上翻圣经，查找今天要学的生词。", "explanation": "这里应该用〈字典〉。圣经是宗教经典，不是查生词的工具书，查词要用字典。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10153, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "圣经", "is_correct": true, "explanation": "正确答案。圣经指基督教经典。"}, {"text": "胜景", "is_correct": false, "explanation": "第二音节 jǐng（第三声）与 jīng（第一声）声调不同，意思是美丽的景色。"}, {"text": "胜境", "is_correct": false, "explanation": "第二音节 jìng（第四声）与 jīng（第一声）声调不同，意思是优美的地方。"}, {"text": "肾经", "is_correct": false, "explanation": "shèn 与 shèng 声调相同，只差韵母（-n 与 -ng），意思是中医所说的肾经络。"}], "explanations": {"圣经": "正确答案。圣经指基督教经典。", "胜景": "第二音节 jǐng（第三声）与 jīng（第一声）声调不同，意思是美丽的景色。", "胜境": "第二音节 jìng（第四声）与 jīng（第一声）声调不同，意思是优美的地方。", "肾经": "shèn 与 shèng 声调相同，只差韵母（-n 与 -ng），意思是中医所说的肾经络。"}, "sentence_index": null, "correct_answer": "圣经"}, "level_3": {"options": [{"text": "圣经", "is_correct": true, "explanation": "正确答案。“一本”配书，圣经是书，句意通顺。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不是书，不能说“送了我一本苹果”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“一本”只配书籍类，冰箱应说“一台”。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“一本”不能与椅子搭配，椅子应说“一把”或“一张”。"}], "explanations": {"圣经": "正确答案。“一本”配书，圣经是书，句意通顺。", "苹果": "语义：苹果是水果，不是书，不能说“送了我一本苹果”。", "冰箱": "搭配：“一本”只配书籍类，冰箱应说“一台”。", "椅子": "搭配：“一本”不能与椅子搭配，椅子应说“一把”或“一张”。"}, "sentence_index": 6, "correct_answer": "圣经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上翻圣经，看看今天是星期几。", "explanation": "这里应该用〈日历〉。圣经是宗教典籍，不是用来查日期的，查日期要用日历。"}, {"text": "他把圣经放进冰箱，想让它保持新鲜。", "explanation": "这里应该用〈食物〉。圣经是书，不需要保鲜，放进冰箱保鲜的是食物。"}, {"text": "他每天晚上都在圣经里查天气预报。", "explanation": "这里应该用〈天气预报〉。圣经是宗教典籍，不能用来查天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天晚上读一条圣经。", "corrected_sentence": "我每天晚上读一段圣经。", "error_description": "“圣经”不能配量词“条”，“条”多用于条状的东西。应说“一段圣经”（一段经文）或“一本圣经”，这里用“一段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只圣经很旧，但我一直保存着。", "corrected_sentence": "这本圣经很旧，但我一直保存着。", "error_description": "“圣经”是书，量词应用“本”，不能用“只”，“只”多用于动物等。应说“这本圣经”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10154, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10154, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10154, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指用文字写成的作品或记录下来的话语。", "primary_collocate": null, "pronunciation": "wén běn", "ipa": "wən˧˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这份文本是用古汉语写的，现代读者读起来很吃力。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与书写文本的固化不同，每一次讲述都是对传统的再创造，讲述者根据当下语境、听众构成与社会需求，对情节进行增删或重构。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这一突破不仅大幅降低了书籍的制作成本，更使《圣经》等文本得以以前所未有的速度和数量被复制，从而打破了教会对知识解释权的垄断。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "随着出版物种类的丰富，除宗教文献外，科学论著、文学作品、法律文本乃至新闻小册子广泛流通，公众对知识的渴求被前所未有地激发。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "标准化的文本催生了语言的规范化，进而强化了民族认同；印刷品的跨地域流通促进了思想的跨国共振，使伏尔泰、卢梭等启蒙思想家的声音得以跨越国界，形成“共和的书信”网络。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "此类义务不仅涉及法律文本的字面遵循，更要求企业构建一套贯穿产品生命周期的伦理—合规架构。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "请先读一遍这个文本，再回答问题。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们发了一份新文本。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个文本太长，我读了两遍。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把文本复制到新的文件里。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "文本文件", "label": "复合词"}, {"form": "文本框", "label": "复合词"}], "register": "书面", "sense_fingerprint": "用文字写成的作品或记录下来的话语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dab81e9-4fc4-4e85-8310-7a60964d0d47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文本", "is_correct": true, "explanation": "正确：“用古汉语写的”指以文字写成的作品，应为“文本”。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：乐曲是音乐作品，不是用文字写成的，不能说“用古汉语写的”。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字是数目或数码，不是用文字写成的，与“用古汉语写的”不符。"}, {"text": "语音", "is_correct": false, "explanation": "语义：语音是发出的声音，不能用文字“写”，与句意不符。"}], "explanations": {"文本": "正确：“用古汉语写的”指以文字写成的作品，应为“文本”。", "乐曲": "语义：乐曲是音乐作品，不是用文字写成的，不能说“用古汉语写的”。", "数字": "语义：数字是数目或数码，不是用文字写成的，与“用古汉语写的”不符。", "语音": "语义：语音是发出的声音，不能用文字“写”，与句意不符。"}, "sentence_index": 0, "correct_answer": "文本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个老人每天晚上给孩子讲文本。", "explanation": "这里应该用〈故事〉。文本指写成文字的作品或记录，口头讲述的内容要用故事。"}, {"text": "这个文本很大声。", "explanation": "这里应该用〈声音〉。文本指用文字写成的作品或记录，不能说大声；说大声的是声音。"}, {"text": "这个文本的笔画很多。", "explanation": "这里应该用〈字〉。笔画是单个汉字的组成部分，文本指整篇用文字写成的作品或记录，不能数笔画，要说这个字的笔画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文本", "is_correct": true, "explanation": "正确：句中指需要阅读的文字内容，应为“文本”。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“读”用于文字，照片不能读。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是视听作品，不是可以阅读的文字，与“读一遍”不符。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“读”不用于歌曲，歌曲应该听或唱。"}], "explanations": {"文本": "正确：句中指需要阅读的文字内容，应为“文本”。", "照片": "搭配：“读”用于文字，照片不能读。", "电影": "语义：电影是视听作品，不是可以阅读的文字，与“读一遍”不符。", "歌曲": "搭配：“读”不用于歌曲，歌曲应该听或唱。"}, "sentence_index": 6, "correct_answer": "文本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汉语是一种文本。", "explanation": "这里应该用〈语言〉。文本指用文字写成的作品或记录，汉语是一种语言体系，不能说成文本。"}, {"text": "他的文本画得很清楚。", "explanation": "这里应该用〈图画〉。文本指用文字写成的作品或记录，不能用画来表现，画出来的应是图画。"}, {"text": "这个文本的味道很好。", "explanation": "这里应该用〈菜〉。文本指用文字写成的作品或记录，没有味道；说味道好的是菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师给我们发了一只新文本。", "corrected_sentence": "老师给我们发了一段新文本。", "error_description": "错误：“文本”的量词用了“只”，“只”用于动物，文本应用“段”或“份”。应为“一段新文本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师改了我文本。", "corrected_sentence": "老师改了我的文本。", "error_description": "错误：代词“我”修饰名词“文本”时要加“的”，应为“我的文本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
