INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10157, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "物体在单位时间内移动的距离，表示运动快慢的程度。", "primary_collocate": null, "pronunciation": "sù dù", "ipa": "su˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这一突破不仅大幅降低了书籍的制作成本，更使《圣经》等文本得以以前所未有的速度和数量被复制，从而打破了教会对知识解释权的垄断。", "target_word": "速度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这辆车的速度很快。", "target_word": "速度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "高铁的速度比普通火车快得多。", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上下雨，司机慢慢降低了速度。", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风越大，小船前进的速度就越快。", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光的速度比声音快得多。", "target_word": "速度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "跑步比赛时，他一直保持着同样的速度。", "target_word": "速度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说这辆车超过了规定的速度。", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机起飞前，速度会越来越快。", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪太滑，我们只好减慢速度。", "target_word": "速度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平均速度", "label": "复合"}, {"form": "加速度", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体运动的快慢，单位时间内移动的距离", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a7c30f6-37cc-4573-8a65-fd66c5bc2a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10157, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速度", "is_correct": true, "explanation": "正确答案。“以前所未有的速度和数量”指复制的速度与数量，搭配通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与复制的快慢无关，“以前所未有的颜色”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能用来说明复制的快慢，句子不通。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“以前所未有的”不能与温度搭配来描述复制过程。"}], "explanations": {"速度": "正确答案。“以前所未有的速度和数量”指复制的速度与数量，搭配通顺。", "颜色": "语义：颜色与复制的快慢无关，“以前所未有的颜色”说不通。", "味道": "语义：味道不能用来说明复制的快慢，句子不通。", "温度": "搭配：“以前所未有的”不能与温度搭配来描述复制过程。"}, "sentence_index": 0, "correct_answer": "速度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "从学校到车站的速度是两公里。", "explanation": "这里应该用〈距离〉。速度是单位时间内移动的快慢，两地之间的远近要用距离。"}, {"text": "今天的速度很高，我们都出汗了。", "explanation": "这里应该用〈温度〉。速度说明运动的快慢，说冷热要用温度。"}, {"text": "这辆车的速度很重，开起来很费力。", "explanation": "这里应该用〈重量〉。速度只说快慢，不能说轻重，车的轻重要用重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速度", "is_correct": true, "explanation": "正确答案。“保持着同样的速度”指跑步时快慢不变，搭配通顺。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子不是快慢的程度，“同样的鞋子”说不通。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量指声音的强弱，与跑步时的快慢无关。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“同样的”不能与窗户搭配，句子不通。"}], "explanations": {"速度": "正确答案。“保持着同样的速度”指跑步时快慢不变，搭配通顺。", "鞋子": "语义：鞋子不是快慢的程度，“同样的鞋子”说不通。", "音量": "语义：音量指声音的强弱，与跑步时的快慢无关。", "窗户": "搭配：“同样的”不能与窗户搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "速度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室的速度很高，我们都看不清黑板。", "explanation": "这里应该用〈亮度〉。速度说的是移动快慢，光线的明暗要用亮度。"}, {"text": "这件衣服的速度很高，我们买不起。", "explanation": "这里应该用〈价格〉。速度说的是快慢，东西贵不贵要用价格。"}, {"text": "他踢球时的速度很强，球一直飞不远。", "explanation": "这里应该用〈力度〉。踢球用力的强弱要说力度，速度说的是移动的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那列火车的速度很多。", "corrected_sentence": "那列火车的速度很快。", "error_description": "错误：「速度」说的是快慢，不能说「多」。正确：写作「速度很快」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骑车时一只速度很稳定。", "corrected_sentence": "他骑车时速度很稳定。", "error_description": "“速度”是抽象名词，不能用量词“只”（“只”多用于动物等），这里不加量词，应说“速度很稳定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
