INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10158, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比喻突破原有的限制、纪录、局面或习惯。", "primary_collocate": null, "pronunciation": "dǎ pò", "ipa": "ta˨˩˦ pʰwo˥˩", "syllable_count": 2, "sentences": [{"text": "这一突破不仅大幅降低了书籍的制作成本，更使《圣经》等文本得以以前所未有的速度和数量被复制，从而打破了教会对知识解释权的垄断。", "target_word": "打破", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "新软件打破了地区的限制。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店打破了大公司的垄断。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一声大叫打破了夜里的安静。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要打破旧习惯，每天早点起床。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该打破对老年人的偏见。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人都不说话，谁也不想打破沉默。", "target_word": "打破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位游泳运动员打破了世界纪录。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司打破了老规矩，让年轻人也能当经理。", "target_word": "打破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想打破旧的想法，换一种方式做事。", "target_word": "打破", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打破了", "label": "体标"}, {"form": "打破过", "label": "体标"}], "register": "中性", "sense_fingerprint": "比喻突破原有的限制、纪录、局面或习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a7c30f6-37cc-4573-8a65-fd66c5bc2a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打破", "is_correct": true, "explanation": "正确。“从而打破了教会对知识解释权的垄断”，打破表示突破原有的限制。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：垄断是要被突破的限制，不能被赞美，句子意思说不通。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”搭配任务、工作，不能说完成垄断。"}, {"text": "颁布", "is_correct": false, "explanation": "搭配：“颁布”搭配法令、政策，不能说颁布垄断。"}], "explanations": {"打破": "正确。“从而打破了教会对知识解释权的垄断”，打破表示突破原有的限制。", "赞美": "语义：垄断是要被突破的限制，不能被赞美，句子意思说不通。", "完成": "搭配：“完成”搭配任务、工作，不能说完成垄断。", "颁布": "搭配：“颁布”搭配法令、政策，不能说颁布垄断。"}, "sentence_index": 0, "correct_answer": "打破"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在关键时刻打破了那张王牌。", "explanation": "这里应该用〈打出〉。打出指把牌拿出来打，王牌要说打出；“打破”指突破限制、纪录或局面，不能用于牌。"}, {"text": "他正说得高兴，我突然打破了他的话。", "explanation": "这里应该用〈打断〉。打断指中途截住别人说话，话语不能用“打破”。"}, {"text": "我们终于打破了对手。", "explanation": "这里应该用〈打败〉。打败指战胜对方，对手不能被“打破”，“打破”的对象是限制、纪录、沉默等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打破", "is_correct": true, "explanation": "正确。“谁也不想打破沉默”，打破表示让沉默结束。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”搭配歌曲，不能说唱沉默。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：沉默不能被点燃，句子意思说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”搭配食物，不能说吃沉默。"}], "explanations": {"打破": "正确。“谁也不想打破沉默”，打破表示让沉默结束。", "唱": "搭配：“唱”搭配歌曲，不能说唱沉默。", "点燃": "语义：沉默不能被点燃，句子意思说不通。", "吃": "搭配：“吃”搭配食物，不能说吃沉默。"}, "sentence_index": 6, "correct_answer": "打破"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快打破了那个讨厌的人。", "explanation": "这里应该用〈打发〉。打发指把人支开、送走，人不能被“打破”。"}, {"text": "他提前打破了那份工作。", "explanation": "这里应该用〈完成〉。完成指做完一件事，工作不能用“打破”来说。"}, {"text": "我们终于打破了这次旅行。", "explanation": "这里应该用〈结束〉。结束指事情到了终点，旅行不能用“打破”来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于僵局打破了。", "corrected_sentence": "他终于把僵局打破了。", "error_description": "错误：漏了“把”。“僵局”是被处置的对象，要用“把”提到动词前，不能直接说“僵局打破了”。正确：“他终于把僵局打破了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们坚决的打破了僵局。", "corrected_sentence": "他们坚决地打破了僵局。", "error_description": "错误：状语后应用“地”，不能用“的”，“的”连接定语与中心语。正确：“坚决地打破了僵局”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10159, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10159, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10159, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "教导别人，使其学会某种知识、技能或道理。", "primary_collocate": null, "pronunciation": "jiāo huì", "ipa": "tɕjɑʊ˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这套方法的核心在于，教师必须先理解学生的思路，才能真正教会他们独立思考。", "target_word": "教会", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "妈妈教会了我做饭。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸花了一个夏天教会我游泳。", "target_word": "教会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教会我们怎么用电脑。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这只小狗教会了坐下。", "target_word": "教会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶教会了孩子们唱这首歌。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师没有教会学生怎样写作文。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想请你教会我用这个软件。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友教会我，做事要有耐心。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥终于教会了弟弟骑自行车。", "target_word": "教会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "教会了", "label": "完成体"}, {"form": "教会过", "label": "经历体"}, {"form": "教會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "教导别人直到对方学会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d76630-55e4-4191-b05f-0cc4fbf0c071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10159, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教会", "is_correct": true, "explanation": "正确：教会（jiāo huì），意思是教别人使其学会。"}, {"text": "教坏", "is_correct": false, "explanation": "huài 与 huì 韵母不同（uai 与 ui），“教坏”意思是把人教得变坏。"}, {"text": "交回", "is_correct": false, "explanation": "huí（第二声）与 huì（第四声）声调不同，“交回”意思是交还。"}, {"text": "叫回", "is_correct": false, "explanation": "jiào 与 jiāo 声调不同，huí 与 huì 声调也不同，“叫回”意思是叫…回来。"}], "explanations": {"教会": "正确：教会（jiāo huì），意思是教别人使其学会。", "教坏": "huài 与 huì 韵母不同（uai 与 ui），“教坏”意思是把人教得变坏。", "交回": "huí（第二声）与 huì（第四声）声调不同，“交回”意思是交还。", "叫回": "jiào 与 jiāo 声调不同，huí 与 huì 声调也不同，“叫回”意思是叫…回来。"}, "sentence_index": null, "correct_answer": "教会"}, "level_3": {"options": [{"text": "教会", "is_correct": true, "explanation": "正确：此句中“教会”为动词，与“真正”搭配，表示使学生真正学会独立思考。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：“书籍”是名词，不能作动词带“他们独立思考”，句子不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”是名词，不能表示“教”的动作，句子不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是名词，不能带“他们独立思考”作宾语，句子不通。"}], "explanations": {"教会": "正确：此句中“教会”为动词，与“真正”搭配，表示使学生真正学会独立思考。", "书籍": "语义：“书籍”是名词，不能作动词带“他们独立思考”，句子不通。", "天空": "语义：“天空”是名词，不能表示“教”的动作，句子不通。", "河流": "语义：“河流”是名词，不能带“他们独立思考”作宾语，句子不通。"}, "sentence_index": 0, "correct_answer": "教会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师教会了这个语法，学生还是没懂。", "explanation": "这里应该用〈说明〉。“说明”只讲清内容，不保证对方学会；“教会”表示对方已学会，与“学生还是没懂”矛盾。"}, {"text": "我教会了他三天，他还是不会游泳。", "explanation": "这里应该用〈教〉。“教会”表示教的结果是对方已经学会，与后面的“还是不会”矛盾；只强调教的过程时用“教”。"}, {"text": "教练教会了游泳的技巧，我还是不会游。", "explanation": "这里应该用〈讲解〉。“讲解”只说明动作要领，不保证对方学会；“教会”表示对方已学会，与“我还是不会游”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10159, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "教会", "is_correct": true, "explanation": "正确：教会（jiāo huì），意思是教别人使其学会。"}, {"text": "教坏", "is_correct": false, "explanation": "huài 与 huì 韵母不同（ai 与 ui），“教坏”意思是把人教得变坏。"}, {"text": "交互", "is_correct": false, "explanation": "hù 与 huì 声调相同，仅韵母少一个 i（u 与 ui），“交互”意思是相互。"}, {"text": "交换", "is_correct": false, "explanation": "huàn 与 huì 声调相同但韵母不同（uan 与 ui），“交换”意思是互相给予或替换。"}], "explanations": {"教会": "正确：教会（jiāo huì），意思是教别人使其学会。", "教坏": "huài 与 huì 韵母不同（ai 与 ui），“教坏”意思是把人教得变坏。", "交互": "hù 与 huì 声调相同，仅韵母少一个 i（u 与 ui），“交互”意思是相互。", "交换": "huàn 与 huì 声调相同但韵母不同（uan 与 ui），“交换”意思是互相给予或替换。"}, "sentence_index": null, "correct_answer": "教会"}, "level_3": {"options": [{"text": "教会", "is_correct": true, "explanation": "正确：“教会”表示教到学生学会，与“没有”组合，说明学生没有学会。"}, {"text": "批改", "is_correct": false, "explanation": "配价：“批改”的宾语应是作文本身，不能带“学生怎样写作文”这样的小句。"}, {"text": "装订", "is_correct": false, "explanation": "语义：“装订”的对象是纸张或书本，不能对“学生”施加动作。"}, {"text": "打磨", "is_correct": false, "explanation": "语义：“打磨”指加工器物表面，与“学生怎样写作文”的语义不合。"}], "explanations": {"教会": "正确：“教会”表示教到学生学会，与“没有”组合，说明学生没有学会。", "批改": "配价：“批改”的宾语应是作文本身，不能带“学生怎样写作文”这样的小句。", "装订": "语义：“装订”的对象是纸张或书本，不能对“学生”施加动作。", "打磨": "语义：“打磨”指加工器物表面，与“学生怎样写作文”的语义不合。"}, "sentence_index": 6, "correct_answer": "教会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个例子教会了我的兴趣。", "explanation": "这里应该用〈培养〉。兴趣不能被教会，应说“培养兴趣”；“教会”的宾语须是能学会的知识或技能。"}, {"text": "爷爷教会了他年轻时的故事。", "explanation": "这里应该用〈讲述〉。“讲述”用于说故事，“教会”的宾语应是要学会的知识或技能，不能是故事。"}, {"text": "他教会了这把椅子的高度。", "explanation": "这里应该用〈测量〉。高度是需要测量的数值，“教会”的宾语须是能学会的知识或技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸教会我了骑车。", "corrected_sentence": "爸爸教会了我骑车。", "error_description": "“了”应紧跟动词“教会”，说“教会了我”；“我了”的位置不对，应写作“教会了我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈会教会了我包饺子。", "corrected_sentence": "妈妈教会了我包饺子。", "error_description": "“教会”本身已表示教到对方学会，前面不必再加能愿动词“会”；应说“妈妈教会了我包饺子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
