INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对法规、条款、规则等作出权威性说明的权力。", "primary_collocate": null, "pronunciation": "jiě shì quán", "ipa": "tɕjɛ˨˩˦ ʂɻ̩˥˩ tɕʰɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这一突破不仅大幅降低了书籍的制作成本，更使《圣经》等文本得以以前所未有的速度和数量被复制，从而打破了教会对知识解释权的垄断。", "target_word": "解释权", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "活动的最终解释权归公司所有。", "target_word": "解释权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规则的解释权在法院。", "target_word": "解释权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广告上写着，最终解释权归商家。", "target_word": "解释权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁有这部法律的解释权？", "target_word": "解释权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家法律的解释权属于全国人大常委会。", "target_word": "解释权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛规则的解释权在组委会。", "target_word": "解释权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份合同没有写清楚谁有解释权。", "target_word": "解释权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不应该随便行使最终解释权。", "target_word": "解释权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想拿回对规则的解释权。", "target_word": "解释权", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "解釋權", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对规则作权威说明的权力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d76630-55e4-4191-b05f-0cc4fbf0c071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解释权", "is_correct": true, "explanation": "正确：“解释权”指对规则或条款作权威说明的权力，此处指对知识的解释权，可被“教会”垄断。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能被垄断，“对知识天气的垄断”句义不通。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”是度量概念，不能作为被垄断的对象。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“垄断”不与“味道”搭配，“知识味道”也不成词。"}], "explanations": {"解释权": "正确：“解释权”指对规则或条款作权威说明的权力，此处指对知识的解释权，可被“教会”垄断。", "天气": "语义：“天气”不能被垄断，“对知识天气的垄断”句义不通。", "面积": "语义：“面积”是度量概念，不能作为被垄断的对象。", "味道": "搭配：“垄断”不与“味道”搭配，“知识味道”也不成词。"}, "sentence_index": 0, "correct_answer": "解释权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子的解释权归他。", "explanation": "这里应该用〈所有权〉。“解释权”指对规则作权威说明的权力，房产归属要说“所有权”。"}, {"text": "这辆车的解释权归公司。", "explanation": "这里应该用〈使用权〉。车辆的使用安排是“使用权”，“解释权”只指对规则的权威说明。"}, {"text": "这条路的解释权归公司。", "explanation": "这里应该用〈收费权〉。“收费权”指收取费用的权利，“解释权”指对规则作权威说明，不能用于道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解释权", "is_correct": true, "explanation": "正确：“解释权”指对比赛规则作权威说明的权力，由组委会掌握。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：规则没有“颜色”，与组委会掌握的权力无关，句子不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”不能属于规则，句子不通。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：“湿度”是环境指标，与比赛规则无关。"}], "explanations": {"解释权": "正确：“解释权”指对比赛规则作权威说明的权力，由组委会掌握。", "颜色": "语义：规则没有“颜色”，与组委会掌握的权力无关，句子不通。", "重量": "语义：“重量”不能属于规则，句子不通。", "湿度": "语义：“湿度”是环境指标，与比赛规则无关。"}, "sentence_index": 6, "correct_answer": "解释权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拥有这栋房子的解释权。", "explanation": "这里应该用〈继承权〉。房产的承接属于“继承权”，“解释权”指对规则的权威说明。"}, {"text": "孩子的解释权归母亲。", "explanation": "这里应该用〈抚养权〉。孩子由谁照顾属于“抚养权”，“解释权”不能这样用。"}, {"text": "他享有这笔贷款的解释权。", "explanation": "这里应该用〈优先权〉。“优先权”表示优先获得的资格，“解释权”指对规则作权威说明，不能用于贷款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一把很重要的解释权。", "corrected_sentence": "这是一项很重要的解释权。", "error_description": "“解释权”是抽象的权力，量词应用“项”，不能用“把”（“把”多用于有柄的器具）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们打开了这条规则的解释权。", "corrected_sentence": "他们拿到了这条规则的解释权。", "error_description": "动宾搭配错误：“解释权”是权力，不能“打开”，应说“拿到 / 掌握解释权”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10162, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。"}, {"text": "保持", "is_correct": false, "explanation": "无关：保持是维持原状，与“扩散”的任何义项都不构成反义。"}, {"text": "停留", "is_correct": false, "explanation": "无关：停留是停下不动，不是“扩散”的反义词。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：搬运是移动物体，与“扩散”之间没有反义关系。"}], "correct_answer": "集中", "explanations": {"集中": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。", "保持": "无关：保持是维持原状，与“扩散”的任何义项都不构成反义。", "停留": "无关：停留是停下不动，不是“扩散”的反义词。", "搬运": "无关：搬运是移动物体，与“扩散”之间没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10162, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。"}, {"text": "隐藏", "is_correct": false, "explanation": "无关：隐藏是藏起来不让人看见，与“扩散”的任何义项都不构成反义。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：打扫是清除灰尘垃圾，与“扩散”没有反义关系。"}, {"text": "砍伐", "is_correct": false, "explanation": "无关：砍伐是砍倒树木，与“扩散”之间没有反义关系。"}], "correct_answer": "集中", "explanations": {"集中": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。", "隐藏": "无关：隐藏是藏起来不让人看见，与“扩散”的任何义项都不构成反义。", "打扫": "无关：打扫是清除灰尘垃圾，与“扩散”没有反义关系。", "砍伐": "无关：砍伐是砍倒树木，与“扩散”之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10162, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物在空间或时间上向外扩展、散布。", "primary_collocate": null, "pronunciation": "kuò sàn", "ipa": "kʰwɔ˥˩ sɑn˥˩", "syllable_count": 2, "sentences": [{"text": "古腾堡印刷术的扩散，迅速重塑了欧洲的文化生态。", "target_word": "扩散", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "墨水滴进水里，慢慢扩散开了。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消息很快在网上扩散。", "target_word": "扩散", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂的烟雾向四周扩散。", "target_word": "扩散", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种病毒容易在人群中扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "香味从厨房扩散到客厅。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谣言扩散得很快，大家都知道了。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水面上的波纹向外扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防员想阻止火势继续扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "污染扩散到了河的下游。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "扩散了", "label": "完成体"}, {"form": "扩散着", "label": "持续体"}, {"form": "扩散开", "label": "复合"}, {"form": "擴散", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物向外扩展散布", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d76630-55e4-4191-b05f-0cc4fbf0c071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扩散", "is_correct": true, "explanation": "正确。“扩散”指事物向外散布、传开，可作“印刷术的扩散”的中心语，与“迅速重塑欧洲文化生态”的语义相合。"}, {"text": "午餐", "is_correct": false, "explanation": "语义：午餐是一顿饭，不能成为“迅速重塑了欧洲文化生态”的主语，句子语义不通。"}, {"text": "草坪", "is_correct": false, "explanation": "语义：草坪是一块地面，不能迅速重塑文化生态，与句中的语境不合。"}, {"text": "恐惧", "is_correct": false, "explanation": "搭配：情绪名词“恐惧”不能作“重塑”的施事，“印刷术的恐惧”也不是可接受的搭配。"}], "explanations": {"扩散": "正确。“扩散”指事物向外散布、传开，可作“印刷术的扩散”的中心语，与“迅速重塑欧洲文化生态”的语义相合。", "午餐": "语义：午餐是一顿饭，不能成为“迅速重塑了欧洲文化生态”的主语，句子语义不通。", "草坪": "语义：草坪是一块地面，不能迅速重塑文化生态，与句中的语境不合。", "恐惧": "搭配：情绪名词“恐惧”不能作“重塑”的施事，“印刷术的恐惧”也不是可接受的搭配。"}, "sentence_index": 0, "correct_answer": "扩散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年公司要把规模扩散到两倍。", "explanation": "这里应该用〈扩大〉。扩散指事物由中心向四周散开，规模、范围变大要用扩大。"}, {"text": "今年我们的收入扩散了三成。", "explanation": "这里应该用〈增加〉。扩散指向四周散开，收入这类数量的增长要用增加。"}, {"text": "这座城市的人口扩散到了三十万。", "explanation": "这里应该用〈增长〉。扩散指向四周散开，人口数量增加要用增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扩散", "is_correct": true, "explanation": "正确。“扩散”描述谣言传播的速度，与“得很快”搭配自然。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是用火加热制作食品，谣言不能被烘焙。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修指装饰房屋，谣言不能被装修，句子不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：咳嗽是人的动作，不能以“谣言”作主语，“谣言咳嗽”不成立。"}], "explanations": {"扩散": "正确。“扩散”描述谣言传播的速度，与“得很快”搭配自然。", "烘焙": "语义：烘焙是用火加热制作食品，谣言不能被烘焙。", "装修": "语义：装修指装饰房屋，谣言不能被装修，句子不通。", "咳嗽": "配价：咳嗽是人的动作，不能以“谣言”作主语，“谣言咳嗽”不成立。"}, "sentence_index": 6, "correct_answer": "扩散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在新公司扩散了很多朋友。", "explanation": "这里应该用〈结交〉。扩散指事物向四周散布，结识朋友要用结交。"}, {"text": "他想在学校扩散一支新球队。", "explanation": "这里应该用〈组建〉。扩散指事物向四周散开，组建团队要用组建。"}, {"text": "老师把试卷扩散给了全班同学。", "explanation": "这里应该用〈发放〉。扩散是向外散布，把东西分发给人要用发放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "谣言很快在网上向扩散开了。", "corrected_sentence": "谣言很快在网上扩散开了。", "error_description": "介词误用：“向”后须接处所宾语，不能直接放在动词“扩散”前，应删去“向”，说“谣言很快在网上扩散开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火势很快向四周很扩散了。", "corrected_sentence": "火势很快向四周扩散了。", "error_description": "程度副词误用：“很”不能修饰动作动词“扩散”，应删去“很”，说“火势很快向四周扩散了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
