INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10167, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "印刷工是指操作印刷机、制作印刷品的人。", "primary_collocate": null, "pronunciation": "yìn shuā gōng", "ipa": "in˥˩ ʂua˥ kʊŋ˥", "syllable_count": 3, "sentences": [{"text": "随着活字印刷术的普及，城市里的印刷工越来越多，书籍从修道院的密室流入市井街巷，识字不再是神职人员的专属技能。", "target_word": "印刷工", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这位印刷工每天都要检查纸张。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷工把新书一本本摆好。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的父亲是一名印刷工。", "target_word": "印刷工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "印刷工正在工厂里操作机器。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位印刷工印了很多报纸。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷工的手上常常沾着墨水。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当一名印刷工，印出好书。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷工先调好颜色，再开始印。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老印刷工教年轻人怎么用机器。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "印刷工人", "label": "复合"}], "register": "中性", "sense_fingerprint": "操作印刷机、制作书报等印刷品的职业人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d76630-55e4-4191-b05f-0cc4fbf0c071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10167, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印刷工", "is_correct": true, "explanation": "正确。“印刷工”指从事印刷的人，与“城市里的……越来越多”搭配自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人，不能作“越来越多”的主语，句子不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是内在状态，不能计数增多，句子不通。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”是状态，不能指代从事印刷的人，句子不通。"}], "explanations": {"印刷工": "正确。“印刷工”指从事印刷的人，与“城市里的……越来越多”搭配自然。", "天气": "语义：“天气”不是人，不能作“越来越多”的主语，句子不通。", "心情": "语义：“心情”是内在状态，不能计数增多，句子不通。", "寂静": "语义：“寂静”是状态，不能指代从事印刷的人，句子不通。"}, "sentence_index": 0, "correct_answer": "印刷工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的父亲每天在家里给印刷工换零件。", "explanation": "这里应该用〈印刷机〉。换零件的对象是机器，印刷工指人，不能这样用。"}, {"text": "他的父亲在印刷工里工作。", "explanation": "这里应该用〈印刷厂〉。印刷工指从事印刷的人，表示工作的地点要用印刷厂。"}, {"text": "他的父亲每天在操作印刷工。", "explanation": "这里应该用〈印刷机〉。操作的对象是机器，印刷工指人，应说“操作印刷机”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10167, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印刷工", "is_correct": true, "explanation": "正确。“印刷工”是人，手上常沾墨水符合印刷工的工作特点。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞没有手，不能沾着墨水。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会有手，也不会沾墨水，句子语义不通。"}, {"text": "云朵", "is_correct": false, "explanation": "配价：“的手”要求有手的人或生物作领属，“云朵”不能拥有手。"}], "explanations": {"印刷工": "正确。“印刷工”是人，手上常沾墨水符合印刷工的工作特点。", "雨伞": "语义：雨伞没有手，不能沾着墨水。", "石头": "语义：石头不会有手，也不会沾墨水，句子语义不通。", "云朵": "配价：“的手”要求有手的人或生物作领属，“云朵”不能拥有手。"}, "sentence_index": 6, "correct_answer": "印刷工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "印刷工在医院里给病人做手术。", "explanation": "这里应该用〈医生〉。印刷工指操作印刷机、制作印刷品的人，做手术要用医生。"}, {"text": "印刷工在法庭上为被告辩护。", "explanation": "这里应该用〈律师〉。印刷工与法庭辩护无关，为被告辩护要用律师。"}, {"text": "印刷工在课堂上给小学生讲数学。", "explanation": "这里应该用〈老师〉。印刷工负责印刷，给小学生讲数学要用老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的舅舅是一只印刷工。", "corrected_sentence": "我的舅舅是一名印刷工。", "error_description": "量词错误：指人的“印刷工”应用量词“名”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表哥是一名很印刷工。", "corrected_sentence": "表哥是一名印刷工。", "error_description": "程度副词误用：“很”不能修饰名词“印刷工”，应删去“很”，说“表哥是一名印刷工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
