INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10169, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示比喻或比较，相当于“像”或“如同”。", "primary_collocate": null, "pronunciation": "rú", "ipa": "ʐu˧˥", "syllable_count": 1, "sentences": [{"text": "她的声音如泉水一样清澈。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜晚的湖面平静如镜。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的笑脸如春天的花朵。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间如流水，一去不回。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体壮如牛。", "target_word": "如", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的风景美如画。", "target_word": "如", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的话如一盏灯，照亮了我。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪花如白色的羽毛，轻轻落下。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲的爱如大山一样深厚。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得快如闪电。", "target_word": "如", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "如同", "label": "复合"}], "register": "书面语", "sense_fingerprint": "用于比喻，表示甲像乙，相当于“像”“如同”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 雪花 (Zipf 3.64), 羽毛 (Zipf 3.77), 落下 (Zipf 3.98)']::text[], '46d76630-55e4-4191-b05f-0cc4fbf0c071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10169, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "如", "is_correct": true, "explanation": "如（rú，第二声）是比喻义的“像”“如同”。"}, {"text": "入", "is_correct": false, "explanation": "rù（第四声）与 rú（第二声）声调不同，意思是进入。"}, {"text": "乳", "is_correct": false, "explanation": "rǔ（第三声）与 rú（第二声）声调不同，意思是乳汁。"}, {"text": "辱", "is_correct": false, "explanation": "rǔ（第三声）与 rú（第二声）声调不同，意思是侮辱。"}, {"text": "炉", "is_correct": false, "explanation": "lú 与 rú 声母不同（l／r），意思是炉子。"}], "explanations": {"如": "如（rú，第二声）是比喻义的“像”“如同”。", "入": "rù（第四声）与 rú（第二声）声调不同，意思是进入。", "乳": "rǔ（第三声）与 rú（第二声）声调不同，意思是乳汁。", "辱": "rǔ（第三声）与 rú（第二声）声调不同，意思是侮辱。", "炉": "lú 与 rú 声母不同（l／r），意思是炉子。"}, "sentence_index": null, "correct_answer": "如"}, "level_3": {"options": [{"text": "如", "is_correct": true, "explanation": "如用于比喻，“她的声音如泉水一样清澈”即声音像泉水一样清澈。"}, {"text": "具有", "is_correct": false, "explanation": "配价：“具有”要求抽象的属性或事物作宾语，“清澈”是形容词，不能接在它后面作宾语。"}, {"text": "用", "is_correct": false, "explanation": "语义：“用”表示使用某物，声音不能被“用”来比作泉水。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”搭配帽子、眼镜等物品，不能用于声音。"}], "explanations": {"如": "如用于比喻，“她的声音如泉水一样清澈”即声音像泉水一样清澈。", "具有": "配价：“具有”要求抽象的属性或事物作宾语，“清澈”是形容词，不能接在它后面作宾语。", "用": "语义：“用”表示使用某物，声音不能被“用”来比作泉水。", "戴": "搭配：“戴”搭配帽子、眼镜等物品，不能用于声音。"}, "sentence_index": 0, "correct_answer": "如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这孩子长得如他父亲。", "explanation": "这里应该用〈像〉（长得像，表示外貌相似）。“如”不用于“长得”之后表示外貌相似，口语中不说“长得如”。"}, {"text": "他说话如老师，总爱讲道理。", "explanation": "这里应该用〈像〉（说话像老师，表示行为相似）。“如”不用于这种人物行为的比拟。"}, {"text": "他的个子如我一样高。", "explanation": "这里应该用〈和……一样〉表示同等程度的比较（个子和我一样高）。“如”不单独用于此类比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10169, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "如", "is_correct": true, "explanation": "如（rú，第二声）是比喻义的“像”“如同”。"}, {"text": "奴", "is_correct": false, "explanation": "nú 与 rú 声母不同（n／r），意思是奴隶。"}, {"text": "芦", "is_correct": false, "explanation": "lú 与 rú 声母不同（l／r），意思是芦苇。"}, {"text": "余", "is_correct": false, "explanation": "yú 与 rú 声母不同（y／r），意思是剩下的。"}], "explanations": {"如": "如（rú，第二声）是比喻义的“像”“如同”。", "奴": "nú 与 rú 声母不同（n／r），意思是奴隶。", "芦": "lú 与 rú 声母不同（l／r），意思是芦苇。", "余": "yú 与 rú 声母不同（y／r），意思是剩下的。"}, "sentence_index": null, "correct_answer": "如"}, "level_3": {"options": [{"text": "如", "is_correct": true, "explanation": "如用于比喻，“老师的话如一盏灯”即老师的话像一盏灯。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”需要买的人和所买的东西，“老师的话”不能去买灯。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关”指关闭开关，与后面的“照亮了我”矛盾，句子不通。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”的宾语多是道理、故事，不能说“讲一盏灯”。"}], "explanations": {"如": "如用于比喻，“老师的话如一盏灯”即老师的话像一盏灯。", "买": "语义：“买”需要买的人和所买的东西，“老师的话”不能去买灯。", "关": "语义：“关”指关闭开关，与后面的“照亮了我”矛盾，句子不通。", "讲": "搭配：“讲”的宾语多是道理、故事，不能说“讲一盏灯”。"}, "sentence_index": 6, "correct_answer": "如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他如是喝醉了。", "explanation": "这里应该用〈像是〉表示推测（看起来像喝醉了）。“如”在此不表示推测。"}, {"text": "她如像没听懂我的话。", "explanation": "这里应该用〈似乎〉表示推测（看起来没听懂）。“如”与“像”不能并用，且不表示推测。"}, {"text": "天色如好像要下雨了。", "explanation": "这里应该只用〈好像〉表示推测。“如”与“好像”不能并用，“如”也不表示推测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的脸色如白纸苍白。", "corrected_sentence": "他的脸色如白纸一样苍白。", "error_description": "错误：“如白纸苍白”句式残缺，“如……”放在形容词前时要用“如……一样”。正确：“如白纸一样苍白”（也可说“苍白如纸”，即形容词在前、“如”在后）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河清如了镜子。", "corrected_sentence": "这条河清如镜子。", "error_description": "错误：“如”后面加了“了”，写成“清如了镜子”。正确：“清如镜子”，比喻句中“如”后直接接名词，不能带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
