INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10170, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻新事物大量出现，发展迅速。", "primary_collocate": null, "pronunciation": "yǔ hòu chūn sǔn", "ipa": "y˨˩ xoʊ˥˩ tʂʰwən˥ swən˨˩", "syllable_count": 4, "sentences": [{"text": "城市中的印刷工坊如雨后春笋般涌现，书籍从修道院的密室流入市井街巷，识字不再是神职人员的专属技能，市民阶层、商人乃至部分工匠开始主动学习阅读。", "target_word": "雨后春笋", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这几年，新的咖啡店像雨后春笋一样出现在街上。", "target_word": "雨后春笋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动车工厂如雨后春笋般建了起来。", "target_word": "雨后春笋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的健身房像雨后春笋一样多。", "target_word": "雨后春笋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的小店如雨后春笋般冒出来，每天都有新店开业。", "target_word": "雨后春笋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，新能源公司如雨后春笋般出现。", "target_word": "雨后春笋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校附近的补习班像雨后春笋，越开越多。", "target_word": "雨后春笋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机软件如雨后春笋般不断出现。", "target_word": "雨后春笋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小城里，新的饭馆如雨后春笋般开了起来。", "target_word": "雨后春笋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政策好了以后，小公司像雨后春笋一样多起来。", "target_word": "雨后春笋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "比喻义：新事物像雨后的竹笋一样大量、快速地出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b46612-8cc8-4c8a-ad20-a3f56ae151b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨后春笋", "is_correct": true, "explanation": "「雨后春笋」作比喻，指新事物像雨后竹笋一样大量、迅速出现，与「如……般涌现」的句意相符。"}, {"text": "深秋", "is_correct": false, "explanation": "语义：深秋是季节，不能像印刷工坊那样涌现，句意不通。"}, {"text": "寒冬", "is_correct": false, "explanation": "语义：寒冬是季节，不会「涌现」，与印刷工坊的兴起无关。"}, {"text": "泥土", "is_correct": false, "explanation": "搭配：「涌现」不与泥土这类具体物质搭配，不能说泥土般涌现。"}], "explanations": {"雨后春笋": "「雨后春笋」作比喻，指新事物像雨后竹笋一样大量、迅速出现，与「如……般涌现」的句意相符。", "深秋": "语义：深秋是季节，不能像印刷工坊那样涌现，句意不通。", "寒冬": "语义：寒冬是季节，不会「涌现」，与印刷工坊的兴起无关。", "泥土": "搭配：「涌现」不与泥土这类具体物质搭配，不能说泥土般涌现。"}, "sentence_index": 0, "correct_answer": "雨后春笋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座古城里的老寺庙像雨后春笋一样，一座座冒了出来。", "explanation": "「雨后春笋」比喻新事物大量、迅速出现，这里说的是古老的寺庙，与「新」的词义相矛盾。"}, {"text": "这一带的旧书店像雨后春笋一样，一家家消失了。", "explanation": "「雨后春笋」只形容新事物大量、迅速出现，不能用来说事物一家家消失，前后语义相反。"}, {"text": "我家门口只冒出了一家小店，却像雨后春笋一样。", "explanation": "「雨后春笋」强调数量多、接连出现，只出现一家时不能用这个比喻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨后春笋", "is_correct": true, "explanation": "「雨后春笋」作比喻，说补习班大量涌现，与「越开越多」的语义呼应。"}, {"text": "旧书", "is_correct": false, "explanation": "搭配：书不说「开」，「越开越多」不能用于旧书。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：阳光不能说「开」，与「越开越多」不搭配。"}, {"text": "秋雨", "is_correct": false, "explanation": "语义：秋雨是天气，不能被说成越开越多的店铺式增长，句意不通。"}], "explanations": {"雨后春笋": "「雨后春笋」作比喻，说补习班大量涌现，与「越开越多」的语义呼应。", "旧书": "搭配：书不说「开」，「越开越多」不能用于旧书。", "阳光": "搭配：阳光不能说「开」，与「越开越多」不搭配。", "秋雨": "语义：秋雨是天气，不能被说成越开越多的店铺式增长，句意不通。"}, "sentence_index": 6, "correct_answer": "雨后春笋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到这个好消息，他高兴得像雨后春笋一样。", "explanation": "「雨后春笋」只形容新事物大量、迅速出现，不能用来比喻人的心情。"}, {"text": "这家老店开了五十年，生意像雨后春笋一样慢慢稳定下来。", "explanation": "「雨后春笋」比喻新事物短时间内大量涌现，不能形容一家老店长期、缓慢的稳定发展。"}, {"text": "这片竹林慢慢地像雨后春笋一样长大。", "explanation": "「雨后春笋」强调短时间内快速冒出，不能用来描写慢慢发生的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年，学校附近的奶茶店在雨后春笋一样多起来了。", "corrected_sentence": "这几年，学校附近的奶茶店像雨后春笋一样多起来了。", "error_description": "错误：比喻句的引导词用错。比喻要用「像……一样」，不能用「在」。正确形式是「像雨后春笋一样多起来了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城里的新书店像雨后春笋一起多起来了。", "corrected_sentence": "城里的新书店像雨后春笋一样多起来了。", "error_description": "错误：比较结构用错。「像……一样」中的「一样」不能换成「一起」，应为「像雨后春笋一样多起来了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
