INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10171, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大量新事物或新现象同时出现。", "primary_collocate": null, "pronunciation": "yǒng xiàn", "ipa": "jʊŋ˨˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "近年来，网络上涌现出许多新词。", "target_word": "涌现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新技术出现以后，各种新工作也涌现了。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中涌现出一批优秀的年轻选手。", "target_word": "涌现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时代涌现了很多伟大的科学家。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，各种新的旅游方式不断涌现。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家说完以后，新的想法不断涌现。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艺术节上涌现出不少有才华的学生。", "target_word": "涌现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年，城市里涌现过不少新的行业。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了那本书以后，我的脑海里涌现出很多想法。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络时代，各种新的网站不断涌现。", "target_word": "涌现", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "涌现了", "label": "体标"}, {"form": "涌现过", "label": "体标"}], "register": "书面", "sense_fingerprint": "大量新人、新事物、新现象在一段时间里接连出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b46612-8cc8-4c8a-ad20-a3f56ae151b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10171, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "涌现", "is_correct": true, "explanation": "「涌现」表示大量新事物同时出现，与「近年来」「许多新词」搭配。"}, {"text": "收割", "is_correct": false, "explanation": "语义：收割针对庄稼，网络上没有庄稼可以收割，句意不通。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：砍伐针对树木，与「新词」无关，句意不通。"}, {"text": "酿造", "is_correct": false, "explanation": "搭配：「酿造」多接酒、醋等，不说酿造新词。"}], "explanations": {"涌现": "「涌现」表示大量新事物同时出现，与「近年来」「许多新词」搭配。", "收割": "语义：收割针对庄稼，网络上没有庄稼可以收割，句意不通。", "砍伐": "语义：砍伐针对树木，与「新词」无关，句意不通。", "酿造": "搭配：「酿造」多接酒、醋等，不说酿造新词。"}, "sentence_index": 0, "correct_answer": "涌现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个时代只涌现了一点点伟大的科学家。", "explanation": "〈涌现〉指大量新事物同时出现，与「只」「一点点」的少量语义相矛盾，这里应该用〈出现〉。"}, {"text": "这个地区的人口正在涌现，每年都在减少。", "explanation": "〈涌现〉表示新事物大量出现，不能用来描述数量的减少，这句话前后语义矛盾。"}, {"text": "书架上的旧书一本本涌现出来。", "explanation": "这里应该用〈拿出〉。涌现指新事物大量同时出现，旧书一本本被取出不是涌现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "涌现", "is_correct": true, "explanation": "「涌现」表示大量人才一起冒出来，与「艺术节上」「不少有才华的学生」搭配。"}, {"text": "淘汰", "is_correct": false, "explanation": "语义：淘汰是剔除，与「有才华」的描述相矛盾。"}, {"text": "剔除", "is_correct": false, "explanation": "语义：剔除是去掉，与「有才华」的学生相矛盾，句意相反。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：驱赶是赶走，与艺术节上出现有才华学生的句意相反。"}], "explanations": {"涌现": "「涌现」表示大量人才一起冒出来，与「艺术节上」「不少有才华的学生」搭配。", "淘汰": "语义：淘汰是剔除，与「有才华」的描述相矛盾。", "剔除": "语义：剔除是去掉，与「有才华」的学生相矛盾，句意相反。", "驱赶": "语义：驱赶是赶走，与艺术节上出现有才华学生的句意相反。"}, "sentence_index": 6, "correct_answer": "涌现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府一下子涌现了很多新政策。", "explanation": "这里应该用〈出台〉。涌现指新事物自己大量出现，没有施事者；政府主动推出政策要用〈出台〉。"}, {"text": "人群一下子涌现到了广场上。", "explanation": "〈涌现〉指很多新事物一下子冒出，不表示人群向某处聚集，这里应该用〈涌向〉。"}, {"text": "这座城市里涌现了很多古老的寺庙。", "explanation": "〈涌现〉指新事物大量出现，不能用来描述早已存在、古老的寺庙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一年，市场上被涌现出许多新的小品牌。", "corrected_sentence": "这一年，市场上涌现出许多新的小品牌。", "error_description": "错误：「涌现」是不及物动词，不能用「被」字句，「被涌现」是错误的说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年，学校附近涌现起不少新的培训班。", "corrected_sentence": "这几年，学校附近涌现出不少新的培训班。", "error_description": "错误：趋向补语错误。「涌现」后应接「出」，「涌现起」不能表示这个意思。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
