INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "修道院是基督教、佛教等宗教中，修道士或修女集体居住、修行和生活的地方。", "primary_collocate": null, "pronunciation": "xiū dào yuàn", "ipa": "ɕjoʊ˥ taʊ˥˩ ɥɛn˥˩", "syllable_count": 3, "sentences": [{"text": "这座修道院建在山顶上，已经有八百年了。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修女们每天早上在修道院里祈祷。", "target_word": "修道院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年轻时进了修道院，再也没有回家。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修道院的院子里种着葡萄和蔬菜。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们参观了山里的一座修道院。", "target_word": "修道院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候，修道院里的人会抄写书。", "target_word": "修道院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座修道院欢迎游客，但是晚上不开门。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修道院里很安静，只能听到钟声。", "target_word": "修道院", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老修士一辈子都住在这座修道院里。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修道院旁边有一家小商店，卖蜂蜜和面包。", "target_word": "修道院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "所", "label": "量词"}], "register": "中性", "sense_fingerprint": "宗教团体中修士或修女集体居住和修行的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b46612-8cc8-4c8a-ad20-a3f56ae151b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修道院", "is_correct": true, "explanation": "修道院是修士、修女集体居住修行的地方，可以建在山顶上，与“已经有八百年了”相符。"}, {"text": "地铁站", "is_correct": false, "explanation": "语义：地铁是近代才有的交通设施，不可能已经存在八百年。"}, {"text": "海港", "is_correct": false, "explanation": "搭配：“海港”需要临海，不能说建在山顶上。"}, {"text": "电视台", "is_correct": false, "explanation": "语义：电视是近代发明的，与“已经有八百年了”矛盾。"}], "explanations": {"修道院": "修道院是修士、修女集体居住修行的地方，可以建在山顶上，与“已经有八百年了”相符。", "地铁站": "语义：地铁是近代才有的交通设施，不可能已经存在八百年。", "海港": "搭配：“海港”需要临海，不能说建在山顶上。", "电视台": "语义：电视是近代发明的，与“已经有八百年了”矛盾。"}, "sentence_index": 0, "correct_answer": "修道院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈在修道院工作，她是出租车司机。", "explanation": "这里应该用〈出租车公司〉。修道院是修士、修女修行生活的场所，出租车司机不在这里工作。"}, {"text": "工人们在修道院里生产汽车。", "explanation": "这里应该用〈工厂〉。修道院是修士、修女修行生活的场所，生产汽车要在工厂。"}, {"text": "那个小偷每天晚上在修道院里跳舞，跳到半夜才回家。", "explanation": "这里应该用〈舞厅〉。修道院是修士、修女修行生活的场所，不是跳舞的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修道院", "is_correct": true, "explanation": "修道院是修行的场所，白天可以开放，晚上关门，符合“这座修道院欢迎游客，但是晚上不开门”。"}, {"text": "夜总会", "is_correct": false, "explanation": "语义：夜总会是晚上营业的场所，与“晚上不开门”矛盾。"}, {"text": "垃圾场", "is_correct": false, "explanation": "搭配：“欢迎游客”一般不用于垃圾场这样的地方。"}, {"text": "夜市", "is_correct": false, "explanation": "语义：夜市是晚上营业的，与“晚上不开门”矛盾。"}], "explanations": {"修道院": "修道院是修行的场所，白天可以开放，晚上关门，符合“这座修道院欢迎游客，但是晚上不开门”。", "夜总会": "语义：夜总会是晚上营业的场所，与“晚上不开门”矛盾。", "垃圾场": "搭配：“欢迎游客”一般不用于垃圾场这样的地方。", "夜市": "语义：夜市是晚上营业的，与“晚上不开门”矛盾。"}, "sentence_index": 6, "correct_answer": "修道院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个月都去修道院取钱。", "explanation": "这里应该用〈银行〉。修道院是修行的场所，不办理存取款业务。"}, {"text": "我每天早上去修道院游泳。", "explanation": "这里应该用〈游泳馆〉。修道院不是体育场所，游泳要去游泳馆。"}, {"text": "他们今天下午在修道院坐飞机出国。", "explanation": "这里应该用〈机场〉。修道院不是乘坐航班的地方，坐飞机要去机场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只修道院里住着很多修女。", "corrected_sentence": "这座修道院里住着很多修女。", "error_description": "量词错误：“修道院”是建筑，应说“这座修道院”，不能说“这只修道院”（“只”多用于动物）。正确形式是“这座修道院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "修女们在修道院上唱歌。", "corrected_sentence": "修女们在修道院里唱歌。", "error_description": "方位错误：“修道院”是建筑，应用方位词“里”，不能用“上”。“在……上”多用于桌面、墙面等表面，不能说“在修道院上”。正确形式是“在修道院里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
