INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10173, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10173, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来做秘密事情或藏东西的房间。", "primary_collocate": null, "pronunciation": "mì shì", "ipa": "mi˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "城市中的印刷工坊如雨后春笋般涌现，书籍从修道院的密室流入市井街巷，识字不再是神职人员的专属技能，市民阶层、商人乃至部分工匠开始主动学习阅读。", "target_word": "密室", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他在家里有一间密室，里面藏着很多旧信。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在墙后发现了一间密室。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王常常一个人走进密室，想办法对付敌人。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架后面有一扇小门，门后就是密室。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在密室里小声商量，不想让别人听见。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把贵重的东西都放在密室里。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的密室很小，只能放下一张桌子。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在老房子里找到了通向密室的楼梯。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "侦探走进密室，发现桌上有一封信。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一间密室", "label": "量词"}], "register": "中性", "sense_fingerprint": "用来做秘密事情或藏东西的隐蔽房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b46612-8cc8-4c8a-ad20-a3f56ae151b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10173, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "密室", "is_correct": true, "explanation": "密室 mì shì，意思是秘密的房间，用来藏东西或做秘密的事。"}, {"text": "秘书", "is_correct": false, "explanation": "秘书 mì shū 与 密室 mì shì 第二个音节韵母不同（ū 与 ì），意思是协助领导处理事务的人。"}, {"text": "密使", "is_correct": false, "explanation": "密使 mì shǐ 与 密室 mì shì 第二个音节声调不同（第三声与第四声），意思是秘密派遣的使者。"}, {"text": "密实", "is_correct": false, "explanation": "密实 mì shí 与 密室 mì shì 第二个音节声调不同（第二声与第四声），意思是紧密结实。"}, {"text": "闭市", "is_correct": false, "explanation": "闭市 bì shì 与 密室 mì shì 声母不同（b 与 m），意思是市场关门。"}], "explanations": {"密室": "密室 mì shì，意思是秘密的房间，用来藏东西或做秘密的事。", "秘书": "秘书 mì shū 与 密室 mì shì 第二个音节韵母不同（ū 与 ì），意思是协助领导处理事务的人。", "密使": "密使 mì shǐ 与 密室 mì shì 第二个音节声调不同（第三声与第四声），意思是秘密派遣的使者。", "密实": "密实 mì shí 与 密室 mì shì 第二个音节声调不同（第二声与第四声），意思是紧密结实。", "闭市": "闭市 bì shì 与 密室 mì shì 声母不同（b 与 m），意思是市场关门。"}, "sentence_index": null, "correct_answer": "密室"}, "level_3": {"options": [{"text": "密室", "is_correct": true, "explanation": "密室是隐蔽的藏东西的房间，书籍可以从这里流出，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：书籍不会从厨房流入市井，厨房不是藏书的地方。"}, {"text": "水井", "is_correct": false, "explanation": "语义：水井用来打水，书籍不可能存放在井里再流入市井。"}, {"text": "马厩", "is_correct": false, "explanation": "搭配：“书籍从……流入市井”的来源不搭配马厩。"}], "explanations": {"密室": "密室是隐蔽的藏东西的房间，书籍可以从这里流出，符合句意。", "厨房": "语义：书籍不会从厨房流入市井，厨房不是藏书的地方。", "水井": "语义：水井用来打水，书籍不可能存放在井里再流入市井。", "马厩": "搭配：“书籍从……流入市井”的来源不搭配马厩。"}, "sentence_index": 0, "correct_answer": "密室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们走进密室上课。", "explanation": "这里应该用〈教室〉。密室是秘密的房间，不是上课的地方。"}, {"text": "孩子们在密室里游泳。", "explanation": "这里应该用〈游泳池〉。密室是藏东西或做秘密事情的房间，不能游泳。"}, {"text": "他每个月去密室剪头发。", "explanation": "这里应该用〈理发店〉。密室是隐蔽的房间，剪头发要去理发店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密室", "is_correct": true, "explanation": "密室是藏东西的隐蔽房间，适合放贵重的东西，符合句意。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园不是存放贵重物品的地方。"}, {"text": "游泳池", "is_correct": false, "explanation": "搭配：贵重的东西不说放在游泳池里。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是卖菜的地方，不适合存放贵重的东西。"}], "explanations": {"密室": "密室是藏东西的隐蔽房间，适合放贵重的东西，符合句意。", "动物园": "语义：动物园不是存放贵重物品的地方。", "游泳池": "搭配：贵重的东西不说放在游泳池里。", "菜市场": "语义：菜市场是卖菜的地方，不适合存放贵重的东西。"}, "sentence_index": 6, "correct_answer": "密室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈走进密室做饭。", "explanation": "这里应该用〈厨房〉。密室是隐蔽的房间，做饭要在厨房。"}, {"text": "旅客们在密室里等车。", "explanation": "这里应该用〈车站〉。密室不是等车的地方，等车要去车站。"}, {"text": "小朋友们在密室里玩滑梯。", "explanation": "这里应该用〈游乐场〉。密室是藏东西的房间，玩滑梯要去游乐场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老宅里藏着一座密室。", "corrected_sentence": "这座老宅里藏着一间密室。", "error_description": "量词错误：“密室”是房间，应用“间”，不能用“座”（“座”用于山、桥、楼等大型建筑）。正确形式是“一间密室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在密室上找到了一封信。", "corrected_sentence": "他们在密室里找到了一封信。", "error_description": "方位错误：“密室”是房间，应用方位词“里”，不能用“上”。“在……上”多用于桌面、墙面等表面，不能说“在密室上”。正确形式是“在密室里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10174, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流出", "is_correct": true, "explanation": "反义：流出指液体等从里面流到外面，与“流入”方向相反。"}, {"text": "停留", "is_correct": false, "explanation": "停留指暂时停在某处，与“流入”的移动义无反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "保存指保持不失，与“流入”无反义关系。"}, {"text": "聚集", "is_correct": false, "explanation": "聚集指集中到一起，与“流入”不构成反义。"}], "correct_answer": "流出", "explanations": {"流出": "反义：流出指液体等从里面流到外面，与“流入”方向相反。", "停留": "停留指暂时停在某处，与“流入”的移动义无反义关系。", "保存": "保存指保持不失，与“流入”无反义关系。", "聚集": "聚集指集中到一起，与“流入”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10174, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "流出", "is_correct": true, "explanation": "反义：流出指液体等从里面流到外面，与“流入”方向相反。"}, {"text": "堆积", "is_correct": false, "explanation": "堆积指东西一层层聚在一起，与“流入”无反义关系。"}, {"text": "封闭", "is_correct": false, "explanation": "封闭指使与外界隔绝，与“流入”无反义关系。"}, {"text": "隐藏", "is_correct": false, "explanation": "隐藏指藏起来不让人看见，与“流入”无反义关系。"}], "correct_answer": "流出", "explanations": {"流出": "反义：流出指液体等从里面流到外面，与“流入”方向相反。", "堆积": "堆积指东西一层层聚在一起，与“流入”无反义关系。", "封闭": "封闭指使与外界隔绝，与“流入”无反义关系。", "隐藏": "隐藏指藏起来不让人看见，与“流入”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10174, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "液体或气体等物质向某个方向移动，进入某个范围或区域。", "primary_collocate": null, "pronunciation": "liú rù", "ipa": "ljoʊ˧˥ ɻu˥˩", "syllable_count": 2, "sentences": [{"text": "河水从山上流入大海。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水顺着窗户流入屋里。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开门以后，冷空气流入房间。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河流入湖里，湖水慢慢变多了。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江从西向东，最后流入东海。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水流入河里，鱼都死了。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得很大，水很快流入了地下室。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤气从坏管子流入厨房，屋里有一股味道。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水龙头关好了，水还是慢慢流入桶里。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水流入街道，车都开不过去了。", "target_word": "流入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流入了", "label": "体标"}, {"form": "流入过", "label": "体标"}, {"form": "流入量", "label": "复合"}], "register": "中性", "sense_fingerprint": "液体或气体向某处移动并进入其中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b46612-8cc8-4c8a-ad20-a3f56ae151b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10174, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "溜入", "is_correct": false, "explanation": "溜入 liū rù 与 流入 liú rù 第一个音节声调不同（第一声与第二声），意思是悄悄进入。"}, {"text": "留住", "is_correct": false, "explanation": "留住 liú zhù 与 流入 liú rù 第二个音节声母不同（zh 与 r），意思是保留、不让离开。"}, {"text": "流露", "is_correct": false, "explanation": "流露 liú lù 与 流入 liú rù 第二个音节声母不同（l 与 r），意思是不自觉地表现出来。"}, {"text": "流入", "is_correct": true, "explanation": "正确答案：流入 liú rù，指液体或气体流进某个范围。"}], "explanations": {"溜入": "溜入 liū rù 与 流入 liú rù 第一个音节声调不同（第一声与第二声），意思是悄悄进入。", "留住": "留住 liú zhù 与 流入 liú rù 第二个音节声母不同（zh 与 r），意思是保留、不让离开。", "流露": "流露 liú lù 与 流入 liú rù 第二个音节声母不同（l 与 r），意思是不自觉地表现出来。", "流入": "正确答案：流入 liú rù，指液体或气体流进某个范围。"}, "sentence_index": null, "correct_answer": "流入"}, "level_3": {"options": [{"text": "流入", "is_correct": true, "explanation": "正确：流入指水流进某处，与“河水”和“大海”的语义相符。"}, {"text": "跳入", "is_correct": false, "explanation": "语义：“跳入”的主体须能跳，河水不能跳进大海。"}, {"text": "游入", "is_correct": false, "explanation": "语义：“游”需要有生命的主体，河水不能游入大海。"}, {"text": "倒入", "is_correct": false, "explanation": "配价：“倒入”需要有人或器具施动，河水不能充当倒的主体。"}], "explanations": {"流入": "正确：流入指水流进某处，与“河水”和“大海”的语义相符。", "跳入": "语义：“跳入”的主体须能跳，河水不能跳进大海。", "游入": "语义：“游”需要有生命的主体，河水不能游入大海。", "倒入": "配价：“倒入”需要有人或器具施动，河水不能充当倒的主体。"}, "sentence_index": 0, "correct_answer": "流入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他流入了房间，正在找东西。", "explanation": "这里应该用〈走进〉。流入只用于液体、气体等流动的物质，人走进房间要说“走进”。"}, {"text": "蛇流入了草丛，很快就不见了。", "explanation": "这里应该用〈钻入〉。流入的主语应是液体或气体，蛇是动物，钻进草丛要说“钻入”。"}, {"text": "石头流入了湖里，咚的一声。", "explanation": "这里应该用〈落入〉。流入形容液体、气体的流动，石头这样的固体掉进湖里要说“落入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流入", "is_correct": true, "explanation": "正确：流入表示水流进地下室，与“雨大、水很快”的语境相符。"}, {"text": "驶入", "is_correct": false, "explanation": "语义：“驶”的主体须是车船等交通工具，水不能驶入地下室。"}, {"text": "运入", "is_correct": false, "explanation": "配价：“运入”需要有人或车辆把东西运进去，水不能充当运送的主体。"}, {"text": "爬入", "is_correct": false, "explanation": "语义：“爬”的主体须是能爬行的生物，水不能爬进地下室。"}], "explanations": {"流入": "正确：流入表示水流进地下室，与“雨大、水很快”的语境相符。", "驶入": "语义：“驶”的主体须是车船等交通工具，水不能驶入地下室。", "运入": "配价：“运入”需要有人或车辆把东西运进去，水不能充当运送的主体。", "爬入": "语义：“爬”的主体须是能爬行的生物，水不能爬进地下室。"}, "sentence_index": 6, "correct_answer": "流入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车流入了隧道，很快就不见了。", "explanation": "这里应该用〈驶入〉。流入只用于液体、气体等流动的物质，汽车开进隧道要说“驶入”。"}, {"text": "皮球流入了床底下，找不到了。", "explanation": "这里应该用〈滚入〉。流入只用于液体、气体等流动的物质，皮球滚进床底下要说“滚入”。"}, {"text": "客人流入了大厅，很快就不见了。", "explanation": "这里应该用〈走入〉。流入只用于液体、气体等流动的物质，客人走进大厅要说“走入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水顺着墙缝流入进了屋里。", "corrected_sentence": "雨水顺着墙缝流入了屋里。", "error_description": "错误：“流入”本身已含“进入”的意思，后面又加了“进”，形成重复。正确应说“流入了屋里”或“流进了屋里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨停以后，积水被流入了排水沟。", "corrected_sentence": "雨停以后，积水流入了排水沟。", "error_description": "错误：“流入”是不及物动词，不能用“被”字句。正确应为“积水流入了排水沟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
