INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10175, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "市井原指古代城市中的市场或街市，现在常用来指普通市民生活的环境或社会底层。", "primary_collocate": null, "pronunciation": "shì jǐng", "ipa": "ʂɻ̩˥˩ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "城市中的印刷工坊如雨后春笋般涌现，书籍从修道院的密室流入市井街巷，识字不再是神职人员的专属技能，市民阶层、商人乃至部分工匠开始主动学习阅读。", "target_word": "市井", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他从小在市井长大，认识很多小店老板。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家喜欢写市井生活。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老北京的市井文化很有意思。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是大官，只是市井中的普通人。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影让我看到了市井里的小人物。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市井里的小吃摊总是很热闹。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢听市井里的老故事。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画里有很多市井小民的笑脸。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，市井的灯一盏一盏亮了起来。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市井生活", "label": "复合"}, {"form": "市井小民", "label": "复合"}, {"form": "市井文化", "label": "复合"}], "register": "书面", "sense_fingerprint": "街市，普通市民生活的环境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b46612-8cc8-4c8a-ad20-a3f56ae151b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10175, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市井", "is_correct": true, "explanation": "正确：市井街巷指市民聚居的街市，与“印刷工坊”和“市民阶层”的语境相符。"}, {"text": "宫廷", "is_correct": false, "explanation": "搭配：“宫廷街巷”不成词组，且与“市民阶层”的语境不符。"}, {"text": "田野", "is_correct": false, "explanation": "搭配：田野没有街巷，“田野街巷”不成词组。"}, {"text": "乡野", "is_correct": false, "explanation": "语义：“乡野”与前文“城市中的印刷工坊”的语境相反，书籍应流入城市的街巷。"}], "explanations": {"市井": "正确：市井街巷指市民聚居的街市，与“印刷工坊”和“市民阶层”的语境相符。", "宫廷": "搭配：“宫廷街巷”不成词组，且与“市民阶层”的语境不符。", "田野": "搭配：田野没有街巷，“田野街巷”不成词组。", "乡野": "语义：“乡野”与前文“城市中的印刷工坊”的语境相反，书籍应流入城市的街巷。"}, "sentence_index": 0, "correct_answer": "市井"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座市井有几百万人口。", "explanation": "这里应该用〈城市〉。市井指街市或市民的生活环境，不能用来指整座城市的人口规模。"}, {"text": "我的市井每天早上来找我一起跑步。", "explanation": "这里应该用〈朋友〉。市井指街市或市民的生活环境，是地方，不指人，找我一起跑步的应说“朋友”。"}, {"text": "我的市井每天教我们读书。", "explanation": "这里应该用〈老师〉。市井指地方，不指教书的人，教我们读书的应说“老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10175, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市井", "is_correct": true, "explanation": "正确：市井指市民聚居的街市，小吃摊多设在这样的地方，与句意相符。"}, {"text": "太空", "is_correct": false, "explanation": "语义：太空中没有市民和小吃摊，“太空里的小吃摊总是很热闹”不合常理。"}, {"text": "深海", "is_correct": false, "explanation": "语义：深海中没有市民和小吃摊，“深海里的小吃摊总是很热闹”不合常理。"}, {"text": "月球", "is_correct": false, "explanation": "语义：月球上没有市民和小吃摊，“月球里的小吃摊总是很热闹”不合常理。"}], "explanations": {"市井": "正确：市井指市民聚居的街市，小吃摊多设在这样的地方，与句意相符。", "太空": "语义：太空中没有市民和小吃摊，“太空里的小吃摊总是很热闹”不合常理。", "深海": "语义：深海中没有市民和小吃摊，“深海里的小吃摊总是很热闹”不合常理。", "月球": "语义：月球上没有市民和小吃摊，“月球里的小吃摊总是很热闹”不合常理。"}, "sentence_index": 6, "correct_answer": "市井"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一个市井，每天在街上卖菜。", "explanation": "这里应该用〈小贩〉。市井指街市或市民生活的环境，不指某一个人，卖菜的人应说“小贩”。"}, {"text": "我在这家市井买了一双鞋。", "explanation": "这里应该用〈商店〉。市井指整个街市环境，不是一家店，买鞋的地方应说“商店”。"}, {"text": "这口市井很深，打上来的水很甜。", "explanation": "这里应该用〈水井〉。市井指街市或市民生活的环境，不是取水的井，应说“水井”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们市井里玩耍。", "corrected_sentence": "孩子们在市井里玩耍。", "error_description": "错误：表示地点的“市井里”前漏掉了介词“在”。正确应为“在市井里玩耍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷从小到市井长大。", "corrected_sentence": "爷爷从小在市井长大。", "error_description": "介词错误：表示成长所在的地点，应用“在市井”，不能用“到市井”。正确应为“在市井长大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10176, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10176, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "街巷指城镇中的街道和小巷，是居民日常通行和活动的公共空间。", "primary_collocate": null, "pronunciation": "jiē xiàng", "ipa": "tɕjɛ˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "城市中的印刷工坊如雨后春笋般涌现，书籍从修道院的密室流入市井街巷，识字不再是神职人员的专属技能，市民阶层、商人乃至部分工匠开始主动学习阅读。", "target_word": "街巷", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老城的街巷很窄，汽车开不进去。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨，街巷里传来小贩的叫卖声。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们常在街巷里追逐玩耍。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城的街巷保留着明清时期的样子。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，街巷两旁的青石板变得很滑。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者每周都会打扫社区的街巷。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客喜欢在古镇的街巷中慢慢散步。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街巷虽然不宽，却连着千家万户。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在整修老街巷，让居民出行更方便。", "target_word": "街巷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "书面", "sense_fingerprint": "城镇中的街道与小巷，居民通行活动的公共空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c5209d6-189a-4b08-9be6-981d2b1ec05c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "街巷", "is_correct": true, "explanation": "街巷指城镇中的街道和小巷，与“书籍流入市井”的世俗街市语境相符。"}, {"text": "田野", "is_correct": false, "explanation": "语义：田野是乡野空旷之地，与“市井”指城镇街市相反，句意不通。"}, {"text": "教堂", "is_correct": false, "explanation": "搭配：“市井”只修饰街巷、小民等世俗场所，不说“市井教堂”；且前文已是修道院的宗教语境。"}, {"text": "乡村", "is_correct": false, "explanation": "语义：乡村与“市井”相对，句子讲的是书籍在城市中的传播。"}], "explanations": {"街巷": "街巷指城镇中的街道和小巷，与“书籍流入市井”的世俗街市语境相符。", "田野": "语义：田野是乡野空旷之地，与“市井”指城镇街市相反，句意不通。", "教堂": "搭配：“市井”只修饰街巷、小民等世俗场所，不说“市井教堂”；且前文已是修道院的宗教语境。", "乡村": "语义：乡村与“市井”相对，句子讲的是书籍在城市中的传播。"}, "sentence_index": 0, "correct_answer": "街巷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个社区的街巷办事处每周都为居民提供服务。", "explanation": "这里应该用〈街道〉。“街道办事处”是固定说法，指基层行政机构；街巷泛指城镇中的街道和小巷，不能用来指行政单位。"}, {"text": "医院的街巷里很安静，病人不能大声说话。", "explanation": "这里应该用〈走廊〉。街巷指城镇里的街道和小巷，是室外的路；医院里的室内通道是走廊，街巷不能这样用。"}, {"text": "飞机的街巷里堆满了行李，乘客很难通过。", "explanation": "这里应该用〈过道〉。街巷指城镇中的街道和小巷，不指飞机内部的通道；飞机里的通道是过道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "街巷", "is_correct": true, "explanation": "街巷是社区中可以打扫的公共通道，与“打扫社区的”相符。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“打扫”的对象是地面、房间等具体空间，不说“打扫天空”。"}, {"text": "大海", "is_correct": false, "explanation": "语义：社区里不会有大海，而且大海也无法被打扫。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“打扫”不用于声音，不能说“打扫歌声”。"}], "explanations": {"街巷": "街巷是社区中可以打扫的公共通道，与“打扫社区的”相符。", "天空": "搭配：“打扫”的对象是地面、房间等具体空间，不说“打扫天空”。", "大海": "语义：社区里不会有大海，而且大海也无法被打扫。", "歌声": "搭配：“打扫”不用于声音，不能说“打扫歌声”。"}, "sentence_index": 6, "correct_answer": "街巷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条街巷通往邻省，每天有很多货车。", "explanation": "这里应该用〈公路〉。街巷是城镇里的街道和小巷，不能通往外省；跨省运输的道路是公路。"}, {"text": "我们在街巷的大厅里办理了登机手续。", "explanation": "这里应该用〈机场〉。街巷指城镇里的室外道路，不是机场大厅；办理登机手续要在机场进行。"}, {"text": "这座街巷很高，我们爬了一上午。", "explanation": "这里应该用〈山〉。街巷是城镇里的道路，不是山，不能说“很高”，也不能用“爬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把老城的几只街巷都走遍了。", "corrected_sentence": "他把老城的几条街巷都走遍了。", "error_description": "量词错误：街巷是线状的，应用量词“条”，不用“只”。正确说法是“几条街巷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些只街巷都被整修过了。", "corrected_sentence": "这些街巷都被整修过了。", "error_description": "量词错误：“这些”后面不接量词“只”，街巷直接说“这些街巷”，不需要量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
