INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10177, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指在宗教组织中担任正式职务、负责主持宗教仪式和传教工作的人。", "primary_collocate": null, "pronunciation": "shén zhí rén yuán", "ipa": "ʂən˧˥ ʈʂɻ̩˧˥ ɻən˧˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "城市中的印刷工坊如雨后春笋般涌现，书籍从修道院的密室流入市井街巷，识字不再是神职人员的专属技能，市民阶层、商人乃至部分工匠开始主动学习阅读。", "target_word": "神职人员", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "教堂里的神职人员每个星期日都主持礼拜。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位神职人员在村子里传教已经二十年。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中世纪的神职人员掌握着大量书籍和知识。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神职人员要为信徒主持婚礼和葬礼。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位穿着黑袍的神职人员正在为信徒祈祷。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多神职人员过着简朴的生活。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神职人员不能随便透露信徒的秘密。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争期间，神职人员帮助过很多穷人。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想成为神职人员，必须先学习多年。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "神職人員", "label": "繁体"}], "register": "书面", "sense_fingerprint": "宗教组织中担任正式职务、主持仪式和传教的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c5209d6-189a-4b08-9be6-981d2b1ec05c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10177, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神职人员", "is_correct": true, "explanation": "神职人员是宗教组织中的专职人员，与“识字曾是专属技能”的历史语境相符。"}, {"text": "工匠", "is_correct": false, "explanation": "语义：后文说工匠也开始主动学习阅读，与“专属技能”的说法矛盾。"}, {"text": "车夫", "is_correct": false, "explanation": "语义：车夫与前文修道院的宗教、书籍语境无关，识字从来不是车夫的专属技能。"}, {"text": "农夫", "is_correct": false, "explanation": "语义：农夫不属于前文描写的修道院与宗教知识传统，与“专属”的所指不符。"}], "explanations": {"神职人员": "神职人员是宗教组织中的专职人员，与“识字曾是专属技能”的历史语境相符。", "工匠": "语义：后文说工匠也开始主动学习阅读，与“专属技能”的说法矛盾。", "车夫": "语义：车夫与前文修道院的宗教、书籍语境无关，识字从来不是车夫的专属技能。", "农夫": "语义：农夫不属于前文描写的修道院与宗教知识传统，与“专属”的所指不符。"}, "sentence_index": 0, "correct_answer": "神职人员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名神职人员，负责设计这座桥。", "explanation": "这里应该用〈工程师〉。神职人员是宗教组织中的职务，不指负责设计桥梁的技术人员。"}, {"text": "他去年在公司当神职人员，负责销售产品。", "explanation": "这里应该用〈职员〉。神职人员是宗教组织的职务，公司岗位不能用这个词。"}, {"text": "他在班里是神职人员，成绩很好。", "explanation": "这里应该用〈学生〉。神职人员指宗教职务，不指在班里读书的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神职人员", "is_correct": true, "explanation": "神职人员是宗教组织中的专职人员，句中“过着简朴的生活”描述的正是这类人的生活状态，与句意相合。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁没有生活，不能“过着简朴的生活”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会过生活，句子主语必须是有生命的人。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车没有生活，不能“过着简朴的生活”，与句意相矛盾。"}], "explanations": {"神职人员": "神职人员是宗教组织中的专职人员，句中“过着简朴的生活”描述的正是这类人的生活状态，与句意相合。", "墙壁": "语义：墙壁没有生活，不能“过着简朴的生活”。", "石头": "语义：石头不会过生活，句子主语必须是有生命的人。", "汽车": "语义：汽车没有生活，不能“过着简朴的生活”，与句意相矛盾。"}, "sentence_index": 6, "correct_answer": "神职人员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天坐神职人员去上班。", "explanation": "这里应该用〈公交车〉。“坐”用于车辆，神职人员指在宗教组织中任职的人，不是交通工具。"}, {"text": "我每天都吃这种神职人员，味道很好。", "explanation": "这里应该用〈食物〉。神职人员是人，不是食物，不能拿来吃。"}, {"text": "这种神职人员会摇尾巴，很可爱。", "explanation": "这里应该用〈宠物〉。神职人员是人，不是动物，不会摇尾巴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只神职人员在教堂里为信徒祈祷。", "corrected_sentence": "一位神职人员在教堂里为信徒祈祷。", "error_description": "量词错误：指人的神职人员应用量词“位”，不用动物量词“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位神职人员一辈子过得简朴的生活。", "corrected_sentence": "一位神职人员一辈子过着简朴的生活。", "error_description": "助词错误：表示持续状态用「着」，「得」只接补语，此处应说「过着简朴的生活」，不能说「过得简朴的生活」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
