INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10178, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指某事物专门属于某个人或某个群体，不与其他共享。", "primary_collocate": null, "pronunciation": "zhuān shǔ", "ipa": "ʈʂwan˥ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这间办公室是经理的专属空间，员工不能随便进。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会员可以享受专属折扣，普通顾客没有。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个停车位是业主专属的，外人不能用。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店为住客准备了专属的接送服务。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条通道是医护人员专属的。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每位顾客都有一个专属客服，随时帮他解决问题。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款饮料是我们店的专属产品，别处买不到。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司有自己专属的办公桌。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项优惠是新用户专属的，老用户不能用。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间是女儿专属的小天地。", "target_word": "专属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专属的", "label": "定语形式"}, {"form": "專屬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "专门属于某人或某群体，不与他人共享", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c5209d6-189a-4b08-9be6-981d2b1ec05c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10178, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "专属", "is_correct": true, "explanation": "正确答案。专属 zhuānshǔ 指专门属于某人或某群体，不与他人共享。"}, {"text": "转述", "is_correct": false, "explanation": "「转述 zhuǎnshù」与「专属 zhuānshǔ」两个音节的声调都不同，意思是把别人的话再告诉他人。"}, {"text": "专注", "is_correct": false, "explanation": "「专注 zhuānzhù」与「专属 zhuānshǔ」第二音节声母（zh 与 sh）和声调（第四声与第三声）都不同，意思是集中注意力。"}, {"text": "专书", "is_correct": false, "explanation": "「专书 zhuānshū」与「专属 zhuānshǔ」第二音节声调不同，意思是专门研究某一对象的书。"}, {"text": "专事", "is_correct": false, "explanation": "「专事 zhuānshì」与「专属 zhuānshǔ」第二音节韵母不同（ì 与 ǔ），意思是专门从事某事。"}], "explanations": {"专属": "正确答案。专属 zhuānshǔ 指专门属于某人或某群体，不与他人共享。", "转述": "「转述 zhuǎnshù」与「专属 zhuānshǔ」两个音节的声调都不同，意思是把别人的话再告诉他人。", "专注": "「专注 zhuānzhù」与「专属 zhuānshǔ」第二音节声母（zh 与 sh）和声调（第四声与第三声）都不同，意思是集中注意力。", "专书": "「专书 zhuānshū」与「专属 zhuānshǔ」第二音节声调不同，意思是专门研究某一对象的书。", "专事": "「专事 zhuānshì」与「专属 zhuānshǔ」第二音节韵母不同（ì 与 ǔ），意思是专门从事某事。"}, "sentence_index": null, "correct_answer": "专属"}, "level_3": {"options": [{"text": "专属", "is_correct": true, "explanation": "正确答案。专属指专门属于某人或某群体，与「经理的」所属关系相合，且与「员工不能随便进」一致。"}, {"text": "公共", "is_correct": false, "explanation": "语义：「公共」指大家共有，与「经理的」所属关系相矛盾。"}, {"text": "开放", "is_correct": false, "explanation": "语义：「开放」指任何人都可以进入，与「员工不能随便进」相矛盾。"}, {"text": "通用", "is_correct": false, "explanation": "搭配：「通用」多用于标准、软件，不说「经理的通用空间」。"}], "explanations": {"专属": "正确答案。专属指专门属于某人或某群体，与「经理的」所属关系相合，且与「员工不能随便进」一致。", "公共": "语义：「公共」指大家共有，与「经理的」所属关系相矛盾。", "开放": "语义：「开放」指任何人都可以进入，与「员工不能随便进」相矛盾。", "通用": "搭配：「通用」多用于标准、软件，不说「经理的通用空间」。"}, "sentence_index": 0, "correct_answer": "专属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个窗口专属办理退税。", "explanation": "这里应该用〈专门〉。专属指某物归某人或某群体所有、不与他人共享，不能用来修饰“办理”这样的动作。"}, {"text": "这个健身房是专属的，大家都能去。", "explanation": "这里应该用〈公用〉。专属指不与他人共享，而健身房供大家使用，不能说专属。"}, {"text": "这首歌在全国很专属，人人都会唱。", "explanation": "这里应该用〈流行〉。专属指只属于某人或某群体、不与他人共享，不能用来说一首歌人人都会唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专属", "is_correct": true, "explanation": "正确答案。专属指专门属于某个店或某群体，与「我们店的」相合，且与「别处买不到」一致。"}, {"text": "普通", "is_correct": false, "explanation": "语义：「普通」指一般、不特别，与「别处买不到」所体现的独有之意相矛盾。"}, {"text": "公用", "is_correct": false, "explanation": "搭配：「公用」多指供大家使用的设施，不说「我们店的公用产品」。"}, {"text": "日常", "is_correct": false, "explanation": "语义：「日常」指每天都用的、常见的，与「别处买不到」所体现的独有之意相矛盾。"}], "explanations": {"专属": "正确答案。专属指专门属于某个店或某群体，与「我们店的」相合，且与「别处买不到」一致。", "普通": "语义：「普通」指一般、不特别，与「别处买不到」所体现的独有之意相矛盾。", "公用": "搭配：「公用」多指供大家使用的设施，不说「我们店的公用产品」。", "日常": "语义：「日常」指每天都用的、常见的，与「别处买不到」所体现的独有之意相矛盾。"}, "sentence_index": 6, "correct_answer": "专属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种花在南方很专属，随处都能看到。", "explanation": "这里应该用〈常见〉。专属指只属于某人或某群体、不与他人共享，不能用来说某种花随处都能看到。"}, {"text": "这本书很专属，大家都能买到。", "explanation": "这里应该用〈畅销〉。专属指不与他人共享，不能用来说书卖得好、大家都能买。"}, {"text": "这款游戏很专属，很多人都在玩。", "explanation": "这里应该用〈热门〉。专属强调不与他人共享，不能用来说很多人都在玩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电脑是爸爸专属了，别人不能用。", "corrected_sentence": "这台电脑是爸爸专属的，别人不能用。", "error_description": "助词错误：表示归属要用“是……专属的”，不能用“了”，应把“了”改为“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个座位是很专属的，别人不能坐。", "corrected_sentence": "这个座位是专属的，别人不能坐。", "error_description": "程度副词误用：“专属”表示归属，没有程度之分，不能受“很”修饰，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
