INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指居住在城市中的居民。", "primary_collocate": null, "pronunciation": "shì mín", "ipa": "ʂʐ̩˥˩ min˧˥", "syllable_count": 2, "sentences": [{"text": "这个城市的市民很友好。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民们每天坐地铁上班。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长和市民一起打扫公园。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多市民周末去江边散步。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民可以免费参观这个博物馆。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，市民都不愿意出门。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有很多市民在锻炼身体。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民要把垃圾放进垃圾桶。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了安全，市民不能放鞭炮。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政府想听听市民的意见。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "市民们", "label": "复数"}], "register": "中性", "sense_fingerprint": "居住在城市里的居民", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c5209d6-189a-4b08-9be6-981d2b1ec05c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市民", "is_correct": true, "explanation": "正确答案。市民指居住在城市中的居民，与「这个城市的」相合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是人，不能说“友好”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流没有态度，不能说“很友好”。"}, {"text": "建筑", "is_correct": false, "explanation": "语义：建筑是物体，不能用“友好”形容。"}], "explanations": {"市民": "正确答案。市民指居住在城市中的居民，与「这个城市的」相合。", "空气": "语义：空气不是人，不能说“友好”。", "河流": "语义：河流没有态度，不能说“很友好”。", "建筑": "语义：建筑是物体，不能用“友好”形容。"}, "sentence_index": 0, "correct_answer": "市民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市民每天赶着牛下地干活。", "explanation": "这里应该用〈农民〉。市民指居住在城市里的人，不能用来指每天赶着牛下地干活的人。"}, {"text": "市民每天在海上撒网捕鱼，很晚才回岸。", "explanation": "这里应该用〈渔民〉。市民指居住在城市中的居民，不能用来指在海上捕鱼的人。"}, {"text": "市民每天在草原上放羊，很少进城。", "explanation": "这里应该用〈牧民〉。市民指居住在城市中的居民，不能用来指常年在草原放羊的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市民", "is_correct": true, "explanation": "正确答案。市民指居住在城市中的居民，能在公园里锻炼身体。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：「锻炼身体」的主语须是人，不能说“猫”在锻炼身体。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能锻炼身体，与句意相矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能锻炼身体，与句意相矛盾。"}], "explanations": {"市民": "正确答案。市民指居住在城市中的居民，能在公园里锻炼身体。", "猫": "搭配：「锻炼身体」的主语须是人，不能说“猫”在锻炼身体。", "石头": "语义：石头没有生命，不能锻炼身体，与句意相矛盾。", "汽车": "语义：汽车不能锻炼身体，与句意相矛盾。"}, "sentence_index": 6, "correct_answer": "市民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市民一年四季住在毡房里，逐水草迁徙。", "explanation": "这里应该用〈牧民〉。市民指城市居民，不能用来指一年四季住在毡房里、逐水草迁徙的人。"}, {"text": "市民每天在深山里打猎为生，很少下山。", "explanation": "这里应该用〈猎人〉。市民指居住在城市中的居民，不能用来指在深山里打猎、很少下山的人。"}, {"text": "市民每天驾着战马在边疆巡逻，守卫边境。", "explanation": "这里应该用〈士兵〉。市民指居住在城市中的居民，不能用来指驻守边疆、驾马巡逻的军人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的一只市民去年拿了奖。", "corrected_sentence": "这座城市的一位市民去年拿了奖。", "error_description": "量词错误：指人的「市民」应用“位”或“个”，不用“只”。应把“一只”改为“一位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条街上有一位市民们在散步。", "corrected_sentence": "这条街上有一位市民在散步。", "error_description": "多余的“们”：“一位”已表示单数，指一个人时不能再加“们”，应说“这条街上有一位市民在散步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
