INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10181, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指从事商品买卖或贸易活动的人。", "primary_collocate": null, "pronunciation": "shāng rén", "ipa": "ʂɑŋ˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "这位商人每年都从南方批发大量茶叶。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商人总是想把东西卖个好价钱。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候，商人骑着马去远方做生意。", "target_word": "商人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个商人在市场上卖丝绸。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商人要先看货，再谈价格。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一位很有钱的商人。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商人们坐船去别的国家做买卖。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "聪明的商人不会只看眼前的钱。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商人在店门口挂上红灯笼，准备开业卖货。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个商人开了三家饭店。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "商人们", "label": "复合"}], "register": "中性", "sense_fingerprint": "从事商品买卖或贸易的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c5209d6-189a-4b08-9be6-981d2b1ec05c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10181, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "商人", "is_correct": true, "explanation": "正确答案。商人指从事商品买卖或贸易活动的人。"}, {"text": "上人", "is_correct": false, "explanation": "shàng（第四声）与 shāng（第一声）声母韵母相同，只差声调；上人是佛教对高僧的尊称。"}, {"text": "生人", "is_correct": false, "explanation": "shēng（第一声）与 shāng（第一声）韵母不同（eng 与 ang），生人指不认识的人。"}, {"text": "山人", "is_correct": false, "explanation": "shān（第一声）与 shāng（第一声）只差韵尾（an 与 ang），山人指隐居山林的人。"}], "explanations": {"商人": "正确答案。商人指从事商品买卖或贸易活动的人。", "上人": "shàng（第四声）与 shāng（第一声）声母韵母相同，只差声调；上人是佛教对高僧的尊称。", "生人": "shēng（第一声）与 shāng（第一声）韵母不同（eng 与 ang），生人指不认识的人。", "山人": "shān（第一声）与 shāng（第一声）只差韵尾（an 与 ang），山人指隐居山林的人。"}, "sentence_index": null, "correct_answer": "商人"}, "level_3": {"options": [{"text": "商人", "is_correct": true, "explanation": "正确。「商人」指做买卖的人，从南方批发大量茶叶属于贸易活动，符合句意。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不做批发贸易，「批发大量茶叶」与学生身份不符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生的职业不涉及批发货物，句意不通。"}, {"text": "画家", "is_correct": false, "explanation": "语义：画家的职业是画画，不从事茶叶批发贸易，句意不通。"}], "explanations": {"商人": "正确。「商人」指做买卖的人，从南方批发大量茶叶属于贸易活动，符合句意。", "学生": "语义：学生不做批发贸易，「批发大量茶叶」与学生身份不符。", "医生": "语义：医生的职业不涉及批发货物，句意不通。", "画家": "语义：画家的职业是画画，不从事茶叶批发贸易，句意不通。"}, "sentence_index": 0, "correct_answer": "商人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的商人每天在教室里给学生讲数学。", "explanation": "这里应该用〈老师〉。「商人」指做买卖的人，在教室里给学生讲数学是老师的工作。"}, {"text": "商人每天在医院里给病人做手术。", "explanation": "这里应该用〈医生〉。「商人」指做买卖的人，给病人做手术是医生的工作。"}, {"text": "商人每天开公交车接送乘客。", "explanation": "这里应该用〈司机〉。「商人」指做买卖的人，开公交车接送乘客是司机的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10181, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "商人", "is_correct": true, "explanation": "正确答案。商人指从事商品买卖或贸易活动的人。"}, {"text": "杀人", "is_correct": false, "explanation": "shā（第一声）与 shāng（第一声）韵母不同（少了 ng），杀人指伤害他人性命。"}, {"text": "上任", "is_correct": false, "explanation": "shàng（第四声）与 shāng（第一声）声调不同，rèn（第四声）与 rén（第二声）声调也不同，上任指就职。"}, {"text": "生人", "is_correct": false, "explanation": "shēng（第一声）与 shāng（第一声）韵母不同（eng 与 ang），生人指不认识的人。"}], "explanations": {"商人": "正确答案。商人指从事商品买卖或贸易活动的人。", "杀人": "shā（第一声）与 shāng（第一声）韵母不同（少了 ng），杀人指伤害他人性命。", "上任": "shàng（第四声）与 shāng（第一声）声调不同，rèn（第四声）与 rén（第二声）声调也不同，上任指就职。", "生人": "shēng（第一声）与 shāng（第一声）韵母不同（eng 与 ang），生人指不认识的人。"}, "sentence_index": null, "correct_answer": "商人"}, "level_3": {"options": [{"text": "商人", "is_correct": true, "explanation": "正确。「商人们」是做买卖的人，可以坐船去别的国家做生意，符合句意。"}, {"text": "教授", "is_correct": false, "explanation": "语义：教授的职业与「做买卖」无关，句意不符。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：运动员的职业与「坐船去别的国家做买卖」无关，句意不符。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手的职业与「坐船去别的国家做买卖」的句意不符。"}], "explanations": {"商人": "正确。「商人们」是做买卖的人，可以坐船去别的国家做生意，符合句意。", "教授": "语义：教授的职业与「做买卖」无关，句意不符。", "运动员": "语义：运动员的职业与「坐船去别的国家做买卖」无关，句意不符。", "歌手": "语义：歌手的职业与「坐船去别的国家做买卖」的句意不符。"}, "sentence_index": 6, "correct_answer": "商人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商人每天在火车上查验乘客车票。", "explanation": "这里应该用〈列车员〉。「商人」指做买卖的人，查验车票是列车员的工作。"}, {"text": "商人在路口指挥交通。", "explanation": "这里应该用〈交警〉。「商人」指做买卖的人，在路口指挥交通是交警的工作。"}, {"text": "商人在法庭上为被告辩护。", "explanation": "这里应该用〈律师〉。「商人」指做买卖的人，在法庭上为被告辩护是律师的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只商人昨天在码头卖掉了一批茶叶。", "corrected_sentence": "那个商人昨天在码头卖掉了一批茶叶。", "error_description": "量词错误：「只」多用于动物，指人应用「个」或「位」，正确说法是「那个商人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位商人们去年在港口买了一艘船。", "corrected_sentence": "那位商人去年在港口买了一艘船。", "error_description": "复数错误：「那位」表示单数，商人后面不能加「们」，正确说法是「那位商人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
