INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10183, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看文字或书籍，理解其中的内容。", "primary_collocate": null, "pronunciation": "yuè dú", "ipa": "ɥe˥˩ tu˧˥", "syllable_count": 2, "sentences": [{"text": "我每天晚上阅读半个小时。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阅读能让人学到很多知识。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢安静地阅读报纸。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在图书馆里阅读故事书。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章太难，我阅读了两遍。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们阅读课文，然后回答问题。", "target_word": "阅读", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在阅读一本关于历史的书。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡觉前阅读，可以帮助放松。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他阅读过很多中国小说。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阅读时，请把手机关掉。", "target_word": "阅读", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "阅读了", "label": "体标"}, {"form": "阅读过", "label": "体标"}, {"form": "阅读着", "label": "体标"}, {"form": "阅读课", "label": "复合"}, {"form": "閱讀", "label": "繁体"}], "register": "书面", "sense_fingerprint": "看文字或书籍并理解内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 篇文章 (Zipf 3.94), 太难 (Zipf 3.32), 两遍 (Zipf 3.03)']::text[], '1c5209d6-189a-4b08-9be6-981d2b1ec05c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10183, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "阅读", "is_correct": true, "explanation": "正确答案。阅读指看文字或书籍并理解内容。"}, {"text": "越多", "is_correct": false, "explanation": "yuè duō：第一个音节与 yuè 完全相同，duō 与 dú 韵母、声调不同；越多表示数量增加，与阅读无关。"}, {"text": "月度", "is_correct": false, "explanation": "dù（第四声）与 dú（第二声）声调不同，月度指按月计算。"}, {"text": "阅历", "is_correct": false, "explanation": "yuè lì：第一个音节相同，lì 与 dú 声母韵母不同；阅历指人生经历，不是阅读这一动作。"}], "explanations": {"阅读": "正确答案。阅读指看文字或书籍并理解内容。", "越多": "yuè duō：第一个音节与 yuè 完全相同，duō 与 dú 韵母、声调不同；越多表示数量增加，与阅读无关。", "月度": "dù（第四声）与 dú（第二声）声调不同，月度指按月计算。", "阅历": "yuè lì：第一个音节相同，lì 与 dú 声母韵母不同；阅历指人生经历，不是阅读这一动作。"}, "sentence_index": null, "correct_answer": "阅读"}, "level_3": {"options": [{"text": "阅读", "is_correct": true, "explanation": "正确。「阅读半个小时」表示持续看书的时长，符合句意。"}, {"text": "到达", "is_correct": false, "explanation": "搭配：「到达」是一次性动作，不能表示持续半个小时。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚不是每晚持续半个小时的活动，句意不通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生是一次性事件，不能表示每晚持续的时长。"}], "explanations": {"阅读": "正确。「阅读半个小时」表示持续看书的时长，符合句意。", "到达": "搭配：「到达」是一次性动作，不能表示持续半个小时。", "结婚": "语义：结婚不是每晚持续半个小时的活动，句意不通。", "出生": "语义：出生是一次性事件，不能表示每晚持续的时长。"}, "sentence_index": 0, "correct_answer": "阅读"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在电影院里阅读电影。", "explanation": "这里应该用〈观看〉。阅读针对文字，看电影要说观看。"}, {"text": "他戴上耳机阅读音乐。", "explanation": "这里应该用〈听〉。阅读针对文字，听音乐要说听。"}, {"text": "妹妹在作业本上阅读字。", "explanation": "这里应该用〈写〉。阅读是看文字，在作业本上写字要说写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10183, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阅读", "is_correct": true, "explanation": "正确。「正在阅读一本关于历史的书」符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：书不能用「煮」，「煮一本书」搭配不当。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：书不能用「煎」，「煎一本书」搭配不当。"}, {"text": "种", "is_correct": false, "explanation": "语义：「种」指栽培植物，与「一本书」的句意不符。"}], "explanations": {"阅读": "正确。「正在阅读一本关于历史的书」符合句意。", "煮": "搭配：书不能用「煮」，「煮一本书」搭配不当。", "煎": "搭配：书不能用「煎」，「煎一本书」搭配不当。", "种": "语义：「种」指栽培植物，与「一本书」的句意不符。"}, "sentence_index": 6, "correct_answer": "阅读"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在厨房里阅读晚饭。", "explanation": "这里应该用〈做〉。阅读针对文字，做晚饭要说做。"}, {"text": "他在体育场阅读比赛。", "explanation": "这里应该用〈观看〉。阅读针对文字，看比赛要说观看。"}, {"text": "妈妈在花园里阅读花草。", "explanation": "这里应该用〈照料〉。阅读针对文字，照料花草要说照料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在阅读过这本小说。", "corrected_sentence": "他正在阅读这本小说。", "error_description": "体标错误：「正在」表示动作进行，「过」表示曾有过的经历，二者不能同用；应说「他正在阅读这本小说」，去掉「过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在咖啡馆里阅读着了这封信。", "corrected_sentence": "她在咖啡馆里阅读着这封信。", "error_description": "体标错误：「着」表示动作正在持续，「了」表示动作完成，二者不能同时跟在「阅读」后面，应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
