INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10184, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指书籍、期刊、音像制品等经过编辑、制作并向公众发行的作品。", "primary_collocate": null, "pronunciation": "chū bǎn wù", "ipa": "tʂʰu˥ pan˨˩˦ u˥˩", "syllable_count": 3, "sentences": [{"text": "随着出版物种类的丰富，除宗教文献外，科学论著、文学作品、法律文本乃至新闻小册子广泛流通，公众对知识的渴求被前所未有地激发。", "target_word": "出版物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家图书馆收藏了大量历史出版物。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府规定，出版物必须有正式的书号。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批出版物是从国外进口的，海关已经检查过。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违法的出版物不能在市场上出售。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个展览展出了上百种早期出版物。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版物发行前，编辑要认真检查内容。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种出版物每个月发行一期，读者很多。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校图书馆里的出版物，大多数是教材和杂志。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家对出版物的内容有严格的管理规定。", "target_word": "出版物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "批", "label": "量词"}, {"form": "电子出版物", "label": "复合"}], "register": "书面", "sense_fingerprint": "经编辑制作并向公众发行的书刊、音像等作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a75c456c-0a28-4657-b2af-ed1ca1e72345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出版物", "is_correct": true, "explanation": "出版物指经编辑发行的书刊、音像等作品，可以与宗教文献、科学论著并列，并且能够流通，符合句意。"}, {"text": "食品", "is_correct": false, "explanation": "语义：句子后面谈的是文献、论著等文本的流通和公众对知识的渴求，食品与此无关。"}, {"text": "工具", "is_correct": false, "explanation": "语义：工具是用来做事的物品，不属于经编辑发行的作品。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“广泛流通”多用于书刊等作品在公众中传播，不能用来描述汽车的流通。"}], "explanations": {"出版物": "出版物指经编辑发行的书刊、音像等作品，可以与宗教文献、科学论著并列，并且能够流通，符合句意。", "食品": "语义：句子后面谈的是文献、论著等文本的流通和公众对知识的渴求，食品与此无关。", "工具": "语义：工具是用来做事的物品，不属于经编辑发行的作品。", "汽车": "搭配：“广泛流通”多用于书刊等作品在公众中传播，不能用来描述汽车的流通。"}, "sentence_index": 0, "correct_answer": "出版物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在一家大型出版物工作，负责编辑教材。", "explanation": "这里应该用〈出版社〉。出版社是机构，人可以在那里工作；出版物是书刊等作品，不能说在它工作。"}, {"text": "这本书的出版物是一位年轻作家。", "explanation": "这里应该用〈作者〉。作者是写书的人，出版物是发行的书刊等作品，不能指人。"}, {"text": "这家出版物每天印刷几千本书。", "explanation": "这里应该用〈印刷厂〉。印刷厂负责印刷，出版物是印好的书刊，本身不能进行印刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出版物", "is_correct": true, "explanation": "出版物发行前需要编辑检查内容，这与“编辑要认真检查内容”的语境相符。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不经过编辑审校，不能说“发行前编辑要检查内容”。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不需要编辑检查内容，句中的“发行前”也不适用于它。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“发行”一般用于书刊、音像等，不能用于桌子。"}], "explanations": {"出版物": "出版物发行前需要编辑检查内容，这与“编辑要认真检查内容”的语境相符。", "饮料": "语义：饮料不经过编辑审校，不能说“发行前编辑要检查内容”。", "蔬菜": "语义：蔬菜不需要编辑检查内容，句中的“发行前”也不适用于它。", "桌子": "搭配：“发行”一般用于书刊、音像等，不能用于桌子。"}, "sentence_index": 6, "correct_answer": "出版物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈去出版物买菜。", "explanation": "这里应该用〈菜市场〉。菜市场是买菜的地方，出版物是书刊等作品，不能用来买菜。"}, {"text": "这位出版物写了很多书。", "explanation": "这里应该用〈作者〉。作者是写书的人，出版物是已经发行的作品，不能充当写书的主体。"}, {"text": "这家出版物的菜很好吃。", "explanation": "这里应该用〈餐厅〉。餐厅供应饭菜，出版物是书刊，不能用来说菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只出版物需要重新印刷。", "corrected_sentence": "这批出版物需要重新印刷。", "error_description": "量词错误：“只”多用于动物或成对物中的单个，“出版物”应用“批”或“种”计数，应说“这批出版物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆新进了一台出版物。", "corrected_sentence": "图书馆新进了一批出版物。", "error_description": "量词错误：“台”用于机器、设备等，出版物不能用“台”计数，应说“一批出版物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10186, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贫乏", "is_correct": true, "explanation": "贫乏指数量少、种类少，与“丰富”构成反义。"}, {"text": "清澈", "is_correct": false, "explanation": "清澈形容水或光线透明，与“丰富”的数量、种类义不构成反义。"}, {"text": "严厉", "is_correct": false, "explanation": "严厉形容态度或要求，与数量、种类无关，不是“丰富”的反义词。"}, {"text": "沉重", "is_correct": false, "explanation": "沉重形容分量大或心情压抑，与“丰富”不构成反义。"}], "correct_answer": "贫乏", "explanations": {"贫乏": "贫乏指数量少、种类少，与“丰富”构成反义。", "清澈": "清澈形容水或光线透明，与“丰富”的数量、种类义不构成反义。", "严厉": "严厉形容态度或要求，与数量、种类无关，不是“丰富”的反义词。", "沉重": "沉重形容分量大或心情压抑，与“丰富”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10186, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贫乏", "is_correct": true, "explanation": "贫乏指数量少、种类少，与“丰富”构成反义。"}, {"text": "狭窄", "is_correct": false, "explanation": "狭窄形容空间或道路窄小，与“丰富”不构成反义。"}, {"text": "温和", "is_correct": false, "explanation": "温和形容性情或天气等不激烈，与“丰富”不构成反义。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松形容心情或负担少，与“丰富”的数量、种类义不构成反义。"}], "correct_answer": "贫乏", "explanations": {"贫乏": "贫乏指数量少、种类少，与“丰富”构成反义。", "狭窄": "狭窄形容空间或道路窄小，与“丰富”不构成反义。", "温和": "温和形容性情或天气等不激烈，与“丰富”不构成反义。", "轻松": "轻松形容心情或负担少，与“丰富”的数量、种类义不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10186, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容数量或种类非常多。", "primary_collocate": null, "pronunciation": "fēng fù", "ipa": "fəŋ˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "这家超市的商品种类很丰富。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日的晚餐非常丰富，有鱼有肉。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里的藏书十分丰富。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的旅游资源很丰富。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云南的物产丰富，水果特别多。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的菜单很丰富，选择很多。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的收藏很丰富，有上千张老照片。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的课外活动越来越丰富了。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典里的例句非常丰富。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早餐的种类不太丰富，只有面包和牛奶。", "target_word": "丰富", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "丰富多彩", "label": "复合"}, {"form": "豐富", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数量多、种类多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a75c456c-0a28-4657-b2af-ed1ca1e72345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丰富", "is_correct": true, "explanation": "丰富形容数量或种类多，与“种类很”搭配，符合句意。"}, {"text": "安静", "is_correct": false, "explanation": "语义：安静形容环境或声音，不能用来形容商品种类。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”形容物体坚固，不能与“种类”搭配。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：寂寞形容人的心情，不能用来形容商品种类。"}], "explanations": {"丰富": "丰富形容数量或种类多，与“种类很”搭配，符合句意。", "安静": "语义：安静形容环境或声音，不能用来形容商品种类。", "结实": "搭配：“结实”形容物体坚固，不能与“种类”搭配。", "寂寞": "语义：寂寞形容人的心情，不能用来形容商品种类。"}, "sentence_index": 0, "correct_answer": "丰富"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她长得很丰富。", "explanation": "这里应该用〈丰满〉。丰满形容身体或物体饱满，丰富形容数量或种类多，不能用来形容人的身材。"}, {"text": "这个房间的面积很丰富。", "explanation": "这里应该用〈大〉。面积的多少说“大”或“小”，丰富指数量或种类多，不能用来说面积。"}, {"text": "他个子很丰富。", "explanation": "这里应该用〈高大〉。高大形容身材，丰富只形容数量或种类多，不能形容个子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丰富", "is_correct": true, "explanation": "丰富指收藏的数量多，与“有上千张老照片”的语境相符。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：陡峭形容山坡或道路，不能用来形容收藏。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：柔软形容质地，不能用来形容收藏的数量。"}, {"text": "辣", "is_correct": false, "explanation": "语义：辣形容味道，不能用来形容收藏。"}], "explanations": {"丰富": "丰富指收藏的数量多，与“有上千张老照片”的语境相符。", "陡峭": "语义：陡峭形容山坡或道路，不能用来形容收藏。", "柔软": "搭配：柔软形容质地，不能用来形容收藏的数量。", "辣": "语义：辣形容味道，不能用来形容收藏。"}, "sentence_index": 6, "correct_answer": "丰富"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很丰富。", "explanation": "这里应该用〈宽阔〉。宽阔形容面积大，丰富形容数量或种类多，不能用来形容路面。"}, {"text": "他身体很丰富。", "explanation": "这里应该用〈健壮〉。健壮形容身体强壮，丰富不用于形容身体的强弱。"}, {"text": "这间屋子很丰富。", "explanation": "这里应该用〈明亮〉。明亮形容光线充足、有光，丰富不能用来形容房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个市场的蔬菜品种很最丰富。", "corrected_sentence": "这个市场的蔬菜品种很丰富。", "error_description": "“很”和“最”都是程度副词，不能同时修饰“丰富”，应只用其一，说“很丰富”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地区的野生动物种类很丰富着。", "corrected_sentence": "这个地区的野生动物种类很丰富。", "error_description": "“丰富”是形容词，这里描写的是一种状态，后面不能加体标“着”，应删去“着”，说“种类很丰富”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
