INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10188, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指具有历史价值或学术价值的文字资料，如书籍、文章、档案等。", "primary_collocate": null, "pronunciation": "wén xiàn", "ipa": "wən˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "博物馆里保存着很多古代文献。", "target_word": "文献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些历史文献非常珍贵。", "target_word": "文献", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "专家在档案馆发现了一份旧文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批文献记录了一百年前的生活。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学者们正在整理敦煌文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文献是用古文写成的。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要好好保护这些古老文献。", "target_word": "文献", "complexity_tier": "T3", "furigana": "wǒ men yào hǎo hǎo bǎohù zhèxiē gǔlǎo wénxiàn", "sentence_source": "generated"}, {"text": "历史学家靠文献了解过去。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书收集了许多战争年代的文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆把旧文献放进了特别的柜子里。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份文献", "label": "量词"}, {"form": "一批文献", "label": "量词"}, {"form": "历史文献", "label": "复合"}, {"form": "文献资料", "label": "复合"}, {"form": "文獻", "label": "繁体"}], "register": "书面", "sense_fingerprint": "有历史或学术价值的书籍、文章、档案等文字资料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c928e1f6-5741-4790-be78-40c893415c14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文献", "is_correct": true, "explanation": "正确：“古代文献”指有历史价值的文字资料，博物馆保存的正是这类材料。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不是古代遗留的文字资料，博物馆也不会把它当作古代文物保存。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“古代”一般修饰具体事物，不说“古代时间”，句中也不能“保存时间”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是近代才出现的物品，不可能是“古代”的遗留，句意不成立。"}], "explanations": {"文献": "正确：“古代文献”指有历史价值的文字资料，博物馆保存的正是这类材料。", "咖啡": "语义：咖啡不是古代遗留的文字资料，博物馆也不会把它当作古代文物保存。", "时间": "搭配：“古代”一般修饰具体事物，不说“古代时间”，句中也不能“保存时间”。", "手机": "语义：手机是近代才出现的物品，不可能是“古代”的遗留，句意不成立。"}, "sentence_index": 0, "correct_answer": "文献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这篇文献拿来当枕头，睡得很香。", "explanation": "这里应该用〈枕头〉。文献是有价值的文字资料，不是睡觉时垫头的物品；垫头要用〈枕头〉。"}, {"text": "他每天饭后都去文献散步。", "explanation": "这里应该用〈公园〉。“文献”是资料，不是可以去散步的地方；饭后散步要去〈公园〉。"}, {"text": "作者在这本文献里描写了主人公的爱情。", "explanation": "这里应该用〈小说〉。文献是资料，不描写人物的爱情；描写人物感情要用〈小说〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文献", "is_correct": true, "explanation": "正确：“保护这些古老文献”中的“文献”是有历史价值的文字资料，语义相合。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是古老的文字资料，“古老饼干”也不成立，句中无法作为保护对象。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“古老”不修饰“心情”，“这些古老心情”说不通，句意不成立。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不能被当作古老的遗存加以保护，句意不成立。"}], "explanations": {"文献": "正确：“保护这些古老文献”中的“文献”是有历史价值的文字资料，语义相合。", "饼干": "语义：饼干不是古老的文字资料，“古老饼干”也不成立，句中无法作为保护对象。", "心情": "搭配：“古老”不修饰“心情”，“这些古老心情”说不通，句意不成立。", "饭菜": "语义：饭菜不能被当作古老的遗存加以保护，句意不成立。"}, "sentence_index": 6, "correct_answer": "文献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件文献是用青铜做的，很重。", "explanation": "这里应该用〈文物〉。青铜器是实物，文献是文字资料，不能用青铜制成。"}, {"text": "他把这份文献喝了下去。", "explanation": "这里应该用〈汤〉。文献是文字资料，不能喝；“喝”的对象应是〈汤〉。"}, {"text": "妈妈把文献放进锅里，煮了一碗面。", "explanation": "这里应该用〈面条〉。文献是文字资料，不能下锅煮着吃；煮面要用〈面条〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这卷文献是用毛笔写成了的。", "corrected_sentence": "这卷文献是用毛笔写成的。", "error_description": "体标错误：“是……的”结构中不能再加“了”，应说“写成的”，不说“写成了的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这些文献整理了好。", "corrected_sentence": "他把这些文献整理好了。", "error_description": "补语位置错误：“整理好”的“好”是结果补语，“了”应放在补语之后，说“整理好了”，不说“整理了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10189, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
