INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10189, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指专门讨论某个学术问题或理论体系的著作。", "primary_collocate": null, "pronunciation": "lùn zhù", "ipa": "lwən˥˩ tʂu˥˩", "syllable_count": 2, "sentences": [{"text": "随着出版物种类的丰富，除宗教文献外，科学论著、文学作品、法律文本乃至新闻小册子广泛流通，公众对知识的渴求被前所未有地激发。", "target_word": "论著", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位教授写过好几部经济学论著。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论著在国内外都有很大影响。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部论著讨论了语言和思维的关系。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆新买了一批历史学论著。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读了很多哲学论著，才写出这篇文章。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部论著分析了古代农业的发展。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了十年时间，完成了这部论著。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论著里的观点很新，引起了学者的讨论。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求我们先读一部经典论著，再写读后感。", "target_word": "论著", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "本", "label": "量词"}, {"form": "論著", "label": "繁体"}], "register": "书面", "sense_fingerprint": "专门讨论学术问题或理论的著作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a75c456c-0a28-4657-b2af-ed1ca1e72345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10189, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌手", "is_correct": false, "explanation": "语义：“歌手”是演唱的人，不是出版物，不能与“科学论著”“法律文本”并列为广泛流通的文本。"}, {"text": "论著", "is_correct": true, "explanation": "填入〈论著〉：指专门讨论学术问题的著作，与“科学”搭配，并与前面的出版物并列，符合句意。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”是日用器具，不是出版物，与“广泛流通”的对象不符。"}, {"text": "广告牌", "is_correct": false, "explanation": "搭配：“流通”多用于书刊、知识等文本，广告牌不能说“广泛流通”。"}], "explanations": {"歌手": "语义：“歌手”是演唱的人，不是出版物，不能与“科学论著”“法律文本”并列为广泛流通的文本。", "论著": "填入〈论著〉：指专门讨论学术问题的著作，与“科学”搭配，并与前面的出版物并列，符合句意。", "闹钟": "语义：“闹钟”是日用器具，不是出版物，与“广泛流通”的对象不符。", "广告牌": "搭配：“流通”多用于书刊、知识等文本，广告牌不能说“广泛流通”。"}, "sentence_index": 0, "correct_answer": "论著"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下周要参加论著答辩，准备了很久。", "explanation": "这里应该用〈论文〉。答辩的是学位论文，论著指成书的著作，不能用于答辩。"}, {"text": "他每天早上都要看论著，了解昨天发生的新闻。", "explanation": "这里应该用〈报纸〉。报纸报道每天的新闻，论著是讨论学术问题的著作，不报道新闻。"}, {"text": "这部论著讲了一个动人的爱情故事。", "explanation": "这里应该用〈小说〉。论著专指讨论学术问题的著作，不写爱情故事，讲故事应该用〈小说〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电视剧", "is_correct": false, "explanation": "语义：“电视剧”是影视作品，不能“分析”古代农业的发展，与句意不符。"}, {"text": "论著", "is_correct": true, "explanation": "填入〈论著〉：学术著作，可以分析古代农业的发展，与“部”搭配，符合句意。"}, {"text": "词典", "is_correct": false, "explanation": "搭配：“分析……的发展”的主语应是研究性著作，词典只收录词条，说不通。"}, {"text": "小说", "is_correct": false, "explanation": "语义：“小说”是虚构的叙事作品，一般不“分析”历史问题，与句意不符。"}], "explanations": {"电视剧": "语义：“电视剧”是影视作品，不能“分析”古代农业的发展，与句意不符。", "论著": "填入〈论著〉：学术著作，可以分析古代农业的发展，与“部”搭配，符合句意。", "词典": "搭配：“分析……的发展”的主语应是研究性著作，词典只收录词条，说不通。", "小说": "语义：“小说”是虚构的叙事作品，一般不“分析”历史问题，与句意不符。"}, "sentence_index": 6, "correct_answer": "论著"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的哥哥是一部很有名的论著，大家都认识他。", "explanation": "这里应该用〈学者〉。论著是书面著作，不能用来指人，描述人应用“学者”等词。"}, {"text": "我家的宠物是一部论著，它很可爱。", "explanation": "这里应该用〈动物〉。论著是书面的学术著作，不是动物，不能当宠物。"}, {"text": "这部论著是我今天的午饭。", "explanation": "这里应该用〈食物〉。论著是学术著作，不是食物，不能当午饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她花了三年时间，写成了一只论著。", "corrected_sentence": "她花了三年时间，写成了一部论著。", "error_description": "量词错误：“论著”是成书的著作，应用“部”或“本”计量，不能用“只”。应说“一部论著”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了一台论著，介绍现代经济的发展。", "corrected_sentence": "他写了一部论著，介绍现代经济的发展。", "error_description": "量词错误：“台”用于机器设备，“论著”应用“部”或“本”计量，应说“一部论著”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
