INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以语言为工具，通过塑造形象、表达思想感情来反映社会生活的创造性作品。", "primary_collocate": null, "pronunciation": "wén xué zuò pǐn", "ipa": "wən˧˥ ɕɥe˧˥ tsuɔ˥˩ pʰin˨˩˦", "syllable_count": 4, "sentences": [{"text": "随着出版物种类的丰富，除宗教文献外，科学论著、文学作品、法律文本乃至新闻小册子广泛流通，公众对知识的渴求被前所未有地激发。", "target_word": "文学作品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这部文学作品反映了那个时代的社会生活。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的文学作品能表达作者真实的思想感情。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求我们每周读一部文学作品。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部文学作品的人物很生动，情节也很感人。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这部文学作品翻译成了英文。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家一生写过很多优秀的文学作品。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文学作品用语言塑造人物形象。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的图书馆收藏着许多古代文学作品。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读文学作品可以帮助我们了解不同时代的生活。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "文學作品", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用语言塑造形象、反映社会生活的创造性作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a75c456c-0a28-4657-b2af-ed1ca1e72345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舞蹈", "is_correct": false, "explanation": "语义：“舞蹈”是一种表演形式，不是可以流通的文本，与“科学论著”“法律文本”并列不通。"}, {"text": "文学作品", "is_correct": true, "explanation": "填入〈文学作品〉：以语言塑造形象的创作，与“科学论著”“法律文本”并列，属于出版物，符合句意。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”是日用器具，不是出版物，与“广泛流通”的对象不符。"}, {"text": "广告牌", "is_correct": false, "explanation": "搭配：“流通”的对象是书刊、文本，广告牌不能说“广泛流通”。"}], "explanations": {"舞蹈": "语义：“舞蹈”是一种表演形式，不是可以流通的文本，与“科学论著”“法律文本”并列不通。", "文学作品": "填入〈文学作品〉：以语言塑造形象的创作，与“科学论著”“法律文本”并列，属于出版物，符合句意。", "闹钟": "语义：“闹钟”是日用器具，不是出版物，与“广泛流通”的对象不符。", "广告牌": "搭配：“流通”的对象是书刊、文本，广告牌不能说“广泛流通”。"}, "sentence_index": 0, "correct_answer": "文学作品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部文学作品是我今天的午饭。", "explanation": "这里应该用〈食物〉。文学作品是用语言写成的创作，不是食物，不能当午饭。"}, {"text": "这部文学作品每天下午五点从北京开往上海。", "explanation": "这里应该用〈火车〉。火车可以开往别的城市，文学作品是用语言写成的创作，不能行驶。"}, {"text": "他大学读的是中文文学作品专业。", "explanation": "这里应该用〈学科〉。文学作品是具体的创作，不是学科，表示专业要用学科名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "语义：“饼干”是食品，不能“写”，与句意不符。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：“洗衣机”是家电，不是作品，无法“写过”。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“写”的对象是文字作品，地图一般是“画”或“绘制”的，说“写过地图”不搭配。"}, {"text": "文学作品", "is_correct": true, "explanation": "填入〈文学作品〉：以语言创作的作品，与“写过”搭配，指作家的创作，符合句意。"}], "explanations": {"饼干": "语义：“饼干”是食品，不能“写”，与句意不符。", "洗衣机": "语义：“洗衣机”是家电，不是作品，无法“写过”。", "地图": "搭配：“写”的对象是文字作品，地图一般是“画”或“绘制”的，说“写过地图”不搭配。", "文学作品": "填入〈文学作品〉：以语言创作的作品，与“写过”搭配，指作家的创作，符合句意。"}, "sentence_index": 6, "correct_answer": "文学作品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家养的宠物是一部文学作品，它很可爱。", "explanation": "这里应该用〈动物〉。文学作品是人们写的故事、诗歌等，不是动物，不能当宠物。"}, {"text": "这道数学题是一部文学作品，很有意思。", "explanation": "这里应该用〈习题〉。文学作品是用语言塑造形象的创作，数学题不属于此类。"}, {"text": "我的邻居是一部文学作品，他很爱笑。", "explanation": "这里应该用〈朋友〉。文学作品是书面创作，不能指人，说人应该用指人的名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位诗人的一只文学作品被翻译成了很多种语言。", "corrected_sentence": "这位诗人的一部文学作品被翻译成了很多种语言。", "error_description": "量词错误：“文学作品”应用“部”计量，“只”用于动物等，不能说“一只文学作品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我读了完这部文学作品，才明白作者的想法。", "corrected_sentence": "我读完了这部文学作品，才明白作者的想法。", "error_description": "补语错误：“读完”是动词加结果补语的结构，“了”应放在“完”后，不能拆开说成“读了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10192, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10192, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10192, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "新闻是指通过报纸、广播、电视、网络等渠道报道的最近发生的有价值的事件或信息。", "primary_collocate": null, "pronunciation": "xīn wén", "ipa": "ɕin˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "这条新闻是今天早上在电视上报道的。", "target_word": "新闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天晚上七点看新闻。", "target_word": "新闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的新闻很多，但不一定都是真的。", "target_word": "新闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上的新闻写得很清楚，大家都看明白了。", "target_word": "新闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者正在现场报道一条重要的新闻。", "target_word": "新闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电视台工作，每天都要做新闻。", "target_word": "新闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的新闻说，明天会下大雪。", "target_word": "新闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢听广播里的新闻。", "target_word": "新闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到这条新闻，很多人都很吃惊。", "target_word": "新闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻要写清楚时间、地点和人物。", "target_word": "新闻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "新闻报道", "label": "复合"}, {"form": "新闻稿", "label": "复合"}, {"form": "新聞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "媒体报道的最近发生的有价值的事件或信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a75c456c-0a28-4657-b2af-ed1ca1e72345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钢琴", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，钢琴应说“架”，而且钢琴不是能被电视报道的事件。"}, {"text": "新闻", "is_correct": true, "explanation": "“新闻”指被电视报道的近期事件，与“条”和“报道”搭配，句子通顺。"}, {"text": "作文", "is_correct": false, "explanation": "语义：作文是学生写的文章，不是在电视上被报道的事件。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食品，不会在电视上被报道。"}], "explanations": {"钢琴": "搭配：“条”用于细长的东西，钢琴应说“架”，而且钢琴不是能被电视报道的事件。", "新闻": "“新闻”指被电视报道的近期事件，与“条”和“报道”搭配，句子通顺。", "作文": "语义：作文是学生写的文章，不是在电视上被报道的事件。", "蛋糕": "语义：蛋糕是食品，不会在电视上被报道。"}, "sentence_index": 0, "correct_answer": "新闻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我生日那天，朋友送给我一份新闻，是一本漂亮的书。", "explanation": "这里应该用〈礼物〉。朋友送的东西是礼物，新闻是媒体报道的最近发生的事件，不能被当作东西送人。"}, {"text": "古代神话里讲了很多神仙的新闻，大家都很喜欢听。", "explanation": "这里应该用〈故事〉。新闻报道的是最近发生的真实事件，不能用来指神仙的传说。"}, {"text": "这盆花的新闻很好闻，屋里都是香味。", "explanation": "这里应该用〈气味〉。“好闻”说的是气味，新闻是报道最近发生的事件，不能用来指花的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会说话，也不能预报天气。"}, {"text": "作业", "is_correct": false, "explanation": "配价：“说”的主语应是能说话的人或信息来源，“作业”不能充当，句子不成立。"}, {"text": "新闻", "is_correct": true, "explanation": "“新闻”能告诉人们信息，可以作“说”的主语，与“明天会下大雪”的预报内容相符。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能发布天气信息，“说明天会下大雪”无法成立。"}], "explanations": {"石头": "语义：石头不会说话，也不能预报天气。", "作业": "配价：“说”的主语应是能说话的人或信息来源，“作业”不能充当，句子不成立。", "新闻": "“新闻”能告诉人们信息，可以作“说”的主语，与“明天会下大雪”的预报内容相符。", "钥匙": "语义：钥匙不能发布天气信息，“说明天会下大雪”无法成立。"}, "sentence_index": 6, "correct_answer": "新闻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上都写新闻，记录自己当天的心情。", "explanation": "这里应该用〈日记〉。“记录自己当天的心情”是私人内容，新闻报道的是公众关心的事件，不用来记录个人心情。"}, {"text": "老师出了一个新闻，让我们猜。", "explanation": "这里应该用〈谜语〉。新闻是报道已经发生的事件，不用来出题让人猜。"}, {"text": "他许下一个新闻，希望明年能去旅行。", "explanation": "这里应该用〈愿望〉。“许下”的宾语是愿望、诺言，新闻不能被“许下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈昨天晚上在手机上看了一把新闻。", "corrected_sentence": "妈妈昨天晚上在手机上看了一条新闻。", "error_description": "错误：“新闻”应用量词“条”，不能用“把”（“把”用于有柄的东西）。应说“看了一条新闻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹今天在网上看到了一本新闻。", "corrected_sentence": "妹妹今天在网上看到了一条新闻。", "error_description": "错误：“新闻”应用量词“条”，不能用“本”（“本”用于书籍、笔记等）。应说“一条新闻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
