INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10193, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指装订成册、篇幅较小的书籍或印刷品。", "primary_collocate": null, "pronunciation": "xiǎo cè zi", "ipa": "ɕjaʊ˨˩˦ tsʰɤ˥˩ tsɨ", "syllable_count": 3, "sentences": [{"text": "他在书店买了一本小册子，回家慢慢看。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小册子只有二十页，几分钟就能读完。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院发给病人一本健康小册子。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行社给我们一本介绍景点的小册子。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把宣传小册子放进了包里。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份小册子用图片讲解了使用方法。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者在路口发小册子，介绍环保知识。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小册子很薄，可以放进口袋里。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小册子的封面印着学校的名字。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览会入口处有免费的小册子。", "target_word": "小册子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "小冊子", "label": "繁体"}], "register": "中性", "sense_fingerprint": "装订成册、篇幅较小的书或印刷品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a75c456c-0a28-4657-b2af-ed1ca1e72345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10193, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能“慢慢看”，也不是书店里买来的读物，“一本钥匙”不成立。"}, {"text": "小册子", "is_correct": true, "explanation": "“买了一本小册子”指在书店买到的装订成册、篇幅较小的印刷品，可以“慢慢看”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食品，不能“慢慢看”，也不是书店里买来的读物。"}, {"text": "货币", "is_correct": false, "explanation": "语义：货币不能“慢慢看”，也不是书店里买来的读物，“一本货币”不成立。"}], "explanations": {"钥匙": "语义：钥匙不能“慢慢看”，也不是书店里买来的读物，“一本钥匙”不成立。", "小册子": "“买了一本小册子”指在书店买到的装订成册、篇幅较小的印刷品，可以“慢慢看”。", "蛋糕": "语义：蛋糕是食品，不能“慢慢看”，也不是书店里买来的读物。", "货币": "语义：货币不能“慢慢看”，也不是书店里买来的读物，“一本货币”不成立。"}, "sentence_index": 0, "correct_answer": "小册子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本小册子有四百多页，我们要学一个学期。", "explanation": "这里应该用〈课本〉。小册子篇幅较小，只有几十页，几百页的厚书要用“课本”。"}, {"text": "我们在操场上玩了一个小册子。", "explanation": "这里应该用〈游戏〉。“玩”的对象是游戏、玩具，小册子是用来读的印刷品，不能“玩”。"}, {"text": "天冷了，妈妈给我穿上了一件小册子。", "explanation": "这里应该用〈外套〉。“穿”的对象是衣服，小册子是印刷品，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是用来介绍环保知识的印刷品，“发玩具介绍知识”说不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：路口分发的应是宣传品，“工资”不能这样分发来介绍知识。"}, {"text": "小册子", "is_correct": true, "explanation": "“发小册子”指在路口分发宣传读物，与“介绍环保知识”相符。"}, {"text": "枕头", "is_correct": false, "explanation": "语义：枕头不是宣传品，不能在路口用来介绍环保知识。"}], "explanations": {"玩具": "语义：玩具不是用来介绍环保知识的印刷品，“发玩具介绍知识”说不通。", "工资": "搭配：路口分发的应是宣传品，“工资”不能这样分发来介绍知识。", "小册子": "“发小册子”指在路口分发宣传读物，与“介绍环保知识”相符。", "枕头": "语义：枕头不是宣传品，不能在路口用来介绍环保知识。"}, "sentence_index": 6, "correct_answer": "小册子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我早上吃了一份小册子。", "explanation": "这里应该用〈面包〉。“吃”的对象是食物，小册子是印刷品，不能吃。"}, {"text": "他在学校话剧里演了一个小册子。", "explanation": "这里应该用〈角色〉。“演”的对象是角色，小册子不能被演。"}, {"text": "妈妈在烤箱里烤了一个小册子。", "explanation": "这里应该用〈蛋糕〉。“烤”的对象是食物，小册子是印刷品，不能烤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐把那只旅游小册子递给了我。", "corrected_sentence": "姐姐把那本旅游小册子递给了我。", "error_description": "错误：“小册子”应用量词“本”，不能用“只”（“只”用于动物等）。应说“那本旅游小册子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很快就把那本小册子吃完了。", "corrected_sentence": "他很快就把那本小册子看完了。", "error_description": "错误：“吃”不能搭配“小册子”，阅读印刷品应用“看”。应说“看完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
