INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10197, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "迫切地希望得到或实现某个目标。", "primary_collocate": null, "pronunciation": "kě qiú", "ipa": "kʰɤ˨˩˦ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "随着出版物种类的丰富，除宗教文献外，科学论著、文学作品、法律文本乃至新闻小册子广泛流通，公众对知识的渴求被前所未有地激发。", "target_word": "渴求", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "孩子们渴求着知识，每天都认真读书。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直渴求自由，终于离开了小城。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人渴求成功，也愿意付出努力。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人渴求亲人的理解，却很少说出口。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就渴求得到老师的肯定。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他渴求过一位真正理解他的朋友，却一直没有找到。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期缺水的地区，人们渴求干净的水。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争年代，人们渴求和平与安定。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生渴求更好的学习机会，老师也看到了。", "target_word": "渴求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "渴求着", "label": "体标：着"}, {"form": "渴求过", "label": "体标：过"}, {"form": "渴求了", "label": "体标：了"}], "register": "书面", "sense_fingerprint": "迫切地希望得到或实现某个目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b713ff2c-e8ec-4a37-94c3-89752342a172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10197, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "渴求", "is_correct": true, "explanation": "「渴求」指迫切地想要得到，与「激发」的积极语境相合。"}, {"text": "厌恶", "is_correct": false, "explanation": "语义：「厌恶」是反感，与「公众对知识的…被前所未有地激发」的意思相反。"}, {"text": "轻视", "is_correct": false, "explanation": "搭配：「激发」多用于积极的心理，不与「轻视」搭配。"}, {"text": "漠视", "is_correct": false, "explanation": "语义：「漠视」表示不在意，与前所未有地被激发的情形矛盾。"}], "explanations": {"渴求": "「渴求」指迫切地想要得到，与「激发」的积极语境相合。", "厌恶": "语义：「厌恶」是反感，与「公众对知识的…被前所未有地激发」的意思相反。", "轻视": "搭配：「激发」多用于积极的心理，不与「轻视」搭配。", "漠视": "语义：「漠视」表示不在意，与前所未有地被激发的情形矛盾。"}, "sentence_index": 0, "correct_answer": "渴求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我渴求你帮我修一下电脑。", "explanation": "这里应该用〈请求〉。「渴求」指自己迫切想要，不用于请别人帮忙。"}, {"text": "我渴求一本字典，明天上课要用。", "explanation": "这里应该用〈需要〉。「渴求」表示极其迫切的愿望，日常一般的需要用「需要」即可。"}, {"text": "我渴求周末能睡个懒觉。", "explanation": "这里应该用〈盼望〉。「渴求」指迫切想得到或实现重要目标，用于周末睡懒觉这类日常小愿望显得过于强烈，应用「盼望」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10197, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渴求", "is_correct": true, "explanation": "「渴求过一位」指曾经迫切地想要遇到这样一位朋友，与后文「却一直没有找到」的寻求相合。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：「躲避」表示有意避开，与「却一直没有找到」所暗示的主动寻找相矛盾。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：「讨厌」表示反感，与「真正理解他」的正面描述相矛盾。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：「忽视」表示不予重视，与「却一直没有找到」所暗示的主动寻找不相接。"}], "explanations": {"渴求": "「渴求过一位」指曾经迫切地想要遇到这样一位朋友，与后文「却一直没有找到」的寻求相合。", "躲避": "语义：「躲避」表示有意避开，与「却一直没有找到」所暗示的主动寻找相矛盾。", "讨厌": "语义：「讨厌」表示反感，与「真正理解他」的正面描述相矛盾。", "忽视": "语义：「忽视」表示不予重视，与「却一直没有找到」所暗示的主动寻找不相接。"}, "sentence_index": 6, "correct_answer": "渴求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长渴求我们明天去开会。", "explanation": "这里应该用〈邀请〉。「渴求」表示自己迫切想要，不用于请对方来做某事。"}, {"text": "我们在车站渴求你。", "explanation": "这里应该用〈等待〉。「渴求」指迫切想得到，不表示在某处耐心等候某人。"}, {"text": "他渴求一瓶酸奶，买完就喝了。", "explanation": "这里应该用〈想要〉。「渴求」表示极其迫切的愿望，买一瓶酸奶用「想要」即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里的老人渴求过一场大雪，盼着来年的麦子长得好。", "corrected_sentence": "村里的老人渴求着一场大雪，盼着来年的麦子长得好。", "error_description": "体标「过」用错：「渴求过」表示曾经有过的渴望，与“盼着来年”的将来语境不合，应用「渴求着」表示持续的渴望。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个年轻人渴求了一份体面的工作，却一直没有机会。", "corrected_sentence": "这个年轻人渴求过一份体面的工作，却一直没有机会。", "error_description": "体标「了」用错：「渴求」是持续的心理状态，一般不用「了」表示完成；此处指曾经有过的渴望、至今未得到，应用「渴求过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10201, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻挠", "is_correct": true, "explanation": "反义：“促成”使事情顺利达成，“阻挠”使事情无法进行，二者意思相反。"}, {"text": "倾听", "is_correct": false, "explanation": "与“促成”不构成反义关系，“倾听”指注意地听。"}, {"text": "更换", "is_correct": false, "explanation": "与“促成”不构成反义关系，“更换”指用新的替换旧的。"}, {"text": "烘焙", "is_correct": false, "explanation": "与“促成”不构成反义关系，“烘焙”指用火烤制食品。"}], "correct_answer": "阻挠", "explanations": {"阻挠": "反义：“促成”使事情顺利达成，“阻挠”使事情无法进行，二者意思相反。", "倾听": "与“促成”不构成反义关系，“倾听”指注意地听。", "更换": "与“促成”不构成反义关系，“更换”指用新的替换旧的。", "烘焙": "与“促成”不构成反义关系，“烘焙”指用火烤制食品。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10201, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻挠", "is_correct": true, "explanation": "反义：“促成”使事情顺利达成，“阻挠”使事情无法进行，二者意思相反。"}, {"text": "观察", "is_correct": false, "explanation": "与“促成”不构成反义关系，“观察”指仔细看以了解情况。"}, {"text": "修补", "is_correct": false, "explanation": "与“促成”不构成反义关系，“修补”指修理破损的东西。"}, {"text": "包装", "is_correct": false, "explanation": "与“促成”不构成反义关系，“包装”指用纸或盒子把东西裹起来。"}], "correct_answer": "阻挠", "explanations": {"阻挠": "反义：“促成”使事情顺利达成，“阻挠”使事情无法进行，二者意思相反。", "观察": "与“促成”不构成反义关系，“观察”指仔细看以了解情况。", "修补": "与“促成”不构成反义关系，“修补”指修理破损的东西。", "包装": "与“促成”不构成反义关系，“包装”指用纸或盒子把东西裹起来。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10201, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "推动事情发展，使达到预期的结果。", "primary_collocate": null, "pronunciation": "cù chéng", "ipa": "tsʰu˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这种基于共识的集体行动，催生出一种新型的公共治理雏形：当某片防护林因规划争议面临砍伐时，村民代表能依据长期积累的生态数据与法律条文，在听证会上提出有理有据的反对意见，并最终促成替代方案的出台。", "target_word": "促成", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种知识传播的民主化，直接促成了文艺复兴的思想复兴、宗教改革的教义争辩以及科学革命的经验积累。", "target_word": "促成", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "朋友的帮助促成了这次合作。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想促成两家公司合作。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次见面促成了他们的婚事。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的鼓励促成了他的决定。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理努力促成这笔生意。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的努力促成了这件好事。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛促成了两国的交流。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们希望促成双方见面。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "促成了", "label": "体标"}, {"form": "促成过", "label": "体标"}], "register": "书面", "sense_fingerprint": "推动事情发展并使它达到预期结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77bd49ee-81b2-46c0-a146-5020ea436bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10201, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能带“替代方案的出台”作宾语，句意荒谬。"}, {"text": "促成", "is_correct": true, "explanation": "正确：“促成”指推动事情达到预期结果，与“最终”及“替代方案的出台”的语境相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“出台”搭配，无法表示推动事情达成。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”不能支配“出台”这样的事件名词，句中无法成立。"}], "explanations": {"吃": "语义：“吃”不能带“替代方案的出台”作宾语，句意荒谬。", "促成": "正确：“促成”指推动事情达到预期结果，与“最终”及“替代方案的出台”的语境相符。", "洗": "搭配：“洗”不能与“出台”搭配，无法表示推动事情达成。", "踢": "搭配：“踢”不能支配“出台”这样的事件名词，句中无法成立。"}, "sentence_index": 0, "correct_answer": "促成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场大雨促成了一场洪水。", "explanation": "这里应该用〈导致〉。促成指推动事情朝预期的好结果发展，洪水是不良后果，不能用“促成”。"}, {"text": "他的粗心促成了这次失败。", "explanation": "这里应该用〈造成〉。促成带有使事情成功的意思，失败是不利结果，不能用“促成”。"}, {"text": "地震促成了这座古城的倒塌。", "explanation": "这里应该用〈导致〉。促成指推动事情朝预期的好结果发展，古城倒塌是不良后果，应说“导致”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能带“生意”作宾语，“经理努力唱这笔生意”句意荒谬。"}, {"text": "劝", "is_correct": false, "explanation": "搭配：“劝”的宾语通常是人，不能说“劝这笔生意”。"}, {"text": "促成", "is_correct": true, "explanation": "正确：“促成”指推动事情达成，与“努力”及“这笔生意”搭配，句意通顺。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”不能用来指对生意采取行动，句意荒谬。"}], "explanations": {"唱": "语义：“唱”不能带“生意”作宾语，“经理努力唱这笔生意”句意荒谬。", "劝": "搭配：“劝”的宾语通常是人，不能说“劝这笔生意”。", "促成": "正确：“促成”指推动事情达成，与“努力”及“这笔生意”搭配，句意通顺。", "闻": "语义：“闻”不能用来指对生意采取行动，句意荒谬。"}, "sentence_index": 6, "correct_answer": "促成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们希望促成这次事故。", "explanation": "这里应该用〈避免〉。促成指推动好事成功，不能用于人们不希望发生的事故。"}, {"text": "他想促成那件往事。", "explanation": "这里应该用〈遗忘〉。促成针对将要发生的事，已经过去的往事不能“促成”。"}, {"text": "他想促成这块石头。", "explanation": "这里应该用〈发现〉。促成的对象是事情或结果，不能是具体的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次会议促成着一项重要合作。", "corrected_sentence": "这次会议促成了一项重要合作。", "error_description": "“着”用错：“促成”表示事情已经达成，完成时应用“了”，不能用“着”表示持续。错误：促成着。正确：促成了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位经理促成着那笔大生意。", "corrected_sentence": "这位经理促成了那笔大生意。", "error_description": "“着”用错：“促成”表示事情已经达成，完成时应用“了”，不能用“着”表示持续。错误：促成着。正确：促成了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
