INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10202, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "14-17世纪欧洲的一场思想文化运动，主张复兴古希腊罗马文化，反对宗教束缚，促进了艺术、科学和文学的发展。", "primary_collocate": null, "pronunciation": "wén yì fù xīng", "ipa": "wən˧˥ i˥˩ fu˥˩ ɕiŋ˥˥", "syllable_count": 4, "sentences": [{"text": "这种知识传播的民主化，直接促成了文艺复兴的思想复兴、宗教改革的教义争辩以及科学革命的经验积累。", "target_word": "文艺复兴", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "至文艺复兴时期，五线谱逐渐确立为标准，配合小节线、调号与拍号的引入，记谱法日趋精密。", "target_word": "文艺复兴", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "文艺复兴开始于意大利。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文艺复兴让欧洲的艺术发展得很快。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "达芬奇是文艺复兴时期的画家。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上讲了文艺复兴。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文艺复兴影响了欧洲的科学和文学。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我读过一本写文艺复兴的书。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文艺复兴时期出现了很多新思想。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市保存着文艺复兴时期的建筑。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "文艺复兴时期", "label": "复合"}, {"form": "意大利文艺复兴", "label": "复合"}], "register": "书面", "sense_fingerprint": "14-17世纪欧洲的思想文化运动，复兴古希腊罗马文化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a854fec-be2f-4f93-bb5b-d6f5ac612a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10202, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文艺复兴", "is_correct": true, "explanation": "“文艺复兴”指欧洲的思想文化运动，与“思想复兴”及并列的宗教改革、科学革命相配。"}, {"text": "丝绸之路", "is_correct": false, "explanation": "语义：“丝绸之路”是贸易通道，不是思想文化运动，不能“促成”其思想复兴。"}, {"text": "高考", "is_correct": false, "explanation": "语义：“高考”是入学考试，与并列的宗教改革、科学革命不属同类。"}, {"text": "老外", "is_correct": false, "explanation": "语域：“老外”口语色彩较强，与本段书面语域不符，且指人而非运动。"}], "explanations": {"文艺复兴": "“文艺复兴”指欧洲的思想文化运动，与“思想复兴”及并列的宗教改革、科学革命相配。", "丝绸之路": "语义：“丝绸之路”是贸易通道，不是思想文化运动，不能“促成”其思想复兴。", "高考": "语义：“高考”是入学考试，与并列的宗教改革、科学革命不属同类。", "老外": "语域：“老外”口语色彩较强，与本段书面语域不符，且指人而非运动。"}, "sentence_index": 0, "correct_answer": "文艺复兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩文艺复兴了很多。", "explanation": "这里应该用〈提高〉。“文艺复兴”是名词，指欧洲的历史运动，不能作动词表示成绩变好。"}, {"text": "他是一位文艺复兴。", "explanation": "这里应该用〈代表人物〉。“文艺复兴”指一场运动，不指人，说某人是它不合适。"}, {"text": "欧洲出现了一本文艺复兴。", "explanation": "这里的量词应为“场”。“本”用于书籍，文艺复兴是一场运动，不是书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文艺复兴", "is_correct": true, "explanation": "“文艺复兴”指影响欧洲科学与文学的文化运动，符合句意。"}, {"text": "熊猫", "is_correct": false, "explanation": "语义：“熊猫”是动物，不能影响欧洲的科学和文学。"}, {"text": "空调", "is_correct": false, "explanation": "语义：“空调”是家电，与科学和文学的影响无关。"}, {"text": "大妈", "is_correct": false, "explanation": "语域：“大妈”是口语称呼，指人而非运动，与书面语境不协调。"}], "explanations": {"文艺复兴": "“文艺复兴”指影响欧洲科学与文学的文化运动，符合句意。", "熊猫": "语义：“熊猫”是动物，不能影响欧洲的科学和文学。", "空调": "语义：“空调”是家电，与科学和文学的影响无关。", "大妈": "语域：“大妈”是口语称呼，指人而非运动，与书面语境不协调。"}, "sentence_index": 6, "correct_answer": "文艺复兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们周末去文艺复兴旅游。", "explanation": "这里应该用〈意大利〉。“文艺复兴”是历史运动，不是地点，不能作旅游目的地。"}, {"text": "我每天吃文艺复兴。", "explanation": "这里应该用〈早饭〉。“吃”的对象应是食物，“文艺复兴”是历史运动，不能吃。"}, {"text": "我们参观了一座文艺复兴。", "explanation": "这里应该用〈博物馆〉。“文艺复兴”是历史运动，不是可以参观的场所，改为“参观了一座博物馆”才通顺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学习了很文艺复兴的艺术。", "corrected_sentence": "我们学习了文艺复兴的艺术。", "error_description": "错误：“文艺复兴”是名词，不能被程度副词“很”修饰（很文艺复兴）。正确：去掉“很”，“文艺复兴”直接作定语修饰“艺术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "欧洲历史上发生过一座文艺复兴。", "corrected_sentence": "欧洲历史上发生过一场文艺复兴。", "error_description": "错误：量词“座”用于建筑，不能修饰运动（一座文艺复兴）。正确：“一场文艺复兴”，“场”用于运动、事件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
