INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人的想法、观念或认识。", "primary_collocate": null, "pronunciation": "sī xiǎng", "ipa": "sɹ̩˥ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的思想很开放，愿意听不同的意见。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的思想影响了很多学生。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人的思想常常比老人更新。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了很多书，思想也变得成熟了。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两代人的思想不同，常常谈不到一起。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章表达了作者深刻的思想。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小受父亲思想的影响，也爱读书。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的旧思想不容易改变。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把自己的思想写成一本书。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，大家交流了各自的思想。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种思想", "label": "量词：种"}, {"form": "一套思想", "label": "量词：套"}, {"form": "思想家", "label": "复合"}, {"form": "思想性", "label": "复合"}], "register": "书面", "sense_fingerprint": "人的想法、观念或认识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b713ff2c-e8ec-4a37-94c3-89752342a172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思想", "is_correct": true, "explanation": "「思想」指想法、观念，「很开放」形容观念，与「愿意听不同的意见」相合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：「脾气」指性格，不能说「很开放」，与「听不同的意见」的语境不符。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：「开放」不能用来形容相貌。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：「很开放」不能修饰身高。"}], "explanations": {"思想": "「思想」指想法、观念，「很开放」形容观念，与「愿意听不同的意见」相合。", "脾气": "语义：「脾气」指性格，不能说「很开放」，与「听不同的意见」的语境不符。", "相貌": "体貌：「开放」不能用来形容相貌。", "身高": "搭配：「很开放」不能修饰身高。"}, "sentence_index": 0, "correct_answer": "思想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上骑思想去上班。", "explanation": "这里应该用〈自行车〉。「思想」是抽象的想法，不能骑；能骑着上班的是自行车。"}, {"text": "这道菜的思想有点儿咸。", "explanation": "这里应该用〈味道〉。「咸」形容食物的味道，「思想」指人的想法，不能用「咸」形容。"}, {"text": "这个人的思想很英俊，很受欢迎。", "explanation": "这里应该用〈相貌〉。「英俊」形容外貌，不能用来形容思想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思想", "is_correct": true, "explanation": "「思想」指人的观念，可以受他人影响，与「受…的影响」和「也爱读书」相合。"}, {"text": "外表", "is_correct": false, "explanation": "语义：「外表」与「也爱读书」的影响无关，不合语境。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：「影响」一般指思想、性格等，不说受身材的影响。"}, {"text": "体格", "is_correct": false, "explanation": "体貌：「体格」指身体状况，与「也爱读书」的影响不符。"}], "explanations": {"思想": "「思想」指人的观念，可以受他人影响，与「受…的影响」和「也爱读书」相合。", "外表": "语义：「外表」与「也爱读书」的影响无关，不合语境。", "身材": "搭配：「影响」一般指思想、性格等，不说受身材的影响。", "体格": "体貌：「体格」指身体状况，与「也爱读书」的影响不符。"}, "sentence_index": 6, "correct_answer": "思想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行是我最难忘的思想。", "explanation": "这里应该用〈经历〉。「思想」指想法，不能指一次具体的旅行。"}, {"text": "她把思想夹进了相册。", "explanation": "这里应该用〈照片〉。「思想」是抽象的，不能像照片那样夹进相册。"}, {"text": "我送给她一份生日思想。", "explanation": "这里应该用〈礼物〉。「思想」是抽象的想法，不能当作礼物送给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位作家有一只独特的思想，对后来的年轻人很有启发。", "corrected_sentence": "这位作家有一种独特的思想，对后来的年轻人很有启发。", "error_description": "量词错误：「思想」应用量词「种」，不能用「只」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的思想的很开明，常常替别人着想。", "corrected_sentence": "他的思想很开明，常常替别人着想。", "error_description": "结构助词错误：「思想」后多出了「的」。「很开明」是形容词谓语，前面不能加「的」，应写作「他的思想很开明」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
