INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10204, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指国家、民族、文化等衰落后重新兴盛起来。", "primary_collocate": null, "pronunciation": "fù xīng", "ipa": "fu˥˩ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "这种知识传播的民主化，直接促成了那个古老文明的复兴、宗教改革的教义争辩以及科学革命的经验积累。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个古老的民族正在复兴。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗歌在那个时代复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要复兴，先要发展教育。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，这个国家慢慢复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们希望传统文化能够复兴。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们相信，只要努力，民族一定会复兴。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种古老的艺术在今天复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济好了，这座古城的文化也复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个王朝衰落后，一直没有复兴。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复兴了", "label": "体标"}, {"form": "復興", "label": "繁体"}, {"form": "文艺复兴", "label": "复合"}], "register": "书面", "sense_fingerprint": "国家民族文化衰落后重新兴盛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a99ff1f-84fe-4580-9f45-814e6a0bd5f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10204, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复兴", "is_correct": true, "explanation": "复兴（fù xīng）指国家、民族、文化衰落后重新兴盛，是正确答案。"}, {"text": "福星", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，福星意思是带来好运的人或物。"}, {"text": "复姓", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，复姓指由两个或以上汉字组成的姓，如“欧阳”。"}, {"text": "赋性", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，赋性意思是天生的性情。"}], "explanations": {"复兴": "复兴（fù xīng）指国家、民族、文化衰落后重新兴盛，是正确答案。", "福星": "fú（第二声）与 fù（第四声）声调不同，福星意思是带来好运的人或物。", "复姓": "xìng（第四声）与 xīng（第一声）声调不同，复姓指由两个或以上汉字组成的姓，如“欧阳”。", "赋性": "xìng（第四声）与 xīng（第一声）声调不同，赋性意思是天生的性情。"}, "sentence_index": null, "correct_answer": "复兴"}, "level_3": {"options": [{"text": "复兴", "is_correct": true, "explanation": "“古老文明的复兴”指文明重新兴盛，与“直接促成了”的积极进程一致。"}, {"text": "衰退", "is_correct": false, "explanation": "语义：衰退指衰落，与“直接促成了”的积极结果相反。"}, {"text": "压制", "is_correct": false, "explanation": "语义：压制指强行限制，与“知识传播的民主化”促进思想发展的语境相反。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”指毁坏，“直接促成了……破坏”与后面的积极成果（宗教改革、科学革命）相冲突。"}], "explanations": {"复兴": "“古老文明的复兴”指文明重新兴盛，与“直接促成了”的积极进程一致。", "衰退": "语义：衰退指衰落，与“直接促成了”的积极结果相反。", "压制": "语义：压制指强行限制，与“知识传播的民主化”促进思想发展的语境相反。", "破坏": "语义：“破坏”指毁坏，“直接促成了……破坏”与后面的积极成果（宗教改革、科学革命）相冲突。"}, "sentence_index": 0, "correct_answer": "复兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经过休息，他的体力复兴了。", "explanation": "这里应该用〈恢复〉。复兴指衰落的国家、文化或事业重新兴盛，体力的恢复要用恢复。"}, {"text": "他的病情终于复兴了。", "explanation": "这里应该用〈好转〉。复兴用于国家、民族、文化，病情的变化要用好转。"}, {"text": "这台旧机器修好以后又复兴了。", "explanation": "这里应该用〈修复〉。修复指把损坏的机器修好，复兴不用于机器的修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10204, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "复兴", "is_correct": true, "explanation": "复兴（fù xīng）指国家、民族、文化衰落后重新兴盛，是正确答案。"}, {"text": "复行", "is_correct": false, "explanation": "xíng（第二声）与 xīng（第一声）声调不同，复行意思是再次行走或重新施行。"}, {"text": "复性", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，复性意思是恢复本性。"}, {"text": "福星", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，福星意思是带来好运的人或物。"}], "explanations": {"复兴": "复兴（fù xīng）指国家、民族、文化衰落后重新兴盛，是正确答案。", "复行": "xíng（第二声）与 xīng（第一声）声调不同，复行意思是再次行走或重新施行。", "复性": "xìng（第四声）与 xīng（第一声）声调不同，复性意思是恢复本性。", "福星": "fú（第二声）与 fù（第四声）声调不同，福星意思是带来好运的人或物。"}, "sentence_index": null, "correct_answer": "复兴"}, "level_3": {"options": [{"text": "复兴", "is_correct": true, "explanation": "“一定会复兴”表达对民族重新兴盛的信心，与“相信”的语境一致。"}, {"text": "衰落", "is_correct": false, "explanation": "语义：衰落指衰弱下去，与“相信”和“一定会”表达的乐观判断相反。"}, {"text": "消亡", "is_correct": false, "explanation": "语义：消亡指消失灭亡，与“相信”所表达的信念相冲突。"}, {"text": "扰乱", "is_correct": false, "explanation": "配价：“扰乱”是及物动词，需要受事宾语，“民族一定会扰乱”缺少宾语，不能直接作谓语。"}], "explanations": {"复兴": "“一定会复兴”表达对民族重新兴盛的信心，与“相信”的语境一致。", "衰落": "语义：衰落指衰弱下去，与“相信”和“一定会”表达的乐观判断相反。", "消亡": "语义：消亡指消失灭亡，与“相信”所表达的信念相冲突。", "扰乱": "配价：“扰乱”是及物动词，需要受事宾语，“民族一定会扰乱”缺少宾语，不能直接作谓语。"}, "sentence_index": 6, "correct_answer": "复兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的公司亏损以后，努力复兴了损失。", "explanation": "这里应该用〈挽回〉。挽回指收回失去的东西，如损失、面子，复兴不能与损失搭配。"}, {"text": "教练的脚伤终于复兴了。", "explanation": "这里应该用〈痊愈〉。复兴用于国家、文化等衰落后重新兴盛的事物，伤病的好转要用痊愈。"}, {"text": "那幅被烧坏的古画终于复兴了。", "explanation": "这里应该用〈复原〉。复原指恢复原样，多用于文物和画作，复兴不用于修复艺术品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个民族终于复兴了过。", "corrected_sentence": "这个民族终于复兴了。", "error_description": "体标错误：“了”与“过”不能同时用在同一动词后，应去掉“过”，说“这个民族终于复兴了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地区正在复兴过。", "corrected_sentence": "这个地区正在复兴。", "error_description": "体标错误：“正在”表示动作进行中，不能与表示经历的“过”同用，应去掉“过”，说“正在复兴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10205, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10205, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10205, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "宗教改革是16世纪欧洲一场反对罗马天主教会权威、推动基督教变革的运动，最终产生了新教。", "primary_collocate": null, "pronunciation": "zōng jiào gǎi gé", "ipa": "tsʊŋ˥˥ tɕjɑʊ̯˥˩ kai̯˨˩˦ kɤ˧˥", "syllable_count": 4, "sentences": [{"text": "这种知识传播的民主化，直接促成了文艺复兴的思想复兴、宗教改革的教义争辩以及科学革命的经验积累。", "target_word": "宗教改革", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "知识的传播对宗教改革很重要。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宗教改革让欧洲的宗教变了很多。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "宗教改革发生在十六世纪的欧洲。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马丁路德开始了宗教改革。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宗教改革产生了新教。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上，我们讲到了马丁路德发起的宗教改革。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宗教改革反对教会的权威。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷术帮助了宗教改革的传播。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宗教改革改变了欧洲人的生活。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宗教改革运动", "label": "复合"}], "register": "书面", "sense_fingerprint": "16世纪欧洲反对罗马天主教会权威、产生新教的运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a854fec-be2f-4f93-bb5b-d6f5ac612a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10205, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业革命", "is_correct": false, "explanation": "搭配：“教义争辩”只用于宗教或学说，“工业革命”是经济技术变革，不能与之搭配。"}, {"text": "宗教改革", "is_correct": true, "explanation": "正确：与前文的“文艺复兴”“科学革命”并列，指16世纪欧洲反对教会权威的运动，与“教义争辩”相符。"}, {"text": "经济危机", "is_correct": false, "explanation": "语义：经济危机是经济现象，没有教义可以争辩，句子读来不通。"}, {"text": "足球比赛", "is_correct": false, "explanation": "语义：足球比赛与“思想复兴”“经验积累”并列不合理，也不涉及教义争辩。"}], "explanations": {"工业革命": "搭配：“教义争辩”只用于宗教或学说，“工业革命”是经济技术变革，不能与之搭配。", "宗教改革": "正确：与前文的“文艺复兴”“科学革命”并列，指16世纪欧洲反对教会权威的运动，与“教义争辩”相符。", "经济危机": "语义：经济危机是经济现象，没有教义可以争辩，句子读来不通。", "足球比赛": "语义：足球比赛与“思想复兴”“经验积累”并列不合理，也不涉及教义争辩。"}, "sentence_index": 0, "correct_answer": "宗教改革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个学生上课很宗教改革。", "explanation": "这里应该用〈认真〉。“宗教改革”是名词，指16世纪欧洲的历史运动，不能用“很”修饰来形容人的表现。"}, {"text": "我们公司每天都在进行宗教改革。", "explanation": "这里应该用〈改革〉。“宗教改革”专指16世纪欧洲反对教会权威的历史运动，不能用来描述公司的日常调整。"}, {"text": "学校为了提高成绩，开展了一场宗教改革。", "explanation": "这里应该用〈运动〉。“宗教改革”特指16世纪欧洲的历史事件，不能用于学校的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“马丁路德发起的”只能修饰运动，“天气”不能被其修饰，句子不通。"}, {"text": "宗教改革", "is_correct": true, "explanation": "正确：指16世纪欧洲的一场历史运动，是历史课常讲的内容，与“历史课上”相符。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语中的闲话，与课堂上讲授历史的正式语境不符。"}, {"text": "红烧肉", "is_correct": false, "explanation": "语义：红烧肉是菜肴，不是历史课讲授的内容。"}], "explanations": {"天气": "语义：“马丁路德发起的”只能修饰运动，“天气”不能被其修饰，句子不通。", "宗教改革": "正确：指16世纪欧洲的一场历史运动，是历史课常讲的内容，与“历史课上”相符。", "八卦": "语域：“八卦”是口语中的闲话，与课堂上讲授历史的正式语境不符。", "红烧肉": "语义：红烧肉是菜肴，不是历史课讲授的内容。"}, "sentence_index": 6, "correct_answer": "宗教改革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他就是宗教改革。", "explanation": "这里应该用〈宗教改革家〉。“宗教改革”是历史事件，不能直接用来称呼人。"}, {"text": "我每天早上都去宗教改革。", "explanation": "这里应该用〈学校〉。“宗教改革”是历史事件，不是地点，不能用“去”表示前往。"}, {"text": "妈妈在超市买了一些宗教改革。", "explanation": "这里应该用〈水果〉。“宗教改革”是历史事件，不是商品，不能用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "十六世纪的欧洲发生了一只宗教改革。", "corrected_sentence": "十六世纪的欧洲发生了一场宗教改革。", "error_description": "错误：“一只宗教改革”，应为“一场宗教改革”。“只”用于动物，宗教改革这类运动应用量词“场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把宗教改革讲很清楚。", "corrected_sentence": "老师把宗教改革讲得很清楚。", "error_description": "错误：补语“清楚”前缺少“得”，应为“讲得很清楚”。动词与补语之间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
