INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10206, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指宗教或某种学说中，作为指导原则的基本信仰和主张。", "primary_collocate": null, "pronunciation": "jiào yì", "ipa": "tɕjɑʊ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "这种知识传播的民主化，直接促成了文艺复兴的思想复兴、宗教改革的教义争辩以及科学革命的经验积累。", "target_word": "教义", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个宗教的教义要求人们善待他人。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认真学习了佛教的基本教义。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同宗教的教义常常有所不同。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师向教徒讲解教义，大家听得很认真。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位僧人一生都遵守着教义。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对教义的理解和别人不一样。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了伊斯兰教的主要教义。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人违背了教义，受到了大家的批评。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把教义当作生活的原则。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条教义", "label": "量词：条"}, {"form": "教义学", "label": "复合"}], "register": "书面", "sense_fingerprint": "宗教或学说中作为指导原则的基本信仰和主张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b713ff2c-e8ec-4a37-94c3-89752342a172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10206, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教义", "is_correct": true, "explanation": "正确。教义指宗教或学说中作为指导原则的基本信仰和主张。"}, {"text": "交易", "is_correct": false, "explanation": "「jiāo（第一声）与 jiào 声调不同，意思是买卖、交易」。"}, {"text": "教育", "is_correct": false, "explanation": "「教育的第二个音节是 yù，与 yì 韵母不同，意思是培养人才的活动」。"}, {"text": "效益", "is_correct": false, "explanation": "「xiào 与 jiào 声母不同（x 与 j），意思是收益、成效」。"}], "explanations": {"教义": "正确。教义指宗教或学说中作为指导原则的基本信仰和主张。", "交易": "「jiāo（第一声）与 jiào 声调不同，意思是买卖、交易」。", "教育": "「教育的第二个音节是 yù，与 yì 韵母不同，意思是培养人才的活动」。", "效益": "「xiào 与 jiào 声母不同（x 与 j），意思是收益、成效」。"}, "sentence_index": null, "correct_answer": "教义"}, "level_3": {"options": [{"text": "教义", "is_correct": true, "explanation": "正确。「宗教改革的教义争辩」指围绕宗教基本主张展开的争论，只有「教义」符合。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是菜谱，不是宗教的基本主张，无法与「宗教改革」的争辩搭配。"}, {"text": "车票", "is_correct": false, "explanation": "搭配：「争辩」的对象是观点或道理，不能说「车票争辩」。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与宗教改革无关，不能成为争辩的内容。"}], "explanations": {"教义": "正确。「宗教改革的教义争辩」指围绕宗教基本主张展开的争论，只有「教义」符合。", "食谱": "语义：食谱是菜谱，不是宗教的基本主张，无法与「宗教改革」的争辩搭配。", "车票": "搭配：「争辩」的对象是观点或道理，不能说「车票争辩」。", "价格": "语义：价格与宗教改革无关，不能成为争辩的内容。"}, "sentence_index": 0, "correct_answer": "教义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次的失败给我留下了一个深刻的教义。", "explanation": "这里应该用〈教训〉。教训指从失败或经历中得到的经验；教义是宗教或学说的基本主张，不能指个人经历的收获。"}, {"text": "这位数学老师的教义很有效，学生们进步很快。", "explanation": "这里应该用〈教学〉。教学指老师讲授知识的过程；教义是宗教或学说的基本主张，不能指数学老师的讲授方法。"}, {"text": "这些年的工作让我积累了宝贵的教义。", "explanation": "这里应该用〈经验〉。经验指从实践中积累的知识和体会；教义是宗教或学说的基本主张，不能指实践中积累的知识。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教义", "is_correct": true, "explanation": "正确。「对……的理解」要求对象是道理或观点，教义符合。"}, {"text": "卫生纸", "is_correct": false, "explanation": "语义：卫生纸不是道理或观点，不能成为「理解」的对象。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子不是可以被理解的道理，与「对……的理解」不搭。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：「理解」多指对抽象内容或道理的理解，不说对冰箱的理解。"}], "explanations": {"教义": "正确。「对……的理解」要求对象是道理或观点，教义符合。", "卫生纸": "语义：卫生纸不是道理或观点，不能成为「理解」的对象。", "鞋子": "语义：鞋子不是可以被理解的道理，与「对……的理解」不搭。", "冰箱": "搭配：「理解」多指对抽象内容或道理的理解，不说对冰箱的理解。"}, "sentence_index": 6, "correct_answer": "教义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他读完这本书，心里有很多教义。", "explanation": "这里应该用〈体会〉。体会指读书或经历后形成的感受和认识；教义是宗教或学说的基本主张，不能指个人的感受。"}, {"text": "他从工作中得到了很多教义。", "explanation": "这里应该用〈收获〉。收获指从劳动或经历中得到的成果；教义是宗教或学说的基本主张，不能说从工作中得到教义。"}, {"text": "这段难忘的教义让他成长了很多。", "explanation": "这里应该用〈经历〉。经历指亲身遭遇过的事情；教义是宗教或学说的基本主张，不能指个人遭遇的事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只教义要求人们诚实。", "corrected_sentence": "这条教义要求人们诚实。", "error_description": "量词错误：教义应用量词「条」，「只」用于动物或成对物品中的一个，不能修饰教义。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他教义了朋友很多道理。", "corrected_sentence": "他教导了朋友很多道理。", "error_description": "词性错误：教义是名词，不能作动词，应改用动词「教导」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
