INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10207, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指双方因意见不合而互相说理，试图说服对方。", "primary_collocate": null, "pronunciation": "zhēng biàn", "ipa": "ʈʂɤŋ˥ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这种知识传播的民主化，直接促成了文艺复兴的思想复兴、宗教改革的教义争辩以及科学革命的经验积累。", "target_word": "争辩", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两个孩子为一道题争辩起来。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们争辩了很久，还是没有结果。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，大家为计划争辩得很热烈。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别和他争辩，他不会听的。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们争辩着谁对谁错，声音越来越大。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不跟家人为小事争辩。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位专家在会上争辩过这个问题。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛后，球迷们争辩谁踢得最好。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲不想争辩，转身走了。", "target_word": "争辩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "争辩了", "label": "体标"}, {"form": "争辩着", "label": "体标"}, {"form": "争辩过", "label": "体标"}], "register": "中性", "sense_fingerprint": "双方意见不合，互相说理，想说服对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b713ff2c-e8ec-4a37-94c3-89752342a172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10207, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "争辩", "is_correct": true, "explanation": "正确。争辩指双方因意见不合而互相说理，试图说服对方。"}, {"text": "政变", "is_correct": false, "explanation": "「zhèng（第四声）与 zhēng（第一声）声调不同，意思是武力推翻政权」。"}, {"text": "生变", "is_correct": false, "explanation": "「shēng 与 zhēng 声母不同（sh 与 zh），意思是出现变化」。"}, {"text": "整编", "is_correct": false, "explanation": "「zhěng（第三声）与 zhēng 声调不同，biān 与 biàn 声调也不同，意思是整顿编制」。"}], "explanations": {"争辩": "正确。争辩指双方因意见不合而互相说理，试图说服对方。", "政变": "「zhèng（第四声）与 zhēng（第一声）声调不同，意思是武力推翻政权」。", "生变": "「shēng 与 zhēng 声母不同（sh 与 zh），意思是出现变化」。", "整编": "「zhěng（第三声）与 zhēng 声调不同，biān 与 biàn 声调也不同，意思是整顿编制」。"}, "sentence_index": null, "correct_answer": "争辩"}, "level_3": {"options": [{"text": "争辩", "is_correct": true, "explanation": "正确。「教义争辩」指围绕宗教主张展开的争论，只有「争辩」符合。"}, {"text": "收割", "is_correct": false, "explanation": "语义：收割指割取庄稼，与宗教改革中的思想争论无关。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是悠闲地走路，不能表示围绕主张的争论。"}, {"text": "烟花", "is_correct": false, "explanation": "语义：烟花是燃放的焰火，与宗教改革中的思想争论无关，「教义烟花」不成立。"}], "explanations": {"争辩": "正确。「教义争辩」指围绕宗教主张展开的争论，只有「争辩」符合。", "收割": "语义：收割指割取庄稼，与宗教改革中的思想争论无关。", "散步": "语义：散步是悠闲地走路，不能表示围绕主张的争论。", "烟花": "语义：烟花是燃放的焰火，与宗教改革中的思想争论无关，「教义烟花」不成立。"}, "sentence_index": 0, "correct_answer": "争辩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两只小狗争辩着一块骨头。", "explanation": "这里应该用〈争抢〉。小狗抢骨头是动手去抢，争辩指用道理互相说服，不能用于抢东西。"}, {"text": "两支球队在赛场上争辩了一个下午。", "explanation": "这里应该用〈比赛〉。比赛指按规则较量技能或体力；争辩指用道理互相说服，不能用于赛场上的较量。"}, {"text": "他一个人坐在房间里争辩了一下午。", "explanation": "争辩需要至少两方持不同意见、互相说理，一个人独自说话不能叫争辩，应说〈自言自语〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10207, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争辩", "is_correct": true, "explanation": "正确。「为小事争辩」指就小事与家人互相说理，符合语境。"}, {"text": "修理", "is_correct": false, "explanation": "配价：「修理」需要具体的宾语，句中没有可修的对象。"}, {"text": "发明", "is_correct": false, "explanation": "语义：发明指创造新事物，不能用来表示为小事而争论。"}, {"text": "播种", "is_correct": false, "explanation": "语义：播种是把种子埋入土中，与为小事而发生的分歧无关。"}], "explanations": {"争辩": "正确。「为小事争辩」指就小事与家人互相说理，符合语境。", "修理": "配价：「修理」需要具体的宾语，句中没有可修的对象。", "发明": "语义：发明指创造新事物，不能用来表示为小事而争论。", "播种": "语义：播种是把种子埋入土中，与为小事而发生的分歧无关。"}, "sentence_index": 6, "correct_answer": "争辩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家餐厅为了争辩顾客，价格一降再降。", "explanation": "这里应该用〈争夺〉。争夺指为得到顾客、市场而竞争；争辩指用道理互相说服，不能以顾客为对象。"}, {"text": "他在台上认真争辩了自己的经历。", "explanation": "这里应该用〈讲述〉。讲述指把经历或故事说给别人听；争辩指用道理互相说服，不能用来形容叙述经历。"}, {"text": "大家在商场门口争辩打折商品。", "explanation": "这里应该用〈抢购〉。抢购指争着买，争辩用于讲道理，不能用来形容争着买东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们为了一件小事争辩下来了。", "corrected_sentence": "他们为了一件小事争辩起来了。", "error_description": "补语错误：表示争论开始应说「争辩起来」；「下来」表示落下或安定，与争辩的开始语义不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们争辩过三个小时，谁也没说服谁。", "corrected_sentence": "他们争辩了三个小时，谁也没说服谁。", "error_description": "时态错误：表示持续一段时间要用「了」；「过」表示曾经发生的经历，不能表示持续时长。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10211, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10211, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10211, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示完全否定或程度极深，相当于‘一点儿也不’。", "primary_collocate": null, "pronunciation": "háo bù", "ipa": "[xɑʊ˧˥ pu˥˩]", "syllable_count": 2, "sentences": [{"text": "可以毫不夸张地说，现代意义上的公共领域、理性批判精神与个体意识的觉醒，皆植根于印刷文化所构筑的信息网络之中。", "target_word": "毫不", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他毫不犹豫地跳进了河里。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对困难，她毫不害怕。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟毫不客气地吃完了我的蛋糕。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我毫不知情。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板毫不在乎别人怎么说。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毫不费力地搬起了箱子。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我毫不怀疑他会成功。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毫不掩饰自己的高兴。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家毫不介意他迟到了。", "target_word": "毫不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，完全否定，一点儿也不", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b713ff2c-e8ec-4a37-94c3-89752342a172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毫不", "is_correct": true, "explanation": "正确：副词“毫不”表示完全否定，“毫不夸张”即一点也不夸张，与句意相合。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示完成，不能与情态动词“可以”搭配，“可以已经夸张地说”不通。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行，与“可以”的可能语义冲突，“可以正在夸张地说”不通。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚发生的时间，与“可以……地说”的可能语义不合。"}], "explanations": {"毫不": "正确：副词“毫不”表示完全否定，“毫不夸张”即一点也不夸张，与句意相合。", "已经": "体貌：“已经”表示完成，不能与情态动词“可以”搭配，“可以已经夸张地说”不通。", "正在": "体貌：“正在”表示进行，与“可以”的可能语义冲突，“可以正在夸张地说”不通。", "刚刚": "语义：“刚刚”指刚发生的时间，与“可以……地说”的可能语义不合。"}, "sentence_index": 0, "correct_answer": "毫不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这件事毫不兴趣。", "explanation": "这里应该用〈毫无〉。毫不只修饰动词或形容词，不能直接修饰名词“兴趣”，名词前应用“毫无”。"}, {"text": "我对数学毫不天赋。", "explanation": "这里应该用〈没有〉。毫不不能直接修饰名词“天赋”，应说“对数学没有天赋”。"}, {"text": "他做事毫不经验。", "explanation": "这里应该用〈缺乏〉。毫不不能直接修饰名词“经验”，应说“做事缺乏经验”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毫不", "is_correct": true, "explanation": "正确：“毫不费力”即一点力气也不费，符合句意。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续，与“搬起了”这一次性动作冲突。"}, {"text": "将", "is_correct": false, "explanation": "体貌：“将”表示将来，与“搬起了”的已完成语义冲突。"}, {"text": "不断", "is_correct": false, "explanation": "语义：“不断”表示反复持续，与一次性的“搬起”动作不合。"}], "explanations": {"毫不": "正确：“毫不费力”即一点力气也不费，符合句意。", "一直": "语义：“一直”表示持续，与“搬起了”这一次性动作冲突。", "将": "体貌：“将”表示将来，与“搬起了”的已完成语义冲突。", "不断": "语义：“不断”表示反复持续，与一次性的“搬起”动作不合。"}, "sentence_index": 6, "correct_answer": "毫不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对这个计划毫不信心。", "explanation": "这里应该用〈毫无〉。毫不只修饰动词或形容词，不能直接修饰名词“信心”，应说“对这个计划毫无信心”。"}, {"text": "他遇事毫不勇气。", "explanation": "这里应该用〈缺少〉。毫不不能修饰名词“勇气”，应说“遇事缺少勇气”。"}, {"text": "这个方法毫不价值。", "explanation": "这里应该用〈毫无〉。毫不不能修饰名词“价值”，应说“这个方法毫无价值”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他毫不地隐瞒自己的想法。", "corrected_sentence": "他毫不隐瞒自己的想法。", "error_description": "错误：“毫不”后多加了“地”。“毫不”是副词，直接修饰动词，不能再加“地”，应说“毫不隐瞒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事我很毫不在乎。", "corrected_sentence": "这件事我毫不在乎。", "error_description": "错误：“毫不”本身已表示程度极深，不能再与程度副词“很”并用，应删去“很”，说“毫不在乎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
