INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10212, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "夸大事实，言过其实。", "primary_collocate": null, "pronunciation": "kuā zhāng", "ipa": "[kʰua˥ ʈʂɑŋ˥]", "syllable_count": 2, "sentences": [{"text": "可以毫不夸张地说，现代意义上的公共领域、理性批判精神与个体意识的觉醒，皆植根于印刷文化所构筑的信息网络之中。", "target_word": "夸张", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他说得太夸张了，我不信。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告的说法很夸张。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的说法有点夸张。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻写得夸张了一些。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说五百人来了，太夸张了吧。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇报道写得很夸张。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里的故事比较夸张。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说他一夜成名一点也不夸张。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我写得不夸张，很真实。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夸张地", "label": "状语形式"}, {"form": "夸张手法", "label": "复合词"}], "register": "中性", "sense_fingerprint": "夸大事实，言过其实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b713ff2c-e8ec-4a37-94c3-89752342a172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夸张", "is_correct": true, "explanation": "正确：“毫不夸张地说”指说话不言过其实，与句意相合。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”指风趣，与“毫不……地说”这种客观陈述的语境不合。"}, {"text": "随便", "is_correct": false, "explanation": "语域：“随便”口语化，与这段书面论述的语域不合。"}, {"text": "精确", "is_correct": false, "explanation": "语义：“精确”指准确，与“毫不……地说”的否定夸大语义冲突。"}], "explanations": {"夸张": "正确：“毫不夸张地说”指说话不言过其实，与句意相合。", "幽默": "语义：“幽默”指风趣，与“毫不……地说”这种客观陈述的语境不合。", "随便": "语域：“随便”口语化，与这段书面论述的语域不合。", "精确": "语义：“精确”指准确，与“毫不……地说”的否定夸大语义冲突。"}, "sentence_index": 0, "correct_answer": "夸张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根绳子夸张了五厘米。", "explanation": "这里应该用〈拉长〉。夸张指夸大事实、言过其实，不表示物体伸长；绳子变长应说“拉长”。"}, {"text": "他的工资夸张了一倍。", "explanation": "这里应该用〈增加〉。夸张不表示数量增长，工资翻倍应说“增加了一倍”。"}, {"text": "这段路夸张了一公里。", "explanation": "这里应该用〈延长〉。夸张不表示路程变长，应说“延长了一公里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夸张", "is_correct": true, "explanation": "正确：“写得很夸张”指报道夸大事实、言过其实，符合句意。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能形容报道的写法。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能形容文字。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，与报道无关。"}], "explanations": {"夸张": "正确：“写得很夸张”指报道夸大事实、言过其实，符合句意。", "响亮": "搭配：“响亮”形容声音，不能形容报道的写法。", "清脆": "搭配：“清脆”形容声音，不能形容文字。", "寒冷": "语义：“寒冷”形容温度，与报道无关。"}, "sentence_index": 6, "correct_answer": "夸张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的开销夸张了一半。", "explanation": "这里应该用〈减少〉。夸张不表示数额下降，应说“开销减少了一半”。"}, {"text": "会议夸张了三天。", "explanation": "这里应该用〈推迟〉。夸张不表示时间的改变，应说“会议推迟了三天”。"}, {"text": "这段录音夸张了一分钟。", "explanation": "这里应该用〈缩短〉。夸张不表示时长减少，应说“录音缩短了一分钟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个说法有些夸张地。", "corrected_sentence": "这个说法有些夸张。", "error_description": "错误：句末“夸张”作谓语，不应加“地”。“地”只用于修饰动词的状语，应说“有些夸张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种话说很夸张，不太可信。", "corrected_sentence": "这种话说得很夸张，不太可信。", "error_description": "错误：程度补语前漏了“得”。“说”后带程度补语时要用“说得很夸张”，不能说“说很夸张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b47aae17-70ff-4dd6-af7c-c32806fc0ff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
