INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10216, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对错误的思想、言论或行为进行系统的分析、评论和否定。", "primary_collocate": null, "pronunciation": "pī pàn", "ipa": "pʰi˥ pʰan˥˩", "syllable_count": 2, "sentences": [{"text": "作者在序言中系统地批判了这种错误观点，指出其中的逻辑漏洞。", "target_word": "批判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批判了这种错误的想法。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章系统地批判了他的观点。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学者们公开批判这种错误的言论。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位作家批判了社会上的不良风气。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作者在书中逐条批判了这种错误的说法。", "target_word": "批判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写书批判过这种错误思想。", "target_word": "批判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸连续发表文章，批判这种错误行为。", "target_word": "批判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认真分析后，批判了这个计划。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在书里系统地批判了旧的教育思想。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "批判了", "label": "完成体"}, {"form": "批判过", "label": "经历体"}, {"form": "批判性", "label": "复合"}, {"form": "批判者", "label": "复合"}], "register": "书面语", "sense_fingerprint": "系统地分析并否定错误的思想、言论或行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6d46d0b-bdfb-4036-8276-2cadd17ec858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批判", "is_correct": true, "explanation": "正确：“系统地批判了这种错误观点”指对错误观点作系统分析与否定，与“指出其中的逻辑漏洞”相合。"}, {"text": "盲从", "is_correct": false, "explanation": "语义：“盲从”指不加思考地听从，与“指出其中的逻辑漏洞”的分析态度相反，句意不通。"}, {"text": "迷信", "is_correct": false, "explanation": "语义：“迷信”指盲目相信，与“指出其中的逻辑漏洞”的否定态度矛盾，句意不通。"}, {"text": "轻信", "is_correct": false, "explanation": "语义：“轻信”指不加辨别地相信，与“指出其中的逻辑漏洞”相矛盾，句意不通。"}], "explanations": {"批判": "正确：“系统地批判了这种错误观点”指对错误观点作系统分析与否定，与“指出其中的逻辑漏洞”相合。", "盲从": "语义：“盲从”指不加思考地听从，与“指出其中的逻辑漏洞”的分析态度相反，句意不通。", "迷信": "语义：“迷信”指盲目相信，与“指出其中的逻辑漏洞”的否定态度矛盾，句意不通。", "轻信": "语义：“轻信”指不加辨别地相信，与“指出其中的逻辑漏洞”相矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "批判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师批判了那位学生的进步。", "explanation": "这里应该用〈表扬〉。批判针对错误的思想、言论或行为，学生的进步应当表扬，不能批判。"}, {"text": "学者们公开批判这种正确的言论。", "explanation": "这里应该用〈赞扬〉。批判的对象必须是错误的东西，正确的言论应当肯定或赞扬，不能批判。"}, {"text": "我批判大家的支持。", "explanation": "这里应该用〈感谢〉。批判指对错误的思想、言论或行为作否定，对大家的支持应当表示感谢，不能批判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批判", "is_correct": true, "explanation": "“写书批判过这种错误思想”，批判的对象是错误思想，与语境一致。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞美好的事物，与“错误思想”相矛盾。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：“歌颂”指颂扬，不能用于“错误思想”，与句意不合。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：“表扬”多用于人或行为，不能以“思想”作宾语。"}], "explanations": {"批判": "“写书批判过这种错误思想”，批判的对象是错误思想，与语境一致。", "赞美": "语义：“赞美”表示称赞美好的事物，与“错误思想”相矛盾。", "歌颂": "语义：“歌颂”指颂扬，不能用于“错误思想”，与句意不合。", "表扬": "搭配：“表扬”多用于人或行为，不能以“思想”作宾语。"}, "sentence_index": 6, "correct_answer": "批判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在本子上批判了他的正确答案。", "explanation": "这里应该用〈肯定〉。批判针对错误的思想、言论或行为，正确的答案应当肯定，不能批判。"}, {"text": "学校在节日里批判了这位烈士。", "explanation": "这里应该用〈缅怀〉。批判指对错误的思想、言论或行为作否定，烈士应当缅怀，不能用批判。"}, {"text": "工人批判了这台旧机器。", "explanation": "这里应该用〈修理〉。批判用于思想、言论等，机器坏了要修理，不能批判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这种错误观点批判了很严厉。", "corrected_sentence": "他对这种错误观点批判得很严厉。", "error_description": "“批判”后面带程度补语时要用“得”引出，不能用“了”。应为“批判得很严厉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这种错误观点批判。", "corrected_sentence": "他把这种错误观点批判了。", "error_description": "“把”字句中，动词“批判”后要带“了”等补充成分，光用动词句子不完整。应为“他把这种错误观点批判了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10217, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10217, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10217, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人的意识、思维活动和一般心理状态。", "primary_collocate": null, "pronunciation": "jīng shén", "ipa": "tɕiŋ˥ ʂən˧˥", "syllable_count": 2, "sentences": [{"text": "可以毫不夸张地说，现代意义上的公共领域、理性批判精神与个体意识的觉醒，皆植根于印刷文化所构筑的信息网络之中。", "target_word": "精神", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他最近工作太忙，精神压力很大。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，睡眠不好会影响人的精神健康。", "target_word": "精神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天他睡得很少，精神状态很差。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好好休息以后，我觉得精神上轻松多了。", "target_word": "精神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在精神上也需要父母的关心。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长期孤单会给老人的精神带来很大的伤害。", "target_word": "精神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，同学们的精神都很紧张。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种病不但伤身体，也伤精神。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做完心理咨询，他的精神负担小了很多。", "target_word": "精神", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精神状态", "label": "复合"}, {"form": "精神压力", "label": "复合"}, {"form": "精神健康", "label": "复合"}], "register": "中性", "sense_fingerprint": "精神：人的意识、思维和心理状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3299c7cb-711f-45ac-8e59-3053bcf7ff57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精神", "is_correct": true, "explanation": "“理性批判精神”指批判的意识与态度，与“个体意识的觉醒”并列，搭配恰当。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：“理性批判”搭配的是精神、态度，不能说“理性批判收入”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是外观，与理性批判这种思想活动无关。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，与理性批判的精神层面无关。"}], "explanations": {"精神": "“理性批判精神”指批判的意识与态度，与“个体意识的觉醒”并列，搭配恰当。", "收入": "搭配：“理性批判”搭配的是精神、态度，不能说“理性批判收入”。", "颜色": "语义：“颜色”是外观，与理性批判这种思想活动无关。", "身材": "体貌：“身材”指人的体形，与理性批判的精神层面无关。"}, "sentence_index": 0, "correct_answer": "精神"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的精神很清脆，老远就能听见。", "explanation": "这里应该用〈声音〉。〈清脆〉形容声音，精神是心理状态，不能用来形容。"}, {"text": "这件衣服的精神很鲜艳，一下子就能看见。", "explanation": "这里应该用〈颜色〉。〈鲜艳〉形容颜色，精神是心理状态，不能这样形容衣服。"}, {"text": "他的精神很笨，连扣子都扣不好。", "explanation": "这里应该用〈手〉。扣扣子靠手，〈笨〉说的是手不灵活；精神是心理状态，不能说“笨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精神", "is_correct": true, "explanation": "“伤害”可以作用于心理状态，“精神”指老人的心理，句意通顺。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是岁数，不会因孤单而受到伤害。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”属于外形，孤单不会给身高带来伤害。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，与“老人”和“伤害”的语境无关。"}], "explanations": {"精神": "“伤害”可以作用于心理状态，“精神”指老人的心理，句意通顺。", "年龄": "语义：“年龄”是岁数，不会因孤单而受到伤害。", "身高": "体貌：“身高”属于外形，孤单不会给身高带来伤害。", "天气": "语义：“天气”是自然现象，与“老人”和“伤害”的语境无关。"}, "sentence_index": 6, "correct_answer": "精神"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一颗很脆弱的精神。", "explanation": "这里应该用〈心〉。“一颗……的心”是固定说法；精神是抽象的心理状态，不能用〈颗〉计量。"}, {"text": "他的精神很小，只能穿三十码的鞋。", "explanation": "这里应该用〈脚〉。〈小〉说的是脚的大小，精神是心理状态，不能用来形容体积。"}, {"text": "这家商店的精神很大，客人很多。", "explanation": "这里应该用〈规模〉。精神指人的心理状态，不能用“很大”来说明商店的规模。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她最近在精神承受着很大的压力。", "corrected_sentence": "她最近在精神上承受着很大的压力。", "error_description": "漏用“上”：心理方面的承受要说“在精神上”，只说“在精神”不符合习惯。错误形式为“在精神承受”，正确形式为“在精神上承受”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到这个消息，他在精神受到了很大的打击。", "corrected_sentence": "听到这个消息，他在精神上受到了很大的打击。", "error_description": "漏用“上”：表示心理方面要说“在精神上”，只说“在精神”不符合习惯。错误形式为“在精神受到”，正确形式为“在精神上受到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10220, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10220, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10220, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指从睡眠中醒来，或比喻从迷惑、模糊状态中醒悟过来。", "primary_collocate": null, "pronunciation": "jué xǐng", "ipa": "tɕyɛ˧˥ ɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "觉醒", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "可以毫不夸张地说，现代意义上的公共领域、理性批判精神与个体意识的觉醒，皆植根于印刷文化所构筑的信息网络之中。", "target_word": "觉醒", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "经历几次失望之后，他终于觉醒，看清了对方的真面目。", "target_word": "觉醒", "complexity_tier": "T3", "furigana": "jué xǐng", "sentence_source": "generated"}, {"text": "这场灾难让人们开始觉醒，重视环境保护。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完这本书，她的女性意识渐渐觉醒了。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青年一代的民族意识正在觉醒。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在失败后才觉醒过来，决定重新做人。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，大地从冬眠中觉醒。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经历这件事，我终于觉醒了，不再盲目相信别人。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当人们觉醒时，社会才会真正改变。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "觉醒了", "label": "完成体标"}, {"form": "觉醒过", "label": "经历体标"}], "register": "书面", "sense_fingerprint": "从沉睡或迷惑中醒来，意识上醒悟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86a9e316-c77e-4d87-af76-e864fd5a52f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "觉醒", "is_correct": true, "explanation": "正确。“日益觉醒的生态自觉”指意识逐渐增强，与后文“逐渐意识到”一致。"}, {"text": "减弱", "is_correct": false, "explanation": "语义：“减弱”指力量变小，与“日益……的生态自觉”及“逐渐意识到”的方向相反。"}, {"text": "消退", "is_correct": false, "explanation": "语义：“消退”指逐渐消失，与句中意识不断增长的语境相矛盾。"}, {"text": "萎缩", "is_correct": false, "explanation": "语义：“萎缩”指变小、衰退，与“日益……的生态自觉”及“逐渐意识到”的增长方向相反。"}], "explanations": {"觉醒": "正确。“日益觉醒的生态自觉”指意识逐渐增强，与后文“逐渐意识到”一致。", "减弱": "语义：“减弱”指力量变小，与“日益……的生态自觉”及“逐渐意识到”的方向相反。", "消退": "语义：“消退”指逐渐消失，与句中意识不断增长的语境相矛盾。", "萎缩": "语义：“萎缩”指变小、衰退，与“日益……的生态自觉”及“逐渐意识到”的增长方向相反。"}, "sentence_index": 0, "correct_answer": "觉醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次期中考试，他的数学成绩终于觉醒了。", "explanation": "这里应该用〈提高〉。觉醒指醒来或醒悟，成绩进步要用提高。"}, {"text": "手术后，他的视力慢慢觉醒了。", "explanation": "这里应该用〈恢复〉。觉醒指醒来或醒悟，视力逐渐恢复正常要用恢复。"}, {"text": "经过治疗，他的病情慢慢觉醒了。", "explanation": "这里应该用〈好转〉。觉醒指醒来或醒悟，病情逐渐变好要用好转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "觉醒", "is_correct": true, "explanation": "正确。“才觉醒过来”指经历失败后醒悟，与“决定重新做人”相呼应。"}, {"text": "沉沦", "is_correct": false, "explanation": "语义：“沉沦”指陷入消极颓废，与“决定重新做人”相反。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”后面不接“过来”表示恢复，不说“才放弃过来”。"}, {"text": "动摇", "is_correct": false, "explanation": "搭配：“动摇”不与“过来”组合表示醒悟，“才动摇过来”不成话。"}], "explanations": {"觉醒": "正确。“才觉醒过来”指经历失败后醒悟，与“决定重新做人”相呼应。", "沉沦": "语义：“沉沦”指陷入消极颓废，与“决定重新做人”相反。", "放弃": "搭配：“放弃”后面不接“过来”表示恢复，不说“才放弃过来”。", "动摇": "搭配：“动摇”不与“过来”组合表示醒悟，“才动摇过来”不成话。"}, "sentence_index": 6, "correct_answer": "觉醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经过治疗，他的伤口慢慢觉醒了。", "explanation": "这里应该用〈复原〉。觉醒指醒来或醒悟，伤口恢复原状要用复原。"}, {"text": "这阵头痛很快觉醒了，他终于能安心工作。", "explanation": "这里应该用〈消退〉。觉醒指醒来或醒悟，头痛逐渐减轻要用消退。"}, {"text": "这阵雷声终于觉醒了，屋里也安静下来。", "explanation": "这里应该用〈停息〉。觉醒指醒来或醒悟，雷声停止要用停息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次事故以后，他终于被觉醒，开始认真工作。", "corrected_sentence": "这次事故以后，他终于觉醒，开始认真工作。", "error_description": "错误在被动：“觉醒”是不及物动词，不能用“被”字句，应去掉“被”，说“他终于觉醒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次事故把他觉醒，不再酗酒。", "corrected_sentence": "这次事故让他觉醒，不再酗酒。", "error_description": "错误在句式：“觉醒”是不及物动词，不能用“把”字句，应改为“让”字句；“让他觉醒”表示使他醒悟。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
