INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10224, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "信息网络是指通过通信线路连接多个计算机或设备，实现信息共享和传输的系统。", "primary_collocate": null, "pronunciation": "xìn xī wǎng luò", "ipa": "ɕin˥˩ ɕi˥ wɑŋ˨˩˦ luo˥˩", "syllable_count": 4, "sentences": [{"text": "学校的每个教室都接入了信息网络，学生可以在线查阅资料。", "target_word": "信息网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代社会离不开信息网络。", "target_word": "信息网络", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公司建立了自己的信息网络。", "target_word": "信息网络", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "信息网络把世界各地的人连在一起。", "target_word": "信息网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校正在建设新的信息网络。", "target_word": "信息网络", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "信息网络出了问题，大家都不能上网。", "target_word": "信息网络", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作是维护信息网络。", "target_word": "信息网络", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "信息网络让我们很快就能查到资料。", "target_word": "信息网络", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院的信息网络保存着病人的资料。", "target_word": "信息网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着科技发展，信息网络越来越重要。", "target_word": "信息网络", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个信息网络", "label": "量词"}, {"form": "信息網絡", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "连接多台设备、实现信息共享和传输的通信系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6d46d0b-bdfb-4036-8276-2cadd17ec858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信息网络", "is_correct": true, "explanation": "正确：“接入了信息网络”指接入由通信线路连接计算机的系统，与“在线查阅资料”相合。"}, {"text": "荒漠", "is_correct": false, "explanation": "语义：“荒漠”是自然地貌，不能被“接入”，句意不通。"}, {"text": "冰川", "is_correct": false, "explanation": "语义：“冰川”是自然景观，不能被“接入”，与句意不合。"}, {"text": "泥沼", "is_correct": false, "explanation": "语义：“泥沼”是自然地貌，不能被“接入”，句意不通。"}], "explanations": {"信息网络": "正确：“接入了信息网络”指接入由通信线路连接计算机的系统，与“在线查阅资料”相合。", "荒漠": "语义：“荒漠”是自然地貌，不能被“接入”，句意不通。", "冰川": "语义：“冰川”是自然景观，不能被“接入”，与句意不合。", "泥沼": "语义：“泥沼”是自然地貌，不能被“接入”，句意不通。"}, "sentence_index": 0, "correct_answer": "信息网络"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "渔民把信息网络撒进了河里。", "explanation": "这里应该用〈渔网〉。信息网络指通过线路连接计算机的系统，不能撒进河里；捕鱼用的是渔网。"}, {"text": "他每天早上喝了一杯信息网络。", "explanation": "这里应该用〈牛奶〉。信息网络是计算机系统，不能喝；喝的应说牛奶。"}, {"text": "他用信息网络织了一件毛衣。", "explanation": "这里应该用〈毛线〉。信息网络指计算机系统，不是织毛衣用的线，织毛衣要用毛线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信息网络", "is_correct": true, "explanation": "“他的工作是维护信息网络”，“维护”的对象是信息网络，句意通顺。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：“闪电”是自然现象，无法被“维护”，与句意不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然状态，不能被人“维护”，句意不通。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：“彩虹”是光学现象，不能作为工作的对象被“维护”。"}], "explanations": {"信息网络": "“他的工作是维护信息网络”，“维护”的对象是信息网络，句意通顺。", "闪电": "语义：“闪电”是自然现象，无法被“维护”，与句意不合。", "天气": "语义：“天气”是自然状态，不能被人“维护”，句意不通。", "彩虹": "语义：“彩虹”是光学现象，不能作为工作的对象被“维护”。"}, "sentence_index": 6, "correct_answer": "信息网络"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙角结满了信息网络。", "explanation": "这里应该用〈蜘蛛网〉。信息网络指计算机系统，不是蜘蛛结的网，墙角结网应说蜘蛛网。"}, {"text": "他在院子周围围了一圈信息网络。", "explanation": "这里应该用〈铁丝网〉。信息网络指计算机系统，不能用来围院子，围院子要用铁丝网。"}, {"text": "这个信息网络很结实，适合挂在篮球场上。", "explanation": "这里应该用〈球网〉。信息网络指计算机系统，不是挂在球场上的网，应说球网。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校正在升级一台信息网络。", "corrected_sentence": "学校正在升级一个信息网络。", "error_description": "“信息网络”的量词应用“个”或“套”，“台”用于机器，不能用于网络。应为“一个信息网络”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院正在建设一只新的信息网络。", "corrected_sentence": "医院正在建设一个新的信息网络。", "error_description": "“信息网络”的量词应用“个”或“套”，“只”用于动物或成对物品中的一个，不能用于网络。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10227, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "双向", "is_correct": true, "explanation": "反义：「双向」与「单向」相对，指两方或两个方面都起作用，与「只有一个方面」相反。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：「明亮」形容光线或颜色，与「单向」不构成相对的关系。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：「柔软」形容质地，与「单向」不构成相对的关系。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：「温暖」形容温度或感受，与「单向」不构成相对的关系。"}], "correct_answer": "双向", "explanations": {"双向": "反义：「双向」与「单向」相对，指两方或两个方面都起作用，与「只有一个方面」相反。", "明亮": "语义：「明亮」形容光线或颜色，与「单向」不构成相对的关系。", "柔软": "语义：「柔软」形容质地，与「单向」不构成相对的关系。", "温暖": "语义：「温暖」形容温度或感受，与「单向」不构成相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10227, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "双向", "is_correct": true, "explanation": "反义：「双向」与「单向」相对，指两方或两个方面都起作用，与「只有一个方面」相反。"}, {"text": "缓慢", "is_correct": false, "explanation": "语义：「缓慢」形容速度，与「单向」不构成相对的关系。"}, {"text": "干净", "is_correct": false, "explanation": "语义：「干净」形容清洁程度，与「单向」不构成相对的关系。"}, {"text": "高大", "is_correct": false, "explanation": "语义：「高大」形容体形或尺寸，与「单向」不构成相对的关系。"}], "correct_answer": "双向", "explanations": {"双向": "反义：「双向」与「单向」相对，指两方或两个方面都起作用，与「只有一个方面」相反。", "缓慢": "语义：「缓慢」形容速度，与「单向」不构成相对的关系。", "干净": "语义：「干净」形容清洁程度，与「单向」不构成相对的关系。", "高大": "语义：「高大」形容体形或尺寸，与「单向」不构成相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10227, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指只有一个方向或一个方面，不涉及其他方向或方面。", "primary_collocate": null, "pronunciation": "dān xiàng", "ipa": "tan˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "值得注意的是，印刷术的影响并非单向的技术决定论。", "target_word": "单向", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他的爱是单向的，对方并不知道。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的交流不是单向的。", "target_word": "单向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好的教学不应该只是单向的。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师生之间的沟通不能是单向的。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种影响不是单向的，而是互相的。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她觉得这段关系是单向的。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的思维太单向，没有看到别的方面。", "target_word": "单向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "媒体不应只做单向的宣传。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习不是单向的，老师也能从学生那里学到东西。", "target_word": "单向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "單向", "label": "繁体"}, {"form": "单向性", "label": "复合"}], "register": "书面语", "sense_fingerprint": "只有一个方向或一个方面，不涉及其他", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6d46d0b-bdfb-4036-8276-2cadd17ec858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单向", "is_correct": true, "explanation": "正确：「并非单向的技术决定论」指影响不是只从技术单向流向社会，只有「单向」能表达这一否定。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：「甜蜜」形容感受或滋味，不能修饰「技术决定论」这类理论。"}, {"text": "热情", "is_correct": false, "explanation": "语义：「热情」形容人的态度，与「印刷术的影响」这类论断无关，句意不通。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：「潮湿」形容环境或物体的含水状态，不能修饰「技术决定论」这类理论。"}], "explanations": {"单向": "正确：「并非单向的技术决定论」指影响不是只从技术单向流向社会，只有「单向」能表达这一否定。", "甜蜜": "语义：「甜蜜」形容感受或滋味，不能修饰「技术决定论」这类理论。", "热情": "语义：「热情」形容人的态度，与「印刷术的影响」这类论断无关，句意不通。", "潮湿": "语义：「潮湿」形容环境或物体的含水状态，不能修饰「技术决定论」这类理论。"}, "sentence_index": 0, "correct_answer": "单向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布料太单向了，穿在身上很不舒服。", "explanation": "这里应该用〈粗糙〉。「单向」不用来形容布料的质地；布料摸着不平滑应说「粗糙」。"}, {"text": "这块饼很单向，一咬就掉渣。", "explanation": "这里应该用〈酥〉。「单向」不能形容食物的口感；一咬就掉渣的食物应说「酥」。"}, {"text": "这杯咖啡太单向了，我喝不下去。", "explanation": "这里应该用〈苦〉。「单向」不能形容味道；咖啡味道太重难以下咽应说「苦」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单向", "is_correct": true, "explanation": "正确：「她觉得这段关系是单向的」指一方投入、另一方不回应，只有「单向」符合句意。"}, {"text": "方正", "is_correct": false, "explanation": "语义：「方正」形容物体的形状，不能用来描述人际关系的性质。"}, {"text": "鲜艳", "is_correct": false, "explanation": "语义：「鲜艳」形容颜色，不能描述「这段关系」的性质。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：「响亮」形容声音，与「这段关系」的性质不相符。"}], "explanations": {"单向": "正确：「她觉得这段关系是单向的」指一方投入、另一方不回应，只有「单向」符合句意。", "方正": "语义：「方正」形容物体的形状，不能用来描述人际关系的性质。", "鲜艳": "语义：「鲜艳」形容颜色，不能描述「这段关系」的性质。", "响亮": "语义：「响亮」形容声音，与「这段关系」的性质不相符。"}, "sentence_index": 6, "correct_answer": "单向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的旋律太单向了，听久了很累。", "explanation": "这里应该用〈单调〉。「单向」不用来形容旋律；旋律变化少、听着乏味应说「单调」。"}, {"text": "这件衣服太单向了，冬天穿不住。", "explanation": "这里应该用〈单薄〉。「单向」不能形容衣物的厚薄，衣服薄应说「单薄」。"}, {"text": "这把椅子太单向了，坐上去就晃。", "explanation": "这里应该用〈摇晃〉。「单向」不用来形容家具的稳固程度；坐上去晃动应说「摇晃」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段友谊对我来说单向的，他并不在意我。", "corrected_sentence": "这段友谊对我来说是单向的，他并不在意我。", "error_description": "「单向」作谓语时，前面要加「是」，应说「是单向的」；漏掉「是」不符合规范。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器单向的传递信息，不能接收反馈。", "corrected_sentence": "这台机器单向地传递信息，不能接收反馈。", "error_description": "「单向」修饰动词「传递」时要用「地」，应说「单向地传递」；用「的」不符合规范。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
