INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10228, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种哲学观点，认为一切事件和人的行为都由先前的原因或自然规律决定，不存在自由选择。", "primary_collocate": null, "pronunciation": "jué dìng lùn", "ipa": "tɕye˧˥ tiŋ˥˩ lwən˥˩", "syllable_count": 3, "sentences": [{"text": "值得注意的是，印刷术的影响并非单向的技术决定论。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "决定论认为一切事情都有原因。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上讲了决定论。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位哲学家不相信决定论。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "决定论和自由意志常常放在一起讨论。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一篇关于决定论的文章。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照决定论，人没有自由选择。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多科学家支持决定论。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "决定论让我们想到命运和选择的问题。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对决定论很感兴趣。", "target_word": "决定论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "決定論", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "哲学上认为一切由原因或规律决定、没有自由选择的观点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6d46d0b-bdfb-4036-8276-2cadd17ec858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10228, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "决定论", "is_correct": true, "explanation": "正确：「并非单向的技术决定论」指技术决定社会的哲学观点，只有「决定论」能作中心词。"}, {"text": "合同", "is_correct": false, "explanation": "语义：“合同”是契约文书，“并非单向的技术合同”句意不通，与句中的哲学论断不相合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”指测试，“并非单向的技术考试”句意不通，与哲学论断无关。"}, {"text": "鉴定", "is_correct": false, "explanation": "语义：“鉴定”指专业评定，“并非单向的技术鉴定”句意不通，句中讨论的是哲学观点。"}], "explanations": {"决定论": "正确：「并非单向的技术决定论」指技术决定社会的哲学观点，只有「决定论」能作中心词。", "合同": "语义：“合同”是契约文书，“并非单向的技术合同”句意不通，与句中的哲学论断不相合。", "考试": "语义：“考试”指测试，“并非单向的技术考试”句意不通，与哲学论断无关。", "鉴定": "语义：“鉴定”指专业评定，“并非单向的技术鉴定”句意不通，句中讨论的是哲学观点。"}, "sentence_index": 0, "correct_answer": "决定论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做了一个重要的决定论。", "explanation": "这里应该用〈选择〉。「决定论」是哲学学说，指一切由原因决定、不存在自由选择的观点，不能指一次作出的选择；做出选择应说「做了一个重要的选择」。"}, {"text": "我们明天开会作个决定论。", "explanation": "这里应该用〈决定〉。开会作出的决断叫「决定」；「决定论」是哲学学说，不能「作」。"}, {"text": "这件事还没有决定论。", "explanation": "这里应该用〈定论〉。「定论」指确定的结论，可说「没有定论」；「决定论」是学说，不能指事情的结论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "决定论", "is_correct": true, "explanation": "正确：「按照决定论」说明判断依据是这一哲学观点，只有「决定论」符合句意。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：「食谱」是做菜的步骤，不能作为判断人是否有自由选择的依据。"}, {"text": "天气预报", "is_correct": false, "explanation": "语义：「天气预报」只说明天气，不能推出人没有自由选择。"}, {"text": "说明书", "is_correct": false, "explanation": "语义：「说明书」是产品使用说明，不能作为推出人没有自由选择的依据。"}], "explanations": {"决定论": "正确：「按照决定论」说明判断依据是这一哲学观点，只有「决定论」符合句意。", "食谱": "语义：「食谱」是做菜的步骤，不能作为判断人是否有自由选择的依据。", "天气预报": "语义：「天气预报」只说明天气，不能推出人没有自由选择。", "说明书": "语义：「说明书」是产品使用说明，不能作为推出人没有自由选择的依据。"}, "sentence_index": 6, "correct_answer": "决定论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的决定论很果断。", "explanation": "这里应该用〈决策〉。「决策」指管理上作出的决定；「决定论」是哲学学说，不能形容公司的行为。"}, {"text": "他办事很有决定论。", "explanation": "这里应该用〈决断〉。形容人做事果断、有主见，用「决断」，不说「决定论」。"}, {"text": "这场决定论很精彩。", "explanation": "这里应该用〈决赛〉。「决赛」指最后一轮比赛，「决定论」不能指比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书详细介绍了一条决定论。", "corrected_sentence": "这本书详细介绍了一种决定论。", "error_description": "「决定论」是哲学学说，量词应用「种」，不用「条」；「条」用于条状事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位学者研究过决定论过。", "corrected_sentence": "这位学者研究过决定论。", "error_description": "「过」只用一次：表示经历的「过」应紧跟动词，写作「研究过决定论」；宾语「决定论」之后不能再加「过」，「研究过决定论过」是错误形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
