INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10233, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种经济制度，生产资料归私人所有，通过市场获取利润。", "primary_collocate": null, "pronunciation": "zī běn zhǔ yì", "ipa": "tsɹ̩˥ pən˨˩ ʈʂu˨˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "它与当时正在兴起的民族国家、教育制度变革及资本主义生产方式相互交织，共同推动社会结构的转型。", "target_word": "资本主义", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "资本主义国家的经济很发达。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资本主义靠市场来获取利润。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲了资本主义的历史。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资本主义社会里，工厂大多归私人所有。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们什么是资本主义。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究过资本主义的发展。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资本主义让市场变得很活跃。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人批评资本主义，也有人支持它。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资本主义和社会主义是两种制度。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "資本主義", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "生产资料私有、依靠市场获取利润的经济制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6d46d0b-bdfb-4036-8276-2cadd17ec858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资本主义", "is_correct": true, "explanation": "正确：句中指当时兴起的经济制度，即资本主义生产方式。"}, {"text": "电影", "is_correct": false, "explanation": "语义：「电影生产方式」不成立，电影不是一种经济制度，不能与「民族国家」「教育制度变革」并列。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「天气生产方式」不成立，天气不是生产形式，不能与「民族国家」「教育制度」并列。"}, {"text": "宗教", "is_correct": false, "explanation": "搭配：「宗教生产方式」不成立，宗教不是生产方式的一种。"}], "explanations": {"资本主义": "正确：句中指当时兴起的经济制度，即资本主义生产方式。", "电影": "语义：「电影生产方式」不成立，电影不是一种经济制度，不能与「民族国家」「教育制度变革」并列。", "天气": "搭配：「天气生产方式」不成立，天气不是生产形式，不能与「民族国家」「教育制度」并列。", "宗教": "搭配：「宗教生产方式」不成立，宗教不是生产方式的一种。"}, "sentence_index": 0, "correct_answer": "资本主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用自己的资本主义开了一家小店。", "explanation": "这里应用〈本钱〉。资本主义指经济制度，不指钱财；表示钱财应说〈本钱〉。"}, {"text": "这位资本主义拥有很多家工厂。", "explanation": "这里应用〈资本家〉。资本主义指制度，不指人。"}, {"text": "我们暑假去资本主义旅游，参观了很多博物馆。", "explanation": "这里应用〈首都〉。资本主义是制度，不是城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资本主义", "is_correct": true, "explanation": "正确：「研究过……的发展」需要一个可以发展的社会或历史对象，资本主义符合。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：「发展」需要可以发展的对象，阳光不能说「发展」。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：雨水没有发展过程，「雨水的发展」不成立。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：「垃圾」指废弃物，不是可以研究其发展的历史对象。"}], "explanations": {"资本主义": "正确：「研究过……的发展」需要一个可以发展的社会或历史对象，资本主义符合。", "阳光": "搭配：「发展」需要可以发展的对象，阳光不能说「发展」。", "雨水": "搭配：雨水没有发展过程，「雨水的发展」不成立。", "垃圾": "语义：「垃圾」指废弃物，不是可以研究其发展的历史对象。"}, "sentence_index": 6, "correct_answer": "资本主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在研究一台资本主义。", "explanation": "这里不能用〈台〉。台用于机器，表示主义应使用〈种〉。"}, {"text": "他买了一瓶资本主义。", "explanation": "这里不能用〈瓶〉。瓶用于装液体的容器，资本主义是抽象制度。"}, {"text": "他研究了一棵资本主义。", "explanation": "这里不能用〈棵〉。棵用于树木，资本主义是抽象制度，不能这样计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "资本主义是一条经济制度。", "corrected_sentence": "资本主义是一种经济制度。", "error_description": "量词错误：「资本主义」是一种制度，不能用长条形事物的量词「条」，应搭配「种」。正确的是「资本主义是一种经济制度」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他研究过资本主义过。", "corrected_sentence": "他研究过资本主义。", "error_description": "「过」只用一次：表示经历的「过」应紧跟动词，写作「研究过资本主义」；宾语「资本主义」之后不能再加「过」，「研究过资本主义过」是错误形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
