INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人类进行物质资料生产的具体形式，包括生产力和生产关系两个方面。", "primary_collocate": null, "pronunciation": "shēng chǎn fāng shì", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩ faŋ˥ ʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "它与当时正在兴起的民族国家、教育制度变革及资本主义生产方式相互交织，共同推动社会结构的转型。", "target_word": "生产方式", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "生产方式改变了人们的生活。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂出现后，生产方式不一样了。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲了古代的生产方式。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术带来了新的生产方式。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产方式包括生产力和生产关系。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业社会的生产方式比较简单。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们比较两种生产方式。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产方式决定社会的样子。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究过不同国家的生产方式。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生產方式", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "人类生产物质资料的形式，含生产力和生产关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6d46d0b-bdfb-4036-8276-2cadd17ec858') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产方式", "is_correct": true, "explanation": "正确：「资本主义生产方式」中的「生产方式」，指人类生产物质资料的具体形式，是这个短语的中心词。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是生产形式，「资本主义月亮」不成立，句中也不能与「民族国家」「教育制度」并列。"}, {"text": "老百姓", "is_correct": false, "explanation": "语义：「老百姓」指人，不能作为生产形式与制度并列。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，「资本主义铅笔」不成立，不能与「民族国家」「教育制度变革」并列。"}], "explanations": {"生产方式": "正确：「资本主义生产方式」中的「生产方式」，指人类生产物质资料的具体形式，是这个短语的中心词。", "月亮": "语义：月亮是天体，不是生产形式，「资本主义月亮」不成立，句中也不能与「民族国家」「教育制度」并列。", "老百姓": "语义：「老百姓」指人，不能作为生产形式与制度并列。", "铅笔": "语义：铅笔是文具，「资本主义铅笔」不成立，不能与「民族国家」「教育制度变革」并列。"}, "sentence_index": 0, "correct_answer": "生产方式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个工厂提高了生产方式。", "explanation": "这里应用〈生产力〉。提高用于生产力、效率，生产方式应说改变或采用。"}, {"text": "我决定改变我的生产方式，每天早起锻炼。", "explanation": "这里应用〈生活方式〉。生产方式指社会物质生产的形式，个人习惯应说生活方式。"}, {"text": "我换了生产方式，成绩提高了。", "explanation": "这里应用〈学习方式〉。生产方式不能指学习的方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产方式", "is_correct": true, "explanation": "正确：「农业社会的……比较简单」描述的是做事的方法，即生产方式。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民是人，不能用「比较简单」描述它作为生产形式。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是社会生产的形式，「农业社会的天气比较简单」说不通。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不是生产形式，句中讲的是社会的生产方法。"}], "explanations": {"生产方式": "正确：「农业社会的……比较简单」描述的是做事的方法，即生产方式。", "农民": "语义：农民是人，不能用「比较简单」描述它作为生产形式。", "天气": "语义：天气是自然现象，不是社会生产的形式，「农业社会的天气比较简单」说不通。", "小猫": "语义：小猫不是生产形式，句中讲的是社会的生产方法。"}, "sentence_index": 6, "correct_answer": "生产方式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们研究了一条生产方式。", "explanation": "这里不能用〈条〉。条用于长条形的东西，生产方式是抽象的方法，应用〈种〉。"}, {"text": "她的生产方式很幽默。", "explanation": "这里应用〈表达方式〉。生产方式不能形容人说话的风格。"}, {"text": "我们换了生产方式，现在坐地铁。", "explanation": "这里应用〈交通方式〉。生产方式指物质生产，不能指出行的方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂采用了一条新的生产方式。", "corrected_sentence": "工厂采用了一种新的生产方式。", "error_description": "量词错误：「生产方式」是抽象概念，不能用细长物的量词「条」，应搭配「种」。正确的是「一种新的生产方式」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们研究得古代的生产方式。", "corrected_sentence": "他们研究过古代的生产方式。", "error_description": "助词错误：「得」后面需要补语，表示经历应用「过」，写作「研究过古代的生产方式」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e34c34c7-0654-419d-b21d-1f313cf82739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10235, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10235, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10235, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "互相交叉、缠绕在一起。", "primary_collocate": null, "pronunciation": "xiāng hù jiāo zhī", "ipa": "ɕi̯ɑŋ˥ xu˥˩ tɕi̯ɑʊ˥ ʈʂɻ̩˥", "syllable_count": 4, "sentences": [{"text": "它与当时正在兴起的民族国家、教育制度变革及资本主义生产方式相互交织，共同推动社会结构的转型。", "target_word": "相互交织", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "快乐和痛苦常常相互交织。", "target_word": "相互交织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的心里，喜悦和紧张相互交织。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里，爱情和友情相互交织。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个故事相互交织，很有意思。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史和现实在这本书里相互交织。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去的回忆和现在的生活相互交织着。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这座城市，新文化和老传统相互交织。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的梦想和家人的希望相互交织。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多问题相互交织，不容易解决。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相互交织着", "label": "体标"}], "register": "书面", "sense_fingerprint": "抽象事物互相交叉缠绕在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c87be3b-a562-4471-8594-119adfda2aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10235, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相互交织", "is_correct": true, "explanation": "正确：“相互交织”表示两种事物缠绕在一起，与“共同推动社会结构的转型”的语境相合。"}, {"text": "相互对立", "is_correct": false, "explanation": "语义：“对立”与后半句“共同推动”的合作语义相反，句子不通。"}, {"text": "相互排斥", "is_correct": false, "explanation": "语义：“排斥”表示互不容纳，与“共同推动”的语义矛盾。"}, {"text": "相互隔绝", "is_correct": false, "explanation": "搭配：“隔绝”表示断开往来，不能与“共同推动社会结构的转型”这样的合作语境搭配。"}], "explanations": {"相互交织": "正确：“相互交织”表示两种事物缠绕在一起，与“共同推动社会结构的转型”的语境相合。", "相互对立": "语义：“对立”与后半句“共同推动”的合作语义相反，句子不通。", "相互排斥": "语义：“排斥”表示互不容纳，与“共同推动”的语义矛盾。", "相互隔绝": "搭配：“隔绝”表示断开往来，不能与“共同推动社会结构的转型”这样的合作语境搭配。"}, "sentence_index": 0, "correct_answer": "相互交织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "红灯和绿灯每隔一分钟相互交织出现。", "explanation": "这里应该用〈交替〉。红灯和绿灯轮流出现要用交替，“相互交织”指两种事物缠绕在一起。"}, {"text": "同学们在复习时相互交织，一起讨论题目。", "explanation": "这里应该用〈合作〉。共同复习、互相帮助要用合作，“相互交织”指事物缠绕在一起，不表示人与人之间的合作。"}, {"text": "两家公司决定相互交织。", "explanation": "这里应该用〈合并〉。两家公司合成一家要用合并，“相互交织”不能用来描述公司的合并。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10235, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相互交织", "is_correct": true, "explanation": "正确：“过去的回忆”和“现在的生活”可以互相缠绕，“着”表示这一状态持续。"}, {"text": "相互告别", "is_correct": false, "explanation": "配价：“告别”的主体须是人，“回忆”和“生活”不能相互告别。"}, {"text": "相互怀念", "is_correct": false, "explanation": "语义：“怀念”指思念某人或某事，“回忆”不能怀念，句意不通。"}, {"text": "相互问候", "is_correct": false, "explanation": "配价：“问候”需要人作主语，不能用于“回忆和生活”。"}], "explanations": {"相互交织": "正确：“过去的回忆”和“现在的生活”可以互相缠绕，“着”表示这一状态持续。", "相互告别": "配价：“告别”的主体须是人，“回忆”和“生活”不能相互告别。", "相互怀念": "语义：“怀念”指思念某人或某事，“回忆”不能怀念，句意不通。", "相互问候": "配价：“问候”需要人作主语，不能用于“回忆和生活”。"}, "sentence_index": 6, "correct_answer": "相互交织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两位专家在会上相互交织了看法。", "explanation": "这里应该用〈交换〉。交换看法要用交换，“相互交织”指事物缠绕在一起，不能和“看法”搭配。"}, {"text": "两家商店在街上相互交织，争抢顾客。", "explanation": "这里应该用〈竞争〉。争抢顾客是竞争，“相互交织”表示缠绕，不表示竞争。"}, {"text": "两位老朋友在咖啡馆里相互交织，聊了一下午。", "explanation": "这里应该用〈交谈〉。聊天要说交谈，“相互交织”指事物缠绕在一起，不用于人的交谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的想法和回忆相互交织一起。", "corrected_sentence": "他的想法和回忆相互交织在一起。", "error_description": "错误在于缺少介词“在”。“交织”后要接“在一起”，写成“相互交织一起”是错误。正确形式是“相互交织在一起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "矛盾和困难相互交织的很紧。", "corrected_sentence": "矛盾和困难相互交织得很紧。", "error_description": "错误在于补语标记。表示动作程度的补语要用结构助词“得”，写成“的”是常见错误。正确形式是“相互交织得很紧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68dd2c7e-def6-4884-8dc1-6e403cd7c618') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
