INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10241, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10241, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指使事物符合统一的标准或要求，从而达到有序、一致的状态。", "primary_collocate": null, "pronunciation": "guī fàn huà", "ipa": "kwei˥ fan˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "标准化的文本催生了语言的规范化，进而强化了民族认同；印刷品的跨地域流通促进了思想的跨国共振，使伏尔泰、卢梭等启蒙思想家的声音得以跨越国界，形成“共和的书信”网络。", "target_word": "规范化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司的管理需要规范化。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校很重视作业的规范化。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场规范化以后，价格更清楚了。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文字规范化对学习汉字很有帮助。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要推动医院服务的规范化。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规范化让工作更有秩序。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的规范化做得很好。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上购物也需要规范化。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名字的写法没有规范化，大家写得不一样。", "target_word": "规范化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "規範化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "使事物符合统一标准而有序一致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e84b5b62-f832-4dbb-bc2a-7fd6d14aeece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10241, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规范化", "is_correct": true, "explanation": "正确：此处指语言向统一标准靠拢，与前句“标准化的文本”呼应。"}, {"text": "多样化", "is_correct": false, "explanation": "语义：“多样化”与前句“标准化”的统一方向相反，句意不通。"}, {"text": "私有化", "is_correct": false, "explanation": "语义：“私有化”指归个人所有，与语言标准化的语境无关。"}, {"text": "绿化", "is_correct": false, "explanation": "语义：“绿化”指种植花草树木，与语言统一标准无关，句意不通。"}], "explanations": {"规范化": "正确：此处指语言向统一标准靠拢，与前句“标准化的文本”呼应。", "多样化": "语义：“多样化”与前句“标准化”的统一方向相反，句意不通。", "私有化": "语义：“私有化”指归个人所有，与语言标准化的语境无关。", "绿化": "语义：“绿化”指种植花草树木，与语言统一标准无关，句意不通。"}, "sentence_index": 0, "correct_answer": "规范化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经过治理，这条河的水质已经规范化了。", "explanation": "这里应该用〈净化〉。规范化指使事物符合统一标准，不用来说水质变干净。"}, {"text": "教室每天都要规范化一次。", "explanation": "这里应该用〈消毒〉。规范化指使事物符合统一标准，不指杀菌。"}, {"text": "他是个规范化的人，很爱开玩笑。", "explanation": "这里应该用〈守规矩〉。规范化指把事物统一到标准，不用来形容人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规范化", "is_correct": true, "explanation": "正确：“规范化”指统一标准，使工作有秩序，与“让工作更有秩序”一致。"}, {"text": "复杂化", "is_correct": false, "explanation": "语义：“复杂化”使事情更繁乱，与“有秩序”的结果相反，句子不通。"}, {"text": "无序化", "is_correct": false, "explanation": "语义：“无序化”直接否定“有秩序”，与句中的结果矛盾。"}, {"text": "老龄化", "is_correct": false, "explanation": "语义：“老龄化”指人口变老，与让工作更有秩序无关，句意不通。"}], "explanations": {"规范化": "正确：“规范化”指统一标准，使工作有秩序，与“让工作更有秩序”一致。", "复杂化": "语义：“复杂化”使事情更繁乱，与“有秩序”的结果相反，句子不通。", "无序化": "语义：“无序化”直接否定“有秩序”，与句中的结果矛盾。", "老龄化": "语义：“老龄化”指人口变老，与让工作更有秩序无关，句意不通。"}, "sentence_index": 6, "correct_answer": "规范化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果很规范化，又甜又脆。", "explanation": "这里应该用〈新鲜〉。规范化指使事物符合统一标准，不用来形容水果的品质。"}, {"text": "规范化以后，写法变得更加多样化了。", "explanation": "这里说写法变得多样，是〈分化〉的意思；规范化指使事物统一，二者相反。"}, {"text": "他唱了一首规范化的歌，很好听。", "explanation": "这里应该用〈动听〉。规范化指使事物统一、符合标准，不用来评价歌声好不好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只规范化工作很重要。", "corrected_sentence": "这项规范化工作很重要。", "error_description": "“规范化”指统一标准的工作或过程，量词应用“项”。“只”用于动物或小件物品，不能修饰“工作”。错误句“这只规范化工作”应改为“这项规范化工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的管理已经规范化着，大家都很满意。", "corrected_sentence": "学校的管理已经规范化了，大家都很满意。", "error_description": "“规范化”表示已经完成的变化，应用“了”，不用“着”；“着”表示持续的状态，与“已经”搭配不当。错误句“规范化着”应改为“规范化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
