INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10243, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示承认、认可，同意某人的观点或事情。", "primary_collocate": null, "pronunciation": "rèn tóng", "ipa": "ʐən˥˩ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "由此，水资源不仅是物质供给的载体，更是社会关系中彼此认同的纽带。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在此类框架下，讲述一则民间传说不仅是在复述往事，更是在执行一种文化实践：说者通过语言激活神圣时空，听者则在沉浸中认同这一叙述的意义。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都认同他的看法。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太认同这个办法。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师认同了我的想法。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人认同这种生活方式。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你认同他的说法吗？", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不认同我去外地工作。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我完全认同你说的话。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们认同这个计划，也愿意帮忙。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认同了", "label": "体标（了）"}, {"form": "认同过", "label": "体标（过）"}, {"form": "认同感", "label": "复合词"}], "register": "中性", "sense_fingerprint": "承认认可并同意某人的观点或事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dab81e9-4fc4-4e85-8310-7a60964d0d47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10243, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认同", "is_correct": true, "explanation": "正确：“彼此认同”指互相认可，正是纽带所连接的内容。"}, {"text": "差异", "is_correct": false, "explanation": "语义：“差异”指不同之处，不能作为联结社会关系的纽带。"}, {"text": "冲突", "is_correct": false, "explanation": "语义：“冲突”是矛盾对立，与“纽带”所表示的联结相反。"}, {"text": "隔阂", "is_correct": false, "explanation": "搭配：“隔阂”表示隔膜、阻碍，与“纽带”所表示的联结搭配不通。"}], "explanations": {"认同": "正确：“彼此认同”指互相认可，正是纽带所连接的内容。", "差异": "语义：“差异”指不同之处，不能作为联结社会关系的纽带。", "冲突": "语义：“冲突”是矛盾对立，与“纽带”所表示的联结相反。", "隔阂": "搭配：“隔阂”表示隔膜、阻碍，与“纽带”所表示的联结搭配不通。"}, "sentence_index": 0, "correct_answer": "认同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他认同了那把椅子。", "explanation": "这里应该用〈买〉。“认同”的对象是观点、做法，不能指具体的物品；买椅子要说“买”。"}, {"text": "他认同地写完了作业。", "explanation": "这里应该用〈认真〉。“认同”不能作状语修饰动作，描述做事态度要说“认真”。"}, {"text": "我对这条路很认同。", "explanation": "这里应该用〈熟悉〉。“认同”的对象是观点、做法，不能用来说人对地方的了解，应说“很熟悉这条路”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10243, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认同", "is_correct": true, "explanation": "正确：“你认同他的说法吗”即问对方是否认可这种说法，符合句意。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是咀嚼的动作，不能用来表示对说法的态度。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮品，不能用于“说法”。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：“砍”多用于具体的物体，不与“说法”搭配。"}], "explanations": {"认同": "正确：“你认同他的说法吗”即问对方是否认可这种说法，符合句意。", "咬": "语义：“咬”是咀嚼的动作，不能用来表示对说法的态度。", "喝": "语义：“喝”的对象是饮品，不能用于“说法”。", "砍": "搭配：“砍”多用于具体的物体，不与“说法”搭配。"}, "sentence_index": 6, "correct_answer": "认同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们认同那只受伤的小狗。", "explanation": "这里应该用〈同情〉。“认同”的宾语是观点、做法，不能指动物；对受伤的小狗表示怜悯要用“同情”。"}, {"text": "我认同这个字。", "explanation": "这里应该用〈认识〉。“认同”指认可观点或做法，不用于辨认字词，认出字要说“认识”。"}, {"text": "他去派出所认同了丢失的钱包。", "explanation": "这里应该用〈认领〉。“认领”指认出并领回失物，“认同”不能用于失物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都认同得她的做法。", "corrected_sentence": "大家都认同她的做法。", "error_description": "“认同”后不带补语“得”，应说“认同她的做法”，不说“认同得她的做法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没认同了我的建议。", "corrected_sentence": "他没认同我的建议。", "error_description": "“没”表示否定，否定句中“认同”后不加“了”。应说“他没认同我的建议”，不说“他没认同了我的建议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
