INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10244, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10244, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "印刷品指通过印刷技术制成的成品，如书籍、报纸、杂志等。", "primary_collocate": null, "pronunciation": "yìn shuā pǐn", "ipa": "in˥˩ ʂwa˥ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "标准化的文本催生了语言的规范化，进而强化了民族认同；印刷品的跨地域流通促进了思想的跨国共振，使伏尔泰、卢梭等启蒙思想家的声音得以跨越国界，形成“共和的书信”网络。", "target_word": "印刷品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家工厂每天生产很多印刷品。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸、杂志和书都是印刷品。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批印刷品要在明天送到学校。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些印刷品的纸很厚，颜色也很漂亮。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮局对这种印刷品的价格有特别规定。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把印刷品放在桌子上了。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游时，我收集了很多印刷品，比如地图和海报。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要先检查印刷品，再发给客人。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些印刷品是用来宣传新产品的。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "批", "label": "量词"}], "register": "中性", "sense_fingerprint": "用印刷技术制成的书报杂志等成品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e84b5b62-f832-4dbb-bc2a-7fd6d14aeece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印刷品", "is_correct": true, "explanation": "正确：指印出来的书报等，与“跨地域流通”和“思想”的语境相符。"}, {"text": "农产品", "is_correct": false, "explanation": "语义：“农产品”不承载思想与书信，不能“促进思想的跨国共振”。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与这段书面语体不合。"}, {"text": "肥料", "is_correct": false, "explanation": "语义：“肥料”与思想传播毫无关系，句子不通。"}], "explanations": {"印刷品": "正确：指印出来的书报等，与“跨地域流通”和“思想”的语境相符。", "农产品": "语义：“农产品”不承载思想与书信，不能“促进思想的跨国共振”。", "玩意儿": "语域：“玩意儿”是口语，与这段书面语体不合。", "肥料": "语义：“肥料”与思想传播毫无关系，句子不通。"}, "sentence_index": 0, "correct_answer": "印刷品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家印刷品要在明天把产品送到学校。", "explanation": "这里应该用〈印刷厂〉。印刷品指印好的成品，不能指生产它的工厂。"}, {"text": "这批印刷品会说话，还会唱歌。", "explanation": "这里应该用〈机器人〉。印刷品指印好的纸制成品，不会说话唱歌。"}, {"text": "他是我们班的印刷品，成绩很好。", "explanation": "这里应该用〈学生〉。印刷品指印好的成品，不指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印刷品", "is_correct": true, "explanation": "正确：“印刷品”是能被拿起来放在桌子上的具体物品，与“把……放在桌子上”相符。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“放”需要可移动的具体事物作宾语，“天气”不能被放在桌子上。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”体量巨大，不能被放在桌子上，句意不通。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”是抽象情感，无法实体化地放在桌子上。"}], "explanations": {"印刷品": "正确：“印刷品”是能被拿起来放在桌子上的具体物品，与“把……放在桌子上”相符。", "天气": "配价：“放”需要可移动的具体事物作宾语，“天气”不能被放在桌子上。", "大海": "语义：“大海”体量巨大，不能被放在桌子上，句意不通。", "友谊": "语义：“友谊”是抽象情感，无法实体化地放在桌子上。"}, "sentence_index": 6, "correct_answer": "印刷品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些印刷品的过程需要三天。", "explanation": "这里应该用〈制作〉。印刷品指印好的成品，不指制作的过程。"}, {"text": "这些印刷品是我们家的新电视。", "explanation": "这里应该用〈电视〉。印刷品是印出来的纸制品，不指电器。"}, {"text": "这些印刷品是我们的新手机。", "explanation": "这里应该用〈手机〉。印刷品指印出来的纸制品，不指电子设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天收到了一只印刷品。", "corrected_sentence": "我昨天收到了一份印刷品。", "error_description": "“印刷品”是纸制品，数量用“份”或“批”，不用“只”。错误句“一只印刷品”应改为“一份印刷品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台印刷品很漂亮。", "corrected_sentence": "这份印刷品很漂亮。", "error_description": "“印刷品”是纸制品，量词用“份”，不用“台”（“台”用于机器等）。错误句“这台印刷品”应改为“这份印刷品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
