INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10249, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10249, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个振动系统在特定条件下，一个振动引起另一个振动，且振幅增大的现象。", "primary_collocate": null, "pronunciation": "gòng zhèn", "ipa": "kʊŋ˥˩ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "研究人员发现，当激励频率接近机器部件的固有频率时，部件会因共振而产生剧烈振动，这是许多机械故障的重要原因之一。", "target_word": "共振", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "一个音叉响了，旁边的音叉发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共振会让振幅变得越来越大。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥的振动和风的节奏相同，就会出现共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师要避免大楼和地震波发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱高音时，玻璃杯可能因共振而碎裂。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "荡秋千时，推的节奏对了，就是利用了共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收音机调台，就是让电路和电波产生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机转得太快，会和地板发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐器的音箱靠共振把声音放大。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共振频率", "label": "复合"}, {"form": "磁共振", "label": "复合"}], "register": "书面语", "sense_fingerprint": "一个振动系统带动另一个，振幅增大的物理现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b9e127-76e2-48c8-a316-ec41d410e34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10249, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共振", "is_correct": true, "explanation": "正确：激励频率接近固有频率时振幅增大，正是“共振”，与句意相符。"}, {"text": "隔阂", "is_correct": false, "explanation": "语义：“隔阂”指彼此不通、心存隔膜，与机器部件的振动无关，句子不通。"}, {"text": "封锁", "is_correct": false, "explanation": "语义：“封锁”指阻断通行或交流，不能使部件因之产生振动，句子不通。"}, {"text": "障碍", "is_correct": false, "explanation": "语义：“障碍”指阻挡通行的事物，不能使部件产生剧烈振动，句子不通。"}], "explanations": {"共振": "正确：激励频率接近固有频率时振幅增大，正是“共振”，与句意相符。", "隔阂": "语义：“隔阂”指彼此不通、心存隔膜，与机器部件的振动无关，句子不通。", "封锁": "语义：“封锁”指阻断通行或交流，不能使部件因之产生振动，句子不通。", "障碍": "语义：“障碍”指阻挡通行的事物，不能使部件产生剧烈振动，句子不通。"}, "sentence_index": 0, "correct_answer": "共振"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山谷里传来了共振，声音传得很远。", "explanation": "这里应该用〈回声〉。回声是声音遇到障碍物反射回来的现象；共振是物体因频率相同而振幅增大，不是声音的反射，不能这样说。"}, {"text": "天气突然共振，路面变得很滑。", "explanation": "这里应该用〈下雪〉。下雪指天空降下雪花；共振指物体因同频振动而振幅增大，不能用来说明天气现象。"}, {"text": "屋子里的温度慢慢共振。", "explanation": "这里应该用〈升高〉。升高指温度或数值上升；共振指物体因同频振动而振幅增大，不表示温度的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10249, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共振", "is_correct": true, "explanation": "正确：荡秋千时利用的是推动节奏与摆动频率相同，使振幅增大的现象，即共振。"}, {"text": "电流", "is_correct": false, "explanation": "语义：荡秋千靠的是摆动节奏，与电流无关，“利用了电流”与句意不符。"}, {"text": "地震", "is_correct": false, "explanation": "搭配：“利用了”一般接原理、能量等，地震是灾害，不能作为被利用的对象。"}, {"text": "光合作用", "is_correct": false, "explanation": "语义：光合作用是植物的生理过程，与荡秋千的节奏毫无关系。"}], "explanations": {"共振": "正确：荡秋千时利用的是推动节奏与摆动频率相同，使振幅增大的现象，即共振。", "电流": "语义：荡秋千靠的是摆动节奏，与电流无关，“利用了电流”与句意不符。", "地震": "搭配：“利用了”一般接原理、能量等，地震是灾害，不能作为被利用的对象。", "光合作用": "语义：光合作用是植物的生理过程，与荡秋千的节奏毫无关系。"}, "sentence_index": 6, "correct_answer": "共振"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车靠共振减少颠簸。", "explanation": "这里应该用〈减震〉。减震指用装置减少震动和颠簸；共振会使振幅增大，恰好与“减少颠簸”相反。"}, {"text": "这间屋子靠共振挡住噪音。", "explanation": "这里应该用〈隔音〉。隔音指阻挡声音的传入或传出；共振会增强振动，与“挡住噪音”的作用相反。"}, {"text": "电视突然没信号，画面一下子共振了。", "explanation": "这里应该用〈黑屏〉。黑屏指屏幕突然变黑、没有画面；共振指物体因同频振动而振幅增大，与画面变黑不是一回事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风一大，窗户就经常出现了共振。", "corrected_sentence": "风一大，窗户就经常出现共振。", "error_description": "“经常”表示反复发生的习惯性情况，与表示已经完成的“了”不能同用，应删去“了”。错误形式为“经常出现了共振”，正确形式为“经常出现共振”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吉他的音箱靠一把共振让声音变大。", "corrected_sentence": "吉他的音箱靠共振让声音变大。", "error_description": "量词用错：“把”用于有柄的器具，不能修饰抽象的“共振”，应删去“一把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10253, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10253, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10253, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对事物有深刻见解和系统理论的人，如哲学家、理论家。", "primary_collocate": null, "pronunciation": "sī xiǎng jiā", "ipa": "sɿ˥ ɕjɑŋ˨˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "标准化的文本催生了语言的规范化，进而强化了民族认同；印刷品的跨地域流通促进了思想的跨国共振，使伏尔泰、卢梭等启蒙思想家的声音得以跨越国界，形成“共和的书信”网络。", "target_word": "思想家", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他是一位著名的思想家，写过很多书。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位思想家认为，教育可以改变社会。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孔子是中国历史上最有名的思想家之一。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "思想家的书让很多年轻人开始思考生活。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位思想家一生都在研究人和社会的关系。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们介绍了一位法国思想家。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位思想家的理论影响了整个时代。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想成为一名思想家，所以每天读哲学书。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人去听了那位思想家的讲座。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "书面语", "sense_fingerprint": "有深刻见解和系统理论的学者，如哲学家、理论家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968499f2-4a88-4c01-811d-facd00e81028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10253, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "画家", "is_correct": false, "explanation": "语义：画家指以绘画为业的人，句中是启蒙时代的哲学家，“启蒙画家的声音”说不通。"}, {"text": "思想家", "is_correct": true, "explanation": "“思想家”指对事物有深刻见解、建立系统理论的人，这里指伏尔泰、卢梭等启蒙思想家。"}, {"text": "书呆子", "is_correct": false, "explanation": "语域：“书呆子”是口语词，带贬义，与句子的书面语风格不协调。"}, {"text": "企业家", "is_correct": false, "explanation": "语义：企业家指经营企业的人，与伏尔泰、卢梭这类启蒙哲人的身份不符。"}], "explanations": {"画家": "语义：画家指以绘画为业的人，句中是启蒙时代的哲学家，“启蒙画家的声音”说不通。", "思想家": "“思想家”指对事物有深刻见解、建立系统理论的人，这里指伏尔泰、卢梭等启蒙思想家。", "书呆子": "语域：“书呆子”是口语词，带贬义，与句子的书面语风格不协调。", "企业家": "语义：企业家指经营企业的人，与伏尔泰、卢梭这类启蒙哲人的身份不符。"}, "sentence_index": 0, "correct_answer": "思想家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位著名的思想家，发现了一种新元素。", "explanation": "用词错误：这里应该用〈科学家〉。思想家指提出系统理论的人，发现新元素属于科学家的工作。"}, {"text": "那位思想家每天在医院给病人打针。", "explanation": "用词错误：这里应该用〈医生〉。思想家指提出系统理论的人，不指给病人打针的人。"}, {"text": "这次考试的思想家很难。", "explanation": "用词错误：这里应该用〈题目〉。思想家指人，不能用来指考试的题目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "搭配：“一位”只能计量人，石头不能用“位”计量，也不能被介绍为人物。"}, {"text": "思想家", "is_correct": true, "explanation": "“法国思想家”指有系统理论的法国学者，句中是老师向学生介绍的人物。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象是动物，老师不会把它当作人物介绍给学生。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不是人，不能用“位”计量，也不能被老师介绍为人物。"}], "explanations": {"石头": "搭配：“一位”只能计量人，石头不能用“位”计量，也不能被介绍为人物。", "思想家": "“法国思想家”指有系统理论的法国学者，句中是老师向学生介绍的人物。", "大象": "语义：大象是动物，老师不会把它当作人物介绍给学生。", "咖啡": "语义：咖啡是饮品，不是人，不能用“位”计量，也不能被老师介绍为人物。"}, "sentence_index": 6, "correct_answer": "思想家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位思想家每天在工厂里开车送货。", "explanation": "语义：“思想家”指提出系统理论的人，不指驾驶或送货的人；这里应说〈司机〉。"}, {"text": "这两位思想家在奥运会上拿了金牌。", "explanation": "用词错误：这里应该用〈运动员〉。思想家指提出系统理论的人，不指参加比赛的选手。"}, {"text": "那位思想家每天在农田里种水稻，再拿到市场上卖。", "explanation": "用词错误：这里应该用〈农民〉。思想家指提出系统理论的人，不指种地卖粮的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只很受尊敬的思想家。", "corrected_sentence": "他是一位很受尊敬的思想家。", "error_description": "量词错误：“只”用于动物或成对物品中的一个，指人应用“位”，应说“一位很受尊敬的思想家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的父亲是一位著名的思想家们。", "corrected_sentence": "他的父亲是一位著名的思想家。", "error_description": "词缀错误：“们”表示复数，与“一位”这类单数量词不能同用，应去掉“们”，说“一位著名的思想家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
