INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10254, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10254, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "声波通过耳朵产生的感觉，指说话、唱歌或物体发出的响声。", "primary_collocate": null, "pronunciation": "shēng yīn", "ipa": "ʂɤŋ˥ in˥", "syllable_count": 2, "sentences": [{"text": "外面有一个奇怪的声音。", "target_word": "声音", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房间里很安静，没有一点声音。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨打在窗户上，发出轻轻的声音。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器的声音太吵了。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我听到楼上有脚步的声音。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把电视的声音关小一点。", "target_word": "声音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水的声音让我睡得很香。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门开的时候会发出很大的声音。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐的声音从隔壁传了过来。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他唱歌的声音传到了很远的地方。", "target_word": "声音", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个声音", "label": "量词"}, {"form": "一种声音", "label": "量词"}], "register": "中性", "sense_fingerprint": "耳朵听到的响声，包括说话、唱歌和物体发出的声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425e7d8f-3989-4c55-aef2-e45784558d9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身份", "is_correct": false, "explanation": "语义：“身份”指人的社会地位或资格，不是可以存在于外面的东西。"}, {"text": "声音", "is_correct": true, "explanation": "“声音”指耳朵能听到的响声，“外面有一个奇怪的……”说的是听到的东西，是正确答案。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的个性，不能像东西一样“在外面”。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”是内心的状态，不能跟“外面有”搭配。"}], "explanations": {"身份": "语义：“身份”指人的社会地位或资格，不是可以存在于外面的东西。", "声音": "“声音”指耳朵能听到的响声，“外面有一个奇怪的……”说的是听到的东西，是正确答案。", "性格": "语义：“性格”指人的个性，不能像东西一样“在外面”。", "心情": "搭配：“心情”是内心的状态，不能跟“外面有”搭配。"}, "sentence_index": 0, "correct_answer": "声音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器发出了一只很吵的声音。", "explanation": "这里应该用〈个〉或〈种〉。“只”一般用于动物或成对的东西，不用于声音。"}, {"text": "他用剪刀把这个声音剪了下来。", "explanation": "这里把“声音”误当成可以用剪刀剪断的实物。“声音”是耳朵听到的响声，没有形状，不能剪。"}, {"text": "我把这个声音抓在手里了。", "explanation": "这里把“声音”误当成可以用手抓住的实物。“声音”是耳朵听到的响声，没有形状，不能抓在手里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，河水没有身材，不能用来说“让我睡得很香”。"}, {"text": "声音", "is_correct": true, "explanation": "“声音”指水流发出的轻响，能让人入睡，是正确答案。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：河水没有年龄，“年龄”指人的岁数，与“让我睡得很香”无关。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，河水的轻重不能让人睡得很香。"}], "explanations": {"身材": "体貌：“身材”指人的体形，河水没有身材，不能用来说“让我睡得很香”。", "声音": "“声音”指水流发出的轻响，能让人入睡，是正确答案。", "年龄": "语义：河水没有年龄，“年龄”指人的岁数，与“让我睡得很香”无关。", "重量": "语义：“重量”指物体的轻重，河水的轻重不能让人睡得很香。"}, "sentence_index": 6, "correct_answer": "声音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段音乐的声音很便宜，只要两块钱。", "explanation": "〈便宜〉是价钱的形容词，“声音”不能用价钱来形容，这里误把声音当成了商品。"}, {"text": "这段音乐的声音有五斤重，可以放在秤上称。", "explanation": "〈五斤重〉是重量，“声音”没有重量，不能放在秤上称，这里误把声音当成实物。"}, {"text": "这个声音很咸，我不爱吃。", "explanation": "〈咸〉是味觉形容词，“声音”不能用咸淡来形容，这里搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗外传来一只奇怪的声音。", "corrected_sentence": "窗外传来一阵奇怪的声音。", "error_description": "“声音”的量词应用“阵”“个”“种”等，不用“只”。“只”一般用于动物或成对的东西，所以“一只声音”错误，应说“一阵声音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口传来一阵很轻声音。", "corrected_sentence": "门口传来一阵很轻的声音。", "error_description": "“很轻”修饰“声音”时要加“的”，应说“很轻的声音”，不能说“很轻声音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
