INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10257, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10257, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书信是人们用文字写下来，通过邮寄或传递方式送给远方亲友的书面信息。", "primary_collocate": null, "pronunciation": "shū xìn", "ipa": "ʂu˥ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "标准化的文本催生了语言的规范化，进而强化了民族认同；印刷品的跨地域流通促进了思想的跨国共振，使伏尔泰、卢梭等启蒙思想家的声音得以跨越国界，形成“共和的书信”网络。", "target_word": "书信", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "爷爷还保存着很多旧书信。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候没有手机，大家靠书信联系。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书信记录了他们多年的友情。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都给家人写书信。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书信要过好几天才能送到远方。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里展出了一位作家的书信。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把书信放进盒子，小心地收好。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读着这些书信，我想起了过去。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在古代，书信是人们联系远方亲友的主要办法。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封", "label": "量词"}, {"form": "书信集", "label": "复合"}], "register": "书面语", "sense_fingerprint": "写给远方亲友、靠邮寄或传递送达的书面信件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968499f2-4a88-4c01-811d-facd00e81028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书信", "is_correct": true, "explanation": "正确：书信指书面信件，与“印刷品流通、思想传播”的语境相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：这段讲的是启蒙时代的印刷品流通，当时没有手机。"}, {"text": "石碑", "is_correct": false, "explanation": "语义：石碑无法大范围跨地域流通，不能形成印刷品那样的网络。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与这段书面语的语域不合。"}], "explanations": {"书信": "正确：书信指书面信件，与“印刷品流通、思想传播”的语境相符。", "手机": "语义：这段讲的是启蒙时代的印刷品流通，当时没有手机。", "石碑": "语义：石碑无法大范围跨地域流通，不能形成印刷品那样的网络。", "玩意儿": "语域：“玩意儿”是口语，与这段书面语的语域不合。"}, "sentence_index": 0, "correct_answer": "书信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天晚上都给朋友打书信。", "explanation": "这里应该用〈电话〉。打的是电话，书信要用写或寄，不说“打书信”。"}, {"text": "进场前要先买书信。", "explanation": "这里应该用〈门票〉。进场要买的是门票，书信是写给亲友的信件，不能用来买票进场。"}, {"text": "他连夜拍书信求救。", "explanation": "这里应该用〈电报〉。拍的是电报，书信是纸质信件，不能拍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书信", "is_correct": true, "explanation": "正确：书信可以作为文物展出，符合“博物馆里展出”的语境。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“展出”说作品或文物，不能说展出人的体温。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：“展出”的对象是作品或文物，身材是人的形体，不能作为展品陈列。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：“展出”不能搭配“呼吸”，呼吸无法陈列。"}], "explanations": {"书信": "正确：书信可以作为文物展出，符合“博物馆里展出”的语境。", "体温": "搭配：“展出”说作品或文物，不能说展出人的体温。", "身材": "搭配：“展出”的对象是作品或文物，身材是人的形体，不能作为展品陈列。", "呼吸": "搭配：“展出”不能搭配“呼吸”，呼吸无法陈列。"}, "sentence_index": 6, "correct_answer": "书信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出国前要办好护照和书信。", "explanation": "这里应该用〈证件〉。办出国手续要的是护照等证件，书信是写给亲友的信件，不能代替证件。"}, {"text": "他用手机给朋友发书信，很快就收到了回复。", "explanation": "这里应该用〈短信〉。用手机发的是短信，书信是纸质信件，寄送要等很多天。"}, {"text": "孩子们在操场上唱书信。", "explanation": "这里应该用〈歌〉。唱的是歌，书信不能唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈收到了一只书信，高兴得哭了。", "corrected_sentence": "妈妈收到了一封书信，高兴得哭了。", "error_description": "量词错误：书信的量词是“封”，“只”用于动物或成对的物品，不能用于书信。应说“一封书信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些书信们都很珍贵。", "corrected_sentence": "这些书信都很珍贵。", "error_description": "词缀错误：“们”一般只加在指人的名词后，“书信”是事物，不能加“们”，应说“这些书信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
