INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10259, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10259, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指公元1700年至1799年这一百年间。", "primary_collocate": null, "pronunciation": "shí bā shì jì", "ipa": "ʂʅ˧˥ pa˥˥ ʂʅ˥˩ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "至十八世纪，识字率在西欧显著上升，公共图书馆、阅读社团与报刊媒体相继兴起，知识的传播不再局限于口耳相传或封闭的手稿交流，而是进入了一个可存储、可检索、可广泛复制的媒介时代。", "target_word": "十八世纪", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "十八世纪的欧洲出现了很多新思想。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子是十八世纪盖的。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在博物馆看到了十八世纪的地图。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八世纪的人没有电灯，晚上用蜡烛。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是十八世纪的法国历史。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八世纪末，那个国家发生了大变化。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很喜欢十八世纪的音乐。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八世纪初，这个城市只有几千人。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，十八世纪是一个重要的时代。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "十八世纪初", "label": "复合"}, {"form": "十八世纪末", "label": "复合"}, {"form": "十八世紀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公元1700至1799年的一百年时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968499f2-4a88-4c01-811d-facd00e81028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10259, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "十八世纪", "is_correct": true, "explanation": "正确：指一百年的历史时段，与“识字率上升、媒介兴起”的时代背景相符。"}, {"text": "十八岁", "is_correct": false, "explanation": "语义：“至十八岁”指一个人的年龄，不能作为识字率上升的时代界标。"}, {"text": "十八小时", "is_correct": false, "explanation": "搭配：“至”后接时代，不接“十八小时”这类短时段，句子说不通。"}, {"text": "十八次", "is_correct": false, "explanation": "语义：“十八次”指次数，不是时段或时间点，与“至……时”不合。"}], "explanations": {"十八世纪": "正确：指一百年的历史时段，与“识字率上升、媒介兴起”的时代背景相符。", "十八岁": "语义：“至十八岁”指一个人的年龄，不能作为识字率上升的时代界标。", "十八小时": "搭配：“至”后接时代，不接“十八小时”这类短时段，句子说不通。", "十八次": "语义：“十八次”指次数，不是时段或时间点，与“至……时”不合。"}, "sentence_index": 0, "correct_answer": "十八世纪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今年十八世纪了。", "explanation": "这里应该用〈十八岁〉。十八世纪是一百年的历史时段，不能用来说一个人的年龄。"}, {"text": "我每天早上十八世纪起床。", "explanation": "这里应该用〈七点〉。十八世纪是长时段，不能指具体的钟点。"}, {"text": "这座房子已经有十八世纪了。", "explanation": "这里应该用〈一百年〉。十八世纪是固定的历史时段，不能用来计算房子存在的年数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "十八世纪", "is_correct": true, "explanation": "正确：指一百年的历史时段，“十八世纪末”指这段时间的末期。"}, {"text": "十八辈子", "is_correct": false, "explanation": "语域：“十八辈子”是口语说法，与这句书面的历史叙述不合。"}, {"text": "十八分钟", "is_correct": false, "explanation": "语义：十八分钟太短，不能说“末”，也不能发生这样的大变化。"}, {"text": "十八天", "is_correct": false, "explanation": "语义：十八天不足以称作历史时段，与“末”搭配不合。"}], "explanations": {"十八世纪": "正确：指一百年的历史时段，“十八世纪末”指这段时间的末期。", "十八辈子": "语域：“十八辈子”是口语说法，与这句书面的历史叙述不合。", "十八分钟": "语义：十八分钟太短，不能说“末”，也不能发生这样的大变化。", "十八天": "语义：十八天不足以称作历史时段，与“末”搭配不合。"}, "sentence_index": 6, "correct_answer": "十八世纪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他花了十八世纪完成作业。", "explanation": "这里应该用〈一个月〉。十八世纪是百年时段，不能用来说完成作业这种短时间。"}, {"text": "他的身高是十八世纪。", "explanation": "这里应该用〈一米八〉。身高要用长度，十八世纪是时段，不能说明人的身高。"}, {"text": "这盒牛奶的保质期是十八世纪。", "explanation": "这里应该用〈一周〉。保质期是较短的时长，十八世纪不能用来表示牛奶的保质期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他出生十八世纪的一个小城。", "corrected_sentence": "他出生在十八世纪的一个小城。", "error_description": "介词缺失：表示出生的时间和地点要用“出生在”，“在”不能省，应说“出生在十八世纪”，不能说“出生十八世纪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位诗人在十八世纪去世着。", "corrected_sentence": "那位诗人在十八世纪去世了。", "error_description": "体标误用：“去世”表示一次性完成的变化，不能用表示持续的“着”，应改用“了”，说“去世了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
