INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "识字率指一个国家或地区中，具备基本读写能力的人口占总人口的比例，是衡量教育水平的重要指标。", "primary_collocate": null, "pronunciation": "shí zì lǜ", "ipa": "ʂʅ˧˥ tsɹ̩˥˩ ly˥˩", "syllable_count": 3, "sentences": [{"text": "至十八世纪，识字率在西欧显著上升，公共图书馆、阅读社团与报刊媒体相继兴起，知识的传播不再局限于口耳相传或封闭的手稿交流，而是进入了一个可存储、可检索、可广泛复制的媒介时代。", "target_word": "识字率", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个地区的识字率越来越高。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八世纪的识字率比现在低得多。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想提高农村的识字率。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "识字率是衡量教育水平的指标。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的识字率已经超过百分之九十了。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上学的女孩多了，识字率也提高了。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，识字率高，国家就更有力量。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的识字率只有一半左右。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校多了以后，当地的识字率上升了。", "target_word": "识字率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "識字率", "label": "繁体"}], "register": "书面", "sense_fingerprint": "具备基本读写能力的人口占总人口的比例，衡量教育水平的指标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968499f2-4a88-4c01-811d-facd00e81028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "识字率", "is_correct": true, "explanation": "正确：指具备读写能力的人口占总人口的比例，与图书馆、阅读社团和知识传播的语境相符。"}, {"text": "文盲率", "is_correct": false, "explanation": "语义：文盲率指不识字人口的比例，“上升”与后文图书馆、阅读社团相继兴起的语境相矛盾。"}, {"text": "收视率", "is_correct": false, "explanation": "语义：收视率指电视观众的比例，十八世纪的欧洲还没有电视，不能用于此处。"}, {"text": "颜值", "is_correct": false, "explanation": "语域：颜值是网络口语，指外貌好看的程度，与本句的书面语风格不协调。"}], "explanations": {"识字率": "正确：指具备读写能力的人口占总人口的比例，与图书馆、阅读社团和知识传播的语境相符。", "文盲率": "语义：文盲率指不识字人口的比例，“上升”与后文图书馆、阅读社团相继兴起的语境相矛盾。", "收视率": "语义：收视率指电视观众的比例，十八世纪的欧洲还没有电视，不能用于此处。", "颜值": "语域：颜值是网络口语，指外貌好看的程度，与本句的书面语风格不协调。"}, "sentence_index": 0, "correct_answer": "识字率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村的识字率增加了两百人。", "explanation": "这里应该用〈识字人数〉。识字率是比例，不能用“增加了两百人”这样的人数来表示。"}, {"text": "他的识字率很高，已经读完了大学。", "explanation": "这里应该用〈教育程度〉。识字率是对一个地区或国家人口的统计，不能用来形容某一个人。"}, {"text": "政府开展了识字率运动，帮助农民读书。", "explanation": "这里应该用〈扫盲〉。识字率是统计指标，不是可以开展的运动，应说“开展扫盲运动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "识字率", "is_correct": true, "explanation": "正确：与“上学的人多了”相呼应，表示识字人口的比例随之提高。"}, {"text": "辍学率", "is_correct": false, "explanation": "语义：“也提高了”与前半句“上学的人多了”同向，辍学率提高是负面变化，与句意不符。"}, {"text": "物价", "is_correct": false, "explanation": "语义：上学的人多了与物价提高之间没有关联，句子不成立。"}, {"text": "文盲人数", "is_correct": false, "explanation": "语义：上学的人多了，文盲人数却提高，与“识字率也提高了”的因果关系相反。"}], "explanations": {"识字率": "正确：与“上学的人多了”相呼应，表示识字人口的比例随之提高。", "辍学率": "语义：“也提高了”与前半句“上学的人多了”同向，辍学率提高是负面变化，与句意不符。", "物价": "语义：上学的人多了与物价提高之间没有关联，句子不成立。", "文盲人数": "语义：上学的人多了，文盲人数却提高，与“识字率也提高了”的因果关系相反。"}, "sentence_index": 6, "correct_answer": "识字率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校普及了识字率，每个孩子都能读书。", "explanation": "这里应该用〈教育〉作“普及”的对象。“普及”的对象是教育、知识，识字率是统计比例，不能被普及。"}, {"text": "学校多了以后，当地的一条识字率上升了。", "explanation": "这里应直接说“当地的识字率”。“条”用于长条形的事物，不能用来修饰识字率这种统计指标。"}, {"text": "这所大学的识字率很低，每年只录取三百人。", "explanation": "这里应该用〈录取率〉。录取率指报名者中被录取的比例，识字率指会认字的人口比例，两者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个县的一个识字率已经超过了百分之八十。", "corrected_sentence": "这个县的识字率已经超过了百分之八十。", "error_description": "量词错误：“识字率”是比例，不能用“一个”计量；应去掉“一个”，说“这个县的识字率”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年城市的识字率慢慢长大了。", "corrected_sentence": "这几年城市的识字率慢慢上升了。", "error_description": "搭配错误：“识字率”是比例，只能说“上升 / 提高”，不能说“长大”；“长大”用于人或动植物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
