INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由一些有共同兴趣或目标的人组成的组织或集体。", "primary_collocate": null, "pronunciation": "shè tuán", "ipa": "ʂɤ˥˩ tʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "至十八世纪，识字率在西欧显著上升，公共图书馆、阅读社团与报刊媒体相继兴起，知识的传播不再局限于口耳相传或封闭的手稿交流，而是进入了一个可存储、可检索、可广泛复制的媒介时代。", "target_word": "社团", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我加入了学校的摄影社团。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社团每周六开一次会。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是学校音乐社团的负责人。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里有很多有意思的社团。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社团活动让我认识了新朋友。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们社团准备办一场演出。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加过两个社团。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八世纪的欧洲有不少读书社团。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社团的成员都爱爬山。", "target_word": "社团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "学生社团", "label": "复合"}, {"form": "社团活动", "label": "复合"}, {"form": "社團", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有共同兴趣或目标的人组成的组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968499f2-4a88-4c01-811d-facd00e81028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社团", "is_correct": true, "explanation": "正确：指由有共同兴趣的人组成的组织，与“阅读”相关的语境相合。"}, {"text": "乐团", "is_correct": false, "explanation": "搭配：“阅读”后接“社团”“小组”一类组织，不接“乐团”。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：“阅读工厂”不成立，工厂是生产单位，不是由共同兴趣的人组成的组织，句子不通。"}, {"text": "团伙", "is_correct": false, "explanation": "语域：团伙带有贬义，与本句客观叙述的书面语风格不协调。"}], "explanations": {"社团": "正确：指由有共同兴趣的人组成的组织，与“阅读”相关的语境相合。", "乐团": "搭配：“阅读”后接“社团”“小组”一类组织，不接“乐团”。", "工厂": "语义：“阅读工厂”不成立，工厂是生产单位，不是由共同兴趣的人组成的组织，句子不通。", "团伙": "语域：团伙带有贬义，与本句客观叙述的书面语风格不协调。"}, "sentence_index": 0, "correct_answer": "社团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在社团里买了一斤苹果。", "explanation": "这里应该用〈超市〉。社团是由共同兴趣的人组成的组织，不是买东西的商店。"}, {"text": "这个社团很高，已经长到一米八了。", "explanation": "这里应该用〈同学〉。社团是组织，没有身高，说人的身高应用“同学”。"}, {"text": "他是学校的社团。", "explanation": "这里应该用〈学生〉。社团指一群人组成的团体，不能用来指某一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社团", "is_correct": true, "explanation": "正确：与“准备办一场演出”相符，社团是可以组织活动的团体。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不会组织或举办演出，句子不成立。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能组织或举办演出，句子不成立。"}, {"text": "水库", "is_correct": false, "explanation": "语义：水库是蓄水工程，不会组织或举办演出，句子不成立。"}], "explanations": {"社团": "正确：与“准备办一场演出”相符，社团是可以组织活动的团体。", "冰箱": "语义：冰箱是家用电器，不会组织或举办演出，句子不成立。", "沙发": "语义：沙发是家具，不能组织或举办演出，句子不成立。", "水库": "语义：水库是蓄水工程，不会组织或举办演出，句子不成立。"}, "sentence_index": 6, "correct_answer": "社团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们去社团散步。", "explanation": "这里应该用〈公园〉。社团是组织，不是可以去散步的场所。"}, {"text": "这个社团每天生产两千件衣服。", "explanation": "这里应该用〈工厂〉。社团是非营利的业余组织，不进行生产，生产的主体应是工厂。"}, {"text": "这个社团结婚了，大家都很高兴。", "explanation": "这里应该用〈夫妻〉。结婚的主体是人，社团不能结婚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他同时参加了三条社团。", "corrected_sentence": "他同时参加了三个社团。", "error_description": "错误在量词。“条”用于长条形的事物，社团是组织，应用量词“个”，应为“三个社团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个社团地活动很精彩。", "corrected_sentence": "这个社团的活动很精彩。", "error_description": "错误在“社团”后的助词。“地”用于修饰动词，修饰名词“活动”要用“的”，应为“这个社团的活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebee54d7-0ca1-4797-be42-befb4040de88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
