INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10265, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "报纸和杂志的总称。", "primary_collocate": null, "pronunciation": "bào kān", "ipa": "pɑʊ̯˥˩ kʰan˥", "syllable_count": 2, "sentences": [{"text": "至十八世纪，识字率在西欧显著上升，公共图书馆、阅读社团与报刊媒体相继兴起，知识的传播不再局限于口耳相传或封闭的手稿交流，而是进入了一个可存储、可检索、可广泛复制的媒介时代。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "图书馆里有很多报刊和书。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上都看报刊。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店卖各种报刊。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阅览室里的报刊都很新。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸订了几种报刊。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在报刊上发表过文章。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报刊上的新闻每天都不一样。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧报刊可以卖给收废品的人。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给我们买了许多报刊。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "報刊", "label": "繁体"}, {"form": "报刊亭", "label": "复合"}], "register": "中性", "sense_fingerprint": "报纸和杂志的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '315084ee-027b-4238-8c77-6176fc5e8545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10265, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报刊", "is_correct": true, "explanation": "报刊：报纸和杂志的总称，与“媒体”搭配，指十八世纪兴起的印刷媒介。"}, {"text": "电视", "is_correct": false, "explanation": "语义：十八世纪还没有电视，“电视媒体”与句中的时代背景不符。"}, {"text": "网络", "is_correct": false, "explanation": "语义：十八世纪还没有互联网，“网络媒体”与句中“十八世纪”的时代背景不符。"}, {"text": "石碑", "is_correct": false, "explanation": "搭配：“媒体”通常指报刊、电视、网络这类传播介质，不说“石碑媒体”。"}], "explanations": {"报刊": "报刊：报纸和杂志的总称，与“媒体”搭配，指十八世纪兴起的印刷媒介。", "电视": "语义：十八世纪还没有电视，“电视媒体”与句中的时代背景不符。", "网络": "语义：十八世纪还没有互联网，“网络媒体”与句中“十八世纪”的时代背景不符。", "石碑": "搭配：“媒体”通常指报刊、电视、网络这类传播介质，不说“石碑媒体”。"}, "sentence_index": 0, "correct_answer": "报刊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早上买了一棵报刊。", "explanation": "这里应该用〈份〉。报刊按份、种计量，〈棵〉只用于树木、植物，不能用来量报刊。"}, {"text": "桌子上放着一只报刊。", "explanation": "这里应该用〈份〉。〈只〉多用于动物或成对的物品，报刊要用〈份〉或〈种〉来量。"}, {"text": "妈妈从外面拿进来一根报刊。", "explanation": "这里应该用〈份〉。〈根〉用于细长的东西，报刊不能用〈根〉来量，应用〈份〉或〈种〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报刊", "is_correct": true, "explanation": "报刊：报纸、杂志等公开出版物，可以在报刊上发表文章。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是公开发表文章的媒介，“在冰箱上发表过文章”不合逻辑。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是活动场地，不是发表文章的媒介。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子不是可以发表文章的媒介，“在鞋子上发表过文章”不成立。"}], "explanations": {"报刊": "报刊：报纸、杂志等公开出版物，可以在报刊上发表文章。", "冰箱": "语义：冰箱不是公开发表文章的媒介，“在冰箱上发表过文章”不合逻辑。", "操场": "语义：操场是活动场地，不是发表文章的媒介。", "鞋子": "语义：鞋子不是可以发表文章的媒介，“在鞋子上发表过文章”不成立。"}, "sentence_index": 6, "correct_answer": "报刊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚从书店买回来一座报刊。", "explanation": "这里应该用〈份〉。〈座〉用于山、房屋等大型固定物，报刊不能用〈座〉来量，应用〈份〉或〈种〉。"}, {"text": "电视上每天都播放报刊。", "explanation": "这里应该用〈新闻〉。报刊是印刷品，电视上播放的应是新闻节目，不能说播放报刊。"}, {"text": "他在地铁里捡到一颗报刊。", "explanation": "这里应该用〈份〉。〈颗〉用于粒状或圆形的小东西，报刊不能用〈颗〉来量，应用〈份〉或〈种〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天早上都买一朵报刊。", "corrected_sentence": "他每天早上都买一份报刊。", "error_description": "量词错误：“报刊”应用量词“份”计量，“朵”只用于花朵，不能修饰报刊。正确说法：他每天早上都买一份报刊。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没买了报刊。", "corrected_sentence": "我从来没买过报刊。", "error_description": "体标错误：表示“从来没有过”的经历，否定要用“没……过”，“没……了”不成立。正确说法：我从来没买过报刊。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
