INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10268, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指通过口头讲述的方式，从一个人传到另一个人，代代相传或众人相传。", "primary_collocate": null, "pronunciation": "kǒu ěr xiāng chuán", "ipa": "kʰoʊ̯˨˩˦ ɚ˨˩˦ ɕjɑŋ˥ ʈʂʰwan˧˥", "syllable_count": 4, "sentences": [{"text": "至十八世纪，识字率在西欧显著上升，公共图书馆、阅读社团与报刊媒体相继兴起，知识的传播不再局限于口耳相传或封闭的手稿交流，而是进入了一个可存储、可检索、可广泛复制的媒介时代。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个故事是口耳相传下来的。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，很多歌都靠口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的菜谱一直是口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有文字的时候，知识只能口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民间传说在村里口耳相传了几百年。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那首老歌靠口耳相传流传到今天。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门手艺从来不写下来，只是口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好消息很快在小镇上口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多民间故事都是口耳相传的。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "靠口头讲述一人传一人地传下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '315084ee-027b-4238-8c77-6176fc5e8545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10268, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口耳相传", "is_correct": true, "explanation": "口耳相传：靠口头讲述、一人传一人地传播，与“封闭的手稿交流”形成对比。"}, {"text": "通过网络传播", "is_correct": false, "explanation": "语义：十八世纪还没有网络，与句中的时代背景不符。"}, {"text": "通过电报传递", "is_correct": false, "explanation": "语义：电报是十九世纪才普及的通讯方式，不符合十八世纪的背景。"}, {"text": "通过铁轨运输", "is_correct": false, "explanation": "语义：知识的传播不靠“铁轨运输”，铁轨运输的是货物和乘客，放在句中不通。"}], "explanations": {"口耳相传": "口耳相传：靠口头讲述、一人传一人地传播，与“封闭的手稿交流”形成对比。", "通过网络传播": "语义：十八世纪还没有网络，与句中的时代背景不符。", "通过电报传递": "语义：电报是十九世纪才普及的通讯方式，不符合十八世纪的背景。", "通过铁轨运输": "语义：知识的传播不靠“铁轨运输”，铁轨运输的是货物和乘客，放在句中不通。"}, "sentence_index": 0, "correct_answer": "口耳相传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇游记是他一年前口耳相传的。", "explanation": "这里应该用〈写〉。口耳相传靠口头一人传一人，不能用于由个人写成的文字作品。"}, {"text": "他一个人在房间里口耳相传。", "explanation": "这里应该用〈自言自语〉。口耳相传需要一人讲给另一人、代代传递，不能形容一个人独自说话。"}, {"text": "这份名单是他一笔一画口耳相传的。", "explanation": "这里应该用〈抄写〉。口耳相传靠口头传递，不能用来形容一笔一画写下来的名单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口耳相传", "is_correct": true, "explanation": "口耳相传：靠口头讲述代代传递，与“流传到今天”相符。"}, {"text": "短暂流行", "is_correct": false, "explanation": "语义：“短暂流行”表示时间很短，与“流传到今天”的长久传承相矛盾。"}, {"text": "封存", "is_correct": false, "explanation": "语义：“封存”是收藏起来不让流通，与“流传到今天”的意思相反。"}, {"text": "查阅", "is_correct": false, "explanation": "搭配：“流传”指通过人们的传播延续下去，不能靠“查阅”来流传。"}], "explanations": {"口耳相传": "口耳相传：靠口头讲述代代传递，与“流传到今天”相符。", "短暂流行": "语义：“短暂流行”表示时间很短，与“流传到今天”的长久传承相矛盾。", "封存": "语义：“封存”是收藏起来不让流通，与“流传到今天”的意思相反。", "查阅": "搭配：“流传”指通过人们的传播延续下去，不能靠“查阅”来流传。"}, "sentence_index": 6, "correct_answer": "口耳相传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同是律师口耳相传签下的。", "explanation": "这里应该用〈签订〉。口耳相传指靠口头讲述、一人传一人，不能用来表示签署合同。"}, {"text": "这栋楼是工匠一块块口耳相传砌起来的。", "explanation": "这里应该用〈砌〉。口耳相传靠口头讲述传递，不能用来表示砌墙、盖楼。"}, {"text": "他用手机给朋友口耳相传了照片。", "explanation": "这里应该用〈发送〉。口耳相传只用于口头讲述的内容，照片不能靠口耳相传，应说“发送照片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门手艺是口耳相传下来。", "corrected_sentence": "这门手艺是口耳相传下来的。", "error_description": "句式错误：“是……的”强调句式中漏掉了“的”，应说“这门手艺是口耳相传下来的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一只民歌在村里口耳相传了几百年。", "corrected_sentence": "这一首民歌在村里口耳相传了几百年。", "error_description": "量词错误：“民歌”的量词是“首”，不能用“只”（“只”用于动物等）。错误在“只”，应说“这一首民歌在村里口耳相传了几百年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
