INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10270, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "作者亲笔书写的原稿，通常指未被印刷或复制的手写或打字稿件。", "primary_collocate": null, "pronunciation": "shǒu gǎo", "ipa": "ʂoʊ̯˨˩˦ kɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "至十八世纪，识字率在西欧显著上升，公共图书馆、阅读社团与报刊媒体相继兴起，知识的传播不再局限于口耳相传或封闭的手稿交流，而是进入了一个可存储、可检索、可广泛复制的媒介时代。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "博物馆里展出了作家的手稿。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份手稿上有很多修改的地方。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手稿交给了出版社。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的手稿写得很整齐。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人的手稿保存了一百年。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在手稿上用红笔改了几处。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在图书馆看到了鲁迅的手稿。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是根据作者的手稿印出来的。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手稿放进了盒子里。", "target_word": "手稿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "作者亲笔写的未印刷原稿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '315084ee-027b-4238-8c77-6176fc5e8545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10270, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手稿", "is_correct": true, "explanation": "正确答案：手稿（shǒu gǎo），作者亲笔写的未印刷原稿。"}, {"text": "首脑", "is_correct": false, "explanation": "nǎo 与 gǎo 声母不同（n 与 g），“首脑”意思是领导人，与“手稿”区分开。"}, {"text": "收稿", "is_correct": false, "explanation": "shōu 与 shǒu 声调不同（第一声），“收稿”意思是收取稿件。"}, {"text": "首告", "is_correct": false, "explanation": "gào 与 gǎo 声调不同（第四声），“首告”指向有关部门首先告发。"}], "explanations": {"手稿": "正确答案：手稿（shǒu gǎo），作者亲笔写的未印刷原稿。", "首脑": "nǎo 与 gǎo 声母不同（n 与 g），“首脑”意思是领导人，与“手稿”区分开。", "收稿": "shōu 与 shǒu 声调不同（第一声），“收稿”意思是收取稿件。", "首告": "gào 与 gǎo 声调不同（第四声），“首告”指向有关部门首先告发。"}, "sentence_index": null, "correct_answer": "手稿"}, "level_3": {"options": [{"text": "手稿", "is_correct": true, "explanation": "正确：手稿指作者亲笔写的原稿，符合“封闭的……交流”的语境。"}, {"text": "广播", "is_correct": false, "explanation": "语义：广播面向大众公开传播，与“封闭”相矛盾。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸是公开发行的印刷媒体，与“封闭的……交流”不符。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是后来出现的影像作品，不是作者亲笔的文稿，与“封闭的……交流”的时代背景不符。"}], "explanations": {"手稿": "正确：手稿指作者亲笔写的原稿，符合“封闭的……交流”的语境。", "广播": "语义：广播面向大众公开传播，与“封闭”相矛盾。", "报纸": "语义：报纸是公开发行的印刷媒体，与“封闭的……交流”不符。", "电影": "语义：电影是后来出现的影像作品，不是作者亲笔的文稿，与“封闭的……交流”的时代背景不符。"}, "sentence_index": 0, "correct_answer": "手稿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钱都装在手稿里，带去了商店。", "explanation": "这里应该用〈钱包〉。手稿是作者写的原稿，不是用来装钱的东西。"}, {"text": "他在车上打开手稿，找到了去机场的路。", "explanation": "这里应该用〈地图〉。手稿指作者亲笔写的原稿，不能用来查路线，地图才是用来看路线的。"}, {"text": "他在厨房里用手稿煎了一个鸡蛋。", "explanation": "这里应该用〈平底锅〉。手稿是纸上的文稿，不能用来煎东西，应说“用平底锅煎鸡蛋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10270, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手稿", "is_correct": true, "explanation": "正确答案：手稿（shǒu gǎo），作者亲笔写的未印刷原稿。"}, {"text": "手铐", "is_correct": false, "explanation": "kào 与 gǎo 声母不同（k 与 g），声调也不同（第四声）。“手铐”是锁住手腕的刑具。"}, {"text": "瘦高", "is_correct": false, "explanation": "shòu gāo 与 shǒu gǎo 两个字声调都不同（第四声、第一声）。“瘦高”形容人又瘦又高。"}, {"text": "售稿", "is_correct": false, "explanation": "shòu 与 shǒu 声调不同（第四声）。“售稿”意思是出售稿件。"}], "explanations": {"手稿": "正确答案：手稿（shǒu gǎo），作者亲笔写的未印刷原稿。", "手铐": "kào 与 gǎo 声母不同（k 与 g），声调也不同（第四声）。“手铐”是锁住手腕的刑具。", "瘦高": "shòu gāo 与 shǒu gǎo 两个字声调都不同（第四声、第一声）。“瘦高”形容人又瘦又高。", "售稿": "shòu 与 shǒu 声调不同（第四声）。“售稿”意思是出售稿件。"}, "sentence_index": null, "correct_answer": "手稿"}, "level_3": {"options": [{"text": "手稿", "is_correct": true, "explanation": "正确：手稿是可以在上面用红笔修改的文稿，符合句意。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不是可以修改文字内容的载体，“改了几处”不成立。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不是书写载体，句中“用红笔改”无处可改。"}, {"text": "桌布", "is_correct": false, "explanation": "搭配：“改”的对象是文字内容，“桌布”不能说“改了几处”。"}], "explanations": {"手稿": "正确：手稿是可以在上面用红笔修改的文稿，符合句意。", "墙": "语义：墙不是可以修改文字内容的载体，“改了几处”不成立。", "树叶": "语义：树叶不是书写载体，句中“用红笔改”无处可改。", "桌布": "搭配：“改”的对象是文字内容，“桌布”不能说“改了几处”。"}, "sentence_index": 6, "correct_answer": "手稿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手稿做了一个花瓶。", "explanation": "这里应该用〈纸〉。手稿指作者写的原稿，是文字内容，不是做器物的材料。"}, {"text": "他把手稿种在花园里。", "explanation": "这里应该用〈植物〉。手稿是书写的原稿，不能像植物那样种在土里。"}, {"text": "他昨天喝了一份手稿。", "explanation": "这里应该用〈读〉。手稿是文字材料，不是饮料，不能当作饮料喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在拍卖会上买到了一只名人的手稿。", "corrected_sentence": "他在拍卖会上买到了一份名人的手稿。", "error_description": "量词错误：“手稿”是纸页文稿，应用量词“份”，不能用“只”（“只”用于动物或成对物品中的一个）。错误在“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的手稿写很工整，老师很喜欢。", "corrected_sentence": "她的手稿写得很工整，老师很喜欢。", "error_description": "补语错误：描述“写”的程度要用“得”连接补语，应说“写得很工整”，漏掉“得”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
