INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10271, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "互相沟通，交换意见或信息。", "primary_collocate": null, "pronunciation": "jiāo liú", "ipa": "tɕjɑʊ˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "我们开会交流一下各自的意见。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的学生经常互相交流学习经验。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长交流了孩子的学习情况。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在网上交流工作中的问题。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议让大家有机会交流看法。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要多和病人交流病情。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每个月都组织员工交流经验。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想跟你交流一下读书的心得。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同国家的人通过音乐交流感情。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们正在课堂上交流各自的想法。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交流了", "label": "体标"}, {"form": "交流过", "label": "体标"}, {"form": "交流交流", "label": "重叠"}, {"form": "交流会", "label": "复合"}], "register": "中性", "sense_fingerprint": "交流：双方互相沟通，交换意见、经验或信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '315084ee-027b-4238-8c77-6176fc5e8545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10271, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交流", "is_correct": true, "explanation": "正确：交流指互相沟通、交换意见，与“开会……各自的意见”相合。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：忽略是不予理会，与“开会交流各自意见”的目的相反。"}, {"text": "投票", "is_correct": false, "explanation": "搭配：“投票”的对象是票或候选人，不能说“投票各自的意见”。"}, {"text": "争吵", "is_correct": false, "explanation": "语义：争吵是激烈争执，与开会时平和交换意见的语境冲突。"}], "explanations": {"交流": "正确：交流指互相沟通、交换意见，与“开会……各自的意见”相合。", "忽略": "语义：忽略是不予理会，与“开会交流各自意见”的目的相反。", "投票": "搭配：“投票”的对象是票或候选人，不能说“投票各自的意见”。", "争吵": "语义：争吵是激烈争执，与开会时平和交换意见的语境冲突。"}, "sentence_index": 0, "correct_answer": "交流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国交流了几只大熊猫，各自送到对方动物园。", "explanation": "这里应该用〈交换〉。交换指互相调换人或物，交流指沟通意见，不能用来指调换动物。"}, {"text": "两人在门口交流了钥匙，然后各自回家了。", "explanation": "这里应该用〈交接〉。交流指沟通意见或信息，不能用来指移交钥匙。"}, {"text": "他交流了一本书给老师，老师很高兴。", "explanation": "这里应该用〈送〉。交流指沟通意见或信息，不能用来表示把东西送给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10271, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交流", "is_correct": true, "explanation": "正确：交流经验指互相分享经验，符合句意。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：隐瞒与“组织员工”共同分享的语境相反。"}, {"text": "检查", "is_correct": false, "explanation": "搭配：“检查”的对象是工作或质量，不说“检查经验”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“组织员工忘记经验”与组织活动的目的相矛盾。"}], "explanations": {"交流": "正确：交流经验指互相分享经验，符合句意。", "隐瞒": "语义：隐瞒与“组织员工”共同分享的语境相反。", "检查": "搭配：“检查”的对象是工作或质量，不说“检查经验”。", "忘记": "语义：“组织员工忘记经验”与组织活动的目的相矛盾。"}, "sentence_index": 6, "correct_answer": "交流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他交流了一台旧电脑，卖给了同学。", "explanation": "这里应该用〈出售〉。交流的宾语是意见、经验或情况，不能是具体物品。"}, {"text": "我们交流了一堆砖块，准备盖房子。", "explanation": "这里应该用〈搬〉。交流不能用于砖块等具体物品。"}, {"text": "她交流了一把椅子，放在客厅里。", "explanation": "这里应该用〈搬〉或〈买〉。交流不能用于具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在会上交流很充分。", "corrected_sentence": "我们在会上交流得很充分。", "error_description": "补语错误：说明“交流”的程度要用“得”连接补语，应说“交流得很充分”，漏掉“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从来没交流了。", "corrected_sentence": "我们从来没交流过。", "error_description": "体标错误：表示“从来没有过”的经历，否定要用“没……过”，“没……了”不成立。正确说法：我们从来没交流过。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
