INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10273, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "查找、搜寻所需的内容或资料。", "primary_collocate": null, "pronunciation": "jiǎn suǒ", "ipa": "tɕjɛn˨˩ swɔ˨˩", "syllable_count": 2, "sentences": [{"text": "至十八世纪，识字率在西欧显著上升，公共图书馆、阅读社团与报刊媒体相继兴起，知识的传播不再局限于口耳相传或封闭的手稿交流，而是进入了一个可存储、可检索、可广泛复制的媒介时代。", "target_word": "检索", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我在图书馆的电脑上检索了这本书。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请输入关键词，系统会自动检索资料。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机检索附近的餐厅。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生可以在网上检索论文。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件检索速度非常快。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们如何检索历史资料。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的目录可以按作者检索。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把书名输入后检索了一遍。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检索了病人的旧病历。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "检索了", "label": "体标"}, {"form": "检索过", "label": "体标"}, {"form": "检索结果", "label": "复合"}, {"form": "检索系统", "label": "复合"}], "register": "书面", "sense_fingerprint": "检索：按条件在书目、数据库、网络中查找所需资料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '315084ee-027b-4238-8c77-6176fc5e8545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "检索", "is_correct": true, "explanation": "“可检索”指可以按条件查找资料，与“可存储”“可广泛复制”并列，描述媒介时代的特征。"}, {"text": "焚毁", "is_correct": false, "explanation": "语义：“焚毁”是烧毁，与“可存储”并列时自相矛盾，媒介的特征不可能是可焚毁。"}, {"text": "口传", "is_correct": false, "explanation": "语义：前文已说知识“不再局限于口耳相传”，此处再说“可口传”与句意相反。"}, {"text": "手抄", "is_correct": false, "explanation": "搭配：“手抄”指手工誊写，与“可广泛复制”的媒介特征不搭，两者的传播方式相反。"}], "explanations": {"检索": "“可检索”指可以按条件查找资料，与“可存储”“可广泛复制”并列，描述媒介时代的特征。", "焚毁": "语义：“焚毁”是烧毁，与“可存储”并列时自相矛盾，媒介的特征不可能是可焚毁。", "口传": "语义：前文已说知识“不再局限于口耳相传”，此处再说“可口传”与句意相反。", "手抄": "搭配：“手抄”指手工誊写，与“可广泛复制”的媒介特征不搭，两者的传播方式相反。"}, "sentence_index": 0, "correct_answer": "检索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察在河边检索失踪的小孩。", "explanation": "这里应该用〈寻找〉。检索用于在资料、数据中查找信息，找人要用寻找。"}, {"text": "他在抽屉里检索钥匙。", "explanation": "这里应该用〈翻找〉。检索的对象是资料和信息，钥匙是实物，要用翻找。"}, {"text": "工人用仪器检索管道的漏水情况。", "explanation": "这里应该用〈检测〉。检索是在资料中查找信息，用仪器查看设备状况要用检测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "检索", "is_correct": true, "explanation": "“教我们如何检索历史资料”：检索指按条件查找所需资料，符合教学内容。"}, {"text": "拆卸", "is_correct": false, "explanation": "语义：拆卸是把器物拆开，历史资料是文字材料，不能拿来拆卸，句意不通。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做菜，历史资料不能用来烹饪，句意不通。"}, {"text": "踢打", "is_correct": false, "explanation": "语义：踢打是用脚或拳头击打，历史资料不能拿来踢打，与“教我们如何”的学习内容不相称。"}], "explanations": {"检索": "“教我们如何检索历史资料”：检索指按条件查找所需资料，符合教学内容。", "拆卸": "语义：拆卸是把器物拆开，历史资料是文字材料，不能拿来拆卸，句意不通。", "烹饪": "语义：烹饪是做菜，历史资料不能用来烹饪，句意不通。", "踢打": "语义：踢打是用脚或拳头击打，历史资料不能拿来踢打，与“教我们如何”的学习内容不相称。"}, "sentence_index": 6, "correct_answer": "检索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每周都检索窗户。", "explanation": "这里应该用〈擦拭〉。检索用于查找资料和信息，擦窗户这类实物动作要用擦拭。"}, {"text": "护士悉心检索病人。", "explanation": "这里应该用〈照顾〉。检索的对象是信息，不能用于照料人，照顾病人要用照顾。"}, {"text": "油漆工检索了整面墙。", "explanation": "这里应该用〈粉刷〉。检索只用于资料、数据，给墙面上漆要用粉刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我终于检索了出那份报告。", "corrected_sentence": "我终于检索出了那份报告。", "error_description": "“检索出”中，结果补语“出”要紧跟动词，“了”放在“出”之后。此处把“了”插在“检索”和“出”之间，应说“检索出了”，不说“检索了出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员把数据库里检索了那批数据。", "corrected_sentence": "研究人员在数据库里检索了那批数据。", "error_description": "介词误用：“在数据库里”是修饰“检索”的地点状语，应用“在”引出，不能用“把”。“把”字句要求“把”后的名词是被处置的对象，“数据库里”是地点，不能作宾语，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10286, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取出", "is_correct": true, "explanation": "反义：“储存”是放入以备用，“取出”是把放好的东西拿出来，二者互为相反的动作。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是悠闲地走动，与“储存”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”是发出曲调的声音，与“储存”没有反义关系。"}, {"text": "拒绝", "is_correct": false, "explanation": "“拒绝”是不接受，与“储存”在任何义项上都不构成反义关系。"}], "correct_answer": "取出", "explanations": {"取出": "反义：“储存”是放入以备用，“取出”是把放好的东西拿出来，二者互为相反的动作。", "散步": "“散步”是悠闲地走动，与“储存”没有反义关系。", "唱歌": "“唱歌”是发出曲调的声音，与“储存”没有反义关系。", "拒绝": "“拒绝”是不接受，与“储存”在任何义项上都不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10286, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取用", "is_correct": true, "explanation": "反义：“储存”是放好备用，“取用”是把存放的东西拿来使用，二者是相反的动作。"}, {"text": "跳舞", "is_correct": false, "explanation": "“跳舞”是随着音乐做动作，与“储存”没有反义关系。"}, {"text": "批评", "is_correct": false, "explanation": "“批评”是指出缺点或错误，与“储存”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”是使损坏的东西恢复正常，与“储存”在任何义项上都没有反义关系。"}], "correct_answer": "取用", "explanations": {"取用": "反义：“储存”是放好备用，“取用”是把存放的东西拿来使用，二者是相反的动作。", "跳舞": "“跳舞”是随着音乐做动作，与“储存”没有反义关系。", "批评": "“批评”是指出缺点或错误，与“储存”没有反义关系。", "修理": "“修理”是使损坏的东西恢复正常，与“储存”在任何义项上都没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10286, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西或信息放在某个地方，方便以后再用。", "primary_collocate": null, "pronunciation": "chǔ cún", "ipa": "ʈʂʰu˨˩˦ tsʰuən˧˥", "syllable_count": 2, "sentences": [{"text": "例如，有些社区会在雨季时把雨水收集起来，储存在地下的水窖里。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "冬天到了，农民把粮食储存在仓库里。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑可以储存很多照片。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的空间满了，不能再储存新视频。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把水果储存在冰箱里，可以放很久。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太阳多，这些电池储存了不少电。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骆驼的驼峰里储存着脂肪，路上可以慢慢用。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每年秋天都储存很多白菜。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把文件储存好，明天再用。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个水库储存了足够全城用的水。", "target_word": "储存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "储存了", "label": "体标"}, {"form": "储存着", "label": "体标"}, {"form": "储存过", "label": "体标"}, {"form": "儲存", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把物品、水、电或数据保存在某处以备日后使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b7ca80-ae1c-4e7c-a5ec-daf599d2e99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10286, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "储存", "is_correct": true, "explanation": "正确：句意是把雨水收集后放进水窖以备日后使用，“储存”正好表示这一点。"}, {"text": "倒掉", "is_correct": false, "explanation": "语义：“倒掉”是丢弃，与前面“收集起来”要留用的意思相反。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”只带可喝之物做宾语，不能接“在……里”表示存放的处所。"}, {"text": "挥发", "is_correct": false, "explanation": "语义：「挥发」指物质变成气体散失，与「存放在水窖里以备日后使用」的保存意思不符。"}], "explanations": {"储存": "正确：句意是把雨水收集后放进水窖以备日后使用，“储存”正好表示这一点。", "倒掉": "语义：“倒掉”是丢弃，与前面“收集起来”要留用的意思相反。", "饮用": "搭配：“饮用”只带可喝之物做宾语，不能接“在……里”表示存放的处所。", "挥发": "语义：「挥发」指物质变成气体散失，与「存放在水窖里以备日后使用」的保存意思不符。"}, "sentence_index": 0, "correct_answer": "储存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要储存这段珍贵的友谊，永远不分开。", "explanation": "这里应该用〈珍惜〉。储存指把东西或信息放在某处备用，友谊这类抽象情感不能储存，应说珍惜。"}, {"text": "这条路每天都很堵，我只能储存拥堵。", "explanation": "这里应该用〈忍受〉。拥堵是一种状况，只能忍受，不能被放在某处备用，储存不合适。"}, {"text": "这次旅行让我储存了很多快乐。", "explanation": "这里应该用〈收获〉。快乐是在经历中得到的，要说收获；储存只用于可以放置的物品或信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "储存", "is_correct": true, "explanation": "正确：“储存着脂肪”表示脂肪存放在驼峰里备用，与“路上慢慢用”相符。"}, {"text": "排出", "is_correct": false, "explanation": "语义：“排出”是排除到外面，与“路上可以慢慢用”的存放用途矛盾。"}, {"text": "挖出", "is_correct": false, "explanation": "体貌：“挖出”表示动作已完成，不能接表示持续状态的“着”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，且不能用“驼峰里”表示存放的处所，句子不通。"}], "explanations": {"储存": "正确：“储存着脂肪”表示脂肪存放在驼峰里备用，与“路上慢慢用”相符。", "排出": "语义：“排出”是排除到外面，与“路上可以慢慢用”的存放用途矛盾。", "挖出": "体貌：“挖出”表示动作已完成，不能接表示持续状态的“着”。", "吃": "搭配：“吃”的宾语是食物，且不能用“驼峰里”表示存放的处所，句子不通。"}, "sentence_index": 6, "correct_answer": "储存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他独自储存了全家的压力，很辛苦。", "explanation": "这里应该用〈承受〉。压力是人要承担的负担，要说承受；储存只用于能放置、留待以后用的物品或信息。"}, {"text": "这个孩子从小就储存了很强的好奇心。", "explanation": "这里应该用〈培养〉。好奇心要靠长期引导才能形成，说培养；储存针对可以放置、留着备用的物品或信息。"}, {"text": "周末的旅行让我储存了一整天的好心情。", "explanation": "这里应该用〈保持〉。心情是一种状态，要说保持；储存只用于物品和信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把这些照片储存着好，明天再看。", "corrected_sentence": "请把这些照片储存好，明天再看。", "error_description": "体标与补语冲突：「着」表示持续状态，与结果补语「好」不能同时用在动词后，应说「储存好」，不能说「储存着好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把钥匙储存抽屉里了。", "corrected_sentence": "他把钥匙储存在抽屉里了。", "error_description": "介词缺失：「储存」后面表示存放处所要用介词「在」引出，应说「储存在抽屉里了」，不能省去「在」说「储存抽屉里了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10293, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10293, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10293, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "深远影响指某个事件或行为在较长时间内对事物发展产生的重大作用或后果。", "primary_collocate": null, "pronunciation": "shēn yuǎn yǐng xiǎng", "ipa": "ʂən˥ ɥɛn˨˩ iŋ˨˩ ɕjɑŋ˨˩", "syllable_count": 4, "sentences": [{"text": "回望这段历史，印刷术不仅是技术的发明，更是认知范式的革命——它重新定义了人类记忆的边界，将知识从个体脑中的脆弱储存，转化为集体共享的、可不断累积的文化资本，其深远影响至今仍在数字时代的洪流中回响。", "target_word": "深远影响", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这件事对国家产生了深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷术对世界有深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话对我有深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次改革带来了深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母的教育会对孩子造成深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项发明的深远影响，人们当时还不知道。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "互联网给我们的生活带来深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场战争留下了深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的鼓励给他的一生带来深远影响。", "target_word": "深远影响", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深远的影响", "label": "变体"}], "register": "书面", "sense_fingerprint": "深远影响：事件或行为长期、重大地作用于事物发展的后果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '315084ee-027b-4238-8c77-6176fc5e8545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10293, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深远影响", "is_correct": true, "explanation": "“其深远影响至今仍在……回响”：深远影响指长期而重大的作用，与“至今仍在回响”的持续性相符。"}, {"text": "短暂的热潮", "is_correct": false, "explanation": "语义：“短暂”与“至今仍在回响”的持续性相悖。"}, {"text": "局部的小事", "is_correct": false, "explanation": "语义：“局部的小事”的规模与“重新定义人类记忆的边界”这样的重大变革不符。"}, {"text": "无声的沉默", "is_correct": false, "explanation": "搭配：“回响”多指声音或影响的延续，“沉默”不能回响。"}], "explanations": {"深远影响": "“其深远影响至今仍在……回响”：深远影响指长期而重大的作用，与“至今仍在回响”的持续性相符。", "短暂的热潮": "语义：“短暂”与“至今仍在回响”的持续性相悖。", "局部的小事": "语义：“局部的小事”的规模与“重新定义人类记忆的边界”这样的重大变革不符。", "无声的沉默": "搭配：“回响”多指声音或影响的延续，“沉默”不能回响。"}, "sentence_index": 0, "correct_answer": "深远影响"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向老板提出了深远影响。", "explanation": "这里应该用〈建议〉。深远影响是事件长期产生的后果，不能被提出，提出的应是建议。"}, {"text": "我从这次失败中吸取了深远影响。", "explanation": "这里应该用〈教训〉。吸取的是经验教训，深远影响是事件的长期作用，不能被吸取。"}, {"text": "这次旅行让我积累了深远影响。", "explanation": "这里应该用〈经验〉。积累的是经验，深远影响是事件产生的长期结果，不能积累。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10293, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深远影响", "is_correct": true, "explanation": "“这项发明的深远影响，人们当时还不知道”：深远影响是长期才显现的作用，与“当时还不知道”相符。"}, {"text": "当场效果", "is_correct": false, "explanation": "语义：“当场”即刻显现，人们当时就会知道，与“当时还不知道”相矛盾。"}, {"text": "明显用途", "is_correct": false, "explanation": "语义：用途明显就说明人们已经知道，与“当时还不知道”相矛盾。"}, {"text": "火候", "is_correct": false, "explanation": "搭配：“火候”指烹饪时对火力的把握，不能用来说发明的影响。"}], "explanations": {"深远影响": "“这项发明的深远影响，人们当时还不知道”：深远影响是长期才显现的作用，与“当时还不知道”相符。", "当场效果": "语义：“当场”即刻显现，人们当时就会知道，与“当时还不知道”相矛盾。", "明显用途": "语义：用途明显就说明人们已经知道，与“当时还不知道”相矛盾。", "火候": "搭配：“火候”指烹饪时对火力的把握，不能用来说发明的影响。"}, "sentence_index": 6, "correct_answer": "深远影响"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师传授了深远影响。", "explanation": "这里应该用〈方法〉。传授的是知识和方法，深远影响是事件的后果，不能传授。"}, {"text": "两人培养了深远影响。", "explanation": "这里应该用〈感情〉。培养的是感情，深远影响不能被培养。"}, {"text": "他不小心打碎了深远影响。", "explanation": "这里应该用〈花瓶〉。打碎的是有形的器物，深远影响是无形的长期作用，不能被打碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10293, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项改革产生了一块深远的影响。", "corrected_sentence": "这项改革产生了一种深远的影响。", "error_description": "量词误用：“块”用于块状的实物，不能修饰抽象的“影响”，应用“种”或“个”。正确说法：这项改革产生了一种深远的影响。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10293, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次地震被城市产生了深远影响。", "corrected_sentence": "这次地震对城市产生了深远影响。", "error_description": "介词误用：“对城市”引出影响的对象，应用“对”，不能用“被”。“被”字句要求受事或施事的明确关系，“被城市产生”把城市当作施事，句意不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9009fb0-cb06-4dc3-be5d-892cec861ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
