INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10297, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10297, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指汹涌澎湃、势不可挡的水流，也比喻强大的社会潮流或力量。", "primary_collocate": null, "pronunciation": "hóng liú", "ipa": "xʊŋ˧˥ lioʊ˧˥", "syllable_count": 2, "sentences": [{"text": "回望这段历史，印刷术不仅是技术的发明，更是认知范式的革命——它重新定义了人类记忆的边界，将知识从个体脑中的脆弱储存，转化为集体共享的、可不断累积的文化资本，其深远影响至今仍在数字时代的洪流中回响。", "target_word": "洪流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大雨之后，山上的洪流冲了下来。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪流冲断了小桥，村里的人过不去了。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青年们加入了时代的洪流。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要跟上时代的洪流，不断学习。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变成洪流，一下子淹没了田地。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个人的力量很小，却能汇入改革的洪流。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对信息的洪流，我们要学会选择。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪流从山口冲出来，声音像打雷一样。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在抗战的洪流中长大。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股洪流", "label": "量词"}, {"form": "时代洪流", "label": "复合"}], "register": "书面", "sense_fingerprint": "洪流·汹涌的水流，比喻强大的社会潮流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab2749-257c-4c70-be8d-c6367b76fc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10297, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洪流", "is_correct": true, "explanation": "正确：“洪流”比喻强大的社会潮流，“数字时代的洪流中回响”搭配自然。"}, {"text": "河床", "is_correct": false, "explanation": "语义：河床是河底的土层，不是能在数字时代里“回响”的事物。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：“回响”用于声音或影响，不能与“颜料”搭配。"}, {"text": "树荫", "is_correct": false, "explanation": "语义：树荫是遮挡阳光的阴凉处，与“数字时代”“回响”都不相容。"}], "explanations": {"洪流": "正确：“洪流”比喻强大的社会潮流，“数字时代的洪流中回响”搭配自然。", "河床": "语义：河床是河底的土层，不是能在数字时代里“回响”的事物。", "颜料": "搭配：“回响”用于声音或影响，不能与“颜料”搭配。", "树荫": "语义：树荫是遮挡阳光的阴凉处，与“数字时代”“回响”都不相容。"}, "sentence_index": 0, "correct_answer": "洪流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很符合洪流。", "explanation": "这里应该用〈潮流〉。“符合”搭配的是时尚的潮流；洪流强调汹涌冲击的力量，不能说“符合洪流”。"}, {"text": "他把洪流倒进了杯子里。", "explanation": "这里应该用〈水〉。洪流是汹涌的大水流，不能倒进杯子里；倒进杯子的应是〈水〉。"}, {"text": "他沿着洪流散步，看风景。", "explanation": "这里应该用〈河流〉。洪流湍急危险，不能沿着它散步；可以沿岸散步的是〈河流〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10297, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洪流", "is_correct": true, "explanation": "正确：“汇入改革的洪流”指投身于强大的改革潮流，搭配自然。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印是踩出的痕迹，不是能够“汇入”的事物。"}, {"text": "石阶", "is_correct": false, "explanation": "语义：石阶是台阶，无法“汇入”改革。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“汇入”用于水流、资金、人群，不能说“汇入玻璃”。"}], "explanations": {"洪流": "正确：“汇入改革的洪流”指投身于强大的改革潮流，搭配自然。", "脚印": "语义：脚印是踩出的痕迹，不是能够“汇入”的事物。", "石阶": "语义：石阶是台阶，无法“汇入”改革。", "玻璃": "搭配：“汇入”用于水流、资金、人群，不能说“汇入玻璃”。"}, "sentence_index": 6, "correct_answer": "洪流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把积蓄存进了洪流。", "explanation": "这里应该用〈银行〉。洪流是汹涌的水流，不能存放钱财；存钱要说“存进银行”。"}, {"text": "比赛进入了洪流。", "explanation": "这里应该用〈高潮〉。比赛最激烈的阶段叫高潮，洪流不用于比赛的阶段。"}, {"text": "他们把抗战的洪流切成几块，分给大家。", "explanation": "这里应该用〈蛋糕〉。洪流是汹涌的水流或社会潮流，不能切块分给大家；切开分给大家的应是〈蛋糕〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一颗改革的洪流正在席卷这个行业。", "corrected_sentence": "一股改革的洪流正在席卷这个行业。", "error_description": "量词错误：洪流应用量词“股”，“颗”多用于小而圆的物体，不能修饰洪流。正确应为“一股改革的洪流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们抗战的洪流中成长起来。", "corrected_sentence": "他们在抗战的洪流中成长起来。", "error_description": "介词遗漏：表示处所的“在抗战的洪流中”缺少介词“在”，应说“在抗战的洪流中成长起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10298, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10298, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10298, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "声音反射回来，再次听到。", "primary_collocate": null, "pronunciation": "huí xiǎng", "ipa": "xu̯eɪ˧˥ ɕi̯ɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这座石窟的穹顶极高，人们的低语在洞穴深处久久回响。", "target_word": "回响", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这座古老剧院的木质结构十分精巧，台上的一句台词经过层层反射，在观众席中清晰回响。", "target_word": "回响", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "山谷里的喊声在远处回响。", "target_word": "回响", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教堂里钟声久久回响。", "target_word": "回响", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对着大山喊，山里回响着他的声音。", "target_word": "回响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空房子里，脚步声清楚地回响。", "target_word": "回响", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "歌声在夜空中回响，大家都安静了。", "target_word": "回响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隧道里汽车的声音不停地回响。", "target_word": "回响", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在山洞里拍手，掌声在洞里回响。", "target_word": "回响", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大厅很大，说话声在四周回响。", "target_word": "回响", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "回响着", "label": "体标"}, {"form": "回响了", "label": "体标"}, {"form": "回响过", "label": "体标"}, {"form": "回響", "label": "繁体"}], "register": "中性", "sense_fingerprint": "回响：声音碰到阻挡后反射回来，在空间里再次被听到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3701140-a2a2-4137-8b61-b34e446ee27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10298, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回响", "is_correct": true, "explanation": "正确答案：回响（huí xiǎng），指声音碰到阻挡后反射回来，再次被听到。"}, {"text": "回乡", "is_correct": false, "explanation": "huíxiāng（第一声）与 huíxiǎng（第三声）声调不同，意思是回到家乡。"}, {"text": "回翔", "is_correct": false, "explanation": "xiáng（第二声）与 xiǎng（第三声）声调不同，意思是在空中盘旋飞翔。"}, {"text": "回显", "is_correct": false, "explanation": "xiǎn 与 xiǎng 韵母不同（-n 与 -ng），意思是重新显示。"}], "explanations": {"回响": "正确答案：回响（huí xiǎng），指声音碰到阻挡后反射回来，再次被听到。", "回乡": "huíxiāng（第一声）与 huíxiǎng（第三声）声调不同，意思是回到家乡。", "回翔": "xiáng（第二声）与 xiǎng（第三声）声调不同，意思是在空中盘旋飞翔。", "回显": "xiǎn 与 xiǎng 韵母不同（-n 与 -ng），意思是重新显示。"}, "sentence_index": null, "correct_answer": "回响"}, "level_3": {"options": [{"text": "回响", "is_correct": true, "explanation": "正确答案：“低语在洞穴深处久久回响”指声音在空间中反射、持续可闻，符合“穹顶极高”的空间描写。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”无法表示声音在空间中的持续反射，语义不通。"}, {"text": "货色", "is_correct": false, "explanation": "语义：“货色”指货物或人的品质，无法表示声音的反射，语义不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”与声音的持续反射毫无关联，语义不通。"}], "explanations": {"回响": "正确答案：“低语在洞穴深处久久回响”指声音在空间中反射、持续可闻，符合“穹顶极高”的空间描写。", "颜色": "语义：“颜色”无法表示声音在空间中的持续反射，语义不通。", "货色": "语义：“货色”指货物或人的品质，无法表示声音的反射，语义不通。", "价格": "语义：“价格”与声音的持续反射毫无关联，语义不通。"}, "sentence_index": 0, "correct_answer": "回响"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我常常回响小时候的事。", "explanation": "这里应该用〈回想〉。回想指回忆过去的事，回响只指声音被反射回来，不能用于想起往事。"}, {"text": "老师很快回响了我的问题。", "explanation": "这里应该用〈回应〉。回应指对问题作出答复，回响只用于声音被反射回来。"}, {"text": "这个工厂每天回响大量废纸。", "explanation": "这里应该用〈回收〉。回收指把废品收集起来再利用，回响只指声音被反射回来，不能用于处理废品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回响", "is_correct": true, "explanation": "正确答案：“歌声在夜空中回响”指声音在空间中反射传播，与后文“大家都安静了”呼应。"}, {"text": "回击", "is_correct": false, "explanation": "语义：“回击”指还击，歌声不能还击任何人。"}, {"text": "回绝", "is_correct": false, "explanation": "配价：“回绝”需要带拒绝的对象，句中没有受事宾语，不能单独作谓语。"}, {"text": "回头", "is_correct": false, "explanation": "语义：“回头”指转过身，歌声不能转身。"}], "explanations": {"回响": "正确答案：“歌声在夜空中回响”指声音在空间中反射传播，与后文“大家都安静了”呼应。", "回击": "语义：“回击”指还击，歌声不能还击任何人。", "回绝": "配价：“回绝”需要带拒绝的对象，句中没有受事宾语，不能单独作谓语。", "回头": "语义：“回头”指转过身，歌声不能转身。"}, "sentence_index": 6, "correct_answer": "回响"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司每年都回响社会。", "explanation": "这里应该用〈回馈〉。回馈指以实际行动报答社会，回响只用于声音被反射回来。"}, {"text": "我们经常回响去年的工作。", "explanation": "这里应该用〈回顾〉。回顾指回头看、总结过去的事，回响只指声音。"}, {"text": "他常常回响童年的快乐。", "explanation": "这里应该用〈回味〉。回味指事后细细体会，回响只指声音被反射回来，不能用于体会过去的感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "钟声在山谷里久久回响着了。", "corrected_sentence": "钟声在山谷里久久回响着。", "error_description": "错误：“回响着了”，“着”表示持续，不能与“了”连用在动词后。正确：“久久回响着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的喊声回响的很远。", "corrected_sentence": "他的喊声回响得很远。", "error_description": "表示程度的补语要用“得”连接，说“回响得很远”；用“的”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08b01744-fea4-45c1-a265-f99cdcb32ce5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
