INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手从高处或附着处取下。", "primary_collocate": null, "pronunciation": "zhāi xià lái", "ipa": "ʈʂai̯˥ ɕja˥˩ lai̯˧˥", "syllable_count": 3, "sentences": [{"text": "咖啡豆成熟后，人们把它们摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "苹果熟了，爷爷爬上梯子把它们摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树上的橘子太高了，我用长杆把它摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄熟透了，妈妈小心地把它摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里的辣椒红了，姐姐把它们摘下来晒。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花开得最美，小女孩想把它摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶农清早上山，把嫩叶一片一片摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树上的柿子红了，孩子们都想摘下来尝尝。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，农民把棉花摘下来晒干。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豆角老了就不好吃，要早点摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摘下来了", "label": "体标"}, {"form": "摘不下来", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "摘下来：用手把长在枝头或附着在高处的东西取下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a50759fb-3f82-4d2e-b11e-78657eb50899') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摘下来", "is_correct": true, "explanation": "正确。摘下来读 zhāi xià lái，指用手从高处或附着处取下。"}, {"text": "拆下来", "is_correct": false, "explanation": "chāi（拆）与 zhāi（摘）声母不同（ch 与 zh），意思是把连着的东西拆下来。"}, {"text": "栽下来", "is_correct": false, "explanation": "zāi（栽）与 zhāi（摘）声母不同（z 与 zh），意思是栽倒、摔下来。"}, {"text": "窄下来", "is_correct": false, "explanation": "zhǎi（窄）与 zhāi（摘）声调不同，意思是变窄。"}], "explanations": {"摘下来": "正确。摘下来读 zhāi xià lái，指用手从高处或附着处取下。", "拆下来": "chāi（拆）与 zhāi（摘）声母不同（ch 与 zh），意思是把连着的东西拆下来。", "栽下来": "zāi（栽）与 zhāi（摘）声母不同（z 与 zh），意思是栽倒、摔下来。", "窄下来": "zhǎi（窄）与 zhāi（摘）声调不同，意思是变窄。"}, "sentence_index": null, "correct_answer": "摘下来"}, "level_3": {"options": [{"text": "摘下来", "is_correct": true, "explanation": "正确。摘下来指用手从枝头取下果实，与咖啡豆成熟后采收相符。"}, {"text": "喝下去", "is_correct": false, "explanation": "搭配：“喝下去”的对象是液体，咖啡豆不能喝。"}, {"text": "摔下去", "is_correct": false, "explanation": "语义：“摔下去”指跌落，与人们采收果实的动作不符。"}, {"text": "砍下来", "is_correct": false, "explanation": "搭配：“砍下来”多用于枝干等较硬的部分，不用于采收咖啡豆。"}], "explanations": {"摘下来": "正确。摘下来指用手从枝头取下果实，与咖啡豆成熟后采收相符。", "喝下去": "搭配：“喝下去”的对象是液体，咖啡豆不能喝。", "摔下去": "语义：“摔下去”指跌落，与人们采收果实的动作不符。", "砍下来": "搭配：“砍下来”多用于枝干等较硬的部分，不用于采收咖啡豆。"}, "sentence_index": 0, "correct_answer": "摘下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从书架上摘下来一本书。", "explanation": "这里应该用〈拿下来〉。摘下来指从枝头或挂着的东西上取下，从书架上拿书要说拿下来。"}, {"text": "妈妈用剪刀把我的一缕头发摘下来。", "explanation": "这里应该用〈剪下来〉。用剪刀把头发弄下来要说剪下来，摘下来是用手从枝头或挂着的地方取下。"}, {"text": "妈妈把沉重的箱子摘下来，放在地上。", "explanation": "这里应该用〈搬下来〉。摘用于从枝头或挂着的东西上取下，把箱子从高处搬下要说搬下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摘下来", "is_correct": true, "explanation": "正确。摘下来指用手把嫩叶从枝上取下，与茶农采茶的动作相符。"}, {"text": "吹走", "is_correct": false, "explanation": "语义：“吹走”指被风带走，与茶农一片一片采嫩叶的动作不符。"}, {"text": "浇湿", "is_correct": false, "explanation": "语义：“浇湿”指加水弄湿，与采摘嫩叶无关。"}, {"text": "拍扁", "is_correct": false, "explanation": "搭配：“拍扁”多用于较硬或扁平的东西，不用于采摘嫩叶。"}], "explanations": {"摘下来": "正确。摘下来指用手把嫩叶从枝上取下，与茶农采茶的动作相符。", "吹走": "语义：“吹走”指被风带走，与茶农一片一片采嫩叶的动作不符。", "浇湿": "语义：“浇湿”指加水弄湿，与采摘嫩叶无关。", "拍扁": "搭配：“拍扁”多用于较硬或扁平的东西，不用于采摘嫩叶。"}, "sentence_index": 6, "correct_answer": "摘下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师把鸡腿摘下来，放进锅里炖。", "explanation": "这里应该用〈切下来〉。摘用于从枝头或挂着的东西上取下，把肉切开要说切下来。"}, {"text": "她把地上的垃圾摘下来扔掉。", "explanation": "这里应该用〈捡起来〉。摘用于从枝头或挂着的东西上取下，地上的东西要说捡起来。"}, {"text": "农民把地里的稻子摘下来，动作很快。", "explanation": "这里应该用〈割下来〉。稻子要用镰刀割，摘用于果实或挂着的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把树上的果子了摘下来了。", "corrected_sentence": "他把树上的果子摘下来了。", "error_description": "错误：“了”插在“把”字宾语与动词“摘”之间，动词前不能用“了”；应删去，正确为“摘下来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅画挂得太牢，我没摘下来了。", "corrected_sentence": "这幅画挂得太牢，我没摘下来。", "error_description": "错误：“没”否定已发生的动作时不能再带“了”；应删去末尾的“了”，正确为“没摘下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
