INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10319, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指具有共同遗传特征（如肤色、头型、血型等）的人类群体，如蒙古人种、高加索人种等。", "primary_collocate": null, "pronunciation": "rén zhǒng", "ipa": "ʐən˧˥ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "农场的工人来自不同的人种。", "target_word": "人种", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世界上有不同的人种，但大家都是人类。", "target_word": "人种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蒙古人种的头发一般又黑又直。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家说，人种不同并不代表能力不同。", "target_word": "人种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者研究人种的起源已经三十年了。", "target_word": "人种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高加索人种的皮肤一般比较白。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课本里介绍了世界上几大人种。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同人种的肤色和头型常常不一样。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不应该因为人种不同就看不起别人。", "target_word": "人种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的父母来自两个不同的人种。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "人種", "label": "繁体"}, {"form": "人种学", "label": "复合"}], "register": "书面", "sense_fingerprint": "具有共同遗传特征的人类群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a253744-136e-4587-a572-1ffd876a460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10319, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人种", "is_correct": true, "explanation": "人种：正确答案。"}, {"text": "物种", "is_correct": false, "explanation": "语义：“物种”指生物的种类，工人之间的差别不说“不同的物种”。"}, {"text": "人手", "is_correct": false, "explanation": "搭配：“人手”指干活的人数，不能说“来自不同的人手”。"}, {"text": "作物", "is_correct": false, "explanation": "语义：“作物”指庄稼，工人不能“来自不同的作物”。"}], "explanations": {"人种": "人种：正确答案。", "物种": "语义：“物种”指生物的种类，工人之间的差别不说“不同的物种”。", "人手": "搭配：“人手”指干活的人数，不能说“来自不同的人手”。", "作物": "语义：“作物”指庄稼，工人不能“来自不同的作物”。"}, "sentence_index": 0, "correct_answer": "人种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人种有自己的语言和传统节日。", "explanation": "这里应该用〈民族〉。“人种”指按遗传特征（肤色、头型等）划分的人群，语言和节日应说“民族”。"}, {"text": "他拿的是中国护照，所以他的人种是中国。", "explanation": "这里应该用〈国籍〉。“人种”按遗传特征划分，护照表示的是国籍。"}, {"text": "这片森林里有上千个人种。", "explanation": "这里应该用〈物种〉。“人种”只指人类内部的群体，森林里的动植物要说“物种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人种", "is_correct": true, "explanation": "人种：正确答案，指人类中按遗传特征划分的群体，适合“几大”的介绍。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”指人数，不能说“几大人口”来分类介绍。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是个人特征，课本不会按“几大身高”来介绍世界。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“几大颜色”不构成人群类别，不能用来指代世界上的人。"}], "explanations": {"人种": "人种：正确答案，指人类中按遗传特征划分的群体，适合“几大”的介绍。", "人口": "搭配：“人口”指人数，不能说“几大人口”来分类介绍。", "身高": "语义：身高是个人特征，课本不会按“几大身高”来介绍世界。", "颜色": "搭配：“几大颜色”不构成人群类别，不能用来指代世界上的人。"}, "sentence_index": 6, "correct_answer": "人种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个村子的人说不同的人种。", "explanation": "这里应该用〈方言〉。“人种”是遗传特征的类别，语言上的差异要说“方言”。"}, {"text": "这种狗有很多人种。", "explanation": "这里应该用〈品种〉。“人种”只指人类群体，狗的类别要说“品种”。"}, {"text": "他的人种是医生，每天在医院工作。", "explanation": "这里应该用〈职业〉。“人种”指遗传特征相同的人群，医生是职业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他研究的是一只古老的人种。", "corrected_sentence": "他研究的是一个古老的人种。", "error_description": "错误：“一只人种”；正确：“一个人种”。“人种”是名词，计量用“个”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的人种们很多。", "corrected_sentence": "这个城市的人种很多。", "error_description": "错误：“人种们”；正确：“人种”。“人种”表示类别，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10323, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10323, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10323, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指植物成熟后可食用的部分，通常多汁、味甜。", "primary_collocate": null, "pronunciation": "guǒ zi", "ipa": "kuo˨˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "树上的果子熟了，又大又甜。", "target_word": "果子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种果子多汁，吃起来很甜。", "target_word": "果子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天到了，树上结满了果子。", "target_word": "果子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟飞到树上吃果子。", "target_word": "果子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个果子还没熟，味道很酸。", "target_word": "果子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶摘了一篮果子给我们。", "target_word": "果子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢吃甜甜的果子。", "target_word": "果子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地上掉着几个红红的果子。", "target_word": "果子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些果子洗干净再吃吧。", "target_word": "果子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "果子熟了，农民们都来摘果子。", "target_word": "果子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "颗", "label": "量词"}, {"form": "果子酱", "label": "复合"}], "register": "口语", "sense_fingerprint": "植物成熟后可以吃的部分，多汁味甜，口语说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b11de0e-cf3b-40a3-9579-0c6b07e0660f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10323, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "果子", "is_correct": true, "explanation": "正确。guǒ zi 指植物成熟后可以吃的部分，多汁味甜。"}, {"text": "锅子", "is_correct": false, "explanation": "guō zi（第一声）与 guǒ zi（第三声）只有第一个音节声调不同，锅子指做饭用的锅。"}, {"text": "瓜子", "is_correct": false, "explanation": "guā zi（第一声）与 guǒ zi（第三声）只有第一个音节声调不同，瓜子指炒熟或腌制的葵花子、西瓜子。"}, {"text": "果汁", "is_correct": false, "explanation": "guǒ zhī 与 guǒ zi 第一个音节相同，第二个音节声母（zh 与 z）和声调都不同；果汁是饮品，不是水果本身。"}, {"text": "骨子", "is_correct": false, "explanation": "gǔ zi 与 guǒ zi 只有第一个音节的韵母不同（u 与 uo），骨子指骨头，也指事物的本质。"}], "explanations": {"果子": "正确。guǒ zi 指植物成熟后可以吃的部分，多汁味甜。", "锅子": "guō zi（第一声）与 guǒ zi（第三声）只有第一个音节声调不同，锅子指做饭用的锅。", "瓜子": "guā zi（第一声）与 guǒ zi（第三声）只有第一个音节声调不同，瓜子指炒熟或腌制的葵花子、西瓜子。", "果汁": "guǒ zhī 与 guǒ zi 第一个音节相同，第二个音节声母（zh 与 z）和声调都不同；果汁是饮品，不是水果本身。", "骨子": "gǔ zi 与 guǒ zi 只有第一个音节的韵母不同（u 与 uo），骨子指骨头，也指事物的本质。"}, "sentence_index": null, "correct_answer": "果子"}, "level_3": {"options": [{"text": "果子", "is_correct": true, "explanation": "果子指植物成熟后可以吃的部分，与“熟了，又大又甜”相符。"}, {"text": "叶子", "is_correct": false, "explanation": "语义：叶子不会成熟，也不会变甜，“熟了”和“又大又甜”都不能用来形容叶子。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“熟”多用于果实、庄稼，不说花熟了。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会成熟，也不能甜，句意说不通。"}], "explanations": {"果子": "果子指植物成熟后可以吃的部分，与“熟了，又大又甜”相符。", "叶子": "语义：叶子不会成熟，也不会变甜，“熟了”和“又大又甜”都不能用来形容叶子。", "花": "搭配：“熟”多用于果实、庄稼，不说花熟了。", "石头": "语义：石头不会成熟，也不能甜，句意说不通。"}, "sentence_index": 0, "correct_answer": "果子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的努力终于有了果子。", "explanation": "这里应该用〈果实〉。“果子”指植物成熟后可以吃的部分，不能比喻努力的成果。"}, {"text": "我每天早上习惯喝果子。", "explanation": "这里应该用〈果汁〉。“果子”指植物结出的可以直接吃的果实，不是加工成的饮料，不能用来喝。"}, {"text": "这部电影的果子很圆满。", "explanation": "这里应该用〈结局〉。“果子”指植物结出的可吃部分，不能指故事或事情的结局。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10323, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "果子", "is_correct": true, "explanation": "正确。guǒ zi 指植物成熟后可以吃的部分，多汁味甜。"}, {"text": "果籽", "is_correct": false, "explanation": "guǒ zǐ 与 guǒ zi 只有第二个音节声调不同（第三声与轻声），果籽指果实里的种子，不是可吃的果子。"}, {"text": "谷子", "is_correct": false, "explanation": "gǔ zi 与 guǒ zi 只有第一个音节的韵母不同（u 与 uo），谷子是一种粮食作物，不是水果。"}, {"text": "箍子", "is_correct": false, "explanation": "gū zi 与 guǒ zi 第一个音节的韵母和声调都不同，箍子指套在东西外面的圈。"}], "explanations": {"果子": "正确。guǒ zi 指植物成熟后可以吃的部分，多汁味甜。", "果籽": "guǒ zǐ 与 guǒ zi 只有第二个音节声调不同（第三声与轻声），果籽指果实里的种子，不是可吃的果子。", "谷子": "gǔ zi 与 guǒ zi 只有第一个音节的韵母不同（u 与 uo），谷子是一种粮食作物，不是水果。", "箍子": "gū zi 与 guǒ zi 第一个音节的韵母和声调都不同，箍子指套在东西外面的圈。"}, "sentence_index": null, "correct_answer": "果子"}, "level_3": {"options": [{"text": "果子", "is_correct": true, "explanation": "果子指可以吃的水果，与“我喜欢吃甜甜的”相符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能吃，“吃甜甜的垃圾”句意不通。"}, {"text": "泥巴", "is_correct": false, "explanation": "搭配：“甜甜的”说食物的味道，不说甜甜的泥巴。"}, {"text": "煤块", "is_correct": false, "explanation": "语义：煤块不能吃，也没有甜味。"}], "explanations": {"果子": "果子指可以吃的水果，与“我喜欢吃甜甜的”相符。", "垃圾": "语义：垃圾不能吃，“吃甜甜的垃圾”句意不通。", "泥巴": "搭配：“甜甜的”说食物的味道，不说甜甜的泥巴。", "煤块": "语义：煤块不能吃，也没有甜味。"}, "sentence_index": 6, "correct_answer": "果子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的果子很好。", "explanation": "这里应该用〈结果〉。“果子”只指植物结出的可吃部分，不能指事情的结局。"}, {"text": "我在面包上抹了一层果子。", "explanation": "这里应该用〈果酱〉。“果子”指可以直接吃的果实，不是加工后涂抹在面包上的酱。"}, {"text": "他爷爷是一个果子。", "explanation": "这里应该用〈果农〉。“果子”指植物结出的可吃部分，不能指种果树的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10323, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我摘了几张红色的果子。", "corrected_sentence": "我摘了几个红色的果子。", "error_description": "量词错误：“果子”应用量词“个”（或“颗”），不能用“张”。“张”用于纸、桌子等平面的东西。错误形式是“几张红色的果子”，正确形式是“几个红色的果子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10323, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我吃了三条果子。", "corrected_sentence": "我吃了三个果子。", "error_description": "量词错误：“果子”应用量词“个”（或“颗”），不能用“条”。“条”用于鱼、河、裤子等长条形的东西。错误形式是“三条果子”，正确形式是“三个果子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
