INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10324, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把物体放在阳光下，使水分蒸发掉。", "primary_collocate": null, "pronunciation": "shài gān", "ipa": "ʂai˥˩ kan˥", "syllable_count": 2, "sentences": [{"text": "农民把粮食放在院子里晒干。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把湿衣服挂在外面晒干。", "target_word": "晒干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些辣椒要晒干以后才能保存。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每年秋天都把蘑菇晒干。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把鱼晒干后，可以放很久。", "target_word": "晒干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把洗好的鞋子放在窗边晒干。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红枣晒干以后更甜。", "target_word": "晒干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把毛巾拿到阳台上晒干。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些草药需要放在太阳下晒干。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民们把小鱼晒干，再卖到城里。", "target_word": "晒干", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "晒干了", "label": "体标"}, {"form": "晒干过", "label": "体标"}, {"form": "曬乾", "label": "繁体"}], "register": "通用", "sense_fingerprint": "人把东西放在阳光下晒，让水分蒸发而变干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b11de0e-cf3b-40a3-9579-0c6b07e0660f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晒干", "is_correct": true, "explanation": "晒干指把东西放在阳光下，让水分蒸发而变干，与“放在院子里”相合。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻要用冰箱或冷库，放在院子里不能冷冻粮食。"}, {"text": "放牧", "is_correct": false, "explanation": "配价：“放牧”的对象是牲畜，不能带“粮食”作宾语。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：烘烤要用炉子或烤箱，放在院子里并不能烘烤粮食。"}], "explanations": {"晒干": "晒干指把东西放在阳光下，让水分蒸发而变干，与“放在院子里”相合。", "冷冻": "语义：冷冻要用冰箱或冷库，放在院子里不能冷冻粮食。", "放牧": "配价：“放牧”的对象是牲畜，不能带“粮食”作宾语。", "烘烤": "语义：烘烤要用炉子或烤箱，放在院子里并不能烘烤粮食。"}, "sentence_index": 0, "correct_answer": "晒干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用烘干机把衣服晒干了。", "explanation": "这里应该用〈烘干〉。“晒干”靠阳光或通风让水分蒸发，用烘干机加热要用“烘干”。"}, {"text": "工人用火把湿木头晒干。", "explanation": "这里应该用〈烤干〉。“晒干”靠阳光或通风，不靠用火烤。"}, {"text": "他把孩子晒干了。", "explanation": "这里应该用〈晒黑〉。“晒干”只用于东西，使其水分蒸发而变干，人晒太阳要说“晒黑”，不能说“晒干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晒干", "is_correct": true, "explanation": "晒干指让红枣在阳光下失去水分、变干，与“更甜”的语境相合。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉的枣不会更甜，“扔掉以后更甜”句意不通。"}, {"text": "熬夜", "is_correct": false, "explanation": "配价：“熬夜”是不及物动词，不能以“红枣”作动作的对象。"}, {"text": "发霉", "is_correct": false, "explanation": "语义：发霉的红枣会变质，不会更甜。"}], "explanations": {"晒干": "晒干指让红枣在阳光下失去水分、变干，与“更甜”的语境相合。", "扔掉": "语义：扔掉的枣不会更甜，“扔掉以后更甜”句意不通。", "熬夜": "配价：“熬夜”是不及物动词，不能以“红枣”作动作的对象。", "发霉": "语义：发霉的红枣会变质，不会更甜。"}, "sentence_index": 6, "correct_answer": "晒干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "用吹风机把头发晒干了。", "explanation": "这里应该用〈吹干〉。“晒干”靠阳光或通风，用吹风机吹头发要用“吹干”。"}, {"text": "用毛巾把身上晒干。", "explanation": "这里应该用〈擦干〉。“晒干”是让东西变干，不用于擦拭身体。"}, {"text": "厂里用冷冻设备把草莓晒干。", "explanation": "这里应该用〈冻干〉。“晒干”靠阳光或通风，不用冷冻设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把被子搬到阳台上晒干着。", "corrected_sentence": "妈妈把被子搬到阳台上晒干了。", "error_description": "体标错误：“把……晒干”表示动作已完成，应用动态助词“了”，不能用表示持续状态的“着”。错误形式是“晒干着”，正确形式是“晒干了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨停以后，我把衣服拿到外面晒干得。", "corrected_sentence": "雨停以后，我把衣服拿到外面晒干了。", "error_description": "结构错误：“得”须引出补语，句末“晒干得”缺少补语，结构不成立；此处应用完成体“了”，说“晒干了”。错误形式是“晒干得”，正确形式是“晒干了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
