INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10327, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "袋子，指用布、皮、纸、塑料等制成的盛东西的器具。", "primary_collocate": null, "pronunciation": "dài zi", "ipa": "tai˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "然后，咖啡豆被装进大袋子。", "target_word": "袋子", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "顾客要付钱才能拿到袋子。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这些袋子可以用很多次。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我把苹果放进袋子里了。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个袋子是纸做的，很轻。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袋子破了，米都漏出来了。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一个袋子，我要装书。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里拿着一个红色的袋子。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的袋子现在要收费了。", "target_word": "袋子", "complexity_tier": "T3", "furigana": "chāo shì de dài zi xiàn zài yào shōu fèi le", "sentence_source": "generated"}, {"text": "妈妈去买菜，带了两个袋子。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个袋子", "label": "量词"}, {"form": "纸袋子", "label": "复合"}, {"form": "塑料袋子", "label": "复合"}], "register": "中性", "sense_fingerprint": "用布、纸、塑料等做的装东西的器具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b763f8e4-c8e2-4fed-b4e1-513ee2e3c8b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10327, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "袋子", "is_correct": true, "explanation": "袋子（dài zi）指用布、纸、塑料等做的盛东西的器具，是正确答案。"}, {"text": "对子", "is_correct": false, "explanation": "dài 与 duì 韵母不同（ai 与 ui），意思是成对的对联或成对的东西。"}, {"text": "太子", "is_correct": false, "explanation": "d 与 t 声母不同（不送气与送气），意思是君主的继承人。"}, {"text": "稻子", "is_correct": false, "explanation": "dài 与 dào 韵母不同（ai 与 ao），意思是水稻。"}], "explanations": {"袋子": "袋子（dài zi）指用布、纸、塑料等做的盛东西的器具，是正确答案。", "对子": "dài 与 duì 韵母不同（ai 与 ui），意思是成对的对联或成对的东西。", "太子": "d 与 t 声母不同（不送气与送气），意思是君主的继承人。", "稻子": "dài 与 dào 韵母不同（ai 与 ao），意思是水稻。"}, "sentence_index": null, "correct_answer": "袋子"}, "level_3": {"options": [{"text": "袋子", "is_correct": true, "explanation": "“装进”后接能装东西的容器，“大袋子”可以填入。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是能装东西的容器，与“装进”不符。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“装进”后接容器，不能接人，“老师”不搭配。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是电子设备，不能用来装咖啡豆。"}], "explanations": {"袋子": "“装进”后接能装东西的容器，“大袋子”可以填入。", "河流": "语义：河流不是能装东西的容器，与“装进”不符。", "老师": "搭配：“装进”后接容器，不能接人，“老师”不搭配。", "电脑": "语义：电脑是电子设备，不能用来装咖啡豆。"}, "sentence_index": 0, "correct_answer": "袋子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把苹果放进袋子里，用袋子切成了两半。", "explanation": "这里应该用〈刀〉。袋子是装东西的器具，不能用来切苹果，切东西要用刀。"}, {"text": "天太热了，他打开袋子吹凉风。", "explanation": "这里应该用〈电扇〉。袋子是装东西的，不能吹出凉风，吹风要用电扇。"}, {"text": "我用袋子给朋友打了个电话。", "explanation": "这里应该用〈手机〉。袋子是装东西的器具，不能打电话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10327, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "袋子", "is_correct": true, "explanation": "袋子（dài zi）指用布、纸、塑料等做的盛东西的器具，是正确答案。"}, {"text": "盖子", "is_correct": false, "explanation": "dài 与 gài 声母不同（d 与 g），意思是器物的盖子。"}, {"text": "弹子", "is_correct": false, "explanation": "dài 与 dàn 韵母不同（ai 与 an），意思是弹珠。"}, {"text": "赖子", "is_correct": false, "explanation": "dài 与 lài 声母不同（d 与 l），意思是无赖，或麻将中的百搭牌。"}], "explanations": {"袋子": "袋子（dài zi）指用布、纸、塑料等做的盛东西的器具，是正确答案。", "盖子": "dài 与 gài 声母不同（d 与 g），意思是器物的盖子。", "弹子": "dài 与 dàn 韵母不同（ai 与 an），意思是弹珠。", "赖子": "dài 与 lài 声母不同（d 与 l），意思是无赖，或麻将中的百搭牌。"}, "sentence_index": null, "correct_answer": "袋子"}, "level_3": {"options": [{"text": "袋子", "is_correct": true, "explanation": "“装书”要求能装东西的容器，“一个袋子”可以填入。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是用来插花的，不能用来装书。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗是盛饭菜的器具，装不下书。"}, {"text": "盘子", "is_correct": false, "explanation": "搭配：盘子是扁平的餐具，“装书”不搭配。"}], "explanations": {"袋子": "“装书”要求能装东西的容器，“一个袋子”可以填入。", "花瓶": "语义：花瓶是用来插花的，不能用来装书。", "碗": "语义：碗是盛饭菜的器具，装不下书。", "盘子": "搭配：盘子是扁平的餐具，“装书”不搭配。"}, "sentence_index": 6, "correct_answer": "袋子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把袋子放在火上烧开水。", "explanation": "这里应该用〈水壶〉。烧水要把水壶放在火上，袋子不能放在火上烧水。"}, {"text": "他累了，把袋子当作椅子坐下休息。", "explanation": "这里应该用〈椅子〉。袋子不能当椅子坐，坐下休息要用椅子。"}, {"text": "妈妈用袋子给我盛了一碗热汤。", "explanation": "这里应该用〈碗〉。盛汤要用碗，袋子不能用来盛汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一座新袋子装书。", "corrected_sentence": "他买了一个新袋子装书。", "error_description": "“袋子”的量词应用“个”，不能用“座”。“座”用于山、桥、房屋等大型固定物体，袋子应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一个很大袋子。", "corrected_sentence": "他买了一个很大的袋子。", "error_description": "修饰语“很大”与名词“袋子”之间漏了“的”。修饰语是词组时要用“的”连接，应说“很大的袋子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7046fd69-f3c5-4346-8219-70a247f2bab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
