INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指体积较大的船只，通常用于运输或航行。", "primary_collocate": null, "pronunciation": "dà chuán", "ipa": "ta˥˩ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "大船把咖啡豆运到别的国家。", "target_word": "大船", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "港口停着一艘大船。", "target_word": "大船", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘大船从中国开往日本。", "target_word": "大船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大船一次能运很多货物。", "target_word": "大船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们正在往大船上搬箱子。", "target_word": "大船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大船慢慢地离开了港口。", "target_word": "大船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大船上工作了十年。", "target_word": "大船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风太大，大船今天不能出海。", "target_word": "大船", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小河太窄，大船开不进来。", "target_word": "大船", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "码头上的大船把水果运到南方。", "target_word": "大船", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "艘", "label": "量词"}], "register": "中性", "sense_fingerprint": "体积较大、用于运输或航行的船", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b11de0e-cf3b-40a3-9579-0c6b07e0660f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大船", "is_correct": true, "explanation": "大船：体积大的运输船，能把咖啡豆运到别的国家，是唯一符合语境的词。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物不是运输工具，不能把咖啡豆运到外国。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会移动，不能运送货物。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：书包只装随身物品，“运到”的主语要能承载大宗货物，书包不能跨国运货。"}], "explanations": {"大船": "大船：体积大的运输船，能把咖啡豆运到别的国家，是唯一符合语境的词。", "宠物": "语义：宠物不是运输工具，不能把咖啡豆运到外国。", "房子": "语义：房子不会移动，不能运送货物。", "书包": "搭配：书包只装随身物品，“运到”的主语要能承载大宗货物，书包不能跨国运货。"}, "sentence_index": 0, "correct_answer": "大船"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把大船放进了口袋。", "explanation": "这里应该用〈玩具船〉。大船体积大，装不进口袋。"}, {"text": "大船在天上飞得很高。", "explanation": "这里应该用〈飞机〉。大船在水上航行，不能在天上飞。"}, {"text": "我每天骑大船上班。", "explanation": "这里应该用〈自行车〉。“骑”的对象是自行车等两轮车，大船不能骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大船", "is_correct": true, "explanation": "大船：可以在上面工作的大型船只，是唯一符合语境的词。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是可以工作的交通工具，不能说“在教室上工作”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是人能在上面工作的地方。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“在……上”多用于船、车、床等，工厂要说“在工厂里”。"}], "explanations": {"大船": "大船：可以在上面工作的大型船只，是唯一符合语境的词。", "教室": "语义：教室不是可以工作的交通工具，不能说“在教室上工作”。", "冰箱": "语义：冰箱不是人能在上面工作的地方。", "工厂": "搭配：“在……上”多用于船、车、床等，工厂要说“在工厂里”。"}, "sentence_index": 6, "correct_answer": "大船"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天坐大船上楼。", "explanation": "这里应该用〈电梯〉。大船是水上的运输工具，不能在楼层之间运行。"}, {"text": "大船在码头上睡着了。", "explanation": "这里应该用〈工人〉。船不会睡觉，“睡着”的主语应是人。"}, {"text": "他推着大船去市场。", "explanation": "这里应该用〈小推车〉。“推”的对象是能在陆地上移动的物件，大船不能被推着走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那辆大船明天要开往上海。", "corrected_sentence": "那艘大船明天要开往上海。", "error_description": "量词错误：船只应使用量词“艘”，不能用“辆”。“辆”用于车。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "码头上停着一座大船。", "corrected_sentence": "码头上停着一艘大船。", "error_description": "量词错误：船只应用“艘”，不用“座”。“座”用于山、桥、楼等大型固定的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
