INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10329, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将货物或物品从一处运送到某个地方。", "primary_collocate": null, "pronunciation": "yùn dào", "ipa": "yn˥˩ tau̯˥˩", "syllable_count": 2, "sentences": [{"text": "大船把咖啡豆运到别的国家。", "target_word": "运到", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这些水果是昨天运到的。", "target_word": "运到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新的机器已经运到工厂了。", "target_word": "运到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货物明天就能运到这里。", "target_word": "运到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们把大米运到山里的学校。", "target_word": "运到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车把木头运到了河边。", "target_word": "运到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药品要快点儿运到医院。", "target_word": "运到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "船上的茶叶运到港口要三天。", "target_word": "运到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批书什么时候能运到学校？", "target_word": "运到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪天路滑，药品没有运到。", "target_word": "运到", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "运到了", "label": "完成体"}, {"form": "运不到", "label": "否定可能补语"}], "register": "中性", "sense_fingerprint": "把货物或物品从别处运输到某个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b11de0e-cf3b-40a3-9579-0c6b07e0660f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10329, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运到", "is_correct": true, "explanation": "运到：把货物运送到某地，与“大船把咖啡豆”搭配，是唯一符合语境的词。"}, {"text": "吃到", "is_correct": false, "explanation": "配价：“吃”的施事要能吃，宾语要是可吃的东西，大船和咖啡豆都不符合。"}, {"text": "咬到", "is_correct": false, "explanation": "语义：“咬”是用牙齿咬，不能表示把咖啡豆运送到别的国家。"}, {"text": "唱到", "is_correct": false, "explanation": "语义：“唱”不能用于运送货物，“唱到别的国家”没有运输的意思。"}], "explanations": {"运到": "运到：把货物运送到某地，与“大船把咖啡豆”搭配，是唯一符合语境的词。", "吃到": "配价：“吃”的施事要能吃，宾语要是可吃的东西，大船和咖啡豆都不符合。", "咬到": "语义：“咬”是用牙齿咬，不能表示把咖啡豆运送到别的国家。", "唱到": "语义：“唱”不能用于运送货物，“唱到别的国家”没有运输的意思。"}, "sentence_index": 0, "correct_answer": "运到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天要把孩子运到学校。", "explanation": "这里应该用〈送〉。“运到”用于运送货物，送人去学校要说“送”。"}, {"text": "我去车站，把朋友运到了家里。", "explanation": "这里应该用〈送〉。“运到”只用于货物，把人送到某处要说“送”。"}, {"text": "我一个人运到了学校。", "explanation": "这里应该用〈走到〉。“运到”要有被运送的货物，人自己去学校应说“走到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运到", "is_correct": true, "explanation": "运到：把药品运送到医院，是唯一符合语境的词。"}, {"text": "跑到", "is_correct": false, "explanation": "语义：药品不能自己跑，要运到医院需要运输工具或人。"}, {"text": "游到", "is_correct": false, "explanation": "配价：“游”的施事要能游动，药品不能游到医院。"}, {"text": "爬到", "is_correct": false, "explanation": "语义：药品无法自行爬行到医院。"}], "explanations": {"运到": "运到：把药品运送到医院，是唯一符合语境的词。", "跑到": "语义：药品不能自己跑，要运到医院需要运输工具或人。", "游到": "配价：“游”的施事要能游动，药品不能游到医院。", "爬到": "语义：药品无法自行爬行到医院。"}, "sentence_index": 6, "correct_answer": "运到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息运到了村子里。", "explanation": "这里应该用〈传〉。“运到”指搬运有形的货物，消息这类无形之物要说“传”。"}, {"text": "河水运到了大海。", "explanation": "这里应该用〈流〉。“运到”需要有人或工具搬运，河水是自然流到大海。"}, {"text": "风运到了屋里。", "explanation": "这里应该用〈吹〉。“运到”的施事要能搬运东西，风是自然力，不能“运”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "货车已经木材运到工地了。", "corrected_sentence": "货车已经把木材运到工地了。", "error_description": "把字句错误：“运到”的宾语“木材”前要加“把”，应说“把木材运到”；去掉“把”后，“木材”无法与前面的“货车”搭配作主语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天的药品不运到灾区。", "corrected_sentence": "昨天的药品没运到灾区。", "error_description": "否定词错误：说已经发生但没有完成的事，要用“没”，不用“不”。“不”一般用于习惯或将来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8512e2da-dee1-44f2-94c7-9036878361e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
