INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10330, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指商店的内部或所在位置", "primary_collocate": null, "pronunciation": "diàn lǐ", "ipa": "tjɛn⁵¹ li²¹⁴", "syllable_count": 2, "sentences": [{"text": "人们在店里买咖啡喝。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "服务员每天都在店里工作，非常忙。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家鞋店很大，店里有很多新鞋。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雨了，客人都走进店里躲雨。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不在店里，请你晚点再来。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的客人太多，我们要等一会儿。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在店里买了一件好看的衣服。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里卖的水果又新鲜又便宜。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在店里哭着要买玩具。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的灯太暗，我看不清价格。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "店裡", "label": "繁体"}, {"form": "店里面", "label": "复合"}], "register": "口语", "sense_fingerprint": "店里：商店的内部或所在位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c95f3d-3cf8-40ea-b1f4-10f0941e860d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10330, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "店里", "is_correct": true, "explanation": "正确答案：店里（diànlǐ），指商店的内部。"}, {"text": "典礼", "is_correct": false, "explanation": "diǎnlǐ 与 diànlǐ 第一音节声调不同（第三声 / 第四声），意思是典礼。"}, {"text": "电力", "is_correct": false, "explanation": "diànlì 与 diànlǐ 第二音节声调不同（第四声 / 第三声），意思是电力。"}, {"text": "县里", "is_correct": false, "explanation": "xiànlǐ 与 diànlǐ 第一音节声母不同（x / d），意思是县里（县的内部或县政府）。"}], "explanations": {"店里": "正确答案：店里（diànlǐ），指商店的内部。", "典礼": "diǎnlǐ 与 diànlǐ 第一音节声调不同（第三声 / 第四声），意思是典礼。", "电力": "diànlì 与 diànlǐ 第二音节声调不同（第四声 / 第三声），意思是电力。", "县里": "xiànlǐ 与 diànlǐ 第一音节声母不同（x / d），意思是县里（县的内部或县政府）。"}, "sentence_index": null, "correct_answer": "店里"}, "level_3": {"options": [{"text": "店里", "is_correct": true, "explanation": "正确：店里指店内，人们在店内买咖啡，与“买”相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不卖咖啡，与“买咖啡”冲突。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是售卖场所，与“买咖啡”冲突。"}, {"text": "卧室", "is_correct": false, "explanation": "搭配：“买”的处所应是售卖商品的地方，卧室不能与“买咖啡”搭配。"}], "explanations": {"店里": "正确：店里指店内，人们在店内买咖啡，与“买”相符。", "厨房": "语义：厨房是做饭的地方，不卖咖啡，与“买咖啡”冲突。", "教室": "语义：教室不是售卖场所，与“买咖啡”冲突。", "卧室": "搭配：“买”的处所应是售卖商品的地方，卧室不能与“买咖啡”搭配。"}, "sentence_index": 0, "correct_answer": "店里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在露天的店里野餐。", "explanation": "这里应该用〈户外〉。“店里”指商店内部，与“露天”（室外）矛盾。"}, {"text": "我站在店里外面等你。", "explanation": "这里应该用〈店外〉。“店里”表示内部，“外面”表示外部，二者不能同时指同一处所。"}, {"text": "他把车停在店里的马路上。", "explanation": "这里应该用〈店门口〉。“马路”在店外，与表示店内的“店里”位置相冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10330, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "店里", "is_correct": true, "explanation": "正确答案：店里（diànlǐ），指商店的内部。"}, {"text": "献礼", "is_correct": false, "explanation": "xiànlǐ 与 diànlǐ 第一音节声母不同（x / d），意思是献礼。"}, {"text": "电笔", "is_correct": false, "explanation": "diànbǐ 与 diànlǐ 第二音节声母不同（b / l），意思是电笔（测电的工具）。"}, {"text": "电离", "is_correct": false, "explanation": "diànlí 与 diànlǐ 第二音节声调不同（第二声 / 第三声），意思是电离（化学术语）。"}], "explanations": {"店里": "正确答案：店里（diànlǐ），指商店的内部。", "献礼": "xiànlǐ 与 diànlǐ 第一音节声母不同（x / d），意思是献礼。", "电笔": "diànbǐ 与 diànlǐ 第二音节声母不同（b / l），意思是电笔（测电的工具）。", "电离": "diànlí 与 diànlǐ 第二音节声调不同（第二声 / 第三声），意思是电离（化学术语）。"}, "sentence_index": null, "correct_answer": "店里"}, "level_3": {"options": [{"text": "店里", "is_correct": true, "explanation": "正确：店里指店内，在店里买衣服合理。"}, {"text": "书房", "is_correct": false, "explanation": "语义：书房是读书的地方，不卖衣服，与“买”冲突。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅书籍的地方，不卖衣服，与“买衣服”冲突。"}, {"text": "医院", "is_correct": false, "explanation": "搭配：“买衣服”的处所应能售卖衣物，医院不能与之搭配。"}], "explanations": {"店里": "正确：店里指店内，在店里买衣服合理。", "书房": "语义：书房是读书的地方，不卖衣服，与“买”冲突。", "图书馆": "语义：图书馆是借阅书籍的地方，不卖衣服，与“买衣服”冲突。", "医院": "搭配：“买衣服”的处所应能售卖衣物，医院不能与之搭配。"}, "sentence_index": 6, "correct_answer": "店里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们骑马穿过店里的草原。", "explanation": "这里应该用〈店外〉。“店里”指室内，“草原”在室外，二者位置冲突。"}, {"text": "我们在店里的大海里游泳。", "explanation": "这里应该用〈海边〉。“店里”指商店内部，不能与“大海”这类室外场所并列。"}, {"text": "孩子在店里的雪山上滑雪。", "explanation": "这里应该用〈店外的〉修饰“雪山”。“店里”指店内，与“雪山”这类室外场所的位置相冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐店里挑了一条围巾。", "corrected_sentence": "我姐姐在店里挑了一条围巾。", "error_description": "错误：“店里挑”，缺少介词“在”。正确：“在店里挑”。“店里”作处所状语时要用“在”引出，不能直接放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天在店里的买了一双好看的鞋。", "corrected_sentence": "我昨天在店里买了一双好看的鞋。", "error_description": "错误：“在店里的买了”，处所短语“在店里”后多加了结构助词“的”。正确：“在店里买了”。处所短语作状语修饰动词时不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
