INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指用于盛放液体（多为饮用水）的器皿，通常为圆柱状，有把手或无把手。", "primary_collocate": null, "pronunciation": "bēi zi", "ipa": "peɪ̯˥ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "咖啡从农场到杯子，要经过很多地方。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个标志出现在杯子上、盒子上和街上。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "桌子上有一个红色的杯子。", "target_word": "杯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我一个干净的杯子。", "target_word": "杯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把热水倒进杯子里。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的杯子里有牛奶。", "target_word": "杯子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不小心打破了一个杯子。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子太烫，我拿不住。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天用同一个杯子喝水。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把杯子放在桌子上。", "target_word": "杯子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "只", "label": "量词"}, {"form": "水杯", "label": "复合"}, {"form": "茶杯", "label": "复合"}], "register": "中性", "sense_fingerprint": "盛放饮用水等液体的圆柱形器皿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65ed119e-0d7b-4fd6-9dc2-f9c5d6a85cda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "配价：“到”要求处所作终点，“时间”不能充当咖啡流转的终点。"}, {"text": "杯子", "is_correct": true, "explanation": "正确：“杯子”是盛放饮料的器皿，是咖啡流转链条的终点，与“从农场到……要经过很多地方”的语境相符。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：咖啡不会“到”身体器官，“眼睛”不是可以到达的地点。"}, {"text": "问题", "is_correct": false, "explanation": "语义：“问题”是抽象概念，不能作为咖啡流转的终点。"}], "explanations": {"时间": "配价：“到”要求处所作终点，“时间”不能充当咖啡流转的终点。", "杯子": "正确：“杯子”是盛放饮料的器皿，是咖啡流转链条的终点，与“从农场到……要经过很多地方”的语境相符。", "眼睛": "语义：咖啡不会“到”身体器官，“眼睛”不是可以到达的地点。", "问题": "语义：“问题”是抽象概念，不能作为咖啡流转的终点。"}, "sentence_index": 0, "correct_answer": "杯子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个杯子里的水够全家人洗澡用。", "explanation": "这里应该用〈桶〉。杯子容量小，只用来盛饮料，装够全家洗澡的水要用〈桶〉。"}, {"text": "杯子里装着全家的冬衣。", "explanation": "这里应该用〈箱子〉。杯子太小，装不下衣物，收纳冬衣要用〈箱子〉。"}, {"text": "孩子们在杯子里游泳。", "explanation": "这里应该用〈游泳池〉。杯子很小，只用来盛饮料，人不能在里面游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地毯", "is_correct": false, "explanation": "语义：“地毯”是铺设的织物，不是能被“打破”的器物。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“打破”常接“沉默”“纪录”“平静”等，不能接“天气”。"}, {"text": "杯子", "is_correct": true, "explanation": "正确：“打破”的对象是具体器物，“一个杯子”符合句意。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”是人，不是可以被打破的器物。"}], "explanations": {"地毯": "语义：“地毯”是铺设的织物，不是能被“打破”的器物。", "天气": "搭配：“打破”常接“沉默”“纪录”“平静”等，不能接“天气”。", "杯子": "正确：“打破”的对象是具体器物，“一个杯子”符合句意。", "学生": "语义：“学生”是人，不是可以被打破的器物。"}, "sentence_index": 6, "correct_answer": "杯子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用杯子吃饭。", "explanation": "这里应该用〈碗〉。杯子用来盛饮料，不能用来吃饭。"}, {"text": "妈妈用杯子夹菜。", "explanation": "这里应该用〈筷子〉。杯子不能用来夹取食物。"}, {"text": "他用杯子写字。", "explanation": "这里应该用〈笔〉。杯子不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌子上放着两张杯子。", "corrected_sentence": "桌子上放着两个杯子。", "error_description": "量词错误：“杯子”应用量词“个”或“只”，不能用“张”（“张”用于纸、桌子等扁平物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一张杯子拿起来了。", "corrected_sentence": "他把一个杯子拿起来了。", "error_description": "量词错误：“杯子”应用量词“个”或“只”，不能用“张”（“张”用于纸、桌子等扁平物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
