INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10336, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指全球各个地区或国家。", "primary_collocate": null, "pronunciation": "shì jiè gè dì", "ipa": "ʂɻ̩˥˩ tɕjɛ˥˩ kɤ˥˩ ti˥˩", "syllable_count": 4, "sentences": [{"text": "通过国际贸易，咖啡豆从生产地运往世界各地。", "target_word": "世界各地", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们喝的咖啡，来自世界各地的农场。", "target_word": "世界各地", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "世界各地的游客都来这里看雪。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的朋友遍布世界各地。", "target_word": "世界各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日在世界各地都很有名。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想去世界各地旅行。", "target_word": "世界各地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世界各地的人都喜欢吃面条。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书已经卖到世界各地了。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的学生来自世界各地。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻很快就传到了世界各地。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "全球各个地区或国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ed7dbc-a6e5-40ee-911c-fb724370c835') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世界各地", "is_correct": true, "explanation": "“世界各地”指全球各个地区，与“运往”的目的地相符。"}, {"text": "月球", "is_correct": false, "explanation": "语义：咖啡豆不会运往月球，句子在常识上不成立。"}, {"text": "生产地", "is_correct": false, "explanation": "语义：句中已说“从生产地”出发，再运往生产地自相矛盾。"}, {"text": "海底", "is_correct": false, "explanation": "搭配：“运往”的目的地需要能通行货运，“海底”不能作咖啡豆的运往地。"}], "explanations": {"世界各地": "“世界各地”指全球各个地区，与“运往”的目的地相符。", "月球": "语义：咖啡豆不会运往月球，句子在常识上不成立。", "生产地": "语义：句中已说“从生产地”出发，再运往生产地自相矛盾。", "海底": "搭配：“运往”的目的地需要能通行货运，“海底”不能作咖啡豆的运往地。"}, "sentence_index": 0, "correct_answer": "世界各地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春运期间，世界各地的火车站都很拥挤。", "explanation": "这里应该用〈全国各地〉。春运是中国国内的返乡高峰，用“世界各地”会把范围扩大到全球，与事实不符。"}, {"text": "他的东西散落在房间的世界各地。", "explanation": "这里应该用〈各个角落〉。“世界各地”指全球范围，不能用来指一个房间里的各处。"}, {"text": "这座城市的世界各地都有公园。", "explanation": "这里应该用〈市区〉。“世界各地”指全球，不能用来指某一座城市之内。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世界各地", "is_correct": true, "explanation": "“世界各地”指全球各个地区的人，能够与“的人”搭配，句意通顺。"}, {"text": "火星", "is_correct": false, "explanation": "语义：火星上没有人群居住，不能说“火星的人”。"}, {"text": "火山口", "is_correct": false, "explanation": "语义：火山口不是人群聚居的地方，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”是物品，不能与“的人”搭配指人群。"}], "explanations": {"世界各地": "“世界各地”指全球各个地区的人，能够与“的人”搭配，句意通顺。", "火星": "语义：火星上没有人群居住，不能说“火星的人”。", "火山口": "语义：火山口不是人群聚居的地方，句意不通。", "冰箱": "搭配：“冰箱”是物品，不能与“的人”搭配指人群。"}, "sentence_index": 6, "correct_answer": "世界各地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国和世界各地建立了外交关系。", "explanation": "这里应该用〈各国〉。建立外交关系的对象必须是具体的国家，“世界各地”是笼统的范围，不能作为一方。"}, {"text": "工厂的机器分布在车间的世界各地。", "explanation": "这里应该用〈各处〉。“世界各地”指全球，不能用来指车间里的各处。"}, {"text": "我家的世界各地有很多超市。", "explanation": "这里应该用〈附近〉。“世界各地”是全球范围，不能用来指家附近的区域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的产品卖世界各地。", "corrected_sentence": "这家公司的产品卖到世界各地。", "error_description": "错误：“卖”后漏掉趋向补语“到”，句子不成立。正确说法是“卖到世界各地”，“到”表示产品卖去的地点，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去着世界各地。", "corrected_sentence": "他去过世界各地。", "error_description": "错误：体标用错。“去着世界各地”不成立，“着”表示动作持续，不能表示去过某地的经历。表示经历应该用“过”，正确说法是“他去过世界各地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10341, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10341, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10341, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指地球表面靠近赤道、全年气温较高的区域。", "primary_collocate": null, "pronunciation": "rè dài dì qū", "ipa": "ʐɤ˥˩ taɪ˥˩ ti˥˩ tɕʰy˥", "syllable_count": 4, "sentences": [{"text": "咖啡豆的种植属于农业活动，主要在热带地区进行。", "target_word": "热带地区", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "热带地区全年都很热。", "target_word": "热带地区", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "香蕉常常长在热带地区。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去过很多热带地区。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热带地区的雨很多。", "target_word": "热带地区", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在热带地区，人们很少穿厚衣服。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种水果只在热带地区才有。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去热带地区的海边玩。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热带地区的动物种类很多。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在热带地区工作了三年。", "target_word": "热带地区", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱帶地區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地理上靠近赤道、全年气温高的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b265e353-0a56-4f5b-a790-095a42c113c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10341, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热带地区", "is_correct": true, "explanation": "正确。咖啡豆主要种植在热带地区，符合句意。"}, {"text": "寒带", "is_correct": false, "explanation": "语义：寒带气候寒冷，咖啡豆无法在那里种植，与“种植”冲突。"}, {"text": "极地", "is_correct": false, "explanation": "语义：极地常年低温，不适合农业活动，与句子语境冲突。"}, {"text": "北极", "is_correct": false, "explanation": "搭配：“主要在…进行”的农业活动一般不说在北极进行，与“咖啡豆的种植”不搭配。"}], "explanations": {"热带地区": "正确。咖啡豆主要种植在热带地区，符合句意。", "寒带": "语义：寒带气候寒冷，咖啡豆无法在那里种植，与“种植”冲突。", "极地": "语义：极地常年低温，不适合农业活动，与句子语境冲突。", "北极": "搭配：“主要在…进行”的农业活动一般不说在北极进行，与“咖啡豆的种植”不搭配。"}, "sentence_index": 0, "correct_answer": "热带地区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "热带地区是一条假想的线。", "explanation": "这里应该用〈赤道〉。赤道才是一条假想的线，热带地区是一片有范围的地区，不能说成线。"}, {"text": "热带地区一年四季都很冷。", "explanation": "这里应该用〈北极地区〉。北极地区一年四季都很冷，热带地区全年气温较高，不能说很冷。"}, {"text": "热带地区的冬天下着大雪。", "explanation": "这里应该用〈东北〉。东北的冬天下大雪，热带地区全年气温较高，不会下雪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10341, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热带地区", "is_correct": true, "explanation": "正确。“只在…才有”后接产地，热带地区是这种水果的产地。"}, {"text": "冰原", "is_correct": false, "explanation": "语义：冰原上不长水果，与“这种水果”的产地语境冲突。"}, {"text": "冻土带", "is_correct": false, "explanation": "语义：冻土带地表冻结，不产水果，与句意冲突。"}, {"text": "南极", "is_correct": false, "explanation": "搭配：“南极”通常不作水果产地，“只在…才有”的搭配不合理。"}], "explanations": {"热带地区": "正确。“只在…才有”后接产地，热带地区是这种水果的产地。", "冰原": "语义：冰原上不长水果，与“这种水果”的产地语境冲突。", "冻土带": "语义：冻土带地表冻结，不产水果，与句意冲突。", "南极": "搭配：“南极”通常不作水果产地，“只在…才有”的搭配不合理。"}, "sentence_index": 6, "correct_answer": "热带地区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "热带地区的冬天很漫长。", "explanation": "这里应该用〈寒带地区〉。寒带地区冬天漫长，热带地区全年气温较高，没有漫长的冬天。"}, {"text": "热带地区夏天凉爽，冬天寒冷。", "explanation": "这里应该用〈高原地区〉。高原地区夏天凉爽、冬天寒冷，热带地区全年气温较高，不能这样说。"}, {"text": "热带地区常年有冰雪。", "explanation": "这里应该用〈南极地区〉。南极地区常年有冰雪，热带地区气温较高，不会有冰雪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10341, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去过一只热带地区。", "corrected_sentence": "我去过一个热带地区。", "error_description": "量词错误：“热带地区”前应用“个”，“只”是动物的量词，不能用于地区。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10341, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条热带地区的人很喜欢吃水果。", "corrected_sentence": "那片热带地区的人很喜欢吃水果。", "error_description": "量词错误：“热带地区”前应用“片”，“条”用于细长的东西，不能修饰地区。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10348, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "干燥", "is_correct": true, "explanation": "正确。“干燥”与“湿润”是反义词，指没有水分、不潮湿。"}, {"text": "粗糙", "is_correct": false, "explanation": "不构成反义：“粗糙”描述表面质地，与含水量无关。"}, {"text": "明亮", "is_correct": false, "explanation": "不构成反义：“明亮”描述光线，与水分无关。"}, {"text": "温暖", "is_correct": false, "explanation": "不构成反义：“温暖”描述温度，与“湿润”的含水状态不对立。"}], "correct_answer": "干燥", "explanations": {"干燥": "正确。“干燥”与“湿润”是反义词，指没有水分、不潮湿。", "粗糙": "不构成反义：“粗糙”描述表面质地，与含水量无关。", "明亮": "不构成反义：“明亮”描述光线，与水分无关。", "温暖": "不构成反义：“温暖”描述温度，与“湿润”的含水状态不对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10348, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "干燥", "is_correct": true, "explanation": "正确。“干燥”与“湿润”是反义词，指没有水分。"}, {"text": "整洁", "is_correct": false, "explanation": "不构成反义：“整洁”描述干净整齐，与含水量无关。"}, {"text": "柔软", "is_correct": false, "explanation": "不构成反义：“柔软”描述质地，与是否含水不对立。"}, {"text": "冰凉", "is_correct": false, "explanation": "不构成反义：“冰凉”描述温度感受，与水分状态无关。"}], "correct_answer": "干燥", "explanations": {"干燥": "正确。“干燥”与“湿润”是反义词，指没有水分。", "整洁": "不构成反义：“整洁”描述干净整齐，与含水量无关。", "柔软": "不构成反义：“柔软”描述质地，与是否含水不对立。", "冰凉": "不构成反义：“冰凉”描述温度感受，与水分状态无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10348, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物体含有水分，不干燥，有潮湿的感觉。", "primary_collocate": null, "pronunciation": "shī rùn", "ipa": "ʂɨ˥ ʐwən˥˩", "syllable_count": 2, "sentences": [{"text": "一些国家如南美洲和非洲的部分国家，气候温暖湿润，适合咖啡树生长。", "target_word": "湿润", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "海边的空气很湿润。", "target_word": "湿润", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下过雨，泥土变得湿润了。", "target_word": "湿润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼睛湿润了，没有说话。", "target_word": "湿润", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南方的气候温暖湿润。", "target_word": "湿润", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "洗完脸后，要让皮肤保持湿润。", "target_word": "湿润", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湿润的草地上有很多小水珠。", "target_word": "湿润", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块蛋糕又软又湿润。", "target_word": "湿润", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的空气总是很湿润。", "target_word": "湿润", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用湿润的毛巾擦了擦手。", "target_word": "湿润", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "濕潤", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体或空气含有水分、不干燥的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b265e353-0a56-4f5b-a790-095a42c113c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10348, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "湿润", "is_correct": true, "explanation": "正确。“气候温暖湿润”描述咖啡树适宜的气候，符合句意。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”与“温暖”矛盾，且咖啡树不适合寒冷气候。"}, {"text": "酷热", "is_correct": false, "explanation": "语义：“酷热”与“温暖”程度冲突，不是温和的气候描述。"}, {"text": "严寒", "is_correct": false, "explanation": "搭配：“温暖”与“严寒”不能并列描述同一气候，搭配不当。"}], "explanations": {"湿润": "正确。“气候温暖湿润”描述咖啡树适宜的气候，符合句意。", "寒冷": "语义：“寒冷”与“温暖”矛盾，且咖啡树不适合寒冷气候。", "酷热": "语义：“酷热”与“温暖”程度冲突，不是温和的气候描述。", "严寒": "搭配：“温暖”与“严寒”不能并列描述同一气候，搭配不当。"}, "sentence_index": 0, "correct_answer": "湿润"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服湿润得拧得出水。", "explanation": "这里应该用〈湿透〉。“湿润”只表示轻微的潮湿，衣服湿到滴水要用“湿透”。"}, {"text": "我的心情很湿润，想哭。", "explanation": "这里应该用〈伤心〉。“湿润”只描述物体、皮肤或眼睛的水分状态，不用来形容心情。"}, {"text": "沙漠里的空气很湿润，一年都不下雨。", "explanation": "这里应该用〈干燥〉。沙漠里不下雨，空气缺少水分，应说“干燥”，不能说“湿润”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿润", "is_correct": true, "explanation": "正确。草地上有水珠，说明草地是湿润的，符合句意。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：干燥的草地上不会有水珠，与句子后半句冲突。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：滚烫的草地不会凝结水珠，与语境冲突。"}, {"text": "灼热", "is_correct": false, "explanation": "搭配：“灼热”形容高温，与“小水珠”搭配不合理。"}], "explanations": {"湿润": "正确。草地上有水珠，说明草地是湿润的，符合句意。", "干燥": "语义：干燥的草地上不会有水珠，与句子后半句冲突。", "滚烫": "语义：滚烫的草地不会凝结水珠，与语境冲突。", "灼热": "搭配：“灼热”形容高温，与“小水珠”搭配不合理。"}, "sentence_index": 6, "correct_answer": "湿润"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用湿润的钢铁擦了擦手。", "explanation": "这里“湿润”用错了对象。湿润形容含水分、不干燥的东西，钢铁是金属，不含水分，应该说〈光亮〉的钢铁。"}, {"text": "他的湿润的心情很好。", "explanation": "这里“湿润”用错了对象。湿润形容含水分的东西，不能形容心情；表达心情好应该说〈愉快〉。"}, {"text": "他用湿润得滴水的毛巾擦了擦手。", "explanation": "这里应该用〈湿透〉。“湿润”只表示轻微潮湿，毛巾滴水的程度要用“湿透”，不能用“湿润”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨后的泥土得湿润。", "corrected_sentence": "雨后的泥土很湿润。", "error_description": "用词错误：修饰形容词“湿润”的程度词应用副词“很”，不能用助词“得”代替，应说“很湿润”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块湿润布很好用。", "corrected_sentence": "这块湿润的布很好用。", "error_description": "用法问题：“湿润”修饰名词“布”时一般加“的”，“湿润布”不自然，应说“湿润的布”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10351, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "付出", "is_correct": true, "explanation": "付出指投入劳动或努力，与“收获”表示的取得成果相对。"}, {"text": "观察", "is_correct": false, "explanation": "观察是仔细看，与收获没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运是把东西从一处运到另一处，与收获不构成反义。"}, {"text": "休息", "is_correct": false, "explanation": "休息是停下来不做事，与收获不构成反义。"}], "correct_answer": "付出", "explanations": {"付出": "付出指投入劳动或努力，与“收获”表示的取得成果相对。", "观察": "观察是仔细看，与收获没有反义关系。", "搬运": "搬运是把东西从一处运到另一处，与收获不构成反义。", "休息": "休息是停下来不做事，与收获不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10351, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "播种", "is_correct": true, "explanation": "播种是撒下种子，与收获（把成熟的果实取回来）相对。"}, {"text": "修理", "is_correct": false, "explanation": "修理是把坏的东西弄好，与收获没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考是用脑子想问题，与收获没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步是慢慢走路，与收获没有反义关系。"}], "correct_answer": "播种", "explanations": {"播种": "播种是撒下种子，与收获（把成熟的果实取回来）相对。", "修理": "修理是把坏的东西弄好，与收获没有反义关系。", "思考": "思考是用脑子想问题，与收获没有反义关系。", "散步": "散步是慢慢走路，与收获没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10351, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指成熟后的庄稼、果实等从地里或树上取回来，也可指获得成果或得到好处。", "primary_collocate": null, "pronunciation": "shōu huò", "ipa": "ʂou˥ xuo˥˩", "syllable_count": 2, "sentences": [{"text": "农民在那里种植咖啡树，收获咖啡果实，再把果实加工成咖啡豆。", "target_word": "收获", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "秋天农民在田里收获玉米。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九月我们在果园里收获了很多苹果。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一年的努力，他收获了好成绩。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行让我收获了很多快乐。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "稻子黄了，农民开始收获了。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读了这本书，收获了不少新知识。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天种下的小麦，夏天就能收获。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "认真做事的人，总会收获别人的信任。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在山上收获了一大筐茶叶。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收获了", "label": "体标"}, {"form": "收获过", "label": "体标"}, {"form": "收获季节", "label": "复合"}, {"form": "收穫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：收取成熟的庄稼果实，或比喻获得成果、好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bca74fc9-b4a9-4068-a7f1-1de1a45d97e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10351, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收获", "is_correct": true, "explanation": "词条本身，读作 shōu huò。"}, {"text": "售货", "is_correct": false, "explanation": "第一个音节声调不同：shòu 为第四声，shōu 为第一声；意思是卖货。"}, {"text": "搜获", "is_correct": false, "explanation": "第一个音节声母不同：s 与 sh；意思是搜查后得到。"}, {"text": "受惑", "is_correct": false, "explanation": "第一个音节声调不同：shòu 为第四声，shōu 为第一声；意思是被迷惑。"}], "explanations": {"收获": "词条本身，读作 shōu huò。", "售货": "第一个音节声调不同：shòu 为第四声，shōu 为第一声；意思是卖货。", "搜获": "第一个音节声母不同：s 与 sh；意思是搜查后得到。", "受惑": "第一个音节声调不同：shòu 为第四声，shōu 为第一声；意思是被迷惑。"}, "sentence_index": null, "correct_answer": "收获"}, "level_3": {"options": [{"text": "收获", "is_correct": true, "explanation": "正确。前文说在那里种植咖啡树，此处指把成熟的果实从树上取下来。"}, {"text": "播种", "is_correct": false, "explanation": "搭配：播种指撒下种子，咖啡果实已经长成，不能说播种。"}, {"text": "购买", "is_correct": false, "explanation": "语义：前文说农民自己种植咖啡树，购买与此矛盾。"}, {"text": "研磨", "is_correct": false, "explanation": "搭配：研磨用于咖啡豆，不用于咖啡果实；加工是后面才提到的步骤。"}], "explanations": {"收获": "正确。前文说在那里种植咖啡树，此处指把成熟的果实从树上取下来。", "播种": "搭配：播种指撒下种子，咖啡果实已经长成，不能说播种。", "购买": "语义：前文说农民自己种植咖啡树，购买与此矛盾。", "研磨": "搭配：研磨用于咖啡豆，不用于咖啡果实；加工是后面才提到的步骤。"}, "sentence_index": 0, "correct_answer": "收获"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在工厂上班，每个月收获了一顿午饭。", "explanation": "这里应该用〈吃〉。收获指取得成果或好处，或取下成熟的果实；午饭是吃掉的，不能说收获。"}, {"text": "他在决赛中收获了这场比赛。", "explanation": "这里应该用〈赢得〉。赢得可以跟比赛、胜利搭配，收获的对象是成果或好处，不能说收获一场比赛。"}, {"text": "他在地铁站收获了一张车票。", "explanation": "这里应该用〈买〉。收获指从田地或树上取下成熟的果实，或取得成果、好处；车票是买来的，不能说收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10351, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收获", "is_correct": true, "explanation": "正确。读书后获得了知识，与“新知识”搭配。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：搬运的对象是实物，知识不能搬运。"}, {"text": "装卸", "is_correct": false, "explanation": "搭配：装卸用于货物，与“新知识”不搭。"}, {"text": "叫卖", "is_correct": false, "explanation": "语义：叫卖指沿街吆喝着卖东西，与读书的语境无关。"}], "explanations": {"收获": "正确。读书后获得了知识，与“新知识”搭配。", "搬运": "搭配：搬运的对象是实物，知识不能搬运。", "装卸": "搭配：装卸用于货物，与“新知识”不搭。", "叫卖": "语义：叫卖指沿街吆喝着卖东西，与读书的语境无关。"}, "sentence_index": 6, "correct_answer": "收获"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次事故让他收获了巨大的损失。", "explanation": "这里应该用〈遭受〉。收获只用于取得成果或好处，损失是负面结果，要说遭受。"}, {"text": "工人在车间里收获了一台新机器。", "explanation": "这里应该用〈生产〉。收获的对象是庄稼、果实，或成果、好处；车间里造出的机器要说生产。"}, {"text": "我们在公园里收获了一个小时。", "explanation": "这里应该用〈度过〉。收获的对象是成果或好处，时间要说度过，不能说收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年秋天，我们在田里收获的很多土豆。", "corrected_sentence": "去年秋天，我们在田里收获了很多土豆。", "error_description": "“的”误用：加上“的”后，句子变成名词短语，没有谓语；应用“了”表示完成，说“收获了很多土豆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片麦田去年就已经收获完。", "corrected_sentence": "这片麦田去年就已经收获完了。", "error_description": "“收获完”后缺少“了”。“已经”常与“了”搭配表示动作已完成，应说“已经收获完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
