INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10357, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "市场上用来交换或出售的物品。", "primary_collocate": null, "pronunciation": "shāng pǐn", "ipa": "ʂaŋ˥ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "出口意味着把商品卖到国外。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "进口就是从别的国家买进商品。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "虽然咖啡豆原产于非洲，但现在它已经成为全球贸易中的重要商品。", "target_word": "商品", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这家商店的商品又好又便宜。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上商品的价格每天都不一样。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的商品都有价格牌。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买商品以前，我先看看价格。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种商品很受年轻人欢迎。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里有很多外国商品。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，商品的价格常常会涨。", "target_word": "商品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件商品", "label": "量词"}, {"form": "一种商品", "label": "量词"}, {"form": "商品经济", "label": "复合"}, {"form": "商品房", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：市场上用来交换或出售的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bca74fc9-b4a9-4068-a7f1-1de1a45d97e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10357, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商品", "is_correct": true, "explanation": "正确。商品指用来买卖的东西，出口就是把它卖到国外。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是自然物，不能作为商品卖到国外。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“卖”一般用于物品，时间不能这样卖到国外。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不是可以出售的东西。"}], "explanations": {"商品": "正确。商品指用来买卖的东西，出口就是把它卖到国外。", "空气": "语义：空气是自然物，不能作为商品卖到国外。", "时间": "搭配：“卖”一般用于物品，时间不能这样卖到国外。", "地震": "语义：地震是自然灾害，不是可以出售的东西。"}, "sentence_index": 0, "correct_answer": "商品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "放学后，他把自己的商品整理好，放进了书包。", "explanation": "这里应该用〈物品〉。商品专指用来买卖的东西，自己书包里用的东西不是商品。"}, {"text": "他这些年写了很多商品。", "explanation": "这里应该用〈作品〉。商品专指用来买卖的东西，写出来的文学或艺术创作要说作品。"}, {"text": "老师讲课很认真，我们学到了很多商品。", "explanation": "这里应该用〈知识〉。学到的是知识，商品指用来买卖的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10357, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商品", "is_correct": true, "explanation": "正确。买商品是指买用来买卖的东西。"}, {"text": "月光", "is_correct": false, "explanation": "搭配：“买”的对象是物品，月光不能买。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：夜晚不是可以买卖的东西，与“看看价格”的语境矛盾。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然景观，不是可以买卖的物品。"}], "explanations": {"商品": "正确。买商品是指买用来买卖的东西。", "月光": "搭配：“买”的对象是物品，月光不能买。", "夜晚": "语义：夜晚不是可以买卖的东西，与“看看价格”的语境矛盾。", "河流": "语义：河流是自然景观，不是可以买卖的物品。"}, "sentence_index": 6, "correct_answer": "商品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在超市买了一头商品。", "explanation": "这里的量词用错了。“头”用于牲畜，不能用于商品；商品通常用“件”或“种”。"}, {"text": "他在书店挑了一首商品。", "explanation": "这里的量词用错了。“首”用于诗歌、歌曲，不能用于商品；商品通常用“件”或“种”。"}, {"text": "她在花店挑了一朵商品。", "explanation": "这里的量词用错了。“朵”用于花、云等，不能用于商品；商品通常用“件”或“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂生产了三只商品。", "corrected_sentence": "这家工厂生产了三件商品。", "error_description": "量词用错了。商品应该用“件”或“种”计量，“只”用于动物等，不能用于商品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一张商品。", "corrected_sentence": "他买了一件商品。", "error_description": "量词用错了。“张”用于纸张、桌子等平面的东西，商品应该用“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10362, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卖出", "is_correct": true, "explanation": "正确。买进与卖出互为反义，一买一卖。"}, {"text": "保存", "is_correct": false, "explanation": "与买进无反义关系，保存指妥善存放东西。"}, {"text": "参观", "is_correct": false, "explanation": "与买进无反义关系，参观指去某处看看。"}, {"text": "休息", "is_correct": false, "explanation": "与买进无反义关系，休息指停止工作以恢复体力。"}], "correct_answer": "卖出", "explanations": {"卖出": "正确。买进与卖出互为反义，一买一卖。", "保存": "与买进无反义关系，保存指妥善存放东西。", "参观": "与买进无反义关系，参观指去某处看看。", "休息": "与买进无反义关系，休息指停止工作以恢复体力。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
