INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用货币换取物品或资产的所有权。", "primary_collocate": null, "pronunciation": "mǎi jìn", "ipa": "mai˨˩˦ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "进口就是从别的国家买进商品。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "公司从国外买进了一批新机器。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得股票会涨，就买进了一千股。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店老板每天早上买进新鲜蔬菜。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂买进了很多原料。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格低的时候买进，价格高的时候卖出。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打算买进一些大米放在仓库里。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年他买进过一家小公司的股票。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商人买进便宜的布，再高价卖给客人。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行买进了一些美元。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "买进了", "label": "体标"}, {"form": "买进过", "label": "体标"}, {"form": "買進", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：花钱买入货物、股票等资产，与卖出相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bca74fc9-b4a9-4068-a7f1-1de1a45d97e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10362, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。mǎi jìn，指用钱买入货物或股票。"}, {"text": "迈进", "is_correct": false, "explanation": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是向前迈步。"}, {"text": "埋进", "is_correct": false, "explanation": "mái jìn（第二声）与 mǎi（第三声）声调不同，意思是埋入。"}, {"text": "卖劲", "is_correct": false, "explanation": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是使劲、卖力。"}], "explanations": {"买进": "正确。mǎi jìn，指用钱买入货物或股票。", "迈进": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是向前迈步。", "埋进": "mái jìn（第二声）与 mǎi（第三声）声调不同，意思是埋入。", "卖劲": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是使劲、卖力。"}, "sentence_index": null, "correct_answer": "买进"}, "level_3": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。与“进口”方向一致，指从外国买入商品。"}, {"text": "卖出", "is_correct": false, "explanation": "语义：卖出是售出，方向与“进口”相反，句子自相矛盾。"}, {"text": "保存", "is_correct": false, "explanation": "语义：保存是妥善存放东西，与“进口”（买入货物）不符，句子说不通。"}, {"text": "生产", "is_correct": false, "explanation": "配价：“生产”的主语是制造者，“从别的国家”作起点，句子说不通。"}], "explanations": {"买进": "正确。与“进口”方向一致，指从外国买入商品。", "卖出": "语义：卖出是售出，方向与“进口”相反，句子自相矛盾。", "保存": "语义：保存是妥善存放东西，与“进口”（买入货物）不符，句子说不通。", "生产": "配价：“生产”的主语是制造者，“从别的国家”作起点，句子说不通。"}, "sentence_index": 0, "correct_answer": "买进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他深深地买进了一口气，然后开始说话。", "explanation": "这里应该用〈吸〉。“买进”表示用钱购买东西，不能用来指吸气。"}, {"text": "他买进了一个新朋友。", "explanation": "这里应该用〈结交〉。“买进”的对象是货物或资产，不能用来指人。"}, {"text": "她买进了一个好主意。", "explanation": "这里应该用〈想出〉。“买进”只用于货物或资产，不能用于想法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10362, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。mǎi jìn，指用钱买入货物或股票。"}, {"text": "摆进", "is_correct": false, "explanation": "bǎi jìn 与 mǎi jìn 声母不同（b 与 m），意思是摆放进去。"}, {"text": "卖尽", "is_correct": false, "explanation": "mài jìn 与 mǎi 声调不同，意思是全部卖光。"}, {"text": "卖金", "is_correct": false, "explanation": "mài jīn 与 mǎi jìn 两个字的声调都不同，意思是卖掉金子。"}], "explanations": {"买进": "正确。mǎi jìn，指用钱买入货物或股票。", "摆进": "bǎi jìn 与 mǎi jìn 声母不同（b 与 m），意思是摆放进去。", "卖尽": "mài jìn 与 mǎi 声调不同，意思是全部卖光。", "卖金": "mài jīn 与 mǎi jìn 两个字的声调都不同，意思是卖掉金子。"}, "sentence_index": null, "correct_answer": "买进"}, "level_3": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。“打算……放在仓库里”说明要把大米买来储存。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉是丢弃，与“放在仓库里”的意思矛盾。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：吃掉是吃下去，与“放在仓库里”的意思矛盾。"}, {"text": "卖给", "is_correct": false, "explanation": "配价：“卖给”需要说明买方，句中没有买方，且“一些大米”不能作买方。"}], "explanations": {"买进": "正确。“打算……放在仓库里”说明要把大米买来储存。", "扔掉": "语义：扔掉是丢弃，与“放在仓库里”的意思矛盾。", "吃掉": "语义：吃掉是吃下去，与“放在仓库里”的意思矛盾。", "卖给": "配价：“卖给”需要说明买方，句中没有买方，且“一些大米”不能作买方。"}, "sentence_index": 6, "correct_answer": "买进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书买进了书架。", "explanation": "这里应该用〈放〉。“买进”表示用钱购买，不表示把东西放进某处。"}, {"text": "我想买进一场雨，让庄稼长得好。", "explanation": "这里应该用〈盼来〉。“买进”的对象是货物或资产，雨不能买。"}, {"text": "妈妈买进了一句夸奖。", "explanation": "这里应该用〈听到〉。“买进”只用于有形的货物或资产，夸奖不能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
