INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10363, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指不同国家之间进行的商品、服务和资本的交换活动。", "primary_collocate": null, "pronunciation": "guó jì mào yì", "ipa": "kuɔ˧˥ tɕi˥˩ maʊ˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "通过国际贸易，咖啡豆从生产地运往世界各地。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "全球咖啡豆供应链是当代国际贸易体系中最为复杂的商品流通网络之一。", "target_word": "国际贸易", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "国际贸易让各国的商品可以互相流通。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国和很多国家都有国际贸易。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司做国际贸易已经十年了。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际贸易需要办很多手续，比如报关。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业后进入一家从事国际贸易的公司。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "港口是国际贸易的重要通道。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年国际贸易增长很快，港口越来越忙。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际贸易中，货物常常用船来运送。", "target_word": "国际贸易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國際貿易", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国与国之间交换商品、服务和资本的经济活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0ed7dbc-a6e5-40ee-911c-fb724370c835') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10363, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际贸易", "is_correct": true, "explanation": "“国际贸易”指国家之间的商品交换，作为运输的渠道，句意通顺。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不能用来运送咖啡豆，句意不通。"}, {"text": "友情", "is_correct": false, "explanation": "语义：友情不是运输的渠道，句意荒谬。"}, {"text": "咖啡杯", "is_correct": false, "explanation": "搭配：“通过”后接的是方式或渠道，“咖啡杯”不能作运输渠道。"}], "explanations": {"国际贸易": "“国际贸易”指国家之间的商品交换，作为运输的渠道，句意通顺。", "音乐": "语义：音乐不能用来运送咖啡豆，句意不通。", "友情": "语义：友情不是运输的渠道，句意荒谬。", "咖啡杯": "搭配：“通过”后接的是方式或渠道，“咖啡杯”不能作运输渠道。"}, "sentence_index": 0, "correct_answer": "国际贸易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国的学生每年都进行国际贸易。", "explanation": "这里应该用〈国际交流〉。贸易指商品、服务和资本的交换，学生之间的文化往来不属于国际贸易。"}, {"text": "今年的国际贸易在北京召开。", "explanation": "这里应该用〈国际会议〉。“召开”用于会议，国际贸易是交换活动，不能召开。"}, {"text": "这班国际贸易从北京起飞。", "explanation": "这里应该用〈国际航班〉。起飞的是航班，国际贸易不是可以起飞的事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际贸易", "is_correct": true, "explanation": "“国际贸易”指国家之间的商品、服务交换活动，可以作“从事”的宾语，句意通顺。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“从事”后接行业或业务，“天空”不是行业，句意荒谬。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“从事”后接行业或业务，“心情”不是行业，句意不通。"}, {"text": "友情", "is_correct": false, "explanation": "搭配：“从事”后接行业或业务，“友情”不是行业，句意荒谬。"}], "explanations": {"国际贸易": "“国际贸易”指国家之间的商品、服务交换活动，可以作“从事”的宾语，句意通顺。", "天空": "搭配：“从事”后接行业或业务，“天空”不是行业，句意荒谬。", "心情": "搭配：“从事”后接行业或业务，“心情”不是行业，句意不通。", "友情": "搭配：“从事”后接行业或业务，“友情”不是行业，句意荒谬。"}, "sentence_index": 6, "correct_answer": "国际贸易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家小超市只做附近居民之间的国际贸易。", "explanation": "这里应该用〈生意〉。国际贸易是国家之间的交换，同一个小区居民之间的买卖不是国际贸易。"}, {"text": "我和同桌在教室里进行国际贸易，交换了铅笔。", "explanation": "这里应该用〈交换〉。同学之间换铅笔不是国家之间的商品交换。"}, {"text": "她每天在家里做国际贸易，打扫房间、洗衣服。", "explanation": "这里应该用〈家务〉。打扫、洗衣是家务，不是国家之间的贸易活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司每年都国际贸易。", "corrected_sentence": "这家公司每年都做国际贸易。", "error_description": "错误：“国际贸易”前漏掉动词“做”，句子缺少谓语。正确说法是“每年都做国际贸易”，“做”不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司把国际贸易成功了。", "corrected_sentence": "我们公司把国际贸易做成功了。", "error_description": "错误：“把”字句中“国际贸易”后漏掉动词“做”，“把国际贸易成功了”不成立。正确说法是“把国际贸易做成功了”，补上动词“做”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45bd0aa-b3bc-4d3c-b5a0-4dd8d9b903d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
