INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将物品通过运输方式发送到某个目的地。", "primary_collocate": null, "pronunciation": "yùn wǎng", "ipa": "yn˥˩ wɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "通过国际贸易，咖啡豆从生产地运往世界各地。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这些苹果明天会运往北京。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把新鲜的水果运往城市。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货已经运往海边的港口了。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把大米运往南方的商店。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车把煤从山里运往工厂。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些药品要尽快运往受灾的地方。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车正在把牛奶运往学校。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天有一艘船把茶叶运往国外。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书会从上海运往西安。", "target_word": "运往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运往", "label": "基本形"}, {"form": "运往了", "label": "体标（了）"}, {"form": "運往", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用车船等把货物运送到某个目的地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bca74fc9-b4a9-4068-a7f1-1de1a45d97e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运往", "is_correct": true, "explanation": "正确。“运往”表示送到某地，与“从生产地”的去向一致。"}, {"text": "收回", "is_correct": false, "explanation": "语义：收回是拿回来，与“从生产地运往世界各地”的去向相反。"}, {"text": "收购", "is_correct": false, "explanation": "配价：“收购”的对象是要买入的东西，“世界各地”不能作收购对象。"}, {"text": "生产", "is_correct": false, "explanation": "配价：“生产”的对象是制造出的产品，“世界各地”不能作生产的对象。"}], "explanations": {"运往": "正确。“运往”表示送到某地，与“从生产地”的去向一致。", "收回": "语义：收回是拿回来，与“从生产地运往世界各地”的去向相反。", "收购": "配价：“收购”的对象是要买入的东西，“世界各地”不能作收购对象。", "生产": "配价：“生产”的对象是制造出的产品，“世界各地”不能作生产的对象。"}, "sentence_index": 0, "correct_answer": "运往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书运往桌子上放好了。", "explanation": "这里应该用〈搬到〉。“运往”指用车船长途运送货物，把书放在桌子上是近距离移动。"}, {"text": "这个消息已经运往海边的城市了。", "explanation": "这里应该用〈传到〉。“运往”的对象是货物，消息不能用车船运送。"}, {"text": "这封电子邮件已经运往公司了。", "explanation": "这里应该用〈发往〉。“运往”指用车船运送货物，电子邮件是通过网络发送的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运往", "is_correct": true, "explanation": "正确。“运往”表示把药品送到受灾地区。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：收藏是珍藏保存，与“尽快”送到受灾地方的目的不符。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：拆除是拆掉建筑物，句子说不通。"}, {"text": "清点", "is_correct": false, "explanation": "语义：清点是查数，不能表示把药品送往某地。"}], "explanations": {"运往": "正确。“运往”表示把药品送到受灾地区。", "收藏": "语义：收藏是珍藏保存，与“尽快”送到受灾地方的目的不符。", "拆除": "语义：拆除是拆掉建筑物，句子说不通。", "清点": "语义：清点是查数，不能表示把药品送往某地。"}, "sentence_index": 6, "correct_answer": "运往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些电力正在运往小岛。", "explanation": "这里应该用〈输送〉。“运往”用于车船运送货物，电要靠线路输送。"}, {"text": "这个好消息很快就运往了全村。", "explanation": "这里应该用〈传遍〉。“运往”的对象是货物，消息不能用车船运送。"}, {"text": "这首歌已经运往海边的港口了。", "explanation": "这里应该用〈传播〉。“运往”只用于货物，歌曲不能用车船运送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批木材明天会运往了南方的工地。", "corrected_sentence": "这批木材明天会运往南方的工地。", "error_description": "错误在“往”后面。“了”表示已经发生，与“明天会”的将来时间冲突，应去掉“了”，说“明天会运往南方的工地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些药会从广州运往在武汉。", "corrected_sentence": "这些药会从广州运往武汉。", "error_description": "错误在“往”后面多加了介词“在”。“运往”的“往”已经引出去向，后面直接接地点，应说“运往武汉”，不能说“运往在武汉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10367, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59aaf5a9-524b-40e7-8479-dc16d85a9545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
